// Determina el resultat de la partida des de la perspectiva del jugador
function entryOutcome(entry) {
    return ElTaulerCore.historyEntryOutcome(entry && entry.result);
}

// Agrega estadístiques per obertura jugada a partir de l'historial (punt 4)
function analyzeOpeningStatsData() {
    const map = {};
    gameHistory.forEach(entry => {
        if (entry.mode === 'bundle') return;
        const moves = getHistoryMoves(entry);
        const oa = analyzeGameOpening(moves);
        if (!oa || !oa.name) return;
        const key = oa.eco ? `${oa.name}|${oa.eco}` : oa.name;
        if (!map[key]) map[key] = { name: oa.name, eco: oa.eco, games: 0, win: 0, loss: 0, draw: 0 };
        map[key].games++;
        const o = entryOutcome(entry);
        if (o === 'win') map[key].win++;
        else if (o === 'loss') map[key].loss++;
        else if (o === 'draw') map[key].draw++;
    });
    return Object.values(map).sort((a, b) => b.games - a.games);
}

function renderOpeningStats() {
    const container = document.getElementById('stats-openings');
    if (!container) return;
    const data = analyzeOpeningStatsData();
    if (!data.length) {
        container.innerHTML = '<div style="color:var(--text-secondary); font-size:0.9rem;">Encara no hi ha prou partides per analitzar les teves obertures.</div>';
        return;
    }
    let html = '';
    data.slice(0, 8).forEach(d => {
        const decided = d.win + d.loss;
        const wr = decided > 0 ? Math.round((d.win / decided) * 100) : 0;
        const wrColor = wr >= 60 ? '#4a7c59' : (wr >= 40 ? '#c9a227' : '#c62828');
        html += `<div class="opening-stat-row">
            <div class="opening-stat-name">${d.name}${d.eco ? ` <span class="opening-stat-eco">${d.eco}</span>` : ''}</div>
            <div class="opening-stat-record">${d.win}V · ${d.draw}T · ${d.loss}D</div>
            <div class="opening-stat-wr" style="color:${wrColor};">${decided > 0 ? wr + '%' : '—'}</div>
        </div>`;
    });
    container.innerHTML = html;
}

// Modalitat que ensenya la gràfica de progressió: 'main' (ELO principal, les
// partides sense rellotge) o l'id d'un ritme ('3+2'…). Es tria al desplegable
// de sobre la gràfica i es manté mentre l'app és oberta.
let eloChartTcId = 'main';

// Omple el desplegable de modalitats de la gràfica: sempre l'ELO principal i,
// a més, cada ritme que ja té ELO propi. Si la tria guardada ja no és vàlida
// (p. ex. després d'esborrar dades), torna al principal. Amb només el
// principal disponible, el desplegable s'amaga.
function populateEloChartTcSelect() {
    const sel = document.getElementById('elo-chart-tc-select');
    if (!sel) return;
    const options = [{ id: 'main', label: 'Principal · sense rellotge' }].concat(
        TIME_CONTROLS
            .filter(t => t.id !== 'none' && getTimeControlRating(t.id) !== null)
            .map(t => ({ id: t.id, label: t.label }))
    );
    if (!options.some(o => o.id === eloChartTcId)) eloChartTcId = 'main';
    sel.innerHTML = options
        .map(o => `<option value="${o.id}"${o.id === eloChartTcId ? ' selected' : ''}>${escapeHtml(o.label)}</option>`)
        .join('');
    const bar = document.getElementById('elo-chart-toolbar');
    if (bar) bar.style.display = options.length > 1 ? '' : 'none';
}

// Sèrie {date, elo} de la modalitat triada. Per als ritmes amb ELO d'abans que
// es guardés historial, se'n crea un amb el valor actual com a primer punt.
function eloChartSeries(tcId) {
    if (tcId === 'main') {
        if (eloHistory.length === 0) { eloHistory.push({ date: getToday(), elo: userELO }); saveStorage(); }
        return eloHistory;
    }
    const entry = timeControlElos[tcId];
    if (!entry || typeof entry.elo !== 'number') return [];
    if (!Array.isArray(entry.history) || !entry.history.length) {
        entry.history = [{ date: getToday(), elo: Math.round(entry.elo) }];
        saveStorage();
    }
    return entry.history;
}

function updateEloChart() {
    const canvas = document.getElementById('elo-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (isCalibrationActive()) {
        if (eloChart) eloChart.destroy();
        return;
    }
    populateEloChartTcSelect();
    const series = eloChartSeries(eloChartTcId);
    // Peu de la gràfica: quina modalitat s'està veient i quantes partides té.
    const hint = document.getElementById('elo-chart-hint');
    if (hint) {
        if (eloChartTcId === 'main') {
            hint.textContent = 'ELO principal: les partides sense rellotge.';
        } else {
            const entry = timeControlElos[eloChartTcId] || {};
            const games = entry.games || 0;
            hint.textContent = `${getTimeControlLabel(eloChartTcId)} · ${games} ${games === 1 ? 'partida' : 'partides'}`
                + (series.length < 2 ? ' · la línia creixerà amb cada partida d\'aquest ritme' : '');
        }
    }
    const labels = series.map(entry => { const parts = entry.date.split('-'); return `${parts[2]}/${parts[1]}`; });
    const data = series.map(entry => entry.elo);
    const strokeColor = epaperEnabled ? '#555' : '#c9a227';
    const fillColor = epaperEnabled ? 'rgba(90, 90, 90, 0.12)' : 'rgba(201, 162, 39, 0.1)';
    const pointBorder = epaperEnabled ? '#666' : '#f4e4bc';
    const gridColor = epaperEnabled ? '#d0d0d0' : 'rgba(201, 162, 39, 0.1)';
    const tickColor = epaperEnabled ? '#444' : '#a89a8a';
    
    if (eloChart) eloChart.destroy();
    eloChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [{
                label: 'ELO',
                data: data,
                borderColor: strokeColor,
                backgroundColor: fillColor,
                tension: 0.3,
                fill: true,
                pointBackgroundColor: strokeColor,
                pointBorderColor: pointBorder,
                pointBorderWidth: 2,
                pointRadius: 4,
                pointHoverRadius: 6
            }]
        },
        options: {
            responsive: true, maintainAspectRatio: false,
            plugins: { legend: { display: false } },
            scales: {
                y: { beginAtZero: false, grid: { color: gridColor }, ticks: { color: tickColor } },
                x: { grid: { color: gridColor }, ticks: { color: tickColor, maxRotation: 45, minRotation: 45 } }
            }
        }
    });
}

function classifyMoveQuality(swing, playerMove = null, bestMove = null) {
    if (playerMove && bestMove && playerMove === bestMove) return 'excel';
    if (swing === null || swing === undefined || Number.isNaN(swing)) return 'unknown';
    const absSwing = Math.abs(swing);
    const useEnrichedThresholds = Boolean(playerMove || bestMove);

    if (useEnrichedThresholds) {
        if (absSwing <= 25) return 'excel';
        if (absSwing <= 50) return 'good';
        if (absSwing <= 100) return 'inaccuracy';
        if (absSwing <= 300) return 'mistake';
        return 'blunder';
    }

    if (absSwing <= 30) return 'excel';
    if (absSwing <= 80) return 'good';
    if (absSwing <= 200) return 'inaccuracy';
    if (absSwing <= 600) return 'mistake';
    return 'blunder';
}

function initStockfishEnriched(stockfishInstance, multiPvCount = 3) {
    stockfishInstance.postMessage('uci');
    stockfishInstance.postMessage(`setoption name MultiPV value ${multiPvCount}`);
    stockfishInstance.postMessage('isready');
}

function parseUciInfo(line) {
    if (!line.startsWith('info') || !line.includes(' pv ')) return null;

    const info = {
        depth: null,
        seldepth: null,
        multipv: 1,
        score: null,
        scoreType: 'cp',
        nodes: null,
        nps: null,
        time: null,
        pv: []
    };

    const depthMatch = line.match(/\bdepth (\d+)/);
    if (depthMatch) info.depth = Number.parseInt(depthMatch[1], 10);

    const seldepthMatch = line.match(/\bseldepth (\d+)/);
    if (seldepthMatch) info.seldepth = Number.parseInt(seldepthMatch[1], 10);

    const multipvMatch = line.match(/\bmultipv (\d+)/);
    if (multipvMatch) info.multipv = Number.parseInt(multipvMatch[1], 10);

    const scoreCpMatch = line.match(/\bscore cp (-?\d+)/);
    if (scoreCpMatch) {
        info.score = Number.parseInt(scoreCpMatch[1], 10);
        info.scoreType = 'cp';
    }

    const scoreMateMatch = line.match(/\bscore mate (-?\d+)/);
    if (scoreMateMatch) {
        info.score = Number.parseInt(scoreMateMatch[1], 10);
        info.scoreType = 'mate';
    }

    const nodesMatch = line.match(/\bnodes (\d+)/);
    if (nodesMatch) info.nodes = Number.parseInt(nodesMatch[1], 10);

    const npsMatch = line.match(/\bnps (\d+)/);
    if (npsMatch) info.nps = Number.parseInt(npsMatch[1], 10);

    const timeMatch = line.match(/\btime (\d+)/);
    if (timeMatch) info.time = Number.parseInt(timeMatch[1], 10);

    const pvMatch = line.match(/ pv (.+)$/);
    if (pvMatch) {
        info.pv = pvMatch[1].trim().split(/\s+/);
    }

    return info;
}

class EnrichedAnalysis {
    constructor(fen, targetDepth = 20, multiPvCount = 3) {
        this.fen = fen;
        this.targetDepth = targetDepth;
        this.multiPvCount = multiPvCount;
        this.alternatives = new Map();
        this.maxDepthReached = 0;
        this.isComplete = false;
    }

    processLine(line) {
        const info = parseUciInfo(line);
        if (!info || info.depth === null) return;

        const existing = this.alternatives.get(info.multipv);
        if (!existing || info.depth >= existing.depth) {
            this.alternatives.set(info.multipv, info);
        }

        if (info.depth > this.maxDepthReached) {
            this.maxDepthReached = info.depth;
        }
    }

    complete() {
        this.isComplete = true;
    }

    getAlternatives() {
        return Array.from(this.alternatives.values())
            .sort((a, b) => a.multipv - b.multipv)
            .map((info) => ({
                move: info.pv[0] || null,
                eval: info.score,
                evalType: info.scoreType,
                depth: info.depth,
                pv: info.pv
            }));
    }

    getBestMove() {
        const best = this.alternatives.get(1);
        if (!best) return null;

        return {
            move: best.pv[0] || null,
            eval: best.score,
            evalType: best.scoreType,
            depth: best.depth,
            pv: best.pv
        };
    }
}

function analyzePositionEnriched(stockfishInstance, fen, depth = 20, multiPv = 3) {
    return new Promise((resolve) => {
        const analysis = new EnrichedAnalysis(fen, depth, multiPv);
        let timeoutId = null;

        const cleanup = () => {
            stockfishInstance.removeEventListener('message', messageHandler);
            if (timeoutId) {
                clearTimeout(timeoutId);
                timeoutId = null;
            }
        };

        const messageHandler = (event) => {
            const line = event.data;
            if (typeof line !== 'string') return;

            if (line.startsWith('info')) {
                analysis.processLine(line);
            }

            if (line.startsWith('bestmove')) {
                cleanup();
                analysis.complete();
                resolve({
                    fen,
                    depth: analysis.maxDepthReached,
                    bestMove: analysis.getBestMove(),
                    alternatives: analysis.getAlternatives()
                });
            }
        };

        timeoutId = setTimeout(() => {
            cleanup();
            analysis.complete();
            resolve({
                fen,
                depth: analysis.maxDepthReached,
                bestMove: analysis.getBestMove(),
                alternatives: analysis.getAlternatives(),
                timedOut: true
            });
        }, 30000);

        stockfishInstance.addEventListener('message', messageHandler);
        try { stockfishInstance.postMessage(`setoption name MultiPV value ${multiPv}`); } catch (e) {}
        stockfishInstance.postMessage(`position fen ${fen}`);
        stockfishInstance.postMessage(`go depth ${depth}`);
    });
}

// Variant amb límit de temps real: el motor s'atura al primer límit (depth o movetime),
// així cap anàlisi pot quedar-se penjada en dispositius lents.
function analyzePositionEnrichedTimed(stockfishInstance, fen, depth, multiPv, moveTimeMs, timeoutMs) {
    return new Promise((resolve) => {
        const analysis = new EnrichedAnalysis(fen, depth, multiPv);
        let timeoutId = null;
        const cleanup = () => {
            stockfishInstance.removeEventListener('message', messageHandler);
            if (timeoutId) { clearTimeout(timeoutId); timeoutId = null; }
        };
        const finish = (timedOut) => {
            cleanup();
            analysis.complete();
            resolve({
                fen,
                depth: analysis.maxDepthReached,
                bestMove: analysis.getBestMove(),
                alternatives: analysis.getAlternatives(),
                timedOut: !!timedOut
            });
        };
        const messageHandler = (event) => {
            const line = event.data;
            if (typeof line !== 'string') return;
            if (line.startsWith('info')) analysis.processLine(line);
            if (line.startsWith('bestmove')) finish(false);
        };
        timeoutId = setTimeout(() => {
            try { stockfishInstance.postMessage('stop'); } catch (e) {}
            finish(true);
        }, timeoutMs);
        stockfishInstance.addEventListener('message', messageHandler);
        try { stockfishInstance.postMessage(`setoption name MultiPV value ${multiPv}`); } catch (e) {}
        stockfishInstance.postMessage(`position fen ${fen}`);
        stockfishInstance.postMessage(`go depth ${depth} movetime ${moveTimeMs}`);
    });
}

// Handshake UCI: confirma que el motor és viu i ha buidat la cua de missatges.
function waitForEngineReady(timeoutMs = 4000) {
    return new Promise(resolve => {
        if (!stockfish) { resolve(false); return; }
        let done = false;
        let tid = null;
        const onMsg = (e) => {
            if (typeof e.data === 'string' && e.data.indexOf('readyok') === 0) finish(true);
        };
        const finish = (ok) => {
            if (done) return;
            done = true;
            try { stockfish.removeEventListener('message', onMsg); } catch (e) {}
            if (tid) clearTimeout(tid);
            resolve(ok);
        };
        tid = setTimeout(() => finish(false), timeoutMs);
        try {
            stockfish.addEventListener('message', onMsg);
            stockfish.postMessage('isready');
        } catch (e) { finish(false); }
    });
}

function restartStockfishWorker() {
    try { if (stockfish && stockfish.terminate) stockfish.terminate(); } catch (e) {}
    stockfish = null;
    stockfishReady = false;
    return ensureStockfish();
}

// Anàlisi robusta per a la preparació d'exercicis: handshake previ, límit de temps,
// validació que la jugada és legal per a AQUEST fen (descarta respostes de cerques
// antigues) i un reintent amb reinici del worker si el motor no respon.
async function analyzeFenRobust(fen, depth = 15, multiPv = 1, moveTimeMs = 8000, shouldAbort = null) {
    for (let attempt = 0; attempt < 2; attempt++) {
        if (shouldAbort && shouldAbort()) return null;
        if (!stockfish) ensureStockfish();
        if (!stockfish) return null;
        try { stockfish.postMessage('stop'); } catch (e) {}
        let ready = await waitForEngineReady(4000);
        if (!ready) {
            console.warn('[Anàlisi] Motor sense resposta; es reinicia el worker');
            restartStockfishWorker();
            ready = await waitForEngineReady(6000);
            if (!ready) continue;
        }
        const analysis = await analyzePositionEnrichedTimed(stockfish, fen, depth, multiPv, moveTimeMs, moveTimeMs + 6000);
        const best = analysis?.bestMove?.move;
        if (best && uciToSanForFen(fen, best)) return analysis;
        console.warn('[Anàlisi] Jugada invàlida o buida per al fen; reintent', best || '(cap)');
    }
    return null;
}

// ── FASE C — Re-anàlisi profunda per a la ressenya ───────────────────────────
// Driu el motor sobre les posicions clau d'una partida a més profunditat i
// ENRIQUEIX els moveReviews: millor jugada + línia, refutació concreta, i les
// avaluacions abans/després. Així les etiquetes (error/imprecisió) i les línies
// són de màxima fiabilitat, sense alentir el joc en viu (es fa sota demanda).
//
// És additiu i segur: si una anàlisi falla, conserva les dades existents. Driu
// el motor amb analyzeFenRobust, que té el seu propi listener i no interfereix
// amb la màquina d'estats de l'anàlisi en viu; tot i així se serialitza i no
// s'executa mentre hi ha una anàlisi de partida en curs.
//
// NOTA: NO s'auto-executa. Com que escriu a l'historial desat, cal validar-ho
// al navegador abans d'activar-lo automàticament en obrir la ressenya. Exposat
// com a window.deepenEntryAnalysis(entry) per provar-ho manualment.
let deepReviewInProgress = false;
async function deepenEntryAnalysis(entry, opts = {}) {
    if (!entry || !Array.isArray(entry.moveReviews) || !entry.moveReviews.length) return 0;
    if (entry.deepAnalyzed && !opts.force) return 0;
    if (deepReviewInProgress || waitingForBlunderAnalysis) return 0;
    deepReviewInProgress = true;
    const depth = opts.depth || 16;
    // Temps màxim de tota la reanàlisi: en un dispositiu lent (o amb el motor
    // tocat) val més tancar amb el que ja s'ha aprofundit que girar minuts.
    const startedAt = Date.now();
    const deadlineMs = opts.deadlineMs || 120000;
    // L'avaluació torna en perspectiva del bàndol que mou; el mat es codifica ±10000.
    const cpOf = b => !b ? null : (b.evalType === 'mate' ? (b.eval > 0 ? 10000 : -10000) : b.eval);
    let updated = 0;
    try {
        const targets = entry.moveReviews
            .filter(r => r && r.fen && ['inaccuracy', 'mistake', 'blunder'].includes(r.quality))
            // No es gasta motor en FEN inservibles (dades corruptes antigues):
            // una posició que chess.js no pot carregar pot deixar el worker penjat.
            .filter(r => { try { return new Chess(r.fen).moves().length > 0; } catch (e) { return false; } })
            .slice(0, opts.max || 8);
        for (let ti = 0; ti < targets.length; ti++) {
            const r = targets[ti];
            // Progrés per posició PROCESSADA (no per encert): així la barra avança
            // de manera fiable encara que alguna posició se salti.
            if (typeof opts.onProgress === 'function') {
                try { opts.onProgress(ti, targets.length); } catch (e) {}
            }
            if (opts.shouldAbort && opts.shouldAbort()) break;
            if (Date.now() - startedAt > deadlineMs) break; // conserva el que ja s'ha aprofundit
            // ABANS de la jugada: millor jugada, línia i avaluació (perspectiva del jugador).
            const before = await analyzeFenRobust(r.fen, depth, 3, 6000, opts.shouldAbort);
            if (!before || !before.bestMove || !before.bestMove.move) continue;
            const bm = before.bestMove;
            r.bestMove = bm.move;
            r.bestMovePv = bm.pv || [];
            r.bestMoveSan = uciToSan(r.fen, bm.move);
            r.evalBefore = cpOf(bm);
            r.alternatives = (before.alternatives || []).map(a => ({
                move: a.move, moveSan: a.move ? uciToSan(r.fen, a.move) : null,
                eval: cpOf(a), evalType: a.evalType, pv: a.pv || []
            }));
            // MultiPV cru (avaluació sense convertir: el mat conserva la
            // distància i el tipus), per mesurar gaps de forçament amb fidelitat.
            r.multipvBefore = (before.alternatives || []).map(a => ({
                move: a.move, moveSan: a.move ? uciToSan(r.fen, a.move) : null,
                eval: a.eval, evalType: a.evalType, pv: a.pv || []
            }));
            // DESPRÉS de la jugada real: refutació (perspectiva del rival).
            let afterFen = null;
            if (r.playerMove && r.playerMove.length >= 4) {
                try {
                    const g = new Chess(r.fen);
                    const mv = g.move({ from: r.playerMove.slice(0, 2), to: r.playerMove.slice(2, 4), promotion: r.playerMove.length > 4 ? r.playerMove[4] : undefined });
                    if (mv) afterFen = g.fen();
                } catch (e) {}
            }
            if (afterFen) {
                const after = await analyzeFenRobust(afterFen, depth, 1, 6000, opts.shouldAbort);
                if (after && after.bestMove) {
                    r.afterFen = afterFen;
                    r.refutationPv = after.bestMove.pv || [];
                    r.evalAfter = cpOf(after.bestMove);
                }
            }
            // DESPRÉS de la millor jugada: alternatives de RESPOSTA del rival,
            // per saber si la rèplica de la PV era forçada (gap MultiPV) i què
            // valia la posició si hagués jugat el millor (evalAfterBest).
            let evalAfterBest = null;
            let replyAlternatives = null;
            let bestAfterFen = null;
            try {
                const g = new Chess(r.fen);
                const mv = g.move({ from: bm.move.slice(0, 2), to: bm.move.slice(2, 4), promotion: bm.move.length > 4 ? bm.move[4] : undefined });
                if (mv) bestAfterFen = g.fen();
            } catch (e) {}
            if (bestAfterFen && !(opts.shouldAbort && opts.shouldAbort()) && Date.now() - startedAt <= deadlineMs) {
                const afterBest = await analyzeFenRobust(bestAfterFen, depth, 3, 6000, opts.shouldAbort);
                if (afterBest && afterBest.bestMove) {
                    // El rival mou a bestAfterFen: negat = perspectiva del jugador.
                    evalAfterBest = -cpOf(afterBest.bestMove);
                    replyAlternatives = (afterBest.alternatives || []).map(a => ({
                        move: a.move, eval: a.eval, evalType: a.evalType
                    }));
                }
            }
            // Recalcular swing/qualitat amb les avaluacions noves (mateix conveni
            // que el viu: swing = evalBefore + evalAfter, perspectives oposades).
            if (typeof r.evalBefore === 'number' && typeof r.evalAfter === 'number') {
                r.swing = Math.abs(r.evalBefore + r.evalAfter);
                r.quality = classifyMoveQuality(r.swing, r.playerMove, r.bestMove);
            }
            // CAMPS CANÒNICS DE L'ERRADA (noms estables; perspectiva del jugador).
            r.beforeFen = r.fen;
            r.playedMoveUci = (r.playerMove && r.playerMove !== '—') ? r.playerMove : null;
            r.playedMoveSan = (r.playerMoveSan && r.playerMoveSan !== '—') ? r.playerMoveSan : null;
            r.bestMoveUci = bm.move;
            r.bestPv = bm.pv || [];
            r.playedPv = Array.isArray(r.refutationPv) ? r.refutationPv : [];
            r.evalAfterPlayed = typeof r.evalAfter === 'number' ? -r.evalAfter : null;
            r.evalAfterBest = evalAfterBest;
            r.replyAlternatives = replyAlternatives;
            r.cpLoss = (typeof r.evalBefore === 'number' && typeof r.evalAfterPlayed === 'number')
                ? Math.max(0, Math.round(r.evalBefore - r.evalAfterPlayed))
                : (typeof r.swing === 'number' ? Math.round(r.swing) : null);
            // Forçament de la línia: gap de la millor jugada, gap de la resposta
            // del rival, i fets del tauler (única legal, escac, mat) via chess.js.
            try {
                r.forcingInfo = ElTaulerCore.buildPvForcingInfo({
                    fen: r.fen,
                    bestPv: r.bestPv,
                    multipvBefore: r.multipvBefore,
                    replyAlternatives: replyAlternatives,
                    evalBefore: bm.eval,
                    evalBeforeType: bm.evalType,
                    evalAfterBest: (typeof evalAfterBest === 'number') ? evalAfterBest : undefined,
                    board: getPvBoardHelpers()
                });
            } catch (e) { r.forcingInfo = null; }
            r.depth = before.depth || depth;
            r.deep = true;
            updated++;
        }
        if (typeof opts.onProgress === 'function') {
            try { opts.onProgress(targets.length, targets.length); } catch (e) {}
        }
        entry.deepAnalyzed = true;
        // La requalificació pot canviar el desglossament (excel·lents/errors…).
        try { entry.counts = summarizeReview(entry.moveReviews); } catch (e) {}
        // …i, amb ell, el resum per fases que el bessó llegeix de l'índex.
        try { entry.phaseStats = ElTaulerCore.bessoPhaseStatsFromGame(entry); } catch (e) {}
        if (typeof saveStorage === 'function') saveStorage();
    } catch (e) {
        console.warn('[DeepReview] error inesperat', e);
    } finally {
        deepReviewInProgress = false;
    }
    return updated;
}
if (typeof window !== 'undefined') window.deepenEntryAnalysis = deepenEntryAnalysis;

function uciToSan(fen, uciMove) {
    if (typeof Chess === 'undefined') return uciMove;
    const chess = new Chess(fen);
    const move = chess.move({
        from: uciMove.slice(0, 2),
        to: uciMove.slice(2, 4),
        promotion: uciMove.length > 4 ? uciMove[4] : undefined
    });
    return move ? move.san : uciMove;
}

function pvToSan(fen, pvArray) {
    if (typeof Chess === 'undefined') return pvArray;
    const chess = new Chess(fen);
    const sanMoves = [];
    for (const uciMove of pvArray) {
        const move = chess.move({
            from: uciMove.slice(0, 2),
            to: uciMove.slice(2, 4),
            promotion: uciMove.length > 4 ? uciMove[4] : undefined
        });
        sanMoves.push(move ? move.san : uciMove);
        if (!move) break;
    }
    return sanMoves;
}

function createEnrichedMoveReview(
    fen,
    playerMove,
    playerMoveSan,
    analysisBefore,
    analysisAfter,
    moveNumber
) {
    const bestMove = analysisBefore.bestMove;
    const evalBefore = bestMove ? bestMove.eval : null;
    const evalAfter = analysisAfter.bestMove ? analysisAfter.bestMove.eval : null;

    let swing = null;
    if (evalBefore !== null && evalAfter !== null) {
        swing = Math.abs(evalAfter - evalBefore);
    }

    const quality = classifyMoveQuality(swing, playerMove, bestMove?.move);

    return {
        fen,
        moveNumber,
        playerMove,
        playerMoveSan,
        bestMove: bestMove?.move || null,
        evalBefore,
        evalAfter,
        swing,
        quality,
        isCapture: playerMoveSan.includes('x'),
        isCheck: playerMoveSan.includes('+') || playerMoveSan.includes('#'),
        timestamp: Date.now(),
        depth: analysisBefore.depth,
        bestMoveSan: bestMove?.move ? uciToSan(fen, bestMove.move) : null,
        bestMovePv: bestMove?.pv || [],
        bestMovePvSan: bestMove?.pv ? pvToSan(fen, bestMove.pv) : [],
        alternatives: (analysisBefore.alternatives || []).map((alt) => ({
            move: alt.move,
            moveSan: alt.move ? uciToSan(fen, alt.move) : null,
            eval: alt.eval,
            evalType: alt.evalType,
            pv: alt.pv,
            pvSan: alt.pv ? pvToSan(fen, alt.pv) : []
        }))
    };
}

function parseFenPosition(fen) {
    const [board, turn, castling, enPassant] = fen.split(' ');
    const expandedBoard = expandBoard(board);
    const whiteKing = findPiece(expandedBoard, 'K');
    const blackKing = findPiece(expandedBoard, 'k');
    const material = countMaterial(expandedBoard);
    const passedPawns = findPassedPawns(expandedBoard);
    const kingSafety = evaluateKingSafety(expandedBoard, whiteKing, blackKing, castling);

    return {
        turn,
        castling,
        enPassant,
        whiteKing,
        blackKing,
        material,
        passedPawns,
        kingSafety,
        expandedBoard
    };
}

function expandBoard(boardFen) {
    const board = [];
    const rows = boardFen.split('/');

    for (const row of rows) {
        for (const char of row) {
            if (char >= '1' && char <= '8') {
                for (let i = 0; i < Number.parseInt(char, 10); i++) {
                    board.push(null);
                }
            } else {
                board.push(char);
            }
        }
    }

    return board;
}

function findPiece(board, piece) {
    const index = board.indexOf(piece);
    if (index === -1) return null;

    const file = String.fromCharCode(97 + (index % 8));
    const rank = 8 - Math.floor(index / 8);
    return `${file}${rank}`;
}

function findAllPieces(board, piece) {
    const positions = [];
    for (let i = 0; i < board.length; i++) {
        if (board[i] === piece) {
            const file = String.fromCharCode(97 + (i % 8));
            const rank = 8 - Math.floor(i / 8);
            positions.push(`${file}${rank}`);
        }
    }
    return positions;
}

function countMaterial(board) {
    const values = { p: 1, n: 3, b: 3, r: 5, q: 9, k: 0 };
    let white = 0;
    let black = 0;

    const whitePieces = { P: 0, N: 0, B: 0, R: 0, Q: 0 };
    const blackPieces = { p: 0, n: 0, b: 0, r: 0, q: 0 };

    for (const piece of board) {
        if (!piece) continue;

        if (piece === piece.toUpperCase()) {
            white += values[piece.toLowerCase()] || 0;
            if (whitePieces[piece] !== undefined) whitePieces[piece] += 1;
        } else {
            black += values[piece] || 0;
            if (blackPieces[piece] !== undefined) blackPieces[piece] += 1;
        }
    }

    return {
        white,
        black,
        balance: white - black,
        whitePieces,
        blackPieces
    };
}

function findPassedPawns(board) {
    const passed = { white: [], black: [] };

    for (let i = 0; i < 64; i++) {
        const piece = board[i];
        const file = i % 8;
        const rank = Math.floor(i / 8);

        if (piece === 'P') {
            let isPassed = true;
            for (let r = rank - 1; r >= 0 && isPassed; r--) {
                for (let f = Math.max(0, file - 1); f <= Math.min(7, file + 1); f++) {
                    if (board[r * 8 + f] === 'p') isPassed = false;
                }
            }
            if (isPassed && rank <= 5) {
                const square = `${String.fromCharCode(97 + file)}${8 - rank}`;
                passed.white.push(square);
            }
        }

        if (piece === 'p') {
            let isPassed = true;
            for (let r = rank + 1; r < 8 && isPassed; r++) {
                for (let f = Math.max(0, file - 1); f <= Math.min(7, file + 1); f++) {
                    if (board[r * 8 + f] === 'P') isPassed = false;
                }
            }
            if (isPassed && rank >= 2) {
                const square = `${String.fromCharCode(97 + file)}${8 - rank}`;
                passed.black.push(square);
            }
        }
    }

    return passed;
}

function evaluateKingSafety(board, whiteKing, blackKing, castling) {
    const safety = {
        white: { canCastle: false, hasCastled: false, exposed: false },
        black: { canCastle: false, hasCastled: false, exposed: false }
    };

    safety.white.canCastle = castling.includes('K') || castling.includes('Q');
    safety.black.canCastle = castling.includes('k') || castling.includes('q');

    if (whiteKing === 'g1' || whiteKing === 'c1') safety.white.hasCastled = true;
    if (blackKing === 'g8' || blackKing === 'c8') safety.black.hasCastled = true;

    const exposedFiles = ['d', 'e', 'f'];
    if (whiteKing && exposedFiles.includes(whiteKing[0]) && !safety.white.canCastle) {
        safety.white.exposed = true;
    }
    if (blackKing && exposedFiles.includes(blackKing[0]) && !safety.black.canCastle) {
        safety.black.exposed = true;
    }

    return safety;
}

// Construeix la seqüència d'un exercici a partir d'una línia JA verificada, sense
// tocar el motor: la part de tauler la fa ElTaulerCore i aquí només s'hi afegeix
// el context posicional i les amenaces (càlcul local). S'usa quan la línia ja es
// coneix (mat en 1, rebost estàtic del banc, PV desada d'una errada pròpia).
function buildBundleSequenceFromLine(fen, line, opts = {}) {
    if (typeof Chess !== 'function') return null;
    const helpers = ElTaulerCore.createBundleSequenceHelpers(Chess);
    if (!helpers) return null;
    const seq = helpers.buildSequenceFromLine(fen, line, {
        stepMeta: opts.stepMeta || [],
        replyMeta: opts.replyMeta || [],
        maxPlayerMoves: opts.maxPlayerMoves || 3
    });
    if (!seq) return null;
    // Context posicional i amenaces de cada pas (el fen de cada pas el fixa el core).
    for (let i = 1; i <= seq.totalSteps; i++) {
        const step = seq['step' + i];
        if (!step) continue;
        const pv = (step.playerMovePv && step.playerMovePv.length) ? step.playerMovePv : [step.playerMove];
        if (!step.position) { try { step.position = parseFenPosition(step.fen); } catch (e) { step.position = null; } }
        if (!step.threats) {
            try { step.threats = analyzePvThreats(step.fen, pv); }
            catch (e) { step.threats = { threats: [], themes: [], immediateThreats: [] }; }
        }
    }
    return seq;
}

async function prepareBundleSequence(fen, opts = {}) {
    // silent: no mostra alertes (preparació en segon pla)
    // shouldAbort: permet interrompre la preparació entre anàlisis
    // fast: elimina pauses artificials entre cerques. Les cerques robustes ja fan
    // handshake UCI (`isready`) i validen que la resposta sigui legal per al FEN,
    // així no cal pagar gairebé 1,1 s fixos abans de cada exercici.
    const silent = !!opts.silent;
    const fast = opts.fast !== false;
    const shouldAbort = () => !!(opts.shouldAbort && opts.shouldAbort());
    // Validació inicial més robusta
    if (!stockfish) {
        console.error('[Bundle] Stockfish no existeix');
        ensureStockfish();
        await new Promise(resolve => setTimeout(resolve, 500));
    }
    
    if (!stockfish) {
        console.error('[Bundle] No es pot inicialitzar Stockfish');
        return null;
    }
    
    // Esperar que Stockfish estigui llest
    let waitCount = 0;
    while (!stockfishReady && waitCount < 20) {
        await new Promise(resolve => setTimeout(resolve, 100));
        waitCount++;
    }
    
    if (!stockfishReady) {
        console.error('[Bundle] Stockfish no està llest després d\'esperar');
        return null;
    }
    
    try {
        // Neteja inicial més agressiva
        stockfish.postMessage('stop');
        stockfish.postMessage('setoption name MultiPV value 1');
        if (!fast) await new Promise(resolve => setTimeout(resolve, 300));
        
        console.log('[Bundle] Iniciant preparació seqüència per FEN:', fen);

        if (shouldAbort()) { console.log('[Bundle] Preparació interrompuda abans del pas 1'); return null; }
        // 1. Analitzar posició inicial (Pas 1)
        console.log('[Bundle] Pas 1: Analitzant posició inicial...');
        const step1Analysis = await analyzeFenRobust(fen, 15, 2, 8000, shouldAbort);

        if (shouldAbort()) { console.log('[Bundle] Preparació interrompuda després del pas 1'); return null; }
        if (!step1Analysis || !step1Analysis.bestMove || !step1Analysis.bestMove.move) {
            console.error('[Bundle] Pas 1 fallit: no hi ha bestMove', step1Analysis);
            if (!silent) alert('Error: No es pot analitzar la posició inicial. Torna-ho a provar.');
            return null;
        }
        
        const playerMove1 = step1Analysis.bestMove.move;
        console.log('[Bundle] Pas 1 - Millor jugada:', playerMove1);
        
        const playerMove1San = uciToSan(fen, playerMove1);
        const playerMove1Pv = step1Analysis.bestMove.pv || [];
        const playerMove1Eval = step1Analysis.bestMove.eval || 0;
        
        // 2. Aplicar la millor jugada del jugador
        const tempGame1 = new Chess(fen);
        const move1 = tempGame1.move({
            from: playerMove1.slice(0, 2),
            to: playerMove1.slice(2, 4),
            promotion: playerMove1.length > 4 ? playerMove1[4] : undefined
        });
        
        if (!move1) {
            console.error('[Bundle] No es pot aplicar jugada 1:', playerMove1);
            if (!silent) alert('Error: Jugada no vàlida. Prova un altre error.');
            return null;
        }
        
        const afterPlayerFen = tempGame1.fen();
        console.log('[Bundle] Després jugada 1, FEN:', afterPlayerFen);

        // La millor jugada ja acaba la partida (mat en 1, ofegat…): no hi ha cap
        // resposta del rival a calcular i l'exercici és d'UN sol pas. Sense això
        // les posicions de mat en 1 del banc no es podien preparar mai i la
        // secció es quedava sense exercici.
        if (tempGame1.game_over()) {
            console.log('[Bundle] La millor jugada acaba la partida: exercici d\'un sol pas');
            return buildBundleSequenceFromLine(fen, [playerMove1], {
                stepMeta: [{
                    playerMovePv: playerMove1Pv,
                    evalBefore: playerMove1Eval,
                    alternatives: step1Analysis.alternatives || []
                }]
            });
        }

        if (!fast) await new Promise(resolve => setTimeout(resolve, 400));

        if (shouldAbort()) { console.log('[Bundle] Preparació interrompuda abans del pas 2'); return null; }
        // 3. Calcular millor resposta de l'oponent
        console.log('[Bundle] Pas 2: Analitzant resposta oponent...');
        const opponentAnalysis = await analyzeFenRobust(afterPlayerFen, 15, 1, 8000, shouldAbort);

        if (shouldAbort()) { console.log('[Bundle] Preparació interrompuda després del pas 2'); return null; }
        if (!opponentAnalysis || !opponentAnalysis.bestMove || !opponentAnalysis.bestMove.move) {
            console.error('[Bundle] Pas 2 fallit: no hi ha bestMove oponent', opponentAnalysis);
            if (!silent) alert('Error: No es pot calcular la resposta. Prova un altre error.');
            return null;
        }
        
        const opponentMove = opponentAnalysis.bestMove.move;
        console.log('[Bundle] Pas 2 - Resposta oponent:', opponentMove);
        
        const opponentMoveSan = uciToSan(afterPlayerFen, opponentMove);
        const opponentMoveEval = opponentAnalysis.bestMove.eval || 0;
        
        // 4. Aplicar resposta de l'oponent
        const tempGame2 = new Chess(afterPlayerFen);
        const move2 = tempGame2.move({
            from: opponentMove.slice(0, 2),
            to: opponentMove.slice(2, 4),
            promotion: opponentMove.length > 4 ? opponentMove[4] : undefined
        });
        
        if (!move2) {
            console.error('[Bundle] No es pot aplicar jugada oponent:', opponentMove);
            if (!silent) alert('Error: Resposta no vàlida. Prova un altre error.');
            return null;
        }
        
        const afterOpponentFen = tempGame2.fen();
        console.log('[Bundle] Després resposta oponent, FEN:', afterOpponentFen);

        // La rèplica del rival acaba la partida: tampoc no hi ha segon pas.
        if (tempGame2.game_over()) {
            console.log('[Bundle] La resposta del rival acaba la partida: exercici d\'un sol pas');
            return buildBundleSequenceFromLine(fen, [playerMove1], {
                stepMeta: [{
                    playerMovePv: playerMove1Pv,
                    evalBefore: playerMove1Eval,
                    alternatives: step1Analysis.alternatives || []
                }]
            });
        }

        if (!fast) await new Promise(resolve => setTimeout(resolve, 400));

        if (shouldAbort()) { console.log('[Bundle] Preparació interrompuda abans del pas 3'); return null; }
        // 5. Calcular millor segona jugada del jugador (Pas 3)
        console.log('[Bundle] Pas 3: Analitzant segona jugada jugador...');
        const step2Analysis = await analyzeFenRobust(afterOpponentFen, 15, 2, 8000, shouldAbort);

        if (shouldAbort()) { console.log('[Bundle] Preparació interrompuda després del pas 3'); return null; }
        if (!step2Analysis || !step2Analysis.bestMove || !step2Analysis.bestMove.move) {
            console.error('[Bundle] Pas 3 fallit: no hi ha bestMove pas 2', step2Analysis);
            if (!silent) alert('Error: No es pot calcular la segona jugada. Prova un altre error.');
            return null;
        }
        
        const playerMove2 = step2Analysis.bestMove.move;
        console.log('[Bundle] Pas 3 - Segona jugada:', playerMove2);
        
        const playerMove2San = uciToSan(afterOpponentFen, playerMove2);
        const playerMove2Pv = step2Analysis.bestMove.pv || [];
        const playerMove2Eval = step2Analysis.bestMove.eval || 0;
        
        // 6. Analitzar context posicional de cada pas
        const positionStep1 = parseFenPosition(fen);
        const positionStep2 = parseFenPosition(afterOpponentFen);
        const threatsStep1 = analyzePvThreats(fen, playerMove1Pv);
        const threatsStep2 = analyzePvThreats(afterOpponentFen, playerMove2Pv);
        
        console.log('[Bundle] Seqüència completa preparada:', 
            [playerMove1San, opponentMoveSan, playerMove2San]);
        
        // 7. Retornar seqüència completa i fixa
        return {
            initialFen: fen,
            
            step1: {
                fen: fen,
                playerMove: playerMove1,
                playerMoveSan: playerMove1San,
                playerMovePv: playerMove1Pv,
                evalBefore: playerMove1Eval,
                alternatives: step1Analysis.alternatives || [],
                position: positionStep1,
                threats: threatsStep1
            },
            
            opponentMove: {
                fen: afterPlayerFen,
                move: opponentMove,
                moveSan: opponentMoveSan,
                eval: opponentMoveEval
            },
            
            step2: {
                fen: afterOpponentFen,
                playerMove: playerMove2,
                playerMoveSan: playerMove2San,
                playerMovePv: playerMove2Pv,
                evalBefore: playerMove2Eval,
                alternatives: step2Analysis.alternatives || [],
                position: positionStep2,
                threats: threatsStep2
            },
            
            fullSequence: [playerMove1, opponentMove, playerMove2],
            fullSequenceSan: [playerMove1San, opponentMoveSan, playerMove2San]
        };
        
    } catch (error) {
        console.error('[Bundle] Error preparant seqüència:', error);
        if (!silent) showToast('Error inesperat preparant l\'exercici. Torna-ho a provar.', 'error');
        return null;
    }
}

// ============================================================================
// EXERCICI "MILLOR LÍNIA" DE 3 JUGADES (Lliurament 1 — generador i origen)
// ============================================================================
// Genera una línia FIXA i verificada de N jugades del jugador (per defecte 3),
// on a CADA pas del jugador la millor jugada supera clarament la segona (gap),
// de manera que la línia és "neta" i la pista pot coincidir sempre amb la
// solució. No exigeix mat. La part interactiva (playback/pista) és el
// Lliurament 2; aquí només es prepara i es verifica la seqüència.

// Verifica i construeix la línia a partir d'un FEN. Retorna l'estructura de
// l'exercici o null si la posició no compleix el filtre de qualitat.
async function prepareBestLineExercise(fen, opts = {}) {
    const playerMoves = opts.playerMoves || 3;
    const gapCp = typeof opts.gapCp === 'number' ? opts.gapCp : 150;
    const depth = opts.depth || 15;
    const shouldAbort = () => !!(opts.shouldAbort && opts.shouldAbort());

    if (!stockfish) { ensureStockfish(); await new Promise(r => setTimeout(r, 300)); }
    let waitCount = 0;
    while (!stockfishReady && waitCount < 20) { await new Promise(r => setTimeout(r, 100)); waitCount++; }
    if (!stockfishReady) return null;

    try {
        try { stockfish.postMessage('stop'); } catch (e) {}
        const steps = [];          // metadades per pas (gap, eval…)
        const playerStepData = [];  // objectes compatibles amb el playback (step1/2/3)
        const opponentMoves = [];   // rèpliques del rival (opponentMove/opponentMove2)
        const fullSequence = [];
        const fullSequenceSan = [];
        let curFen = fen;
        let endsInMate = false;

        for (let i = 0; i < playerMoves; i++) {
            if (shouldAbort()) return null;
            // Pas del jugador: MultiPV 3 per poder mesurar el gap amb la 2a opció.
            const a = await analyzeFenRobust(curFen, depth, 3, 8000, shouldAbort);
            if (!a || !a.bestMove || !a.bestMove.move) return null;
            // gapCp>0: exigeix que la millor superi la 2a per un marge. gapCp<=0:
            // mode "3 millors jugades fixes" sense filtre (sempre accepta la millor).
            if (gapCp > 0 && !ElTaulerCore.bestLineStepQualifies(a.alternatives, gapCp)) return null;

            const pMove = a.bestMove.move;
            const pSan = uciToSan(curFen, pMove);
            const g = new Chess(curFen);
            const mv = g.move({ from: pMove.slice(0, 2), to: pMove.slice(2, 4), promotion: pMove.length > 4 ? pMove[4] : undefined });
            if (!mv) return null;

            const stepFen = curFen;
            playerStepData.push({
                fen: stepFen,
                playerMove: pMove,
                playerMoveSan: pSan,
                playerMovePv: a.bestMove.pv || [],
                evalBefore: a.bestMove.eval,
                alternatives: a.alternatives || [],
                position: (() => { try { return parseFenPosition(stepFen); } catch (e) { return null; } })(),
                threats: (() => { try { return analyzePvThreats(stepFen, a.bestMove.pv || []); } catch (e) { return null; } })()
            });
            steps.push({ fen: stepFen, playerMove: pMove, playerMoveSan: pSan, evalBefore: a.bestMove.eval, evalType: a.bestMove.evalType, gap: ElTaulerCore.bestLineGapCp(a.alternatives) });
            fullSequence.push(pMove);
            fullSequenceSan.push(pSan);
            curFen = g.fen();
            if (g.game_over()) { endsInMate = g.in_checkmate(); break; }

            // Rèplica del rival (millor jugada) si encara queden jugades del jugador.
            if (i < playerMoves - 1) {
                if (shouldAbort()) return null;
                const o = await analyzeFenRobust(curFen, depth, 1, 8000, shouldAbort);
                if (!o || !o.bestMove || !o.bestMove.move) return null;
                const oMove = o.bestMove.move;
                const oSan = uciToSan(curFen, oMove);
                const g2 = new Chess(curFen);
                const mv2 = g2.move({ from: oMove.slice(0, 2), to: oMove.slice(2, 4), promotion: oMove.length > 4 ? oMove[4] : undefined });
                if (!mv2) return null;
                opponentMoves.push({ fen: curFen, move: oMove, moveSan: oSan, eval: o.bestMove.eval });
                fullSequence.push(oMove);
                fullSequenceSan.push(oSan);
                curFen = g2.fen();
                if (g2.game_over()) { endsInMate = g2.in_checkmate(); break; }
            }
        }

        if (!playerStepData.length) return null;
        // Estructura compatible amb el playback de bundle (step1/step2/step3,
        // opponentMove/opponentMove2, totalSteps) + metadades pròpies.
        const ex = {
            initialFen: fen,
            totalSteps: playerStepData.length,
            playerMoves: playerStepData.length,
            fullSequence,
            fullSequenceSan,
            endsInMate,
            gapCp,
            source: 'bestline',
            steps
        };
        playerStepData.forEach((s, idx) => { ex['step' + (idx + 1)] = s; });
        if (opponentMoves[0]) ex.opponentMove = opponentMoves[0];
        if (opponentMoves[1]) ex.opponentMove2 = opponentMoves[1];
        return ex;
    } catch (e) {
        console.warn('[BestLine] error preparant exercici', e);
        return null;
    }
}

// Recull posicions candidates NOMÉS del banc curat de posicions tàctiques (i el
// banc de reptes diaris com a reserva). No es parteix de cap "suposada errada"
// del jugador: el jeroglífic de 3 passos surt de posicions netes.
function collectBestLineCandidateFens(maxN = 40) {
    const out = [];
    const seen = new Set();
    const add = (fen) => { if (fen && typeof fen === 'string' && !seen.has(fen)) { seen.add(fen); out.push(fen); } };

    const bank = (typeof TACTICS_BANK !== 'undefined' && TACTICS_BANK.length)
        ? TACTICS_BANK.slice()
        : [];
    bank.forEach(add);
    DAILY_PUZZLE_BANK.forEach(p => add(p && p.fen));

    // Barreja per donar varietat (no sortir sempre la mateixa).
    for (let i = out.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [out[i], out[j]] = [out[j], out[i]];
    }
    return out.slice(0, maxN);
}

// Banc artificial desactivat: els jeroglífics han de néixer de moments clau
// de les partides jugades, no de finals prefabricats KQ/KR contra rei.
const BESTLINE_MATE_BANK = [];
function bestLineMateCandidates() {
    // Els jeroglífics ja no surten de bancs artificials (KQ/KR vs rei, etc.).
    // Només es generen des de moments clau de partides jugades.
    return [];
}

// Troba un mat en 3 verificat (en forma de seqüència de bundle). Retorna-la o
// null. Accepta excludeFens per donar varietat al rebost.
function bestLineFenLegal(fen) { try { return !!new Chess(fen); } catch (e) { return false; } }
async function generateBestLineExercise(opts = {}) {
    const maxTries = opts.maxTries || 6;
    const shouldAbort = () => !!(opts.shouldAbort && opts.shouldAbort());
    const excludeFens = opts.excludeFens instanceof Set ? opts.excludeFens : new Set(opts.excludeFens || []);
    const candidates = bestLineMateCandidates().filter(f => !excludeFens.has(f) && bestLineFenLegal(f));

    let tried = 0;
    for (const fen of candidates) {
        if (tried >= maxTries || shouldAbort()) break;
        tried++;
        const seq = await prepareMateSequence(fen);
        if (seq) {
            seq.source = 'bestline';
            seq.endsInMate = true;
            seq.totalSteps = 3;
            seq.gapUsed = 'mat-en-3';
            seq.triedCandidates = tried;
            return seq;
        }
    }
    return null;
}

// ── Rebost artificial desactivat: ja no alimenta jeroglífics ────────────────
const BESTLINE_POOL_TARGET = 3;
let bestLinePool = [];
let bestLinePrepInFlight = false;
let personalHieroglyphicPool = [];
// Mantenim sempre que es pugui un rebost de 3 jeroglífics nous validats: en
// consumir-ne un, se'n prepara un altre en segon pla fins a tornar a omplir-lo.
const PERSONAL_HIERO_POOL_TARGET = 3;
let personalHieroglyphicPrepInFlight = false;
let personalHieroglyphicLastAttempt = 0;

// No omplim cap rebost de posicions prefabricades.
async function ensureBestLinePoolTick() {
    // Desactivat: no pre-generem jeroglífics de bancs curats/artificials.
    // El botó Jeroglífic passa pel flux personal validat amb Stockfish.
    return false;
}

// No hi ha rebost artificial: sempre retorna null.
function takeBestLineFromPool() {
    bestLinePool = [];
    refreshJeroglificButton();
    return null;
}

// El botó "Jeroglífic" queda gris/inactiu fins que hi ha moments clau
// de partides pròpies que es poden validar abans de jugar-los.
function jeroglificsReady() {
    // La cua sincronitzada (eltauler_hieroglyphics_state) és la font principal; el
    // rebost antic en memòria només compta com a reserva. La generació la porta
    // hgTick (un sol camí, amb bloqueig entre dispositius i objectius per aparell).
    const queueReady = (typeof hgNewCount === 'function') ? hgNewCount() > 0 : false;
    return queueReady || (Array.isArray(personalHieroglyphicPool) && personalHieroglyphicPool.length > 0);
}
function refreshJeroglificButton() {
    const btn = document.getElementById('btn-bestline');
    if (!btn) return;
    const ready = jeroglificsReady();
    const hasRetry = retryableHieroglyphicHistory().length > 0;
    // La secció de jeroglífics sempre està disponible: el botó no es bloqueja mai.
    btn.disabled = false;
    btn.classList.remove('btn-disabled');
    const desc = document.getElementById('bestline-info');
    if (desc) desc.textContent = ready
        ? 'Desxifra un moment clau de les teves partides'
        : (hasRetry ? 'Refés un jeroglífic pendent' : 'Preparant jeroglífic personal…');
}

// ── Magatzem de jeroglífics (puzzles tàctics) — Lliurament 1 ────────────────
// Model ChessPuzzle (JS): { id, fen, sideToMove, solutionUci[], solutionSan[],
// engineRepliesUci[], engineRepliesSan[], fullLineUci[], fullLineSan[], theme[],
// difficulty, ratingEstimate, sourceGameId?, sourcePgn?, moveNumber?, evalBefore?,
// evalAfter?, bestMoveMargin?, finalEval?, endsInMate?, createdAt, status }.

function genPuzzleId() {
    return 'pz_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
}

function getPuzzles(status) {
    if (!status) return puzzles.slice();
    return puzzles.filter(p => p && p.status === status);
}

// ── Classificador de FINAL TÀCTIC ───────────────────────────────────────────
// Embolcall prim sobre el classificador pur de core.js (necessita chess.js).
// Un jeroglífic només s'aprova si acaba amb una imatge tàctica clara: mat,
// escac (amb avantatge), forquilla, clavada, descoberta, promoció o guany de
// dama/torre.
const HIERO_ALLOWED_FINAL_MOTIFS = ElTaulerCore.HIERO_ALLOWED_FINAL_MOTIFS;
const HIERO_FINAL_MOTIF_LABELS = ElTaulerCore.HIERO_FINAL_MOTIF_LABELS;
let _hieroMotifHelpers = null;
function hieroMotifHelpers() {
    if (_hieroMotifHelpers) return _hieroMotifHelpers;
    if (typeof Chess === 'undefined') return null;
    _hieroMotifHelpers = ElTaulerCore.createHieroglyphicMotifHelpers(Chess);
    return _hieroMotifHelpers;
}
function classifyPuzzleFinalMotif(initialFen, fullLineUci, opts = {}) {
    const H = hieroMotifHelpers();
    if (!H) return { motif: 'none', motifs: [], isCheck: false, isMate: false, finalFen: null, finalMoveUci: null, finalMoveSan: null, confidence: 'low', reason: 'Sense motor d’escacs disponible.' };
    return H.classifyPuzzleFinalMotif(initialFen, fullLineUci, opts);
}
// Construeix la línia completa UCI (jugador + rèpliques entremig) d'un puzzle a
// partir de solutionUci/engineRepliesUci si no en porta ja de feta.
function puzzleFullLineUci(p) {
    if (p && Array.isArray(p.fullLineUci) && p.fullLineUci.length) return p.fullLineUci.slice();
    const sol = (p && Array.isArray(p.solutionUci)) ? p.solutionUci : (p && Array.isArray(p.solutionMoves) ? p.solutionMoves : []);
    const rep = (p && Array.isArray(p.engineRepliesUci)) ? p.engineRepliesUci : (p && Array.isArray(p.replyMoves) ? p.replyMoves : []);
    const line = [];
    for (let i = 0; i < sol.length; i++) {
        line.push(sol[i]);
        if (rep[i] && i < sol.length - 1) line.push(rep[i]);
    }
    return line;
}
// Calcula el motiu de final i el desa dins del puzzle (finalMotif, finalMotifs,
// finalMotifLabel, finalMotifReason, finalMotifConfidence). Retorna motifInfo.
function attachFinalMotif(p, opts = {}) {
    if (!p || !p.fen) return null;
    const line = puzzleFullLineUci(p);
    const info = classifyPuzzleFinalMotif(p.fen, line, Object.assign({
        finalEval: typeof p.finalEval === 'number' ? p.finalEval : undefined,
        marginOk: p.endsInMate || p.bestMoveMargin === Infinity || (typeof p.bestMoveMargin === 'number' && p.bestMoveMargin >= 150)
    }, opts));
    p.finalMotif = info.motif;
    p.finalMotifs = info.motifs;
    p.finalMotifLabel = HIERO_FINAL_MOTIF_LABELS[info.motif] || null;
    p.finalMotifReason = info.reason;
    p.finalMotifConfidence = info.confidence;
    return info;
}
if (typeof window !== 'undefined') {
    window.classifyPuzzleFinalMotif = classifyPuzzleFinalMotif;
    window.attachFinalMotif = attachFinalMotif;
}

// Desa un puzzle: dedup per FEN, completa dificultat/rating/explicació i
// AUTO-APROVA si compleix els criteris (si no, queda 'rejected'). Retorna el
// puzzle desat o null si era duplicat / dades incompletes.
function savePuzzleDraft(raw) {
    if (!raw || !raw.fen || !Array.isArray(raw.solutionUci) || raw.solutionUci.length !== 3) return null;
    if (ElTaulerCore.puzzleIsDuplicateFen(puzzles, raw.fen)) return null; // no duplicats per FEN

    const p = Object.assign({
        id: genPuzzleId(),
        theme: [],
        engineRepliesUci: [],
        engineRepliesSan: [],
        solutionSan: [],
        fullLineUci: [],
        fullLineSan: [],
        createdAt: Date.now(),
        status: 'draft'
    }, raw);

    p.sideToMove = p.sideToMove || (String(p.fen).split(' ')[1] === 'b' ? 'b' : 'w');
    p.difficulty = ElTaulerCore.puzzleDifficulty(p);
    p.ratingEstimate = ElTaulerCore.puzzleRatingEstimate(p);
    p.explanation = ElTaulerCore.puzzleExplanation(p);
    p.origin = p.origin || 'game_real';
    // Classifica el final tàctic i el desa dins del puzzle.
    try { attachFinalMotif(p); } catch (e) { p.finalMotif = p.finalMotif || 'none'; }
    // Auto-aprovació: a més dels criteris de qualitat (gap ≥150 o mat, final
    // decisiu, 3 jugades) cal un FINAL TÀCTIC permès amb confiança no baixa.
    p.status = ElTaulerCore.hieroglyphicMeetsFinalMotifCriteria(p, { requiredFinalMotifs: HIERO_ALLOWED_FINAL_MOTIFS }) ? 'approved' : 'rejected';

    puzzles.push(p);
    if (puzzles.length > 500) puzzles = puzzles.slice(-500);
    try { saveStorage(); } catch (e) {}
    if (p.status === 'approved') refreshJeroglificButton();
    return p;
}

if (typeof window !== 'undefined') {
    window.getPuzzles = getPuzzles;
    window.savePuzzleDraft = savePuzzleDraft;
}

// Helper de proves: genera un exercici i el mostra a la consola.
// Ús: a la consola del navegador, `await testBestLineExercise()`.
async function testBestLineExercise(opts = {}) {
    console.log('[BestLine] Generador de banc desactivat: usa moments clau de partides.');
    const ex = await generateBestLineExercise(opts);
    if (!ex) { console.warn('[BestLine] Cap jeroglífic artificial: banc desactivat.'); return null; }
    console.log('[BestLine] Jeroglífic trobat:', {
        initialFen: ex.initialFen,
        jugadesJugador: ex.totalSteps,
        liniaSAN: (ex.fullSequenceSan || []).join(' '),
        candidatsProvats: ex.triedCandidates
    });
    return ex;
}
if (typeof window !== 'undefined') {
    window.prepareBestLineExercise = prepareBestLineExercise;
    window.generateBestLineExercise = generateBestLineExercise;
    window.testBestLineExercise = testBestLineExercise;
}

function analyzePvThreats(fen, pv) {
    if (!pv || pv.length === 0) {
        return { threats: [], themes: [], immediateThreats: [] };
    }

    const threats = [];
    const themes = new Set();
    const immediateThreats = [];

    for (let i = 0; i < Math.min(pv.length, 6); i++) {
        const move = pv[i];
        const moveInfo = parseUciMove(move);

        if (i === 0 && isLikelyCapture(fen, move)) {
            immediateThreats.push({
                type: 'capture',
                move,
                description: `Captura a ${moveInfo.to}`
            });
            themes.add('material');
        }

        if (moveInfo.promotion) {
            threats.push({
                type: 'promotion',
                move,
                piece: moveInfo.promotion,
                ply: i + 1
            });
            themes.add('promotion');
        }
    }

    const forkPattern = detectForkPattern(pv);
    if (forkPattern) {
        themes.add('fork');
        threats.push(forkPattern);
    }

    const checkCount = countChecksInPv(fen, pv);
    if (checkCount >= 2) {
        themes.add('king_attack');
        threats.push({
            type: 'king_attack',
            checks: checkCount,
            description: 'Atac persistent al rei'
        });
    }

    return {
        threats,
        themes: Array.from(themes),
        immediateThreats
    };
}

function parseUciMove(uciMove) {
    return {
        from: uciMove.slice(0, 2),
        to: uciMove.slice(2, 4),
        promotion: uciMove.length > 4 ? uciMove[4] : null
    };
}

function isLikelyCapture(fen, uciMove) {
    const board = expandBoard(fen.split(' ')[0]);
    const to = parseUciMove(uciMove).to;
    const toIndex = squareToIndex(to);
    return board[toIndex] !== null;
}

function squareToIndex(square) {
    const file = square.charCodeAt(0) - 97;
    const rank = Number.parseInt(square[1], 10);
    return (8 - rank) * 8 + file;
}

function detectForkPattern(pv) {
    if (pv.length < 3) return null;

    const move1 = pv[0];
    const move3 = pv[2];

    if (move1 && move3 && move1.slice(2, 4) === move3.slice(0, 2)) {
        return {
            type: 'fork',
            knightMove: move1,
            capture: move3,
            description: `Possible forquilla: ${move1} seguida de ${move3}`
        };
    }

    return null;
}

function countChecksInPv(fen, pv) {
    if (typeof Chess === 'undefined') return 0;
    const chess = new Chess(fen);
    let checks = 0;

    for (const uciMove of pv) {
        const move = chess.move({
            from: uciMove.slice(0, 2),
            to: uciMove.slice(2, 4),
            promotion: uciMove.length > 4 ? uciMove[4] : undefined
        });
        if (!move) break;
        if (move.san && move.san.includes('+')) checks += 1;
    }

    return checks;
}

function generateHieroglyphics(moveReview, positionInfo, pvAnalysis) {
    const result = {
        moveSymbol: '',
        positionSymbol: '',
        themeSymbols: [],
        explanations: []
    };

    result.moveSymbol = getMoveQualitySymbol(moveReview);
    result.positionSymbol = getPositionEvalSymbol(moveReview.evalAfter);

    if (pvAnalysis.themes.includes('king_attack')) {
        result.themeSymbols.push('→');
        result.explanations.push('Atac directe al rei');
    }

    if (pvAnalysis.immediateThreats.length > 0) {
        result.themeSymbols.push('↑');
        result.explanations.push('Iniciativa amb amenaces');
    }

    if (pvAnalysis.threats.length > 0) {
        result.themeSymbols.push('Δ');
        const threat = pvAnalysis.threats[0];
        result.explanations.push(`Amenaça: ${threat.description || threat.type}`);
    }

    if (pvAnalysis.themes.includes('promotion')) {
        result.themeSymbols.push('⇑');
        result.explanations.push('Amenaça de promoció');
    }

    if (pvAnalysis.themes.includes('fork')) {
        result.themeSymbols.push('⑂');
        result.explanations.push('Tema de forquilla');
    }

    if (positionInfo.material.balance < -2 && moveReview.evalAfter > 0) {
        result.themeSymbols.push('⇆');
        result.explanations.push('Compensació per material');
    }

    if (Math.abs((moveReview.evalBefore || 0) - (moveReview.evalAfter || 0)) > 200 &&
        moveReview.quality === 'inaccuracy') {
        result.themeSymbols.push('⊕');
        result.explanations.push('Posició complicada');
    }

    const turn = positionInfo.turn;
    const enemySafety = turn === 'w' ? positionInfo.kingSafety.black : positionInfo.kingSafety.white;
    if (enemySafety.exposed) {
        result.themeSymbols.push('⊙');
        result.explanations.push('Rei enemic exposat');
    }

    return result;
}

function getMoveQualitySymbol(moveReview) {
    const { swing, quality, playerMove, bestMove } = moveReview;

    if (playerMove && bestMove && playerMove === bestMove) return '!!';
    if (swing === null || swing === undefined) return '';

    if (swing <= 10) return '!';
    if (swing <= 25) return '';
    if (swing <= 50) return '!?';
    if (swing <= 100) return '?!';
    if (swing <= 300) return '?';
    if (quality === 'blunder') return '??';
    return '';
}

function getPositionEvalSymbol(evalCp) {
    if (evalCp === null || evalCp === undefined) return '∞';

    const abs = Math.abs(evalCp);
    const sign = evalCp >= 0 ? 'w' : 'b';

    if (abs <= 25) return '=';
    if (abs <= 50) return sign === 'w' ? '⩲' : '⩱';
    if (abs <= 150) return sign === 'w' ? '±' : '∓';
    if (abs <= 500) return sign === 'w' ? '+-' : '-+';
    return sign === 'w' ? '+−' : '−+';
}

function generateCompleteAnalysis(moveReview) {
    const positionInfo = parseFenPosition(moveReview.fen);
    const pvAnalysis = analyzePvThreats(moveReview.fen, moveReview.bestMovePv || []);
    const hieroglyphics = generateHieroglyphics(moveReview, positionInfo, pvAnalysis);

    const llmContext = {
        position: moveReview.fen,
        played: moveReview.playerMoveSan,
        best: moveReview.bestMoveSan || moveReview.bestMove,
        bestLine: moveReview.bestMovePv,
        evalSwing: moveReview.swing,
        materialBalance: positionInfo.material.balance,
        whiteKingSafe: !positionInfo.kingSafety.white.exposed,
        blackKingSafe: !positionInfo.kingSafety.black.exposed,
        passedPawns: positionInfo.passedPawns,
        threats: pvAnalysis.threats,
        themes: pvAnalysis.themes,
        symbols: hieroglyphics
    };

    return {
        moveReview,
        positionInfo,
        pvAnalysis,
        hieroglyphics,
        llmContext
    };
}

function generateLlmPrompt(analysis) {
    const { moveReview, hieroglyphics, llmContext } = analysis;

    return `Analitza aquesta errada d'escacs i genera una màxima didàctica:

POSICIÓ (FEN): ${moveReview.fen}
JUGAT: ${moveReview.playerMoveSan} ${hieroglyphics.moveSymbol}
MILLOR: ${llmContext.best}
LÍNIA CORRECTA: ${llmContext.bestLine?.join(' ') || 'No disponible'}
PÈRDUA: ${moveReview.swing} centipeons

CONTEXT POSICIONAL:
- Balanç material: ${llmContext.materialBalance > 0 ? '+' : ''}${llmContext.materialBalance}
- Rei blanc segur: ${llmContext.whiteKingSafe ? 'Sí' : 'No'}
- Rei negre segur: ${llmContext.blackKingSafe ? 'Sí' : 'No'}
- Peons passats blancs: ${llmContext.passedPawns.white.join(', ') || 'Cap'}
- Peons passats negres: ${llmContext.passedPawns.black.join(', ') || 'Cap'}

TEMES DETECTATS: ${llmContext.themes.join(', ') || 'Cap'}
AMENACES: ${llmContext.threats.map((t) => t.description || t.type).join('; ') || 'Cap'}

SÍMBOLS: ${hieroglyphics.moveSymbol} ${hieroglyphics.positionSymbol} ${hieroglyphics.themeSymbols.join(' ')}

Genera:
1. Una màxima d'escacs (1 frase memorable)
2. Explicació breu de per què la jugada és un error
3. Explicació de per què la línia correcta és millor`;
}

function registerMoveReview(swing, analysisData = {}) {
    if (blunderMode) return;
    // Passem la jugada feta i la millor perquè, si coincideixen, es classifiqui
    // com a 'excel' (vas jugar el millor) i no com a error per un swing fantasma
    // —típic en posicions guanyades on l'anàlisi posterior (poc profunda) baixa
    // l'avaluació respecte a l'anàlisi prèvia—.
    const quality = classifyMoveQuality(Math.abs(swing), lastHumanMoveUci, analysisData.bestMove);
    const history = game.history({ verbose: true });
    const lastMove = history[history.length - 1];
    
    // Intentar convertir bestMove UCI a SAN
    let bestMoveSan = null;
    if (analysisData.bestMove && analysisData.fen) {
        try {
            const tempGame = new Chess(analysisData.fen);
            const uci = analysisData.bestMove;
            const moveObj = tempGame.move({
                from: uci.slice(0, 2),
                to: uci.slice(2, 4),
                promotion: uci.length > 4 ? uci[4] : undefined
            });
            if (moveObj) bestMoveSan = moveObj.san;
        } catch (e) {}
    }
    
    const beforeFen = analysisData.fen || lastPosition || null;
    // Convenció de perspectives: evalBefore és del JUGADOR (posició de decisió,
    // mou ell) i evalAfter és del RIVAL (posició després de la jugada feta).
    // Les còpies canòniques (evalAfterPlayed, cpLoss) queden totes en
    // perspectiva del jugador, que és com les llegeix la ressenya.
    const evalBeforeNum = typeof analysisData.evalBefore === 'number' ? analysisData.evalBefore : null;
    const evalAfterNum = typeof analysisData.evalAfter === 'number' ? analysisData.evalAfter : null;
    const evalAfterPlayed = evalAfterNum !== null ? -evalAfterNum : null;
    const cpLoss = (evalBeforeNum !== null && evalAfterPlayed !== null)
        ? Math.max(0, Math.round(evalBeforeNum - evalAfterPlayed))
        : Math.max(0, Math.round(Math.abs(swing)));

    // És la línia del motor una seqüència forçada? Sense reanàlisi profunda
    // només es pot demostrar per fets del tauler (única resposta legal, mat);
    // la resta queda com a "no demostrat" i la ressenya en parla amb prudència.
    let forcingInfo = null;
    try {
        forcingInfo = ElTaulerCore.buildPvForcingInfo({
            fen: beforeFen,
            bestPv: analysisData.bestMovePv || [],
            multipvBefore: analysisData.multipvBefore || null,
            replyAlternatives: null,
            evalBefore: evalBeforeNum,
            board: getPvBoardHelpers()
        });
    } catch (e) {}

    currentReview.push({
        fen: beforeFen,
        moveNumber: Math.ceil(history.length / 2),
        playerMove: lastHumanMoveUci || '—',
        playerMoveSan: lastMove ? lastMove.san : '—',
        bestMove: analysisData.bestMove || null,
        color: lastMove ? lastMove.color : null,
        evalBefore: analysisData.evalBefore ?? null,
        evalAfter: analysisData.evalAfter ?? null,
        swing: Math.abs(swing),
        quality: quality,
        isCapture: lastMove ? !!lastMove.captured : false,
        isCheck: game.in_check(),
        timestamp: Date.now(),

        // NOUS CAMPS ENRIQUITS
        depth: analysisData.depth || null,
        bestMoveSan: bestMoveSan,
        bestMovePv: analysisData.bestMovePv || [],
        alternatives: analysisData.alternatives || [],
        // Línia de refutació (el càstig concret) i la posició a què es refereix.
        refutationPv: analysisData.refutationPv || [],
        afterFen: analysisData.afterFen || null,

        // CAMPS CANÒNICS DE L'ERRADA (noms estables; perspectiva del jugador)
        beforeFen: beforeFen,
        playedMoveUci: lastHumanMoveUci || null,
        playedMoveSan: lastMove ? lastMove.san : null,
        bestMoveUci: analysisData.bestMove || null,
        evalAfterPlayed: evalAfterPlayed,
        evalAfterBest: null, // només la reanàlisi profunda analitza la millor jugada
        cpLoss: cpLoss,
        bestPv: analysisData.bestMovePv || [],
        playedPv: analysisData.refutationPv || [],
        multipvBefore: analysisData.multipvBefore || null,
        forcingInfo: forcingInfo
    });
}

function summarizeReview(entries) {
    const base = { excel: 0, good: 0, inaccuracy: 0, mistake: 0, blunder: 0 };
    (entries || []).forEach(item => {
        if (base[item.quality] !== undefined) base[item.quality]++;
    });
    return base;
}

function calculateAverageCpLoss(entries) {
    const list = entries || [];
    if (!list.length) return 0;
    const total = list.reduce((sum, entry) => sum + (entry.swing || 0), 0);
    return Math.round(total / list.length);
}

function countBlunders(entries, threshold = 200) {
    return (entries || []).filter(entry => (entry.swing || 0) > threshold).length;
}

function identifyTacticalPatterns(entries, avgCpLoss, blunderCount) {
    const counts = summarizeReview(entries);
    const patterns = [];

    if (blunderCount > 0) {
        patterns.push('Errades tàctiques greus (>200 CP)');
    }
    if ((counts.mistake || 0) >= 2 || (counts.blunder || 0) >= 1) {
        patterns.push('Pèrdua de material en combinacions');
    }
    if ((counts.inaccuracy || 0) >= 3) {
        patterns.push('Imprecisions en la coordinació de peces');
    }
    if (avgCpLoss <= 60 && (counts.good + counts.excel) >= (counts.inaccuracy + counts.mistake + counts.blunder)) {
        patterns.push('Bona execució tàctica');
    }
    if (patterns.length === 0) {
        patterns.push('Sense patrons crítics destacats');
    }
    return patterns;
}

function getCalibrationResultsSummary() {
    const results = calibrationGames.map(game => game.result || 'draw');
    const wins = results.filter(r => r === 'win').length;
    const losses = results.filter(r => r === 'loss').length;
    const draws = results.filter(r => r === 'draw').length;
    const avgCpLoss = calibrationGames.length
        ? Math.round(calibrationGames.reduce((sum, game) => sum + (game.avgCpLoss || 0), 0) / calibrationGames.length)
        : 0;
    const blunders = calibrationGames.reduce((sum, game) => sum + (game.blunders || 0), 0);
    const patterns = calibrationGames.flatMap(game => game.tacticalPatterns || []);
    const patternCounts = patterns.reduce((acc, pattern) => {
        acc[pattern] = (acc[pattern] || 0) + 1;
        return acc;
    }, {});

    const strengths = [];
    const weaknesses = [];

    if (avgCpLoss <= 70) strengths.push('Precisió consistent al llarg del calibratge');
    if (patternCounts['Bona execució tàctica']) strengths.push('Bona execució tàctica');
    if (wins >= 3) strengths.push('Bona capacitat de convertir avantatges');

    if (avgCpLoss > 90) weaknesses.push('Cal reduir les pèrdues de centipeons');
    if (blunders > 0) weaknesses.push('Evita blunders crítics (>200 CP)');
    if (patternCounts['Pèrdua de material en combinacions']) weaknesses.push('Vigila les combinacions que perden material');
    if (patternCounts['Imprecisions en la coordinació de peces']) weaknesses.push('Millora la coordinació de peces');

    if (!strengths.length) strengths.push('Joc equilibrat sense punts forts clars');
    if (!weaknesses.length) weaknesses.push('Cap feblesa crítica detectada');

    return { wins, losses, draws, avgCpLoss, strengths, weaknesses };
}

function buildCalibrationChartData() {
    return calibrationGames.map(game => {
        const quality = getCalibrationGameQuality(game);
        return CALIBRATION_ROC_MIN + (quality * (CALIBRATION_ROC_MAX - CALIBRATION_ROC_MIN));
    });
}

function renderCalibrationResults() {
    const summary = getCalibrationResultsSummary();
    $('#calibration-elo-value').text(`${userELO} ROC`);
    $('#calibration-wld-summary').text(`W ${summary.wins} · L ${summary.losses} · D ${summary.draws}`);
    const resultRow = $('#calibration-wld-row');
    resultRow.empty();
    calibrationGames.forEach(game => {
        const cls = game.result === 'win' ? 'win' : game.result === 'loss' ? 'loss' : 'draw';
        const label = game.result === 'win' ? 'W' : game.result === 'loss' ? 'L' : 'D';
        resultRow.append(`<span class="calibration-result-badge ${cls}">${label}</span>`);
    });

    const strengthsList = $('#calibration-strengths');
    strengthsList.empty();
    summary.strengths.forEach(item => strengthsList.append(`<li>${item}</li>`));

    const weaknessesList = $('#calibration-weaknesses');
    weaknessesList.empty();
    summary.weaknesses.forEach(item => weaknessesList.append(`<li>${item}</li>`));

    const ctx = document.getElementById('calibration-chart');
    if (!ctx) return;
    const labels = calibrationGames.map((_, idx) => `Partida ${idx + 1}`);
    const data = buildCalibrationChartData();
    if (calibrationResultsChart) calibrationResultsChart.destroy();
    calibrationResultsChart = new Chart(ctx.getContext('2d'), {
        type: 'line',
        data: {
            labels,
            datasets: [{
                label: 'Evolució del nivell',
                data,
                borderColor: '#c9a227',
                backgroundColor: 'rgba(201, 162, 39, 0.15)',
                tension: 0.3,
                fill: true,
                pointBackgroundColor: '#c9a227',
                pointBorderColor: '#f4e4bc',
                pointBorderWidth: 2,
                pointRadius: 4
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: { legend: { display: false } },
            scales: {
                y: { beginAtZero: false, grid: { color: 'rgba(201, 162, 39, 0.1)' }, ticks: { color: '#a89a8a' } },
                x: { grid: { color: 'rgba(201, 162, 39, 0.1)' }, ticks: { color: '#a89a8a' } }
            }
        }
    });
}

function showCalibrationResultsScreen() {
    renderCalibrationResults();
    $('#game-screen').removeClass('active').hide();
    $('#league-screen').hide();
    $('#stats-screen').hide();
    $('#settings-screen').hide();
    $('#history-screen').hide();
    $('#start-screen').hide();
    $('#calibration-result-screen').show();
    navPush('calibration-result-screen');
}

function persistReviewSummary(finalPrecision, resultLabel) {
    if (blunderMode) { currentReview = []; return; }
    const summary = summarizeReview(currentReview);
    const now = new Date();
    const label = now.toLocaleDateString('ca-ES', { day: '2-digit', month: 'short' }) + ' ' + now.toLocaleTimeString('ca-ES', { hour: '2-digit', minute: '2-digit' });
    reviewHistory.push({
        label: label,
        precision: finalPrecision,
        result: resultLabel,
        ...summary
    });
    if (reviewHistory.length > 60) reviewHistory = reviewHistory.slice(-60);
    currentReview = [];
}

function updateReviewLegend(entry) {
    const lastEntry = entry || reviewHistory[reviewHistory.length - 1] || null;
    const counts = { excel: 0, good: 0, inaccuracy: 0, mistake: 0, blunder: 0 };
    if (lastEntry) {
        counts.excel = lastEntry.excel || 0;
        counts.good = lastEntry.good || 0;
        counts.inaccuracy = lastEntry.inaccuracy || 0;
        counts.mistake = lastEntry.mistake || 0;
        counts.blunder = lastEntry.blunder || 0;
    }
    Object.keys(counts).forEach(key => {
        const el = document.getElementById(`legend-${key}`);
        if (el) el.textContent = counts[key];
    });
}

function updateReviewChart() {
    const canvas = document.getElementById('review-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const hasData = reviewHistory.length > 0;
    const labels = hasData ? reviewHistory.map(r => r.label) : ['—'];
    const graySteps = ['#444', '#555', '#666', '#777', '#888'];
    const tickColor = epaperEnabled ? '#444' : '#a89a8a';
    const gridColor = epaperEnabled ? '#d0d0d0' : 'rgba(201, 162, 39, 0.1)';
    const datasets = [
        { key: 'excel', label: 'Excel·lents', color: '#4a7c59' },
        { key: 'good', label: 'Bones', color: '#c9a227' },
        { key: 'inaccuracy', label: 'Imprecisions', color: '#ffb74d' },
        { key: 'mistake', label: 'Errors', color: '#ef5350' },
        { key: 'blunder', label: 'Errades greus', color: '#b71c1c' }
        ].map((meta, idx) => {
        const gray = graySteps[idx % graySteps.length];
        return {
        label: meta.label,
        data: hasData ? reviewHistory.map(r => r[meta.key] || 0) : [0],
        borderColor: epaperEnabled ? gray : meta.color,
        backgroundColor: epaperEnabled ? `rgba(${80 + idx * 20}, ${80 + idx * 20}, ${80 + idx * 20}, 0.2)` : meta.color + '33',
        tension: 0.25,
        fill: false
        };
    });

    if (reviewChart) reviewChart.destroy();
    reviewChart = new Chart(ctx, {
        type: 'line',
        data: { labels, datasets },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: true, labels: { color: tickColor } },
                tooltip: { mode: 'index', intersect: false }
            },
            scales: {
                y: { beginAtZero: true, ticks: { color: tickColor }, grid: { color: gridColor } },
                x: { ticks: { color: tickColor, maxRotation: 45, minRotation: 45 }, grid: { color: gridColor } }
            }
        }
    });
    updateReviewLegend();
}

function formatHistoryMode(mode) {
    if (mode === 'league') return 'Lliga';
    if (mode === 'free') return 'Amistosa';
    if (mode === 'positional') return 'Joc vista';
    if (mode === 'imported') return 'Importada';
    return 'Partida';
}

// Ritme de rellotge d'una entrada de l'historial ("Blitz 3+2"...), o null si es
// va jugar sense rellotge (o l'entrada és antiga i no el va desar).
function historyTimeControlLabel(entry) {
    const tcId = entry && entry.timeControl;
    if (!tcId || tcId === 'none') return null;
    const cfg = TIME_CONTROLS.find(t => t.id === tcId);
    return cfg ? cfg.label : null;
}

// Descripció de la partida en una sola frase natural (mode, ritme si en tenia i
// color de les peces), en lloc d'encadenar etiquetes soltes amb "· amb blanques"
// al final: "Amistosa Blitz 3+2 amb blanques", "Lliga amb negres"...
function describeHistoryGame(entry) {
    const mode = formatHistoryMode(entry.mode);
    const color = entry.playerColor === 'b' ? 'negres' : 'blanques';
    const tcLabel = historyTimeControlLabel(entry);
    return tcLabel ? `${mode} ${tcLabel} amb ${color}` : `${mode} amb ${color}`;
}

