function stopHistoryPlayback() {
    if (historyReplay && historyReplay.timer) {
        clearInterval(historyReplay.timer);
        historyReplay.timer = null;
    }
    if (historyReplay) historyReplay.isPlaying = false;
    updateHistoryControls();
}

function updateHistoryControls() {
    const playBtn = $('#history-play');
    const pauseBtn = $('#history-pause');
    const prevBtn = $('#history-prev');
    const nextBtn = $('#history-next');
    const hasEntry = historyReplay && historyReplay.entry;
    const movesCount = hasEntry ? historyReplay.moves.length : 0;
    const atStart = !hasEntry || historyReplay.moveIndex === 0;
    const atEnd = !hasEntry || historyReplay.moveIndex >= movesCount;

    playBtn.prop('disabled', !hasEntry || movesCount === 0 || historyReplay.isPlaying || atEnd);
    pauseBtn.prop('disabled', !hasEntry || !historyReplay.isPlaying);
    prevBtn.prop('disabled', !hasEntry || atStart || historyReplay.isPlaying);
    nextBtn.prop('disabled', !hasEntry || atEnd || historyReplay.isPlaying);
}

function updateHistoryProgress() {
    const progress = $('#history-progress');
    if (!historyReplay || !historyReplay.entry) {
        progress.text('0/0');
        return;
    }
    progress.text(`${historyReplay.moveIndex}/${historyReplay.moves.length}`);
}

// Transcripció clicable de la partida oberta a l'historial: cada jugada duu el
// tauler a la posició de després de jugar-la, i la jugada actual queda marcada
// perquè sempre sigui clar de quin moviment es parla.
function renderHistoryMovesList() {
    const box = $('#history-moves');
    if (!box.length) return;
    const moves = (historyReplay && historyReplay.moves) || [];
    if (!moves.length) { box.hide().empty(); return; }
    let html = '';
    for (let i = 0; i < moves.length; i++) {
        if (i % 2 === 0) html += '<span class="hist-move-num">' + (i / 2 + 1) + '.</span> ';
        html += '<span class="hist-move" data-idx="' + (i + 1) + '" title="Toca per veure aquesta jugada al tauler">' + escapeHtml(moves[i]) + '</span> ';
    }
    box.html(html).show();
    updateHistoryMovesActive();
}

// Marca a la transcripció la jugada on és el tauler (l'última aplicada) i
// manté-la a la vista dins la caixa (sense moure la pàgina).
function updateHistoryMovesActive() {
    const box = document.getElementById('history-moves');
    if (!box) return;
    $('#history-moves .hist-move').removeClass('hist-move-active');
    // Amb un moment clau actiu es marca la jugada de la qual es parla; si no,
    // l'última jugada aplicada al tauler.
    const idx = !historyReplay ? 0
        : (activeReviewHighlight ? (historyReplay.keyMoveIdx || 0) : historyReplay.moveIndex);
    if (idx <= 0) return;
    const el = box.querySelector('.hist-move[data-idx="' + idx + '"]');
    if (!el) return;
    el.classList.add('hist-move-active');
    if (el.offsetTop < box.scrollTop || el.offsetTop + el.offsetHeight > box.scrollTop + box.clientHeight) {
        box.scrollTop = Math.max(0, el.offsetTop - box.clientHeight / 2);
    }
}

// Salta a la posició de DESPRÉS de la jugada `idx` (1-based) de la transcripció.
function seekHistoryMove(idx) {
    if (!historyReplay || !historyReplay.entry) return;
    stopHistoryPlayback();
    const target = Math.max(0, Math.min(idx, historyReplay.moves.length));
    const game = new Chess();
    let last = null;
    for (let i = 0; i < target; i++) {
        const mv = game.move(historyReplay.moves[i], { sloppy: true });
        if (!mv) break;
        last = mv;
    }
    historyReplay.game = game;
    historyReplay.moveIndex = target;
    historyReplay.lastMove = last ? { from: last.from, to: last.to } : null;
    activeReviewHighlight = null; // el moment clau deixa pas a la jugada clicada
    updateHistoryBoard();
}

// Caselles (origen→destinació) de la jugada actual, en or. Només quan no hi ha
// cap moment clau actiu (el vermell/verd del moment clau té prioritat).
function applyCurrentMoveMark() {
    $('#history-board .square-55d63').removeClass('hl-cur-from hl-cur-to');
    if (activeReviewHighlight) return;
    const lm = historyReplay && historyReplay.lastMove;
    if (!lm) return;
    $("#history-board .square-55d63[data-square='" + lm.from + "']").addClass('hl-cur-from');
    $("#history-board .square-55d63[data-square='" + lm.to + "']").addClass('hl-cur-to');
}

function updateHistoryBoard() {
    if (!historyBoard || !historyReplay || !historyReplay.game) return;
    // Sempre orienta el tauler cap al color del jugador perquè les TEVES peces
    // quedin a la part inferior durant tota la revisió i en navegar pels moments
    // clau, independentment de qui mou (i de crides que reinicien l'orientació).
    if (typeof historyBoard.orientation === 'function') {
        const want = (historyReplay.entry && historyReplay.entry.playerColor === 'b') ? 'black' : 'white';
        if (historyBoard.orientation() !== want) historyBoard.orientation(want);
    }
    historyBoard.position(historyReplay.game.fen(), false);
    if (typeof historyBoard.resize === 'function') historyBoard.resize();
    // Reaplica els ressaltats del moment clau actiu (si n'hi ha); si no, els neteja.
    applyReviewHighlights();
    applyCurrentMoveMark();
    updateHistoryMovesActive();
    updateHistoryProgress();
    updateHistoryControls();
}

// CERCA AQUESTA FUNCIÓ:
function initHistoryBoard() {
    if (historyBoard) return;
    const boardEl = document.getElementById('history-board');
    if (!boardEl) return;
    historyBoard = Chessboard('history-board', {
        draggable: false,
        position: 'start',
        pieceTheme: 'https://chessboardjs.com/img/chesspieces/wikipedia/{piece}.png'
    });
}

// CANVIA-LA PER AQUESTA:
function initHistoryBoard(entry) {
    const boardEl = document.getElementById('history-board');
    if (!boardEl) return;
    
    // Determinar orientació segons el color jugat
    let orientation = 'white';
    if (entry && entry.playerColor === 'b') {
        orientation = 'black';
    }
    
    // Si ja existeix el tauler, només canviar orientació si cal
    if (historyBoard) {
        historyBoard.orientation(orientation);
        return;
    }
    
    historyBoard = Chessboard('history-board', {
        draggable: false,
        position: 'start',
        orientation: orientation,
        pieceTheme: 'https://chessboardjs.com/img/chesspieces/wikipedia/{piece}.png'
    });
}

function getHistoryMoves(entry) {
    if (!entry) return [];
    const baseMoves = Array.isArray(entry.moves) ? entry.moves : [];
    if ((!baseMoves.length || baseMoves.length === 1) && entry.pgn) {
        const pgnGame = new Chess();
        if (pgnGame.load_pgn(entry.pgn, { sloppy: true })) {
            const parsedMoves = pgnGame.history();
            if (parsedMoves.length) return parsedMoves;
        }
    }
    return baseMoves;
}

// Construeix un PGN complet (amb capçaleres) a partir d'una entrada de l'historial
function buildEntryPgn(entry) {
    if (!entry) return '';
    const moves = getHistoryMoves(entry);
    if (!moves.length) return entry.pgn || '';
    const replay = new Chess();
    moves.forEach(m => { replay.move(m, { sloppy: true }); });
    const playerWhite = (entry.playerColor || 'w') === 'w';
    const oppName = entry.opponent && entry.opponent.name ? entry.opponent.name : 'Stockfish';
    let resultTag = '*';
    const res = (entry.result || '').toLowerCase();
    if (res.includes('victòr') || res.includes('guany') || res.includes('win')) resultTag = playerWhite ? '1-0' : '0-1';
    else if (res.includes('derrot') || res.includes('perd') || res.includes('loss')) resultTag = playerWhite ? '0-1' : '1-0';
    else if (res.includes('tau') || res.includes('draw')) resultTag = '1/2-1/2';
    // Les partides importades conserven les capçaleres del PGN original
    // (noms reals, torneig, data); les jugades dins l'app porten les nostres.
    const ih = entry.importHeaders || null;
    replay.header(
        'Event', (ih && ih.Event) || 'El Tauler',
        'Site', (ih && ih.Site) || 'El Tauler PWA',
        'Date', (ih && ih.Date) || (entry.date || new Date().toLocaleDateString()),
        'White', (ih && ih.White) || (playerWhite ? 'Jugador' : oppName),
        'Black', (ih && ih.Black) || (playerWhite ? oppName : 'Jugador'),
        'Result', (ih && ih.Result) || resultTag
    );
    return replay.pgn();
}

// ── Importació de partides externes (PGN) ────────────────────────────────────
// Permet portar a l'historial partides jugades fora de l'app (Lichess,
// Chess.com, tornejos presencials…) i passar-les per la MATEIXA maquinària que
// les partides pròpies: anàlisi amb Stockfish jugada a jugada, ressenya de
// l'entrenador, errades comentades i biblioteca d'errors (SRS i jeroglífics).

// Parseja un text PGN (una o més partides) i valida les jugades amb chess.js.
// Retorna només les partides jugables: { headers, moves (SAN), finalFen,
// skippedTokens (tokens que no s'han pogut interpretar al final) }.
function parseExternalPgnGames(text) {
    const blocks = ElTaulerCore.splitPgnGames(text);
    const games = [];
    for (const block of blocks) {
        const parsed = ElTaulerCore.parsePgnHeaders(block);
        // Posicions inicials personalitzades (FEN/SetUp): no es poden revisar
        // des de la jugada 1, així que es descarten.
        if (parsed.headers.FEN || parsed.headers.SetUp === '1') continue;
        const tokens = ElTaulerCore.sanitizePgnMoveText(parsed.moveText);
        if (!tokens.length) continue;
        const g = new Chess();
        const moves = [];
        for (const tok of tokens) {
            let mv = null;
            try { mv = g.move(tok, { sloppy: true }); } catch (e) { mv = null; }
            if (!mv) break;
            moves.push(mv.san);
        }
        if (moves.length < 2) continue;
        games.push({
            headers: parsed.headers,
            moves: moves,
            finalFen: g.fen(),
            skippedTokens: tokens.length - moves.length
        });
    }
    return games;
}

// Data de la partida segons les capçaleres del PGN («2024.03.15»), o null.
function importedPgnDate(headers) {
    const raw = headers && (headers.UTCDate || headers.Date);
    if (raw && /^\d{4}\.\d{2}\.\d{2}$/.test(raw)) {
        const d = new Date(raw.replace(/\./g, '-') + 'T12:00:00');
        if (!isNaN(d.getTime())) return d;
    }
    return null;
}

// Construeix una entrada de l'historial (mateixa forma que recordGameHistory)
// a partir d'una partida importada. Arriba SENSE anàlisi (moveReviews buit):
// l'anàlisi es fa després amb el motor, sota demanda o en acceptar l'avís.
// sourceFileName és el nom del fitxer PGN triat (si n'hi havia): serveix de
// recanvi per posar nom als jugadors quan el PGN no duu capçaleres White/Black.
function buildImportedHistoryEntry(parsedGame, playerColor, sourceFileName) {
    const headers = parsedGame.headers || {};
    const now = new Date();
    const gameDate = importedPgnDate(headers);
    const color = playerColor === 'b' ? 'b' : 'w';
    const rivalName = (color === 'w' ? headers.Black : headers.White) || null;
    const replay = new Chess();
    parsedGame.moves.forEach(m => replay.move(m, { sloppy: true }));
    return {
        id: `import_${now.getTime()}_${Math.floor(Math.random() * 10000)}`,
        label: '📥 ' + (gameDate || now).toLocaleDateString('ca-ES', { day: '2-digit', month: 'short', year: 'numeric' }),
        players: ElTaulerCore.pgnPlayersLabel(headers, sourceFileName || null),
        sourceFile: sourceFileName || null,
        date: (gameDate || now).toISOString(),
        mode: 'imported',
        result: ElTaulerCore.pgnResultToLabel(headers.Result, color) || 'Partida importada',
        precision: null,
        counts: null,
        moves: parsedGame.moves.slice(),
        errors: [],
        moveReviews: [],
        review: [],
        severeErrors: [],
        aiReview: null,
        playerColor: color,
        timeControl: 'none',
        opponent: (rivalName && rivalName !== '?') ? { name: rivalName } : null,
        fen: parsedGame.finalFen || replay.fen(),
        pgn: replay.pgn(),
        roc: null,
        level: null,
        accuracy: null,
        mistakes: 0,
        imported: true,
        importHeaders: {
            Event: headers.Event || null,
            Site: headers.Site || null,
            Date: headers.Date || null,
            White: headers.White || null,
            Black: headers.Black || null,
            Result: headers.Result || null
        },
        createdAt: now.toISOString(),
        updatedAt: now.toISOString()
    };
}

// Anàlisi COMPLETA d'una entrada sense moveReviews (partida importada): passa
// el motor per cada jugada del jugador (posició abans i després, com el joc en
// viu) i omple moveReviews, counts, precisió i errades greus. Les errades
// greus s'afegeixen a la biblioteca d'errors (savedErrors), de manera que la
// partida alimenta el repàs SRS, els jeroglífics personals i el diagnòstic com
// qualsevol partida jugada dins l'app. Reutilitza analyzeFenRobust i el mateix
// flag de serialització que la reanàlisi profunda (deepReviewInProgress).
async function analyzeHistoryEntryFromScratch(entry, opts = {}) {
    if (!entry) return 0;
    const moves = getHistoryMoves(entry);
    if (!moves.length) return 0;
    if (deepReviewInProgress || waitingForBlunderAnalysis) return 0;
    deepReviewInProgress = true;
    const depth = opts.depth || 13;
    const startedAt = Date.now();
    // Una partida llarga vol el seu temps (2 anàlisis per jugada pròpia), però
    // amb un límit global perquè un mòbil lent no s'hi quedi girant per sempre.
    const deadlineMs = opts.deadlineMs || 480000;
    const cpOf = b => !b ? null : (b.evalType === 'mate' ? (b.eval > 0 ? 10000 : -10000) : b.eval);
    try {
        // El motor és NOSTRE mentre duri l'anàlisi: atura la generació en segon
        // pla (jeroglífics i seqüències) i espera que la feina en curs cedeixi.
        // Dues anàlisis alhora sobre el mateix worker es roben les respostes.
        // (deepReviewInProgress ja impedeix que en comenci cap de nova.)
        try { requestBackgroundPrepAbort(); } catch (e) {}
        try { if (stockfish) stockfish.postMessage('stop'); } catch (e) {}
        const yieldStart = Date.now();
        while ((hgGenerating || personalHieroglyphicPrepInFlight || backgroundPrepPromise) && Date.now() - yieldStart < 10000) {
            await new Promise(r => setTimeout(r, 250));
        }
        // L'anàlisi sempre a força completa: el joc en viu re-afirma la seva
        // força (UCI_LimitStrength/UCI_Elo) a cada jugada, així que no cal restaurar-la.
        if (!stockfish) ensureStockfish();
        try { stockfish.postMessage('setoption name UCI_LimitStrength value false'); } catch (e) {}
        const playerColor = entry.playerColor === 'b' ? 'b' : 'w';
        const g = new Chess();
        const steps = [];
        for (const san of moves) {
            const fenBefore = g.fen();
            const turn = g.turn();
            const mv = g.move(san, { sloppy: true });
            if (!mv) break;
            steps.push({
                fenBefore: fenBefore,
                fenAfter: g.fen(),
                turn: turn,
                san: mv.san,
                uci: mv.from + mv.to + (mv.promotion || ''),
                moveNumber: parseInt(fenBefore.split(' ')[5], 10) || null,
                mateDelivered: g.in_checkmate(),
                drawnAfter: !g.in_checkmate() && g.game_over()
            });
        }
        const playerSteps = steps.filter(s => s.turn === playerColor);
        const total = playerSteps.length;
        const reviews = [];
        for (let i = 0; i < total; i++) {
            const step = playerSteps[i];
            if (typeof opts.onProgress === 'function') {
                try { opts.onProgress(i, total); } catch (e) {}
            }
            if (opts.shouldAbort && opts.shouldAbort()) break;
            if (Date.now() - startedAt > deadlineMs) break;
            // ABANS de la jugada: millor jugada, línia i avaluació (perspectiva del jugador).
            const before = await analyzeFenRobust(step.fenBefore, depth, 2, 5000, opts.shouldAbort);
            if (!before || !before.bestMove || !before.bestMove.move) continue;
            const bm = before.bestMove;
            const review = {
                moveNumber: step.moveNumber,
                quality: 'unknown',
                color: playerColor,
                swing: 0,
                fen: step.fenBefore,
                bestMove: bm.move,
                bestMoveSan: uciToSan(step.fenBefore, bm.move),
                playerMove: step.uci,
                playerMoveSan: step.san,
                bestMovePv: bm.pv || [],
                alternatives: (before.alternatives || []).map(a => ({
                    move: a.move,
                    moveSan: a.move ? uciToSan(step.fenBefore, a.move) : null,
                    eval: cpOf(a),
                    evalType: a.evalType,
                    pv: a.pv || []
                })),
                evalBefore: cpOf(bm),
                evalAfter: null,
                refutationPv: [],
                afterFen: step.fenAfter
            };
            // DESPRÉS de la jugada real (perspectiva del rival). Si la partida
            // s'acaba amb la jugada, no cal motor: mat fet = -10000, taules = 0.
            if (step.mateDelivered) {
                review.evalAfter = -10000;
            } else if (step.drawnAfter) {
                review.evalAfter = 0;
            } else {
                const after = await analyzeFenRobust(step.fenAfter, depth, 1, 5000, opts.shouldAbort);
                if (after && after.bestMove) {
                    review.evalAfter = cpOf(after.bestMove);
                    review.refutationPv = after.bestMove.pv || [];
                }
            }
            // Mateix conveni que el joc en viu: swing = evalBefore + evalAfter
            // (perspectives oposades: una bona jugada suma ~0).
            if (typeof review.evalBefore === 'number' && typeof review.evalAfter === 'number') {
                review.swing = Math.abs(review.evalBefore + review.evalAfter);
                review.quality = classifyMoveQuality(review.swing, review.playerMove, review.bestMove);
            } else if (review.playerMove === review.bestMove) {
                review.quality = 'excel';
            } else {
                continue; // sense avaluació fiable, la jugada no es puntua
            }
            reviews.push(review);
        }
        if (!reviews.length) return 0;
        entry.moveReviews = reviews;
        entry.counts = summarizeReview(reviews);
        entry.precision = Math.round(((entry.counts.excel + entry.counts.good) / reviews.length) * 100);
        entry.accuracy = entry.precision;
        entry.mistakes = entry.counts.mistake || 0;
        entry.severeErrors = getSevereErrors(reviews);
        // Recalcula el moment clau amb l'anàlisi profunda (dades més fiables).
        try { entry.keyMoment = keyMomentToStored(computeKeyMoment(entry)); } catch (e) {}
        // Resum per fases a l'índex: fins ara la partida no tenia revisions i,
        // per tant, no comptava per al perfil del bessó.
        try { entry.phaseStats = ElTaulerCore.bessoPhaseStatsFromGame(entry); } catch (e) {}
        entry.errors = entry.severeErrors.map(err => ({
            fen: err.fen,
            severity: err.quality || 'blunder',
            bestMove: err.bestMove || null,
            playerMove: err.playerMove || null,
            bestMovePv: err.bestMovePv || []
        }));
        entry.analyzedAt = new Date().toISOString();
        entry.updatedAt = entry.analyzedAt;
        // Alimenta la biblioteca d'errors i el mapa de debilitats amb les
        // errades greus, com si la partida s'hagués jugat dins l'app — però
        // NOMÉS per a partides pròpies: les de la pestanya PGN poden ser
        // d'altres jugadors (grans mestres) i les seves errades no diuen res
        // del nostre joc. La revisió de la mateixa partida (errades i encerts
        // comentats, gràfic, moments clau) es conserva igualment sencera.
        if (!historyEntryIsImported(entry)) entry.severeErrors.forEach(err => {
            if (!err.fen) return;
            if (!savedErrors.some(e => e.fen === err.fen)) {
                savedErrors.push({
                    fen: err.fen,
                    date: new Date().toLocaleDateString(),
                    severity: err.quality === 'blunder' ? 'blunder' : 'mistake',
                    elo: userELO,
                    bestMove: err.bestMove || null,
                    playerMove: err.playerMove || null,
                    bestMovePv: err.bestMovePv || [],
                    srsReps: 0,
                    srsInterval: 0,
                    srsDue: Date.now()
                });
            }
            try {
                const theme = getTaskTheme(err.fen, err.bestMove || '', err.theme || 'general');
                updateThemeMastery(theme, 'real_game_error', { severity: err.severity || err.quality, source: 'imported_game' });
            } catch (e) {}
        });
        regenerateLocalReview(entry); // nova llavor de ressenya + saveStorage()
        try { if (window.CloudSync && window.CloudSync.flushSoon) window.CloudSync.flushSoon(); } catch (e) {}
        return reviews.length;
    } finally {
        deepReviewInProgress = false;
    }
}
if (typeof window !== 'undefined') window.analyzeHistoryEntryFromScratch = analyzeHistoryEntryFromScratch;

// ═════════════════════════════════════════════════════════════════════════════
// EXPLORADOR — tauler d'anàlisi lliure amb el motor avaluant
// ═════════════════════════════════════════════════════════════════════════════
// Mou peces lliurement (jugades legals del torn), amb Stockfish avaluant cada
// posició: barra i valor d'avaluació, millor línia (i una alternativa) i botó
// per jugar la millor. Té editor de posició (peces de recanvi de chessboard.js)
// i entrada/còpia de FEN. S'hi arriba des del menú («Tauler d'anàlisi») o des
// de l'historial amb «Explora aquesta posició», que porta la posició que
// s'està mirant a la revisió.
const EXPLORER_START_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';
let explorerBoard = null;          // instància Chessboard
let explorerGame = null;           // chess.js amb la línia explorada aplicada
let explorerStartFen = 'start';    // arrel de l'exploració ('start' o un FEN)
let explorerMoves = [];            // SAN de la línia completa explorada
let explorerIndex = 0;             // jugades de la línia aplicades (per anar endavant/enrere)
let explorerActive = false;        // pantalla oberta: cedeix el motor a l'explorador
let explorerEditMode = false;      // editor de posició actiu
let explorerEditSnapshot = null;   // per restaurar la línia si es cancel·la l'edició
let explorerEditSparePiece = null; // peça del palet seleccionada per col·locar-la per tocs
let explorerAnalysisToken = 0;     // descarta respostes del motor d'una posició anterior
let explorerAnalysisTimer = null;  // petit debounce entre jugada i anàlisi
let explorerLastBest = null;       // { fen, uci } de la millor jugada analitzada
let explorerTapSquare = null;      // casella seleccionada en mode «tocar»
let explorerLastTapEventTs = 0;    // antirebot: pointerdown+touchstart del mateix toc
let explorerAnalysisRetries = 0;   // reintents si el motor no respon (contenció)
let explorerBoardControlMode = null; // mode de control aplicat al tauler d'anàlisi
let explorerEngineMoveHighlight = null; // { from, to } de l'última jugada del motor (requadre marró)
let explorerPlayPending = null;    // { fen, playerColor }: petició de «Juga-la contra Stockfish»
// Línies del motor (PV) de la posició analitzada, font ÚNICA per a la navegació
// clicable: { startFen, lines: { best|alt: {label, ...buildPvPositions()} } }.
let explorerPv = null;
// Estat de PREVISUALITZACIÓ d'una línia, SEPARAT de la partida real (explorerGame).
// Navegar-hi no toca explorerGame, ni el PGN, ni l'historial, ni el motor.
let explorerPreview = {
    active: false,     // previsualització en marxa?
    startFen: null,    // FEN inicial de l'anàlisi (arrel de la línia)
    lineKey: null,     // 'best' | 'alt'
    plies: [],         // posicions de la línia (de ElTaulerCore.buildPvPositions)
    stepIndex: 0,      // jugades aplicades (0 = posició inicial; N = final)
    previewFen: null,  // FEN que es mostra al tauler
    lastMove: null     // { from, to } de l'última jugada reproduïda (o null)
};
// Mode PRÀCTICA del moment clau: l'usuari torna a intentar la decisió.
let explorerPractice = { active: false, km: null, answered: false };

function createExplorerBoard(editMode) {
    if (explorerBoard && typeof explorerBoard.destroy === 'function') {
        try { explorerBoard.destroy(); } catch (e) {}
    }
    const placement = explorerGame ? explorerGame.fen().split(' ')[0] : 'start';
    const desiredControlMode = editMode ? 'drag' : (controlMode === 'tap' ? 'tap' : 'drag');
    const config = {
        draggable: desiredControlMode === 'drag',
        position: placement,
        pieceTheme: 'https://chessboardjs.com/img/chesspieces/wikipedia/{piece}.png'
    };
    if (editMode) {
        // Editor: peces de recanvi per afegir-ne, i arrossegar fora per treure'n.
        config.sparePieces = true;
        config.dropOffBoard = 'trash';
    } else {
        config.onDragStart = (source, piece) => {
            // Durant la previsualització d'una línia el tauler és de només lectura.
            if (explorerPreview.active) return false;
            if (!explorerGame || explorerGame.game_over()) return false;
            return !!piece && piece.charAt(0) === explorerGame.turn();
        };
        config.onDrop = (source, target) => {
            if (explorerPreview.active) return 'snapback';
            if (!explorerGame || !target || target === 'offboard') return 'snapback';
            return explorerTryMove(source, target) ? undefined : 'snapback';
        };
        // Sincronitza captures, enrocs i coronacions amb la posició real.
        config.onSnapEnd = () => {
            if (explorerGame && explorerBoard) explorerBoard.position(explorerGame.fen(), false);
        };
    }
    explorerBoard = Chessboard('explorer-board', config);
    explorerBoardControlMode = desiredControlMode;
    updateExplorerBoardInteractivity();
    // Cal lligar-ho aquí (i no un sol cop a l'inici): destroy() de
    // chessboard.js fa unbind() de TOTS els esdeveniments del contenidor.
    if (editMode) bindExplorerEditPlaceEvents();
    if (!editMode) reapplyExplorerEngineMoveHighlight();
}

// Editor: col·locació per tocs. S'escolta mousedown/touchstart (i no 'click')
// perquè chessboard.js comença l'arrossegament amb el mateix toc i el 'click'
// resultant acaba dirigit al body (la peça fantasma queda sota el punter). El
// preventDefault del touchstart evita el mousedown sintetitzat (commutaria
// dues vegades) i el desplaçament de la pàgina.
function bindExplorerEditPlaceEvents() {
    $('#explorer-board').off('.exp-editplace')
        .on('mousedown.exp-editplace touchstart.exp-editplace', '.spare-pieces-7492f .piece-417db', function (e) {
            if (!explorerEditMode) return;
            if (e.type === 'touchstart') e.preventDefault();
            const piece = $(this).attr('data-piece');
            if (!piece) return;
            setExplorerEditSparePiece(piece === explorerEditSparePiece ? null : piece);
        })
        .on('mousedown.exp-editplace touchstart.exp-editplace', '.square-55d63', function (e) {
            if (!explorerEditMode || !explorerEditSparePiece || !explorerBoard) return;
            const square = $(this).attr('data-square');
            if (!square) return;
            const pos = explorerBoard.position();
            // Sobre una casella ocupada es deixa fer l'arrossegament normal
            // (moure la peça o treure-la): la col·locació és a caselles buides.
            if (pos[square]) return;
            if (e.type === 'touchstart') e.preventDefault();
            pos[square] = explorerEditSparePiece;
            explorerBoard.position(pos, false);
        });
}

// Mode «tocar» (preferència de control de l'usuari): tocar peça i destí, amb
// les MATEIXES indicacions que el tauler de joc (casella seleccionada marcada
// i cercles als destins legals: classes compartides tap-selected/tap-move).
function highlightExplorerTapSelection(square) {
    $('#explorer-board .square-55d63').removeClass('tap-selected tap-move');
    const moves = explorerGame ? explorerGame.moves({ square: square, verbose: true }) : [];
    if (moves.length === 0) return false;

    $(`#explorer-board .square-55d63[data-square='${square}']`).addClass('tap-selected');
    for (const mv of moves) {
        $(`#explorer-board .square-55d63[data-square='${mv.to}']`).addClass('tap-move');
    }
    return true;
}

function enableExplorerTapToMove() {
    const boardEl = document.getElementById('explorer-board');
    if (boardEl) boardEl.style.touchAction = 'none';
    $('#explorer-board').off('.exp-tapmove')
        .on('pointerdown.exp-tapmove touchstart.exp-tapmove', '.square-55d63', function (e) {
            if (explorerEditMode || explorerPreview.active || !explorerGame || explorerGame.game_over()) return;
            if (e && e.preventDefault) e.preventDefault();

            const nowTs = Date.now();
            if (nowTs - explorerLastTapEventTs < 180) return;
            explorerLastTapEventTs = nowTs;

            const square = $(this).attr('data-square');
            if (!square) return;

            if (!explorerTapSquare) {
                const p = explorerGame.get(square);
                if (!p || p.color !== explorerGame.turn()) return;
                if (highlightExplorerTapSelection(square)) explorerTapSquare = square;
                return;
            }

            if (square === explorerTapSquare) {
                clearExplorerTapSelection();
                return;
            }

            const from = explorerTapSquare;
            clearExplorerTapSelection();
            // En mode «tocar» no hi ha onSnapEnd: el tauler es repinta aquí.
            if (explorerTryMove(from, square)) {
                if (explorerBoard) explorerBoard.position(explorerGame.fen(), false);
                return;
            }

            // Destinació il·legal sobre una altra peça pròpia: passa a
            // seleccionar-la (mateix comportament que el tauler de joc).
            const p2 = explorerGame.get(square);
            if (p2 && p2.color === explorerGame.turn() && highlightExplorerTapSelection(square)) {
                explorerTapSquare = square;
            }
        });
}

function clearExplorerTapSelection() {
    explorerTapSquare = null;
    $('#explorer-board .square-55d63').removeClass('tap-selected tap-move');
}

function disableExplorerTapToMove() {
    $('#explorer-board').off('.exp-tapmove');
    const boardEl = document.getElementById('explorer-board');
    if (boardEl) boardEl.style.touchAction = '';
    clearExplorerTapSelection();
}

// Requadre marró de jugada del motor (el mateix .engine-move que a la resta de
// l'app): marca la «millor jugada» quan la juga el motor i desapareix així que
// la posició canvia (jugada de l'usuari, navegació, FEN nou o edició). Es desa
// per reaplicar-la quan el tauler es recrea (canvi de mode de control) o es
// gira, que reconstrueixen les caselles i n'esborren les classes.
function clearExplorerEngineMoveHighlight() {
    explorerEngineMoveHighlight = null;
    $('#explorer-board .square-55d63').removeClass('engine-move');
}

function reapplyExplorerEngineMoveHighlight() {
    const h = explorerEngineMoveHighlight;
    if (!h) return;
    $('#explorer-board .square-55d63').removeClass('engine-move');
    [h.from, h.to].forEach((sq) => {
        if (sq) $(`#explorer-board .square-${sq}`).addClass('engine-move');
    });
}

function highlightExplorerEngineMove(from, to) {
    explorerEngineMoveHighlight = { from: from || null, to: to || null };
    reapplyExplorerEngineMoveHighlight();
}

// Nom de l'obertura de la posició explorada, pel GRAF de posicions (transposicions
// incloses): es mostra el nom de la posició amb nom MÉS PROFUNDA assolida per la
// línia fins al punt que s'està mirant (com fan els analitzadors habituals). Mentre
// el graf encara es construeix en segon pla, la línia queda amagada; la crida de
// getOpeningPositionGraph() n'engega la construcció i, en acabar, es refresca.
function updateExplorerOpeningLabel() {
    const el = document.getElementById('explorer-opening');
    if (!el) return;
    let hit = null;
    if (explorerActive && !explorerEditMode && explorerGame && typeof ElTaulerCore !== 'undefined') {
        const graph = getOpeningPositionGraph();
        if (graph && graph.byPos) {
            try {
                const keyFn = ElTaulerCore.positionKeyFromFen;
                const g = explorerStartFen === 'start' ? new Chess() : new Chess(explorerStartFen);
                hit = graph.byPos.get(keyFn(g.fen())) || null;
                for (let i = 0; i < explorerIndex; i++) {
                    if (!g.move(explorerMoves[i], { sloppy: true })) break;
                    hit = graph.byPos.get(keyFn(g.fen())) || hit;
                }
            } catch (e) { hit = null; }
        }
    }
    if (hit) {
        el.textContent = `📖 ${hit.eco ? hit.eco + ' · ' : ''}${hit.name}`;
        el.style.display = '';
    } else {
        el.textContent = '';
        el.style.display = 'none';
    }
}

function updateExplorerBoardInteractivity() {
    if (!explorerBoard) return;
    const desiredControlMode = explorerEditMode ? 'drag' : (controlMode === 'tap' ? 'tap' : 'drag');
    if (explorerBoardControlMode !== desiredControlMode) {
        createExplorerBoard(explorerEditMode);
        return;
    }
    const useTap = desiredControlMode === 'tap';
    explorerBoard.draggable = !useTap;
    if (useTap) enableExplorerTapToMove(); else disableExplorerTapToMove();
}

// Completa un FEN escurçat amb els camps per defecte: molts llocs copien
// només la col·locació (o sense els comptadors), i chess.js vol els 6 camps.
function normalizeExplorerFen(fen) {
    const parts = String(fen || '').trim().replace(/\s+/g, ' ').split(' ');
    if (parts.length >= 6) return parts.slice(0, 6).join(' ');
    const defaults = ['', 'w', '-', '-', '0', '1'];
    return parts.concat(defaults.slice(parts.length)).join(' ');
}

// Fixa una posició nova com a ARREL de l'exploració (la línia es buida).
function setupExplorerPosition(fen, opts = {}) {
    const isStart = !fen || fen === 'start';
    const g = new Chess();
    if (!isStart && !g.load(normalizeExplorerFen(fen))) {
        showToast('Aquest FEN no és vàlid.', 'warn');
        return false;
    }
    // Fixar una posició nova descarta la nota d'importació del moment clau.
    showExplorerImportNote(null);
    explorerStartFen = isStart ? 'start' : g.fen();
    explorerGame = g;
    explorerMoves = [];
    explorerIndex = 0;
    explorerLastBest = null;
    createExplorerBoard(false);
    if (opts.orientation && typeof explorerBoard.orientation === 'function') {
        explorerBoard.orientation(opts.orientation === 'black' ? 'black' : 'white');
    }
    afterExplorerPositionChange();
    return true;
}

function explorerTryMove(from, to) {
    if (isUserPromotionMove(explorerGame, from, to)) {
        showPromotionPicker(explorerGame.turn(), (piece) => {
            if (applyExplorerMove(from, to, piece) && explorerBoard) {
                explorerBoard.position(explorerGame.fen(), false);
            }
        });
        return false; // snapback: el tauler es repinta quan es triï la peça
    }
    return applyExplorerMove(from, to, null);
}

function applyExplorerMove(from, to, promotion) {
    if (!explorerGame) return false;
    // Mode pràctica: la PRIMERA jugada des de la posició del moment clau és
    // l'intent de l'usuari (s'avalua i es dona resposta pedagògica).
    const practiceAttempt = explorerPractice.active && !explorerPractice.answered
        && explorerIndex === 0 && explorerPractice.km && explorerGame.fen() === explorerPractice.km.fen;
    const mv = explorerGame.move({ from: from, to: to, promotion: promotion || undefined });
    if (!mv) return false;
    // Si estàvem enrere dins la línia, la jugada nova en talla la cua.
    explorerMoves = explorerMoves.slice(0, explorerIndex);
    explorerMoves.push(mv.san);
    explorerIndex = explorerMoves.length;
    if (practiceAttempt) {
        const uci = mv.from + mv.to + (mv.promotion || '');
        void evaluateKeyMomentAttempt(uci, explorerGame.fen());
    }
    afterExplorerPositionChange();
    return true;
}

// Reconstrueix la posició fins a la jugada idx de la línia (per navegar).
function explorerSeek(idx) {
    const clamped = Math.max(0, Math.min(explorerMoves.length, idx));
    const g = explorerStartFen === 'start' ? new Chess() : new Chess(explorerStartFen);
    for (let i = 0; i < clamped; i++) g.move(explorerMoves[i], { sloppy: true });
    explorerGame = g;
    explorerIndex = clamped;
    if (explorerBoard) explorerBoard.position(g.fen(), false);
    afterExplorerPositionChange();
}

function explorerStatusText() {
    const g = explorerGame;
    if (!g) return '—';
    if (g.in_checkmate()) return g.turn() === 'w' ? 'Escac i mat: guanyen les negres' : 'Escac i mat: guanyen les blanques';
    if (g.in_stalemate()) return 'Ofegat: taules';
    if (g.in_threefold_repetition()) return 'Triple repetició: es poden reclamar taules';
    if (g.insufficient_material()) return 'Material insuficient: taules';
    if (g.in_draw()) return 'Taules';
    const t = g.turn() === 'w' ? 'les blanques' : 'les negres';
    return g.in_check() ? `Mouen ${t} — escac!` : `Mouen ${t}`;
}


// Passa una avaluació del motor (perspectiva del qui mou) a perspectiva BLANCA.
function explorerWhiteEval(best, turn) {
    const sign = turn === 'b' ? -1 : 1;
    if (best.evalType === 'mate') return { type: 'mate', value: best.eval * sign };
    return { type: 'cp', value: (best.eval || 0) * sign };
}

function explorerEvalText(we) {
    if (we.type === 'mate') {
        const n = Math.abs(we.value);
        return we.value > 0 ? `Mat en ${n} (blanques)` : `Mat en ${n} (negres)`;
    }
    const pawns = we.value / 100;
    return (pawns > 0 ? '+' : '') + pawns.toFixed(2);
}

// Fracció de la barra per a les blanques (0..1), suau perquè es mogui amb sentit.
function explorerWhiteShare(we) {
    if (we.type === 'mate') return we.value > 0 ? 0.98 : 0.02;
    return 1 / (1 + Math.pow(10, -we.value / 600));
}

function setExplorerEvalDisplay(text, share, depthText) {
    const value = document.getElementById('explorer-eval-value');
    if (value) value.textContent = text;
    const depth = document.getElementById('explorer-eval-depth');
    if (depth) depth.textContent = depthText || '';
    const fill = document.getElementById('explorer-eval-fill');
    if (fill && typeof share === 'number') fill.style.width = `${Math.round(Math.max(0.02, Math.min(0.98, share)) * 100)}%`;
}

function scheduleExplorerAnalysis() {
    if (explorerAnalysisTimer) clearTimeout(explorerAnalysisTimer);
    explorerAnalysisTimer = setTimeout(() => { void runExplorerAnalysis(); }, 250);
}

async function runExplorerAnalysis() {
    if (!explorerActive || !explorerGame || explorerEditMode) return;
    const fen = explorerGame.fen();
    const token = ++explorerAnalysisToken;
    const lineEl = document.getElementById('explorer-line');
    const line2El = document.getElementById('explorer-line2');
    const playBest = document.getElementById('explorer-play-best');
    explorerLastBest = null;
    explorerPv = null;
    if (playBest) playBest.style.display = 'none';
    // Posició acabada: el veredicte és del tauler, no cal motor.
    if (explorerGame.game_over()) {
        const mate = explorerGame.in_checkmate();
        const whiteWon = mate && explorerGame.turn() === 'b';
        setExplorerEvalDisplay(mate ? (whiteWon ? '1–0' : '0–1') : '½–½', mate ? (whiteWon ? 0.98 : 0.02) : 0.5, '');
        if (lineEl) lineEl.textContent = explorerStatusText();
        if (line2El) line2El.style.display = 'none';
        return;
    }
    setExplorerEvalDisplay('…', undefined, '');
    if (lineEl) lineEl.textContent = 'Analitzant la posició…';
    if (line2El) line2El.style.display = 'none';
    // El motor, a força completa i sense competir amb la feina de fons.
    try { requestBackgroundPrepAbort(); } catch (e) {}
    if (!stockfish) ensureStockfish();
    try { stockfish.postMessage('setoption name UCI_LimitStrength value false'); } catch (e) {}
    const res = await analyzeFenRobust(fen, 15, 2, 1500, () => token !== explorerAnalysisToken || !explorerActive);
    if (token !== explorerAnalysisToken || !explorerActive || explorerEditMode) return;
    if (!res || !res.bestMove || !res.bestMove.move) {
        // El motor pot fallar un cop si just acabava una altra feina (fons):
        // es reintenta un parell de vegades abans de donar-se per vençut.
        if (explorerAnalysisRetries < 2) {
            explorerAnalysisRetries++;
            setTimeout(() => {
                if (token === explorerAnalysisToken && explorerActive) void runExplorerAnalysis();
            }, 1200);
            return;
        }
        setExplorerEvalDisplay('—', undefined, '');
        if (lineEl) lineEl.textContent = 'El motor no ha respost; mou una peça per tornar-ho a provar.';
        return;
    }
    explorerAnalysisRetries = 0;
    const we = explorerWhiteEval(res.bestMove, explorerGame.turn());
    setExplorerEvalDisplay(explorerEvalText(we), explorerWhiteShare(we), `prof. ${res.depth || '—'}`);
    // Construeix les línies (millor + alternativa) com a UNA font de dades i les
    // renderitza com a botons clicables. Prefereix la UCI (menys ambigua) per
    // reproduir-les; la SAN és per mostrar-les.
    const bestPv = (res.bestMove.pv && res.bestMove.pv.length) ? res.bestMove.pv.slice(0, 10) : [res.bestMove.move];
    const lines = { best: Object.assign({ label: 'Millor línia' }, ElTaulerCore.buildPvPositions(Chess, fen, bestPv)) };
    const alt = (res.alternatives || []).find(a => a && a.move && a.move !== res.bestMove.move);
    if (alt) {
        const altWe = explorerWhiteEval(alt, explorerGame.turn());
        const altPv = (alt.pv && alt.pv.length) ? alt.pv.slice(0, 8) : [alt.move];
        lines.alt = Object.assign(
            { label: `Alternativa (${explorerEvalText(altWe)})` },
            ElTaulerCore.buildPvPositions(Chess, fen, altPv)
        );
    }
    explorerPv = { startFen: fen, lines: lines };
    explorerLastBest = { fen: fen, uci: res.bestMove.move };
    // Mode pràctica sense resposta a la posició del moment clau: NO es revela la
    // millor jugada (ni la línia ni el botó); la resta (barra i valoració) sí.
    const maskForPractice = explorerPractice.active && !explorerPractice.answered
        && explorerPractice.km && fen === explorerPractice.km.fen;
    if (maskForPractice) {
        if (lineEl) lineEl.textContent = 'Troba la millor jugada i mou-la al tauler.';
        if (line2El) { line2El.style.display = 'none'; line2El.innerHTML = ''; }
        if (playBest) playBest.style.display = 'none';
    } else {
        renderExplorerPvLines();
        if (playBest) playBest.style.display = '';
    }
}

// Renderitza les línies del motor (#explorer-line i #explorer-line2) com a
// seqüències de botons: cada moviment és clicable i navegable amb teclat.
function renderExplorerPvLines() {
    renderExplorerPvLine('best', document.getElementById('explorer-line'));
    const line2El = document.getElementById('explorer-line2');
    if (explorerPv && explorerPv.lines.alt && explorerPv.lines.alt.plies.length) {
        renderExplorerPvLine('alt', line2El);
        if (line2El) line2El.style.display = '';
    } else if (line2El) {
        line2El.style.display = 'none';
        line2El.innerHTML = '';
    }
}

function renderExplorerPvLine(lineKey, el) {
    if (!el || !explorerPv || !explorerPv.lines[lineKey]) return;
    const line = explorerPv.lines[lineKey];
    const tokens = ElTaulerCore.pvDisplayTokens(line.plies);
    let html = `<span class="explorer-line-label">${escapeHtml(line.label)}:</span> `;
    if (!tokens.length) {
        el.innerHTML = html + '<span class="explorer-line-empty">—</span>';
        return;
    }
    html += '<span class="explorer-pv">';
    tokens.forEach((tok) => {
        const ply = line.plies[tok.index];
        if (tok.numberLabel) html += `<span class="explorer-move-no">${tok.numberLabel}</span>`;
        const isActive = explorerPreview.active
            && explorerPreview.lineKey === lineKey
            && explorerPreview.stepIndex === tok.index + 1;
        const aria = escapeHtml(ElTaulerCore.pvMoveAriaLabel(ply));
        html += `<button type="button" class="explorer-pv-move${isActive ? ' active' : ''}"`
            + ` data-line="${lineKey}" data-step="${tok.index + 1}" aria-label="${aria}">`
            + `${escapeHtml(tok.san)}</button>`;
    });
    html += '</span>';
    el.innerHTML = html;
}

// ── Previsualització d'una línia del motor ───────────────────────────────────
// Mostra al tauler la posició resultant d'una línia del motor SENSE tocar la
// partida real (explorerGame), ni el PGN, ni l'historial, ni el motor. Només
// canvia la posició VISUAL del tauler i el ressaltat; en sortir es restaura.

// Ressalta al tauler les caselles d'origen/destí de l'última jugada reproduïda,
// reutilitzant la classe .engine-move (el mateix requadre marró de la resta de
// l'app), sense tocar el ressaltat persistent de «Juga la millor jugada».
function paintExplorerPreviewMove(lastMove) {
    $('#explorer-board .square-55d63').removeClass('engine-move');
    if (lastMove) {
        [lastMove.from, lastMove.to].forEach((sq) => {
            if (sq) $(`#explorer-board .square-${sq}`).addClass('engine-move');
        });
    }
}

function updateExplorerPreviewBar() {
    updateExplorerNavButtons();
    const bar = document.getElementById('explorer-preview-bar');
    if (!bar) return;
    if (!explorerPreview.active) { bar.style.display = 'none'; return; }
    bar.style.display = '';
    const total = explorerPreview.plies.length;
    const i = explorerPreview.stepIndex;
    const statusEl = document.getElementById('explorer-preview-status');
    if (statusEl) {
        if (i <= 0) {
            statusEl.textContent = 'Posició inicial de l\'anàlisi';
        } else {
            const ply = explorerPreview.plies[i - 1];
            const num = ply.isWhite ? `${ply.moveNo}.` : `${ply.moveNo}…`;
            statusEl.textContent = `Posició després de ${num}${ply.san} · pas ${i} de ${total}`;
        }
    }
    // Porta el moviment actiu a la zona visible (mòbil: la línia pot ocupar
    // diverses files).
    const activeBtn = document.querySelector('.explorer-pv-move.active');
    if (activeBtn && activeBtn.scrollIntoView) {
        try { activeBtn.scrollIntoView({ block: 'nearest', inline: 'center' }); } catch (e) {}
    }
}

// Aplica un pas de la línia previsualitzada (0 = posició inicial de l'anàlisi).
function explorerPreviewApply(stepIndex) {
    const total = explorerPreview.plies.length;
    const step = ElTaulerCore.pvStepClamp(stepIndex, total);
    explorerPreview.stepIndex = step;
    if (step <= 0) {
        explorerPreview.previewFen = explorerPreview.startFen;
        explorerPreview.lastMove = null;
    } else {
        const ply = explorerPreview.plies[step - 1];
        explorerPreview.previewFen = ply.fenAfter;
        explorerPreview.lastMove = { from: ply.from, to: ply.to };
    }
    // Només canvia la VISTA del tauler; explorerGame no es toca.
    if (explorerBoard) explorerBoard.position(explorerPreview.previewFen, false);
    paintExplorerPreviewMove(explorerPreview.lastMove);
    renderExplorerPvLines();       // reactualitza el ressaltat del moviment actiu
    updateExplorerPreviewBar();
}

// Selecciona una línia i hi entra en previsualització a un pas concret.
function explorerPreviewSelect(lineKey, stepIndex) {
    if (!explorerPv || !explorerPv.lines[lineKey]) return;
    const line = explorerPv.lines[lineKey];
    if (!line.plies || !line.plies.length) return;
    clearExplorerTapSelection();
    explorerPreview.active = true;
    explorerPreview.startFen = explorerPv.startFen;
    explorerPreview.lineKey = lineKey;
    explorerPreview.plies = line.plies;
    explorerPreviewApply(stepIndex);
}

// Surt de la previsualització i restaura la posició analitzada real i el seu
// ressaltat persistent (el de «Juga la millor jugada», si n'hi havia).
function exitExplorerPreview() {
    if (!explorerPreview.active) return;
    explorerPreview.active = false;
    explorerPreview.plies = [];
    explorerPreview.previewFen = null;
    explorerPreview.lastMove = null;
    explorerPreview.lineKey = null;
    explorerPreview.stepIndex = 0;
    if (explorerBoard && explorerGame) explorerBoard.position(explorerGame.fen(), false);
    $('#explorer-board .square-55d63').removeClass('engine-move');
    reapplyExplorerEngineMoveHighlight();
    updateExplorerPreviewBar();
    renderExplorerPvLines();
}

// Llista de jugades de la línia explorada, clicable per navegar-hi.
function renderExplorerMoves() {
    const el = document.getElementById('explorer-moves');
    if (!el) return;
    if (!explorerMoves.length) {
        el.innerHTML = '<span class="explorer-moves-empty">Mou una peça (o carrega un FEN) i el motor anirà avaluant cada posició.</span>';
        return;
    }
    const startParts = (explorerStartFen === 'start' ? EXPLORER_START_FEN : explorerStartFen).split(' ');
    let moveNo = parseInt(startParts[5], 10) || 1;
    let whiteToMove = startParts[1] !== 'b';
    let html = '';
    explorerMoves.forEach((san, i) => {
        if (whiteToMove) html += `<span class="explorer-move-no">${moveNo}.</span>`;
        else if (i === 0) html += `<span class="explorer-move-no">${moveNo}…</span>`;
        html += `<button type="button" class="explorer-move${i < explorerIndex ? '' : ' future'}${i === explorerIndex - 1 ? ' active' : ''}" data-idx="${i}">${escapeHtml(san)}</button>`;
        if (!whiteToMove) moveNo++;
        whiteToMove = !whiteToMove;
    });
    el.innerHTML = html;
}

// Estat dels botons del reproductor (ÚNICS per a tot): mentre es previsualitza
// una línia del motor naveguen aquella línia; si no, la línia explorada.
function updateExplorerNavButtons() {
    const previewing = explorerPreview.active;
    const atStart = previewing ? explorerPreview.stepIndex <= 0 : explorerIndex === 0;
    const atEnd = previewing
        ? explorerPreview.stepIndex >= explorerPreview.plies.length
        : explorerIndex >= explorerMoves.length;
    $('#explorer-start-btn, #explorer-prev').prop('disabled', atStart);
    $('#explorer-next, #explorer-end-btn').prop('disabled', atEnd);
}

function updateExplorerControls() {
    updateExplorerNavButtons();
    const fenInput = document.getElementById('explorer-fen-input');
    if (fenInput && document.activeElement !== fenInput && explorerGame) {
        // A la posició inicial estàndard el camp queda BUIT (no hi ha cap FEN
        // «carregat»); per a qualsevol altra posició s'hi reflecteix el FEN.
        const fen = explorerGame.fen();
        fenInput.value = fen === EXPLORER_START_FEN ? '' : fen;
    }
    const status = document.getElementById('explorer-status');
    if (status) status.textContent = explorerStatusText();
}

function afterExplorerPositionChange() {
    // La posició real ha canviat: qualsevol previsualització de línia queda
    // obsoleta i les línies del motor s'han de recalcular.
    exitExplorerPreview();
    explorerPv = null;
    clearExplorerTapSelection();
    clearExplorerEngineMoveHighlight();
    explorerAnalysisRetries = 0;
    renderExplorerMoves();
    updateExplorerControls();
    updateExplorerOpeningLabel();
    scheduleExplorerAnalysis();
}

// Canvia el torn de la posició actual (per «i si aquí moguessin les negres?»).
// Esdevé l'arrel d'una exploració nova; la casella al pas es neteja.
function explorerSwapTurn() {
    if (!explorerGame || explorerEditMode) return;
    const parts = explorerGame.fen().split(' ');
    parts[1] = parts[1] === 'w' ? 'b' : 'w';
    parts[3] = '-';
    if (!setupExplorerPosition(parts.join(' '))) {
        showToast('No es pot canviar el torn en aquesta posició.', 'warn');
    }
}

// ── Editor de posició ────────────────────────────────────────────────────────
// Col·locació per tocs (mòbil i escriptori): a més d'arrossegar, tocar una
// peça del palet la SELECCIONA (marc daurat) i cada toc en una casella buida
// la col·loca, sense perdre la selecció, fins que se'n tria una altra, es
// torna a tocar la mateixa o se surt de l'editor (jugar demana sortir-ne).
function setExplorerEditSparePiece(piece) {
    explorerEditSparePiece = piece || null;
    applyExplorerEditSpareSelectionUI();
}

// Reaplica el marc de la peça seleccionada: el palet es reconstrueix quan el
// tauler canvia de mida, i les classes es perdrien.
function applyExplorerEditSpareSelectionUI() {
    const $spares = $('#explorer-board .spare-pieces-7492f .piece-417db');
    $spares.removeClass('spare-selected');
    if (explorerEditSparePiece) {
        $spares.filter(`[data-piece='${explorerEditSparePiece}']`).addClass('spare-selected');
    }
}

function enterExplorerEditMode() {
    if (explorerEditMode || !explorerGame) return;
    exitExplorerPreview();
    hideKeyMomentPracticeBanner();
    showExplorerImportNote(null);
    explorerEditMode = true;
    explorerEditSnapshot = { startFen: explorerStartFen, moves: explorerMoves.slice(), index: explorerIndex };
    ++explorerAnalysisToken; // descarta anàlisis en curs
    if (explorerAnalysisTimer) { clearTimeout(explorerAnalysisTimer); explorerAnalysisTimer = null; }
    const turnSel = document.getElementById('explorer-edit-turn');
    if (turnSel) turnSel.value = explorerGame.turn();
    setExplorerEditSparePiece(null); // l'editor comença sense cap peça del palet seleccionada
    createExplorerBoard(true);
    // Sense cap FEN carregat (exploració pristina des de la posició inicial),
    // l'editor comença amb el tauler BUIT: la posició es munta des de zero amb
    // les peces de recanvi. Amb una posició carregada (FEN, historial o
    // jugades fetes), s'edita aquella posició.
    if (explorerStartFen === 'start' && explorerMoves.length === 0 && explorerBoard) {
        explorerBoard.clear(false);
    }
    $('#explorer-eval-card, #explorer-nav, #explorer-moves, #explorer-play-vs, #explorer-tools, #explorer-status, #explorer-opening').hide();
    $('#explorer-edit-toolbar').show();
}

// Drets d'enroc que la col·locació encara permet (rei i torre a casa seva).
function inferCastlingRights(pos) {
    let rights = '';
    if (pos.e1 === 'wK') {
        if (pos.h1 === 'wR') rights += 'K';
        if (pos.a1 === 'wR') rights += 'Q';
    }
    if (pos.e8 === 'bK') {
        if (pos.h8 === 'bR') rights += 'k';
        if (pos.a8 === 'bR') rights += 'q';
    }
    return rights || '-';
}

function exitExplorerEditMode(apply) {
    if (!explorerEditMode) return;
    let nextFen = null;
    if (apply) {
        const pos = explorerBoard.position();
        const placement = Chessboard.objToFen(pos);
        const kings = Object.values(pos);
        if (kings.filter(p => p === 'wK').length !== 1 || kings.filter(p => p === 'bK').length !== 1) {
            showToast('La posició ha de tenir exactament un rei de cada color.', 'warn');
            return;
        }
        const turnSel = document.getElementById('explorer-edit-turn');
        const turn = (turnSel && turnSel.value === 'b') ? 'b' : 'w';
        nextFen = `${placement} ${turn} ${inferCastlingRights(pos)} - 0 1`;
        const probe = new Chess();
        if (!probe.load(nextFen)) {
            showToast('Aquesta posició no és vàlida (peons a la primera/última fila?).', 'warn');
            return;
        }
    }
    explorerEditMode = false;
    setExplorerEditSparePiece(null);
    $('#explorer-edit-toolbar').hide();
    $('#explorer-eval-card, #explorer-nav, #explorer-moves, #explorer-play-vs, #explorer-tools, #explorer-status').show();
    if (apply) {
        setupExplorerPosition(nextFen);
    } else {
        // Restaura l'exploració tal com era abans d'entrar a l'editor.
        const snap = explorerEditSnapshot;
        explorerStartFen = snap ? snap.startFen : 'start';
        explorerMoves = snap ? snap.moves : [];
        createExplorerBoard(false);
        explorerSeek(snap ? snap.index : 0);
    }
    explorerEditSnapshot = null;
}

// ── Obertura i tancament de la pantalla ──────────────────────────────────────
function openExplorer(fen, opts = {}) {
    $('#start-screen').hide();
    $('#history-screen').hide();
    $('#explorer-screen').show();
    explorerActive = true;
    explorerEditMode = false;
    $('#explorer-edit-toolbar').hide();
    $('#explorer-eval-card, #explorer-nav, #explorer-moves, #explorer-play-vs, #explorer-tools, #explorer-status').show();
    // Obertura NORMAL (no pràctica): descarta qualsevol mode de pràctica anterior.
    if (!opts.practiceNote) hideKeyMomentPracticeBanner();
    if (opts.pushHistory !== false) navPush('explorer-screen');
    try { requestBackgroundPrepAbort(); } catch (e) {}
    // Sense posició demanada, s'obre NET: posició inicial i cap FEN al camp.
    const initialFen = fen || 'start';
    if (!setupExplorerPosition(initialFen, opts)) setupExplorerPosition('start', opts);
    // Notes contextuals (importació del moment clau / consigna de pràctica).
    showExplorerImportNote(opts.importNote || null);
    if (opts.practiceNote) setKeyMomentPracticeBanner(opts.practiceNote, 'info', false);
}

function closeExplorerScreen() {
    // En sortir de la pantalla, restaura la posició analitzada (surt de la
    // previsualització) abans d'amagar-la.
    exitExplorerPreview();
    hideKeyMomentPracticeBanner();
    showExplorerImportNote(null);
    explorerActive = false;
    explorerEditMode = false;
    explorerEditSparePiece = null;
    explorerPv = null;
    ++explorerAnalysisToken;
    if (explorerAnalysisTimer) { clearTimeout(explorerAnalysisTimer); explorerAnalysisTimer = null; }
    try { if (stockfish) stockfish.postMessage('stop'); } catch (e) {}
    $('#explorer-screen').hide();
}
if (typeof window !== 'undefined') window.openExplorer = openExplorer;

// «Juga-la contra Stockfish»: converteix la posició explorada en una partida
// REAL al nivell adaptatiu de l'usuari (com una partida lliure). L'usuari juga
// el bàndol a qui toca moure (amb «Canvia el torn» es tria l'altre). La partida
// NO puntua ELO ni es desa a l'historial: amb l'editor es pot muntar qualsevol
// posició (fins i tot de guanyada) i no ha de poder inflar la puntuació.
function startExplorerGame() {
    if (!explorerGame || explorerEditMode) return;
    if (explorerGame.game_over()) {
        showToast('Aquesta posició ja està acabada: no s\'hi pot jugar.', 'warn');
        return;
    }
    const fen = explorerGame.fen();
    const color = explorerGame.turn();
    closeExplorerScreen();
    explorerPlayPending = { fen: fen, playerColor: color };
    showToast(`Jugues amb ${color === 'w' ? 'blanques' : 'negres'} al teu nivell (sense puntuar)`, 'success');
    void startGame(false, fen);
}

// Repara les FEN de decisió dels moveReviews d'una entrada antiga o incompleta.
// Algunes partides (sobretot inacabades o migrades de versions velles) es van
// desar amb la FEN de decisió absent o inservible, i això feia que en clicar el
// moment clau no es ressaltés ni la teva jugada (vermell) ni la millor (verd).
// Aquí recalculem la FEN EXACTA reproduint les jugades reals de la partida fins
// al ply corresponent. Només toquem les que no serveixen, per no alterar dades
// bones. Retorna true si ha canviat alguna cosa (per persistir-ho una sola vegada).
function repairEntryMoveReviewFens(entry, movesArg) {
    if (!entry || !Array.isArray(entry.moveReviews) || !entry.moveReviews.length) return false;
    const moves = Array.isArray(movesArg) ? movesArg : getHistoryMoves(entry);
    if (!moves.length) return false;

    // FEN just abans de cada ply (índex 0-based del ply).
    const fensBefore = [];
    try {
        const g = new Chess();
        for (let i = 0; i < moves.length; i++) {
            fensBefore[i] = g.fen();
            if (!g.move(moves[i], { sloppy: true })) break;
        }
    } catch (e) { return false; }

    const norm = s => String(s || '').trim().replace(/[+#!?]/g, '');
    const playerColor = (entry.playerColor === 'b') ? 'b' : (entry.playerColor === 'w' ? 'w' : null);
    let changed = false;

    for (const r of entry.moveReviews) {
        if (!r) continue;
        const playedRef = r.playerMove || r.playerMoveSan;
        // Si la FEN desada ja permet reconstruir la teva jugada, la deixem estar
        // (el ressaltat ja funcionarà, fins i tot si el torn ve invertit).
        if (r.fen && playedRef && resolveMoveOnFen(r.fen, playedRef)) continue;

        const mn = Number(r.moveNumber);
        if (!mn || mn < 1) continue;
        const color = (r.color === 'w' || r.color === 'b') ? r.color : playerColor;
        if (color !== 'w' && color !== 'b') continue;
        let ply = (mn - 1) * 2 + (color === 'b' ? 1 : 0);

        // Si la SAN desada no quadra amb el ply calculat, la cerquem a prop del
        // número de jugada (per si el número balla en partides migrades).
        const wantSan = norm(r.playerMoveSan || r.playerMove);
        if (wantSan && (ply >= moves.length || norm(moves[ply]) !== wantSan)) {
            let found = -1;
            for (let i = 0; i < moves.length; i++) {
                if (norm(moves[i]) === wantSan && Math.abs(Math.ceil((i + 1) / 2) - mn) <= 1) { found = i; break; }
            }
            if (found >= 0) ply = found;
        }
        if (ply < 0 || ply >= moves.length || !fensBefore[ply]) continue;

        // Només substituïm si tenim prou confiança: o bé la SAN encaixa al ply, o
        // bé no hi havia SAN per comprovar però el número de jugada hi cap.
        const confident = !wantSan || norm(moves[ply]) === wantSan;
        if (!confident) continue;

        r.fen = fensBefore[ply];
        if (!r.playerMoveSan && moves[ply]) r.playerMoveSan = moves[ply];
        changed = true;
    }
    return changed;
}

function loadHistoryEntry(entry) {
    if (!entry) return;
    stopHistoryPlayback();
    activeReviewHighlight = null; // nova partida: cap moment clau actiu encara
    // La veu temporal és de cada ressenya oberta: en obrir-ne una altra,
    // es torna a la veu per defecte de l'usuari.
    historyReviewVoiceOverride = null;
    const voiceSel = document.getElementById('history-voice-select');
    if (voiceSel) voiceSel.value = getReviewVoiceStyle();
    // Engega la construcció del graf de posicions (si encara no s'ha fet): així,
    // quan estigui llest, la ressenya s'actualitzarà amb el nom d'obertura precís.
    try { prewarmOpeningPositionGraph(); } catch (e) {}
    initHistoryBoard(entry);
    const moves = getHistoryMoves(entry);
    historyReplay = {
        entry: entry,
        game: new Chess(),
        moves: moves,
        moveIndex: 0,
        lastMove: null,
        timer: null,
        isPlaying: false
    };
    applyHistoryEntryBody(entry, moves);
    updateHistoryDetails(entry);
    renderHistoryMovesList();
    updateHistoryBoard();
    syncHistoryListActive();
    // El cos pesat de les partides velles viu a IndexedDB: mentre arriba, el
    // tauler i les jugades ja es veuen (surten de l'índex), i quan el tenim es
    // repinta el detall sense tocar la posició del rejoc.
    if (!historyEntryIsHydrated(entry)) {
        ensureHistoryEntryBody(entry).then(loaded => {
            if (!loaded) return;
            if (!historyReplay || historyReplay.entry !== entry) return;
            applyHistoryEntryBody(entry, moves);
            updateHistoryDetails(entry);
            renderHistoryMovesList();
        });
    }
}

// Feines que necessiten el cos de l'entrada carregat: reparar les FEN de decisió
// inservibles d'entrades velles/inacabades i, si s'ha corregit res, desar-ho una
// sola vegada perquè quedi net per sempre.
function applyHistoryEntryBody(entry, moves) {
    if (!entry || !historyEntryIsHydrated(entry)) return;
    try {
        if (repairEntryMoveReviewFens(entry, moves)) {
            if (typeof entry.counts === 'undefined' || entry.counts === null) {
                try { entry.counts = summarizeReview(entry.moveReviews); } catch (e) {}
            }
            saveStorage();
        }
    } catch (e) { console.warn('repairEntryMoveReviewFens', e); }
}

function updateHistoryDetails(entry) {
    const resultEl = $('#history-result');
    const precisionEl = $('#history-precision');
    const precisionPill = $('#history-precision-pill');
    const metaEl = $('#history-meta');
    const breakdown = $('#history-breakdown');
    const reviewContent = $('#history-review-content');
    if (!entry) {
        resultEl.text('—');
        precisionEl.text('—');
        if (precisionPill.length) precisionPill.removeClass('hp-good hp-mid hp-low');
        metaEl.text('Selecciona una partida per veure\'n els detalls.');
        breakdown.empty();
        renderHistoryPhaseChart(null);
        if (reviewContent.length) reviewContent.text('—');
        updateHistoryErrorNotes(null);
        $('#history-moves').hide().empty();
        updateHistoryProgress();
        updateHistoryControls();
        stopReviewTts();
        updateReviewTtsButtons();
        return;
    }

    // A les partides PGN el titular del detall són els jugadors (capçaleres o
    // nom del fitxer); el resultat es manté a la línia de metadades.
    const detailImported = historyEntryIsImported(entry);
    resultEl.text(detailImported && entry.players ? entry.players : (entry.result || '—'));
    precisionEl.text(typeof entry.precision === 'number' ? `${entry.precision}%` : '—');
    if (precisionPill.length) {
        precisionPill.removeClass('hp-good hp-mid hp-low');
        const pillCls = precisionPillClass(entry.precision);
        if (pillCls) precisionPill.addClass(pillCls);
    }
    const movesLabel = `${Math.ceil(getHistoryMoves(entry).length / 2)} jugades`;
    const metaParts = [];
    if (detailImported && entry.players && entry.result) metaParts.push(entry.result);
    metaParts.push(entry.label || '—');
    if (detailImported && entry.importHeaders && entry.importHeaders.Event && entry.importHeaders.Event !== '?') {
        metaParts.push(entry.importHeaders.Event);
    }
    metaParts.push(describeHistoryGame(entry), movesLabel);
    if (detailImported && entry.sourceFile) metaParts.push(`📄 ${entry.sourceFile}`);
    metaEl.text(metaParts.join(' · '));

    const counts = entry.counts || { excel: 0, good: 0, inaccuracy: 0, mistake: 0, blunder: 0 };
    breakdown.html(`
        <div class="review-chip excel">Excel·lents: <strong>${counts.excel || 0}</strong></div>
        <div class="review-chip good">Bones: <strong>${counts.good || 0}</strong></div>
        <div class="review-chip inaccuracy">Imprecisions: <strong>${counts.inaccuracy || 0}</strong></div>
        <div class="review-chip mistake">Errors: <strong>${counts.mistake || 0}</strong></div>
        <div class="review-chip blunder">Errades greus: <strong>${counts.blunder || 0}</strong></div>
    `);
    renderHistoryPhaseChart(entry);
    updateHistoryReview(entry);
    updateHistoryErrorNotes(entry);
    void requestErrorNotes(entry);
    updateHistoryProgress();
    updateHistoryControls();
    updateHistoryDeepenButton(entry);
    updateReviewTtsButtons();
}

// El botó del motor de l'historial té dues cares: per a una partida SENSE
// anàlisi (importada) fa l'anàlisi completa jugada a jugada; per a una amb
// anàlisi, la reanàlisi profunda dels moments clau de sempre.
function updateHistoryDeepenButton(entry) {
    const btn = $('#history-deepen-review');
    if (!btn.length || btn.prop('disabled')) return; // no trepitgem una anàlisi en curs
    // El recompte surt de l'índex: encara que el cos de la partida no hagi
    // arribat de IndexedDB, ja se sap si està analitzada o no.
    const hasAnalysis = entry && historyEntryReviewCount(entry) > 0;
    if (entry && !hasAnalysis && getHistoryMoves(entry).length) {
        btn.html('<svg class="btn-ic" aria-hidden="true"><use href="#ic-search"/></svg>Analitza la partida');
    } else {
        btn.html('<svg class="btn-ic" aria-hidden="true"><use href="#ic-search"/></svg>Recalcular moments clau');
    }
}

// Executa l'anàlisi completa d'una entrada sense anàlisi amb el progrés al
// botó del motor de l'historial, i refresca el detall i la llista en acabar.
async function runHistoryEntryAnalysisWithUi(entry) {
    const btn = $('#history-deepen-review');
    btn.prop('disabled', true).text('Analitzant…');
    let analyzed = 0;
    try {
        analyzed = await analyzeHistoryEntryFromScratch(entry, {
            onProgress: (done, total) => {
                if (total > 0) btn.text(`Analitzant ${Math.min(done + 1, total)}/${total}…`);
            }
        });
    } catch (e) {
        console.warn('[ImportPGN] anàlisi completa', e);
    }
    btn.prop('disabled', false);
    if (analyzed > 0) {
        if (historyReplay && historyReplay.entry && historyReplay.entry.id === entry.id) {
            updateHistoryDetails(entry);
        }
        renderGameHistory();
        const analyzedLabel = historyEntryIsImported(entry) ? 'jugades del color analitzat' : 'jugades teves';
        showToast(`Partida analitzada (${analyzed} ${analyzedLabel}) ✓`, 'success');
    } else {
        updateHistoryDeepenButton(historyReplay && historyReplay.entry);
        showToast('No s\'ha pogut analitzar (motor ocupat o sense resposta). Torna-ho a provar d\'aquí a un moment.', 'warn');
    }
    return analyzed;
}

// ── Modal d'importació de PGN ────────────────────────────────────────────────
let pgnImportParsedGames = [];
// Nom del fitxer PGN triat (si l'usuari n'ha carregat un): d'aquí surten els
// noms dels jugadors quan el PGN no duu capçaleres White/Black.
let pgnImportFileName = null;

function openPgnImportModal() {
    pgnImportParsedGames = [];
    pgnImportFileName = null;
    $('#pgn-import-text').val('');
    $('#pgn-import-games').empty();
    $('#pgn-import-status').hide().text('');
    $('#pgn-import-modal').css('display', 'flex');
}

function closePgnImportModal() {
    $('#pgn-import-modal').hide();
}

function pgnImportSetStatus(text, isError) {
    $('#pgn-import-status')
        .text(text)
        .css('color', isError ? '#c0392b' : 'var(--text-secondary)')
        .show();
}

function parsePgnImportText() {
    const text = String($('#pgn-import-text').val() || '');
    if (!text.trim()) {
        pgnImportSetStatus('Enganxa un PGN o tria un fitxer primer.', true);
        return;
    }
    let games = [];
    try { games = parseExternalPgnGames(text); } catch (e) { console.warn('[ImportPGN] parseig', e); }
    pgnImportParsedGames = games;
    if (!games.length) {
        $('#pgn-import-games').empty();
        pgnImportSetStatus('No hi he sabut llegir cap partida. Comprova que sigui un PGN estàndard (i sense posició inicial personalitzada).', true);
        return;
    }
    renderPgnImportGames(games);
}

function renderPgnImportGames(games) {
    const container = $('#pgn-import-games');
    const username = getUsername();
    const rows = games.map((g, idx) => {
        const h = g.headers || {};
        // Títol amb els jugadors: capçaleres del PGN o, si no n'hi ha, el nom
        // del fitxer carregat (habitual en reculls de partides de grans mestres).
        const players = ElTaulerCore.pgnPlayersLabel(h, pgnImportFileName) || 'Blanques – Negres';
        const result = (h.Result && h.Result !== '*') ? h.Result : 'inacabada';
        const nMoves = Math.ceil(g.moves.length / 2);
        // Si el nom d'usuari coincideix amb White o Black, el color ja ve triat.
        const guess = ElTaulerCore.guessPlayerColorFromPgnHeaders(h, username);
        const extra = [
            (h.Event && h.Event !== '?') ? h.Event : null,
            (h.Date && h.Date !== '????.??.??') ? h.Date : null
        ].filter(Boolean).join(' · ');
        const warn = g.skippedTokens > 0
            ? `<div class="pgn-import-warn">⚠️ No s'han pogut llegir les últimes jugades (${g.skippedTokens}); s'importa fins on s'ha pogut.</div>`
            : '';
        return `
            <div class="pgn-import-game">
                <div class="pgn-import-game-title">${escapeHtml(players)} · ${escapeHtml(result)} · ${nMoves} jugades</div>
                ${extra ? `<div class="pgn-import-game-meta">${escapeHtml(extra)}</div>` : ''}
                ${warn}
                <div class="pgn-import-game-row">
                    <select class="select-control pgn-import-color" data-idx="${idx}" aria-label="Color que vols analitzar">
                        <option value="w"${guess !== 'b' ? ' selected' : ''}>Analitza les blanques</option>
                        <option value="b"${guess === 'b' ? ' selected' : ''}>Analitza les negres</option>
                    </select>
                    <button type="button" class="btn btn-primary pgn-import-btn" data-idx="${idx}">Importa</button>
                </div>
            </div>`;
    }).join('');
    container.html(rows);
    pgnImportSetStatus(games.length === 1
        ? 'He llegit 1 partida. Tria quin color vols analitzar i importa-la.'
        : `He llegit ${games.length} partides. Tria quin color vols analitzar a cadascuna i importa les que vulguis.`, false);
    container.find('.pgn-import-btn').off('click').on('click', function () {
        importPgnGameAt(parseInt($(this).attr('data-idx'), 10));
    });
}

function importPgnGameAt(idx) {
    const parsed = pgnImportParsedGames[idx];
    if (!parsed) return;
    const colorSel = $(`#pgn-import-games .pgn-import-color[data-idx="${idx}"]`);
    const color = colorSel.val() === 'b' ? 'b' : 'w';
    const entry = buildImportedHistoryEntry(parsed, color, pgnImportFileName);
    // Les partides PGN van a la seva pròpia llista (pestanya «Partides PGN»),
    // amb un màxim de IMPORTED_HISTORY_MAX: les noves desplacen les més velles
    // sense tocar mai les partides pròpies.
    importedGameHistory.push(entry);
    if (importedGameHistory.length > IMPORTED_HISTORY_MAX) {
        importedGameHistory = importedGameHistory.slice(-IMPORTED_HISTORY_MAX);
    }
    pruneHistoryBodies();
    saveStorage();
    closePgnImportModal();
    historyReplay = null; // que la pestanya PGN s'obri amb la partida acabada d'importar
    setHistoryActiveTab('pgn');
    showToast('Partida importada a l\'historial 📥', 'success');
    // L'anàlisi és el que dona valor a la importació (ressenya, errades,
    // exercicis), però gasta motor una estona: es demana, no s'imposa.
    showAppConfirm(
        'Vols analitzar-la ara amb el motor? Trigarà una mica (s\'avalua cada jugada teva) i en acabar tindràs la ressenya de l\'entrenador, les errades comentades i els exercicis derivats.',
        () => { void runHistoryEntryAnalysisWithUi(entry); },
        { title: 'Analitzar la partida importada', confirmText: 'Analitza-la ara', cancelText: 'Més tard' }
    );
}

function updateHistoryReview(entry) {
    const reviewContent = $('#history-review-content');
    const generateBtn = $('#history-generate-review');
    if (!reviewContent.length) return;
    if (!entry) {
        reviewContent.text('—');
        if (generateBtn.length) generateBtn.prop('disabled', true);
        return;
    }
    // El botó de re-generar ressenya queda SEMPRE actiu quan hi ha una partida
    // carregada (es pot tornar a demanar la redacció amb OpenAI tantes vegades
    // com calgui). Si no hi ha clau d'OpenAI configurada, en clicar-lo s'avisa.
    if (generateBtn.length) generateBtn.prop('disabled', false);
    // Capçalera de la revisió de les partides PGN: els jugadors (de les
    // capçaleres del PGN o del nom del fitxer), torneig i data si se saben.
    let playersLine = '';
    if (historyEntryIsImported(entry) && entry.players) {
        const bits = [`<strong>${escapeHtml(entry.players)}</strong>`];
        const ih = entry.importHeaders || {};
        if (ih.Event && ih.Event !== '?') bits.push(escapeHtml(ih.Event));
        if (ih.Date && ih.Date !== '????.??.??') bits.push(escapeHtml(ih.Date));
        playersLine = `<p class="hist-imported-players">${bits.join(' · ')}</p>`;
    }
    // Partida sense anàlisi de jugades (importada d'un PGN i encara no
    // analitzada): la ressenya no tindria dades reals, així que en lloc de
    // text buit es guia cap al botó d'anàlisi.
    if (!historyEntryReviewCount(entry) && getHistoryMoves(entry).length) {
        reviewContent.html(playersLine + '<p>Aquesta partida encara no s\'ha analitzat. Prem <strong>«Analitza la partida»</strong> (sota el tauler) perquè el motor avaluï cada jugada del color triat i l\'entrenador en pugui escriure la ressenya, amb les errades i els encerts comentats.</p>');
        return;
    }
    const review = entry.aiReview || entry.deepseekReview || entry.geminiReview || null;
    // La ressenya local rica (obertura, fases, obertura semblant per practicar i
    // moments clau) es mostra SEMPRE, fins i tot quan hi ha una ressenya d'OpenAI:
    // la d'OpenAI, si n'hi ha, va a dalt com a redacció addicional.
    const localHtml = renderLocalReviewHtml(entry, { voiceStyle: historyReviewVoiceStyle() });
    let html = playersLine;
    if (review && review.text) {
        html += `<div class="ai-review-text">${formatOpenAIReviewText(review.text)}</div>`;
    } else if (review && review.status === 'pending') {
        html += `<p><em>Generant revisió amb OpenAI...</em></p>`;
    } else if (review && review.status === 'error' && openaiApiKey && review.message) {
        html += `<p><em>${escapeHtml(review.message)}</em></p>`;
    }
    html += localHtml;
    if (!html.trim()) {
        reviewContent.text('Encara no hi ha revisió per aquesta partida.');
        return;
    }
    reviewContent.html(html);
    bindOpenAIMoveLinks(reviewContent);
    // Secció «Moment clau de la partida»: pràctica, obertura al tauler d'anàlisi i
    // còpia del FEN. Es captura l'entrada actual per resoldre el moment fresc.
    const keyMomentEntry = entry;
    reviewContent.find('.keymoment-practice').off('click').on('click', function() {
        const km = getEntryKeyMoment(keyMomentEntry);
        if (km) startKeyMomentPractice(km);
    });
    reviewContent.find('.keymoment-open-analysis').off('click').on('click', function() {
        const km = getEntryKeyMoment(keyMomentEntry);
        if (km) openKeyMomentInAnalysis(km);
    });
    reviewContent.find('.keymoment-copy-fen').off('click').on('click', function() {
        void copyKeyMomentFen($(this).attr('data-fen'));
    });
    // Moments clau: navega a la posició de decisió i ressalta la jugada recomanada al tauler.
    reviewContent.find('.hist-keymove-link').off('click').on('click', function(event) {
        event.preventDefault();
        const moveNumber = Number($(this).data('move-number'));
        const playedSan = String($(this).data('san') || '').trim();
        const playedUci = String($(this).data('played-uci') || '').trim();
        const best = String($(this).data('best') || '').trim();
        const decisionFen = String($(this).data('fen') || '').trim();
        jumpToHistoryMove(moveNumber, playedSan, decisionFen, playedUci); // ressalta la teva jugada (vermell)
        // I la millor jugada (verd) sobre la mateixa posició de decisió.
        if (best) setKeyMomentBest(best);
        const boardEl = document.getElementById('history-board');
        if (boardEl && boardEl.scrollIntoView) boardEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
    // Moviments excepcionals: la jugada feta ERA la millor, així que es marca
    // NOMÉS aquesta jugada i en verd (cap ressaltat vermell).
    reviewContent.find('.hist-brilliant-link').off('click').on('click', function(event) {
        event.preventDefault();
        const moveNumber = Number($(this).data('move-number'));
        const san = String($(this).data('san') || '').trim();
        const uci = String($(this).data('uci') || '').trim();
        const fen = String($(this).data('fen') || '').trim();
        jumpToHistoryMove(moveNumber, san, fen, uci);
        if (activeReviewHighlight) {
            activeReviewHighlight.best = activeReviewHighlight.played || uci || san;
            activeReviewHighlight.played = null;
            applyReviewHighlights();
        }
        const boardEl = document.getElementById('history-board');
        if (boardEl && boardEl.scrollIntoView) boardEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
    reviewContent.find('.opening-practice-link').off('click').on('click', function(event) {
        event.preventDefault();
        const idx = Number($(this).data('idx'));
        const color = String($(this).data('color') || '');
        practiceOpeningFromHistory(Number.isNaN(idx) ? -1 : idx, color);
    });
    reviewContent.find('.review-copy-moves').off('click').on('click', function(event) {
        event.preventDefault();
        const txt = String($(this).attr('data-moves') || '');
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(txt)
                .then(() => showToast('Jugades copiades 📋', 'success'))
                .catch(() => showToast('No s\'ha pogut copiar; selecciona el text manualment', 'warn'));
        } else {
            showToast('Còpia no disponible; selecciona el text manualment', 'info');
        }
    });
    // Es manté actiu encara que ja existeixi una ressenya: permet re-generar-la.
}

// Renova la ressenya LOCAL d'una partida (no depèn de cap clau d'IA): incrementa
// la llavor perquè la propera renderització triï una veu i una redacció noves, i
// invalida les memòries cau associades. La nova llavor es desa amb la partida.
function regenerateLocalReview(entry) {
    if (!entry) return;
    entry.reviewSeed = (entry.reviewSeed || 0) + 1;
    const newKey = entry.id + ':r' + entry.reviewSeed;
    try {
        if (_localDebriefCache && typeof _localDebriefCache === 'object') {
            // La memòria cau del debrief porta la veu com a sufix de la clau.
            Object.keys(_localDebriefCache)
                .filter(k => k === newKey || k.indexOf(newKey + '|') === 0)
                .forEach(k => { delete _localDebriefCache[k]; });
        }
        if (_coachVoiceByKey && typeof _coachVoiceByKey === 'object') delete _coachVoiceByKey[newKey];
    } catch (e) {}
    try { saveStorage(); } catch (e) {}
}

function escapeHtml(text) {
    return String(text)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function formatOpenAIReviewText(text) {
    const safe = escapeHtml(text || '');
    
    // Primer, formatem les cometes per a màximes
    let formatted = safe
        .replace(/&quot;([\s\S]*?)&quot;/g, '<em>"$1"</em>')
        .replace(/\"([\s\S]*?)\"/g, '<em>"$1"</em>');
    
    // Patrons AMPLIATS per capturar més formats de referències a jugades
    const movePatterns = [
        // Formats amb paréntesis: "10. Nxe5", "10 (Nxe5)", etc.
        /(\d+)\.\s*([NBRQK]?[a-h]?[1-8]?x?[a-h][1-8](?:=[NBRQ])?[+#]?)/gi,
        /jugada\s+(\d+)\s*\(([^)]+)\)/gi,
        /a\s+la\s+jugada\s+(\d+)\s*\(([^)]+)\)/gi,
        /jugada\s+n[úu]mero\s+(\d+)\s*\(([^)]+)\)/gi,
        /moviment\s+(\d+)\s*\(([^)]+)\)/gi,
        /al\s+moviment\s+(\d+)\s*\(([^)]+)\)/gi,
        // Formats sense paréntesis
        /jugada\s+(\d+):\s*([NBRQK]?[a-h]?[1-8]?x?[a-h][1-8](?:=[NBRQ])?[+#]?)/gi,
        /move\s+(\d+)\s*\(([^)]+)\)/gi,
    ];
    
    // Apliquem cada patró
    movePatterns.forEach(pattern => {
        formatted = formatted.replace(pattern, (match, moveNumber, san) => {
            const cleanSan = san.trim()
                .replace(/&amp;/g, '&')
                .replace(/&lt;/g, '<')
                .replace(/&gt;/g, '>')
                .replace(/&quot;/g, '"')
                .replace(/&#39;/g, "'");
            
            return `<a href="#" class="openai-move-link" data-move-number="${moveNumber}" data-san="${cleanSan}">${match}</a>`;
        });
    });
    
    return formatted;
}

function bindOpenAIMoveLinks(container) {
    if (!container || !container.length) return;
    container.find('.openai-move-link').off('click').on('click', function(event) {
        event.preventDefault();
        const moveNumber = Number($(this).data('move-number'));
        const san = String($(this).data('san') || '').trim();
        jumpToHistoryMove(moveNumber, san);
    });
}

function jumpToHistoryMove(moveNumber, san, decisionFen, playedUci) {
    if (!historyReplay || !historyReplay.entry || !historyReplay.moves) return;
    stopHistoryPlayback();

    // La jugada d'un moment clau SEMPRE és del jugador (els moveReviews només es
    // generen per a les seves jugades). Per ressaltar-la fem servir l'UCI quan el
    // tenim (no és mai ambigu) i, si no, la SAN.
    const playerColor = (historyReplay.entry && historyReplay.entry.playerColor === 'b') ? 'b' : 'w';
    let playedMove = (playedUci && String(playedUci).trim()) || san || null;

    // La posició de decisió (FEN) és el localitzador més fiable. Quan el link la
    // porta incorporada, carreguem EXACTAMENT aquesta posició al tauler i fem servir
    // la jugada feta del mateix link per al ressaltat vermell. Això evita errors
    // d'índex en posicions repetides o quan el número/SAN no quadra, que feien que
    // vermell i verd acabessin apuntant a la mateixa jugada.
    let targetIndex = decisionFen ? findHistoryIndexByFen(decisionFen) : null;
    let beforeFen = decisionFen || null;

    // Normalitzem el torn de la FEN de decisió al color del jugador. Si la FEN ve
    // amb el costat equivocat (un defecte que es veia en algunes partides), ni la
    // teva jugada ni la millor parsegen sobre aquella posició i no es pintava res
    // (ni vermell ni verd). Forçar el torn ho arregla a l'arrel. A més, verifiquem
    // que la jugada del jugador es pot reconstruir sobre la posició; si no, descartem
    // la FEN i caiem a la reconstrucció per índex (replay real de la partida).
    if (beforeFen) {
        beforeFen = normalizeFenTurn(beforeFen, playerColor);
        if (!resolveMoveOnFen(beforeFen, playedMove || san || '')) {
            beforeFen = null;
        }
    }

    if (beforeFen) {
        try {
            historyReplay.game = new Chess(beforeFen);
            historyReplay.moveIndex = targetIndex && targetIndex > 0 ? Math.max(0, targetIndex - 1) : historyReplay.moveIndex;
        } catch (e) {
            beforeFen = null;
        }
    }

    if (!beforeFen) {
        if (targetIndex === null || targetIndex < 0) {
            targetIndex = findHistoryMoveIndex(moveNumber, san);
        }
        if (targetIndex === null || targetIndex < 0) {
            console.warn(`No s'ha trobat la jugada ${moveNumber} (${san})`);
            return;
        }

        // Resetegem el joc i avancem fins a la posició ABANS de la jugada errònia.
        historyReplay.game = new Chess();
        const stopAt = Math.max(0, targetIndex - 1);

        for (let i = 0; i < stopAt; i++) {
            const result = historyReplay.game.move(historyReplay.moves[i], { sloppy: true });
            if (!result) {
                console.warn(`Error aplicant jugada ${i}: ${historyReplay.moves[i]}`);
                break;
            }
        }

        historyReplay.moveIndex = stopAt;
        beforeFen = historyReplay.game.fen();
        if (!playedMove && targetIndex > 0) playedMove = historyReplay.moves[targetIndex - 1] || null;
    }

    // Marca el moment clau actiu (la teva jugada en vermell); la millor jugada
    // l'afegeix qui crida (el handler del link) via setKeyMomentBest.
    activeReviewHighlight = {
        beforeFen,
        played: playedMove,
        best: null
    };
    // La jugada de la qual parla el moment clau, per marcar-la a la transcripció.
    historyReplay.lastMove = null;
    historyReplay.keyMoveIdx = (targetIndex && targetIndex > 0 && targetIndex <= historyReplay.moves.length)
        ? targetIndex : null;
    updateHistoryBoard(); // reaplica els ressaltats actius
}

// Reaplica els ressaltats del moment clau actiu sobre el tauler. Es crida després
// de qualsevol redibuix (navegació o resize) perquè vermell i verd no es perdin
// ni quedin a mitges: sempre s'apliquen tots dos des de la mateixa font.
function applyReviewHighlights() {
    clearReviewHighlights();
    const h = activeReviewHighlight;
    if (!h || !h.beforeFen) { showReviewBoardLegend(false); return; }
    if (h.played) highlightReviewedMove(h.beforeFen, h.played, 'highlight-played');
    if (h.best) highlightReviewedMove(h.beforeFen, h.best, 'highlight-best');
    // Sense jugada vermella (moviment excepcional), la llegenda només mostra el verd.
    showReviewBoardLegend(!!h.best, { playedShown: !!h.played });
}

// Afegeix la millor jugada (verd) al moment clau actiu i la pinta.
function setKeyMomentBest(bestMove) {
    if (!activeReviewHighlight) return;
    activeReviewHighlight.best = bestMove || null;
    applyReviewHighlights();
}

function clearReviewHighlights() {
    $('#history-board .square-55d63').removeClass('highlight-hint highlight-played highlight-best highlight-played-from highlight-played-to highlight-best-from highlight-best-to highlight-overlap');
}

function showReviewBoardLegend(show, opts = {}) {
    const el = $('#review-board-legend');
    if (!el.length) return;
    el.toggle(!!show);
    if (!show) return;
    const playedShown = opts.playedShown !== false;
    const imported = !!(historyReplay && historyReplay.entry && historyEntryIsImported(historyReplay.entry));
    const playedEl = $('#review-legend-played');
    if (playedEl.length) {
        const sw = '<span class="sw" style="background:#6e0f0f; box-shadow: inset 0 0 0 2px #ff1744;"></span>';
        playedEl.html(sw + (imported ? 'jugada analitzada' : 'la teva jugada'));
        playedEl.toggle(playedShown);
    }
    const bestText = $('#review-legend-best-text');
    if (bestText.length) bestText.text(playedShown ? 'la millor jugada' : (imported ? 'moviment excepcional (era la millor)' : 'moviment excepcional (vas jugar la millor)'));
}

// Ressalta origen i destí d'un moviment sobre beforeFen amb la classe donada.
// No esborra ressaltats previs: així es poden marcar dues jugades alhora (la
// teva i la millor). chessboard.js marca les caselles amb data-square.
//
// Força el torn d'una FEN al color indicat ('w'/'b'). Si canvia el torn, anul·la
// la casella d'en passant (deixaria de ser vàlida). Retorna la FEN original si no
// es pot interpretar.
function normalizeFenTurn(fen, color) {
    const parts = String(fen || '').split(' ');
    if (parts.length < 2 || (color !== 'w' && color !== 'b')) return fen;
    if (parts[1] !== color) {
        parts[1] = color;
        if (parts.length >= 4) parts[3] = '-';
    }
    return parts.join(' ');
}

// Resol una jugada (UCI o SAN) sobre una FEN i retorna {from,to}. És tolerant:
// si no parseja amb el torn de la FEN, ho torna a provar amb el torn invertit.
// Així una FEN de decisió amb el costat equivocat no deixa la jugada sense
// ressaltar (era la causa que en algunes partides no sortís ni vermell ni verd).
function resolveMoveOnFen(fen, move) {
    const raw = String(move || '').trim();
    if (!fen || !raw) return null;
    const attempt = (f) => {
        try {
            const g = new Chess(f);
            const mv = /^[a-h][1-8][a-h][1-8][qrbn]?$/i.test(raw)
                ? g.move({ from: raw.slice(0, 2).toLowerCase(), to: raw.slice(2, 4).toLowerCase(), promotion: (raw[4] || 'q').toLowerCase() })
                : g.move(raw, { sloppy: true });
            return mv ? { from: mv.from, to: mv.to } : null;
        } catch (e) { return null; }
    };
    let mv = attempt(fen);
    if (mv) return mv;
    const parts = String(fen).split(' ');
    if (parts.length >= 2) {
        parts[1] = parts[1] === 'w' ? 'b' : 'w';
        if (parts.length >= 4) parts[3] = '-';
        mv = attempt(parts.join(' '));
    }
    return mv;
}

// El color FORT (vermell = la teva jugada, verd = la millor) marca TOT el
// moviment: la casella d'origen i la de destí. Així es veu clarament quina peça
// va moure malament (vermell) i quina hauria d'haver mogut (verd). Quan les dues
// jugades comparteixen una casella —típicament l'origen, perquè és la mateixa
// peça moguda de dues maneres— aquella casella surt mig vermella mig verda
// (highlight-overlap), però els dos destins queden ben diferenciats: el final
// erroni en vermell i el final bo en verd.
function highlightReviewedMove(beforeFen, move, cls) {
    const klass = cls || 'highlight-hint';
    if (!beforeFen || !move) return;
    try {
        const mv = resolveMoveOnFen(beforeFen, move);
        if (!mv) return;
        const fromEl = $("#history-board .square-55d63[data-square='" + mv.from + "']");
        const toEl = $("#history-board .square-55d63[data-square='" + mv.to + "']");
        // Color fort a origen i destí (la peça sencera).
        fromEl.addClass(klass + ' ' + klass + '-from');
        toEl.addClass(klass + ' ' + klass + '-to');
        // Qualsevol casella compartida per totes dues jugades (origen amb la
        // mateixa peça, o un destí coincident) es pinta mig i mig.
        if (fromEl.hasClass('highlight-played') && fromEl.hasClass('highlight-best')) fromEl.addClass('highlight-overlap');
        if (toEl.hasClass('highlight-played') && toEl.hasClass('highlight-best')) toEl.addClass('highlight-overlap');
    } catch (e) {}
}

// Localitza la jugada per la posició de decisió (FEN abans de la jugada). És el
// mètode més fiable perquè no depèn de coincidències de notació SAN ni del color.
// Retorna l'índex+1 (igual que findHistoryMoveIndex) o null.
function findHistoryIndexByFen(targetFen) {
    if (!targetFen || !historyReplay || !Array.isArray(historyReplay.moves)) return null;
    const key = f => String(f || '').split(' ').slice(0, 4).join(' '); // ignora comptadors
    const want = key(targetFen);
    try {
        const g = new Chess();
        if (key(g.fen()) === want) return 1; // decisió abans de la 1a jugada
        for (let i = 0; i < historyReplay.moves.length; i++) {
            const r = g.move(historyReplay.moves[i], { sloppy: true });
            if (!r) break;
            if (key(g.fen()) === want) return i + 2; // decisió just després d'aquest ply
        }
    } catch (e) {}
    return null;
}

function findHistoryMoveIndex(moveNumber, san) {
    if (!historyReplay || !Array.isArray(historyReplay.moves)) return null;
    const moves = historyReplay.moves;
    const normalizedSan = (san || '').trim().replace(/[+#!?]/g, ''); // Eliminar anotacions
    const sameSan = idx => idx >= 0 && idx < moves.length && moves[idx].replace(/[+#!?]/g, '') === normalizedSan;
    // L'error és SEMPRE una jugada del jugador: prioritzem el seu color per no
    // acabar en la jugada del rival quan la SAN no encaixa.
    const playerBlack = !!(historyReplay.entry && historyReplay.entry.playerColor === 'b');

    if (moveNumber) {
        const whiteIndex = (moveNumber - 1) * 2;
        const blackIndex = whiteIndex + 1;
        const primary = playerBlack ? blackIndex : whiteIndex;
        const secondary = playerBlack ? whiteIndex : blackIndex;
        // 1) SAN coincideix al ply del color del jugador (o sense SAN fiable).
        if (primary < moves.length && (!normalizedSan || sameSan(primary))) return primary + 1;
        // 2) SAN coincideix a l'altre color (per si el número balla).
        if (normalizedSan && sameSan(secondary)) return secondary + 1;
        // 3) Sense coincidència de SAN: cau igualment al ply del color del jugador.
        if (primary < moves.length) return primary + 1;
        if (secondary < moves.length) return secondary + 1;
    }

    // 4) Cerca per SAN a tot arreu (a prop del número si en tenim).
    if (normalizedSan) {
        for (let i = 0; i < moves.length; i++) {
            if (moves[i].replace(/[+#!?]/g, '') === normalizedSan) {
                if (!moveNumber || Math.abs(Math.ceil((i + 1) / 2) - moveNumber) <= 1) return i + 1;
            }
        }
    }
    return null;
}

function getSevereErrors(entries) {
    return (entries || [])
        .filter(entry => entry.quality === 'blunder' || (entry.swing || 0) >= 200)
        .map(entry => ({
            fen: entry.fen || null,
            moveNumber: entry.moveNumber || null,
            playerMove: entry.playerMove || null,
            playerMoveSan: entry.playerMoveSan || null,
            bestMove: entry.bestMove || null,
            bestMoveSan: entry.bestMoveSan || null,
            bestMovePv: entry.bestMovePv || [],
            bestMovePvSan: entry.bestMovePvSan || [],
            evalBefore: entry.evalBefore ?? null,
            evalAfter: entry.evalAfter ?? null,
            swing: entry.swing || null,
            isCapture: !!entry.isCapture,
            isCheck: !!entry.isCheck,
            depth: entry.depth || null,
            alternatives: entry.alternatives || [],
            quality: entry.quality || 'blunder',
            // Camps canònics + dades de forçament (per triar el llenguatge de
            // la PV: forçada / possible variant / sense prou dades).
            beforeFen: entry.beforeFen || entry.fen || null,
            playedMoveUci: entry.playedMoveUci || entry.playerMove || null,
            playedMoveSan: entry.playedMoveSan || entry.playerMoveSan || null,
            bestMoveUci: entry.bestMoveUci || entry.bestMove || null,
            evalAfterPlayed: entry.evalAfterPlayed ?? null,
            evalAfterBest: entry.evalAfterBest ?? null,
            cpLoss: entry.cpLoss ?? null,
            bestPv: entry.bestPv || entry.bestMovePv || [],
            playedPv: entry.playedPv || entry.refutationPv || [],
            refutationPv: entry.refutationPv || [],
            afterFen: entry.afterFen || null,
            multipvBefore: entry.multipvBefore || null,
            replyAlternatives: entry.replyAlternatives || null,
            forcingInfo: entry.forcingInfo || null
        }));
}

function getEntrySevereErrors(entry) {
    if (!entry) return [];
    if (Array.isArray(entry.severeErrors) && entry.severeErrors.length) {
        return entry.severeErrors;
    }
    if (Array.isArray(entry.review) && entry.review.length) {
        return getSevereErrors(entry.review);
    }
    return [];
}

// ═════════════════════════════════════════════════════════════════════════════
// MOMENT CLAU DE LA PARTIDA
// ═════════════════════════════════════════════════════════════════════════════
// La lògica de PUNTUACIÓ i SELECCIÓ és pura (core.js). Aquí es GENEREN els
// candidats a partir dels moveReviews (que ja són NOMÉS jugades de l'usuari) i
// es NORMALITZEN les avaluacions a la perspectiva de l'usuari: a moveReviews,
// evalBefore ja és perspectiva de l'usuari i evalAfter és perspectiva del rival
// (conveni de swing = evalBefore + evalAfter), de manera que evalAfter de
// l'usuari = −review.evalAfter i cpLoss (signat, positiu = pèrdua) = evalBefore
// + evalAfter. El mat viatja com a ±10000 (cpOf), un codi controlat.
function keyMomentEvalType(v) {
    return (typeof v === 'number' && Math.abs(v) >= 9000) ? 'mate' : 'cp';
}

function buildKeyMomentCandidates(entry) {
    const reviews = (entry && Array.isArray(entry.moveReviews)) ? entry.moveReviews : [];
    const candidates = [];
    for (const r of reviews) {
        if (!r || !r.fen) continue;
        const eb = (typeof r.evalBefore === 'number') ? r.evalBefore : null;
        const eaOpp = (typeof r.evalAfter === 'number') ? r.evalAfter : null; // perspectiva del rival
        const color = (r.color === 'b') ? 'b' : 'w';
        const moveNumber = Number(r.moveNumber) || null;
        // ply (mitja jugada, 1-based) derivat del número de jugada i el color.
        const ply = moveNumber ? (color === 'w' ? 2 * moveNumber - 1 : 2 * moveNumber) : null;
        // Nombre de jugades legals a la posició de decisió (per descartar jugades
        // obligades / amb una única opció legal).
        let legalCount = null;
        try { legalCount = new Chess(r.fen).moves().length; } catch (e) { legalCount = null; }
        const evalBeforeUser = eb;
        const evalAfterUser = (eaOpp === null) ? null : -eaOpp;
        const cpLoss = (eb === null || eaOpp === null) ? null : (eb + eaOpp);
        candidates.push({
            moveNumber: moveNumber,
            ply: ply,
            playerColor: color,
            fenBefore: r.fen,
            fenAfter: r.afterFen || null,
            playedMoveUci: r.playerMove || null,
            playedMoveSan: r.playerMoveSan || null,
            bestMoveUci: r.bestMove || null,
            bestMoveSan: r.bestMoveSan || null,
            bestPv: Array.isArray(r.bestMovePv) ? r.bestMovePv : [],
            evalBefore: evalBeforeUser,
            evalAfter: evalAfterUser,
            evalBeforeType: keyMomentEvalType(eb),
            evalAfterType: keyMomentEvalType(evalAfterUser),
            cpLoss: cpLoss,
            classification: r.quality || null,
            phase: (() => { try { return ElTaulerCore.phaseFromFen(r.fen); } catch (e) { return 'middlegame'; } })(),
            forcingInfo: r.forcingInfo || null,
            depth: (typeof r.depth === 'number') ? r.depth : null,
            // Alternatives del MultiPV, perspectiva de l'usuari (fenBefore = usuari mou).
            alternatives: Array.isArray(r.alternatives) ? r.alternatives.map(a => ({
                uci: a.move || null,
                san: a.moveSan || null,
                eval: (typeof a.eval === 'number') ? a.eval : null,
                evalType: a.evalType || 'cp',
                pv: a.pv || []
            })) : []
        });
    }
    return candidates;
}

// Calcula el moment clau (forma completa) d'una entrada, o null si no n'hi ha cap
// de prou rellevant. Selecció i explicació surten de dades verificables (core.js).
function computeKeyMoment(entry) {
    const candidates = buildKeyMomentCandidates(entry);
    if (!candidates.length) return null;
    return ElTaulerCore.selectKeyMoment(candidates, { minDepth: 10 });
}

// Forma COMPACTA per desar a l'historial (sense duplicar dades reconstruïbles).
function keyMomentToStored(km) {
    if (!km || !km.fen) return null;
    return {
        fen: km.fen,
        moveNumber: km.moveNumber || null,
        ply: km.ply || null,
        playerColor: km.playerColor || 'w',
        phase: km.phase || null,
        playedMoveSan: (km.playedMove && km.playedMove.san) || null,
        playedMoveUci: (km.playedMove && km.playedMove.uci) || null,
        bestMoveSan: (km.bestMove && km.bestMove.san) || null,
        bestMoveUci: (km.bestMove && km.bestMove.uci) || null,
        bestPv: Array.isArray(km.bestPv) ? km.bestPv.slice(0, 12) : [],
        evalBefore: (typeof km.evalBefore === 'number') ? km.evalBefore : null,
        evalAfter: (typeof km.evalAfter === 'number') ? km.evalAfter : null,
        cpLoss: (typeof km.cpLoss === 'number') ? km.cpLoss : null,
        classification: km.classification || null,
        reasonCode: km.reasonCode || null
    };
}

// Rehidrata la forma compacta a la forma completa per renderitzar (l'explicació
// i l'orientació són deterministes: no cal desar-les).
function keyMomentFromStored(s) {
    if (!s || !s.fen) return null;
    return Object.assign({}, s, {
        playedMove: { uci: s.playedMoveUci || null, san: s.playedMoveSan || null },
        bestMove: { uci: s.bestMoveUci || null, san: s.bestMoveSan || null },
        explanation: ElTaulerCore.keyMomentExplanation(s.reasonCode),
        orientation: s.playerColor === 'b' ? 'black' : 'white'
    });
}

// Moment clau d'una entrada per RENDERITZAR: el desat (compatible amb partides
// antigues sense keyMoment) o, si no n'hi ha, calculat a l'instant dels moveReviews.
function getEntryKeyMoment(entry) {
    if (!entry) return null;
    if (entry.keyMoment && entry.keyMoment.fen) return keyMomentFromStored(entry.keyMoment);
    try { return computeKeyMoment(entry); } catch (e) { return null; }
}

// ── Renderitzat de la secció «Moment clau» ───────────────────────────────────
function keyMomentEvalLabel(cp) {
    if (typeof cp !== 'number') return '—';
    if (cp >= 9000) return 'mat a favor';
    if (cp <= -9000) return 'mat en contra';
    const p = cp / 100;
    return (p > 0 ? '+' : '') + p.toFixed(2);
}
function keyMomentPhaseLabel(phase) {
    return phase === 'opening' ? "l'obertura" : (phase === 'endgame' ? 'el final' : 'el mig joc');
}
function keyMomentQualityLabel(q) {
    return ({ excel: 'excel·lent', good: 'bona', inaccuracy: 'imprecisió', mistake: 'error', blunder: 'errada greu' })[q] || 'error';
}

// HTML de la secció destacada. Retorna '' si la partida no té dades analitzades;
// si té anàlisi però cap decisió prou rellevant, mostra el missatge de «sense
// moment crític clar». La millor jugada i el FEN queden en desplegables (no a la
// vista per no desvelar la solució ni desbordar el mòbil).
function renderKeyMomentHtml(entry) {
    const hasAnalysis = !!(entry && ((entry.keyMoment && entry.keyMoment.fen) || historyEntryReviewCount(entry) > 0));
    if (!hasAnalysis) return '';
    const km = getEntryKeyMoment(entry);
    if (!km || !km.fen) {
        return `<div class="keymoment-card keymoment-empty"><div class="keymoment-title">🔑 Moment clau de la partida</div>`
            + `<p>No hi ha cap moment crític clar en aquesta partida.</p></div>`;
    }
    const num = km.moveNumber || '?';
    const phaseTxt = keyMomentPhaseLabel(km.phase);
    const playedSan = (km.playedMove && km.playedMove.san) ? escapeHtml(km.playedMove.san) : '—';
    const bestSan = (km.bestMove && km.bestMove.san) ? escapeHtml(km.bestMove.san) : '—';
    const evalTxt = `${keyMomentEvalLabel(km.evalBefore)} → ${keyMomentEvalLabel(km.evalAfter)}`;
    const qualityTxt = keyMomentQualityLabel(km.classification);
    const explanationRaw = km.explanation || '';
    // En incrustar l'explicació dins de la frase (després de la coma), la primera
    // lletra va en minúscula («…durant l'obertura, la posició era favorable…»).
    const explanationInline = escapeHtml(explanationRaw.charAt(0).toLowerCase() + explanationRaw.slice(1));
    const fenSafe = escapeHtml(km.fen);
    return `<div class="keymoment-card">
        <div class="keymoment-title">🔑 Moment clau de la partida</div>
        <p class="keymoment-lead">A la jugada <strong>${num}</strong>, durant ${escapeHtml(phaseTxt)}, ${explanationInline}</p>
        <div class="keymoment-meta">
            <span>La teva jugada: <strong>${playedSan}</strong></span>
            <span>Valoració: <strong>${escapeHtml(evalTxt)}</strong></span>
            <span>Classificació: <strong>${escapeHtml(qualityTxt)}</strong></span>
        </div>
        <div class="keymoment-actions">
            <button type="button" class="btn btn-primary keymoment-practice" aria-label="Practica aquest moment: torna a intentar la decisió">Practica aquest moment</button>
            <button type="button" class="btn btn-secondary keymoment-open-analysis" aria-label="Obre la posició al tauler d'anàlisi">Obre al tauler d'anàlisi</button>
            <button type="button" class="btn btn-secondary keymoment-copy-fen" data-fen="${fenSafe}" aria-label="Copia el FEN de la posició al porta-retalls">Copiar FEN</button>
        </div>
        <details class="keymoment-reveal">
            <summary>Mostra la millor jugada</summary>
            <div class="keymoment-reveal-body">La millor jugada era <strong>${bestSan}</strong>.</div>
        </details>
        <details class="keymoment-fen">
            <summary>Mostra el FEN</summary>
            <code class="keymoment-fen-text">${fenSafe}</code>
        </details>
    </div>`;
}

// ── Còpia del FEN (amb sistema alternatiu i confirmació no intrusiva) ─────────
async function copyKeyMomentFen(fen) {
    const text = String(fen || '').trim();
    if (!text) return;
    try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            await navigator.clipboard.writeText(text);
            showToast('FEN copiat.', 'success');
            return;
        }
    } catch (e) {}
    // Alternativa sense navigator.clipboard: camp temporal + execCommand.
    try {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.setAttribute('readonly', '');
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        const ok = document.execCommand && document.execCommand('copy');
        document.body.removeChild(ta);
        showToast(ok ? 'FEN copiat.' : 'No s\'ha pogut copiar; selecciona el text manualment.', ok ? 'success' : 'warn');
    } catch (e) {
        showToast('No s\'ha pogut copiar; selecciona el text manualment.', 'warn');
    }
}

// ── Importa el moment clau al tauler d'anàlisi ───────────────────────────────
// Transfereix el FEN i les metadades per ESTAT central de l'app (no per URL ni
// Firebase). No modifica la partida ni l'historial.
let keyMomentPendingImport = null;
function openKeyMomentInAnalysis(km) {
    if (!km || !km.fen) return;
    keyMomentPendingImport = {
        fen: km.fen,
        orientation: km.orientation || (km.playerColor === 'b' ? 'black' : 'white'),
        moveNumber: km.moveNumber || null
    };
    openExplorer(km.fen, {
        orientation: keyMomentPendingImport.orientation,
        importNote: `Posició importada del moment clau de la partida${km.moveNumber ? ` (jugada ${km.moveNumber})` : ''}.`
    });
}

// ── Nota d'importació al tauler d'anàlisi ────────────────────────────────────
function showExplorerImportNote(text) {
    const el = document.getElementById('explorer-import-note');
    if (!el) return;
    if (text) { el.textContent = text; el.style.display = ''; }
    else { el.style.display = 'none'; el.textContent = ''; }
}

// ── Mode de pràctica del moment clau ─────────────────────────────────────────
function keyMomentPracticePrompt(km) {
    return `Practica el moment clau: mouen ${km.playerColor === 'b' ? 'les negres' : 'les blanques'}. Troba la millor jugada i mou-la al tauler.`;
}

function startKeyMomentPractice(km) {
    if (!km || !km.fen) return;
    explorerPractice = { active: true, km: km, answered: false };
    keyMomentPendingImport = null;
    openExplorer(km.fen, {
        orientation: km.orientation || (km.playerColor === 'b' ? 'black' : 'white'),
        practiceNote: keyMomentPracticePrompt(km)
    });
}

function setKeyMomentPracticeBanner(text, tone, showRetry) {
    const el = document.getElementById('explorer-keymoment');
    if (!el) return;
    el.style.display = '';
    el.className = 'explorer-keymoment tone-' + (tone || 'info');
    const retry = showRetry
        ? '<button type="button" class="btn btn-secondary keymoment-retry" style="margin-top:8px;">Torna-ho a intentar</button>'
        : '';
    el.innerHTML = `<span class="explorer-keymoment-text" role="status" aria-live="polite">${escapeHtml(text)}</span>${retry}`;
    const rb = el.querySelector('.keymoment-retry');
    if (rb) rb.addEventListener('click', retryKeyMomentPractice);
}

function retryKeyMomentPractice() {
    if (!explorerPractice.active || !explorerPractice.km) return;
    explorerPractice.answered = false;
    setupExplorerPosition(explorerPractice.km.fen, { orientation: explorerPractice.km.orientation });
    setKeyMomentPracticeBanner(keyMomentPracticePrompt(explorerPractice.km), 'info', false);
}

function hideKeyMomentPracticeBanner() {
    explorerPractice = { active: false, km: null, answered: false };
    const el = document.getElementById('explorer-keymoment');
    if (el) { el.style.display = 'none'; el.innerHTML = ''; }
}

// Avalua l'intent de l'usuari i dona resposta pedagògica (reutilitza el motor i
// la classificació pura de core.js). No revela la millor jugada fins després.
async function evaluateKeyMomentAttempt(attemptUci, fenAfter) {
    if (!explorerPractice.active || explorerPractice.answered) return;
    explorerPractice.answered = true;
    const km = explorerPractice.km;
    if (!km) return;
    let verdict;
    if (attemptUci === (km.bestMove && km.bestMove.uci)) {
        verdict = ElTaulerCore.classifyPracticeAttempt({ attemptUci, bestUci: km.bestMove.uci });
    } else {
        setKeyMomentPracticeBanner('Avaluant la teva jugada…', 'info', false);
        let attemptCpUser = null;
        try {
            const res = await analyzeFenRobust(fenAfter, 14, 1, 3000, () => !explorerPractice.active);
            if (res && res.bestMove) {
                const oppCp = res.bestMove.evalType === 'mate' ? (res.bestMove.eval > 0 ? 10000 : -10000) : res.bestMove.eval;
                if (typeof oppCp === 'number') attemptCpUser = -oppCp; // perspectiva de l'usuari
            }
        } catch (e) {}
        verdict = ElTaulerCore.classifyPracticeAttempt({
            attemptUci,
            bestUci: km.bestMove && km.bestMove.uci,
            playedGameUci: km.playedMove && km.playedMove.uci,
            attemptCpUser,
            bestCpUser: km.evalBefore,
            playedGameCpUser: km.evalAfter,
            alternatives: [],
            equivalentCp: 40
        });
    }
    if (!explorerPractice.active) return;
    const tone = (verdict.code === 'best' || verdict.code === 'equivalent') ? 'success'
        : (verdict.code === 'better_not_best' ? 'info' : 'warn');
    const bestSan = (km.bestMove && km.bestMove.san) ? km.bestMove.san : null;
    const reveal = bestSan ? ` La millor jugada era ${bestSan}.` : '';
    setKeyMomentPracticeBanner(verdict.text + reveal, tone, true);
}

// Clau d'una errada o d'un moment clau (posició de decisió + jugada feta),
// compartida amb core.js, per no repetir la mateixa errada a "Moments clau"
// i a "Errades comentades".
function reviewErrorKey(err) {
    return ElTaulerCore.reviewErrorKey(err);
}

// Nombre real de jugades (numeració completa) d'una partida de l'historial,
// per rebutjar errades amb un número de jugada impossible.
function entryMaxMoveNumber(entry) {
    let plies = 0;
    try { plies = getHistoryMoves(entry).length; } catch (e) { plies = 0; }
    if (plies) return Math.ceil(plies / 2);
    // Entrades antigues sense llista de jugades: el sostre és el darrer review.
    let max = 0;
    if (entry && Array.isArray(entry.moveReviews)) {
        entry.moveReviews.forEach(r => { if (r && Number(r.moveNumber) > max) max = Number(r.moveNumber); });
    }
    return max || null;
}

// Opcions de validació calculades UNA vegada per entrada (getHistoryMoves pot
// haver de reparsejar el PGN), per passar-les a totes les errades d'un bucle.
function reviewErrorValidationOpts(entry) {
    let moves = [];
    try { moves = getHistoryMoves(entry) || []; } catch (e) { moves = []; }
    return {
        maxMoveNumber: moves.length ? Math.ceil(moves.length / 2) : entryMaxMoveNumber(entry),
        // Legalitat sobre la FEN de decisió: resolveMoveOnFen ja tolera el torn
        // invertit (equivalent a normalitzar amb normalizeFenTurn).
        applyMove: (fen, move) => !!resolveMoveOnFen(fen, move),
        // Identitat de la jugada (reviewMoveIdentityOk): la SAN recalculada amb
        // chess.js ha de coincidir amb la jugada real de la partida al ply del
        // número de jugada. Sense llista de jugades (partides antigues), no es
        // pot contradir res i no es descarta.
        playerColor: (entry && entry.playerColor === 'b') ? 'b' : 'w',
        historySanAt: (ply) => (ply >= 0 && ply < moves.length ? moves[ply] : null),
        sanForMove: (fen, move) => sanOnFen(fen, move)
    };
}

// Validació forta abans de mostrar una errada: FEN present i interpretable,
// número de jugada dins de la partida real, jugada feta i millor jugada legals
// sobre la FEN i diferents entre elles, i IDENTITAT amb la partida real (cap
// "Jugada 14 · Nh4" si al PGN la jugada 14 és Ne4). La lògica viu a core.js;
// aquí hi injectem chess.js i les dades reals de la partida.
function isRenderableReviewError(entry, err, opts) {
    if (!err) return false;
    const o = opts || reviewErrorValidationOpts(entry);
    const color = (entry && entry.playerColor === 'b') ? 'b' : 'w';
    const fen = err.fen ? normalizeFenTurn(err.fen, color) : null;
    // Errades antigues sense moveNumber: es deriva del comptador de la FEN
    // (mateix criteri que describeSevereError) en lloc de descartar-les.
    let moveNumber = err.moveNumber;
    if (!moveNumber && fen) {
        const n = parseInt(String(fen).split(' ')[5], 10);
        if (isFinite(n) && n > 0) moveNumber = n;
    }
    const normalized = Object.assign({}, err, { fen, moveNumber });
    return ElTaulerCore.isRenderableReviewError(normalized, o)
        && ElTaulerCore.reviewMoveIdentityOk(normalized, o);
}

// Errades per comentar a la revisió, garantint un mínim (per defecte 3) si la
// partida en té prou: primer les greus i, si calen més, les pitjors imprecisions
// o errors dels moveReviews. Mai no inventa errades que no s'hagin produït, i
// cap errada incoherent (FEN o jugades invàlides) no arriba a la ressenya.
function getEntryReviewErrors(entry, minCount = 3, maxCount = 5) {
    if (!entry) return [];
    const validationOpts = reviewErrorValidationOpts(entry);
    const result = (getEntrySevereErrors(entry) || [])
        .filter(e => isRenderableReviewError(entry, e, validationOpts));
    const seen = new Set(result.map(e => e.fen).filter(Boolean));
    if (result.length < minCount && Array.isArray(entry.moveReviews)) {
        const extra = entry.moveReviews
            .filter(r => r && r.fen && !seen.has(r.fen) && ['inaccuracy', 'mistake', 'blunder'].includes(r.quality))
            .sort((a, b) => (b.swing || 0) - (a.swing || 0))
            .map(r => ({
                fen: r.fen,
                moveNumber: r.moveNumber || null,
                playerMove: r.playerMove || null,
                playerMoveSan: r.playerMoveSan || null,
                bestMove: r.bestMove || null,
                bestMoveSan: r.bestMoveSan || null,
                bestMovePv: r.bestMovePv || [],
                evalBefore: r.evalBefore ?? null,
                evalAfter: r.evalAfter ?? null,
                swing: r.swing || null,
                alternatives: r.alternatives || [],
                refutationPv: r.refutationPv || [],
                afterFen: r.afterFen || null,
                multipvBefore: r.multipvBefore || null,
                replyAlternatives: r.replyAlternatives || null,
                evalAfterBest: r.evalAfterBest ?? null,
                forcingInfo: r.forcingInfo || null,
                quality: r.quality || 'inaccuracy',
                severity: r.quality === 'blunder' ? 'high' : 'med'
            }))
            .filter(e => isRenderableReviewError(entry, e, validationOpts));
        for (const e of extra) {
            if (result.length >= minCount) break;
            result.push(e);
            seen.add(e.fen);
        }
    }
    return result.slice(0, Math.max(minCount, maxCount));
}

/* ===================== ERRADES COMENTADES (OpenAI) =====================
   Explicació breu i individual per a cada errada greu de la partida. Es
   genera automàticament (el cost per crida ho permet), es guarda dins de
   l'entrada de l'historial (entry.errorNotes, indexat per FEN) i per tant
   persisteix amb gameHistory a localStorage. */

const ERROR_NOTES_MAX = 4;

// Converteix UCI a SAN quan cal; si ja sembla SAN, es retorna tal qual.
function uciToSanSafe(fen, moveStr) {
    if (!moveStr) return null;
    if (!/^[a-h][1-8][a-h][1-8][qrbn]?$/i.test(moveStr)) return moveStr;
    try {
        const g = new Chess(fen);
        const mv = g.move({ from: moveStr.slice(0, 2).toLowerCase(), to: moveStr.slice(2, 4).toLowerCase(), promotion: (moveStr[4] || 'q').toLowerCase() });
        return mv ? mv.san : moveStr;
    } catch (e) { return moveStr; }
}

function describeSevereError(err) {
    const parts = (err.fen || '').split(' ');
    return {
        moveNumber: err.moveNumber || parseInt(parts[5], 10) || '?',
        // La SAN que es mostra es recalcula SEMPRE amb chess.js sobre la FEN
        // (la UCI primer, que és la dada de motor): una SAN desada antiga no
        // pot contradir mai el tauler. Les cadenes desades són l'últim recurs.
        played: sanOnFen(err.fen, err.playerMove || err.playerMoveSan)
            || uciToSanSafe(err.fen, err.playerMoveSan || err.playerMove) || '?',
        best: sanOnFen(err.fen, err.bestMove || err.bestMoveSan)
            || uciToSanSafe(err.fen, err.bestMoveSan || err.bestMove) || '?',
        pv: (err.bestMovePvSan || err.bestMovePv || []).slice(0, 4).map(m => uciToSanSafe(err.fen, m)).join(' ')
    };
}

function getMoveSquareContext(fen, moveStr) {
    if (!fen || !moveStr) return null;
    const raw = String(moveStr).trim();
    try {
        const g = new Chess(fen);
        let mv = null;
        if (/^[a-h][1-8][a-h][1-8][qrbn]?$/i.test(raw)) {
            mv = g.move({ from: raw.slice(0, 2).toLowerCase(), to: raw.slice(2, 4).toLowerCase(), promotion: (raw[4] || 'q').toLowerCase() });
        } else {
            mv = g.move(raw, { sloppy: true });
        }
        if (!mv) return null;
        const names = { p: 'peó', n: 'cavall', b: 'alfil', r: 'torre', q: 'dama', k: 'rei' };
        return { piece: names[mv.piece] || 'peça', from: mv.from, to: mv.to, san: mv.san };
    } catch (e) { return null; }
}

function buildErrorNotePrompt(err) {
    const d = describeSevereError(err);
    const playedCtx = getMoveSquareContext(err.fen, err.playerMove || err.playerMoveSan);
    const bestCtx = getMoveSquareContext(err.fen, err.bestMove || err.bestMoveSan);
    const coordLine = [
        playedCtx ? `Jugada errònia: ${playedCtx.piece} ${playedCtx.from}-${playedCtx.to}` : '',
        bestCtx ? `Millor jugada: ${bestCtx.piece} ${bestCtx.from}-${bestCtx.to}` : ''
    ].filter(Boolean).join('\n');
    // La PV del motor es presenta amb el llenguatge que les dades permeten: si
    // no està demostrat que és forçada, es diu explícitament al model que no
    // pot dir "forçat" ni "obligat".
    let pvLine = '';
    if (d.pv) {
        const fi = reviewForcingInfo(err);
        const lang = ElTaulerCore.classifyPvLanguage({
            bestPv: err.bestPv || err.bestMovePv || [],
            forcingInfo: fi
        });
        if (lang === 'forced') pvLine = `\nSeqüència forçada després de la millor jugada: ${d.pv}`;
        else if (lang === 'illustrative') {
            pvLine = (fi && fi.allRepliesLosing)
                ? `\nUna possible variant del motor (NO és forçada, però qualsevol resposta del rival el deixava perdut): ${d.pv}`
                : `\nUna possible variant del motor (el rival tenia altres opcions; NO és forçada): ${d.pv}`;
        }
    }
    return `Ets un entrenador d'escacs directe i clar que parla en català i tuteja l'alumne.
Posició abans de la jugada (FEN): ${err.fen}
A la jugada ${d.moveNumber} l'alumne va jugar ${d.played}, però la millor jugada era ${d.best}.${pvLine}
${coordLine ? `\n${coordLine}` : ''}

Explica l'errada en 2 frases curtes (màxim 45 paraules).

REGLES OBLIGATÒRIES
- Escriu només noms de peces i caselles amb lletra+número (exemples: cavall f3, dama h5, de e2 a e4).
- No escriguis notació algebraica/SAN com Nxe5, Qh5+, O-O ni símbols com +, #, ! o ?.
- No facis servir llistes, markdown ni cometes.
- No diguis mai que una jugada era "forçada", "obligada" o "l'única" si les dades d'aquí sobre no ho indiquen.
- No inventis jugades que no es dedueixin de la posició.${coachStyleRulesBlock()}`;
}

function getErrorNoteKey(err) { return err && err.fen ? err.fen : ''; }

// Localitza el moveReview complet (alternatives, swing, SAN, eval...) que
// correspon a una errada desada, per donar a l'explicació local el màxim context.
function findMoveReviewForError(entry, err) {
    if (!entry || !Array.isArray(entry.moveReviews) || !err || !err.fen) return null;
    return entry.moveReviews.find(r => r && r.fen === err.fen) || null;
}

// Explicació rica d'una errada generada LOCALMENT (sense OpenAI): fets posicionals
// concrets, diagnòstic segons tema i gravetat, el pla correcte, la continuació de
// la línia i una pregunta de reflexió. Reaprofita el banc de plans humans.
function buildLocalErrorNote(err, entry, opts = {}) {
    if (!err) return 'Errada detectada en aquesta posició.';
    const voiceStyle = getReviewVoiceStyle(opts.voiceStyle);
    const d = describeSevereError(err);
    const mr = findMoveReviewForError(entry, err);
    const review = mr || {
        fen: err.fen,
        moveNumber: err.moveNumber,
        playerMove: err.playerMove,
        playerMoveSan: err.playerMoveSan,
        bestMove: err.bestMove,
        bestMoveSan: err.bestMoveSan,
        bestMovePv: err.bestMovePv || [],
        alternatives: err.alternatives || [],
        swing: typeof err.swing === 'number' ? err.swing : 0,
        evalBefore: err.evalBefore ?? null,
        evalAfter: err.evalAfter ?? null,
        refutationPv: err.refutationPv || [],
        afterFen: err.afterFen || null,
        forcingInfo: err.forcingInfo || null,
        multipvBefore: err.multipvBefore || null,
        replyAlternatives: err.replyAlternatives || null,
        evalAfterBest: err.evalAfterBest ?? null,
        quality: err.quality || (err.severity === 'high' ? 'blunder' : 'mistake')
    };
    let ctx = null;
    try { ctx = buildPlanContext(review); } catch (e) { ctx = null; }
    const themeKey = detectPlanSubtheme(review, ctx);
    const moment = {
        moveNumber: review.moveNumber || d.moveNumber,
        phase: phaseFromContext(ctx, review.moveNumber),
        themeKey,
        theme: planThemeDisplayLabel(themeKey),
        played: review.playerMoveSan || d.played,
        best: review.bestMoveSan || d.best,
        playedDesc: moveHumanText(err.fen, err.playerMove || review.playerMoveSan, d.played),
        bestDesc: moveHumanText(err.fen, err.bestMove || review.bestMoveSan, d.best),
        playedRef: 'la jugada triada',
        bestRef: 'la millor jugada',
        bestMoveUci: review.bestMove || null,
        swing: Math.round(review.swing || 0),
        quality: review.quality || 'mistake',
        evalBefore: review.evalBefore ?? null,
        evalAfter: review.evalAfter ?? null,
        refutationPv: Array.isArray(review.refutationPv) ? review.refutationPv : [],
        afterFen: review.afterFen || null,
        forcingInfo: review.forcingInfo || null,
        multipvBefore: review.multipvBefore || null,
        replyAlternatives: review.replyAlternatives || null,
        evalAfterBest: review.evalAfterBest ?? null,
        fen: review.fen,
        pv: Array.isArray(review.bestMovePv) ? review.bestMovePv : [],
        positional: buildPositionalNote(ctx),
        candidates: buildCandidatesNote(review, voiceStyle)
    };
    let plan = {};
    try { plan = buildLocalHumanPlan(moment); } catch (e) { plan = {}; }
    const structured = buildStructuredLocalExplanation(moment, plan, opts);
    const show = coachSectionsFor(moment.quality);
    const parts = [];
    // Cada camp només s'afegeix si és una frase completa: una línia tallada
    // ("en lloc de…") no es mostra. Millor menys text que text trencat.
    const addPart = (visible, value, label) => {
        const v = String(value || '').trim();
        if (!visible || !v || isIncompleteCoachText(v)) return;
        parts.push(label ? `${label}: ${v}` : v);
    };
    addPart(show.fact, structured.fact, 'Posició');
    addPart(show.mistake, structured.mistake, 'Què va fallar');
    addPart(show.consequence, structured.consequence, 'Conseqüència');
    addPart(show.refutation, structured.refutation);
    addPart(show.plan, structured.plan, 'Pla millor');
    addPart(show.continuation, structured.continuation, 'Moviments següents');
    addPart(show.candidates, moment.candidates);
    addPart(show.question, structured.question, 'Pregunta clau');
    // A l'exportació (full) posem cada camp en una línia; a pantalla, en línia seguida.
    const text = parts.join(opts.full ? '\n' : ' ').trim();
    return text || voiceText(voiceStyle, 'safeFallback');
}

// =================== NOMENCLATURA DESCRIPTIVA + ENLLAÇOS ===================
// Descriu un moviment amb llenguatge planer (nom i COLOR de la peça, casella
// d'origen si cal desambiguar, columna del peó) en comptes de notació
// algebraica, perquè sigui llegible per a algú sense coneixements de
// nomenclatura. Retorna també la SAN i les caselles origen/destí per poder
// visualitzar la jugada al tauler.

// Ajudants de tauler compartits (core.js + chess.js) per verificar PV i
// descriure moviments. Cache d'una sola instància.
let pvBoardHelpersCache = null;
function getPvBoardHelpers() {
    if (!pvBoardHelpersCache && typeof Chess !== 'undefined') {
        try { pvBoardHelpersCache = ElTaulerCore.createPvBoardHelpers(Chess); } catch (e) {}
    }
    return pvBoardHelpersCache;
}

function describeMoveHuman(fen, move) {
    if (!fen || !move) return null;
    try {
        const helpers = getPvBoardHelpers();
        const facts = helpers ? helpers.moveFacts(fen, move) : null;
        if (!facts) return null;
        // La redacció catalana (color de la peça, peça capturada, escac...) viu
        // al redactor normatiu, que és pur i testejat: "la dama blanca captura
        // el peó a h7 amb escac", "el rei negre captura la dama a h7".
        const text = (typeof ElTaulerRedactor !== 'undefined' && ElTaulerRedactor.descriuMovimentFets)
            ? ElTaulerRedactor.descriuMovimentFets(facts)
            : null;
        if (!text) return null;
        return { text, san: facts.san, from: facts.origen, to: facts.desti };
    } catch (e) { return null; }
}

// Text descriptiu curt d'un moviment (només el text), amb la SAN com a fallback.
function moveHumanText(fen, move, fallback) {
    const d = describeMoveHuman(fen, move);
    return d ? d.text : (fallback || uciToSanSafe(fen, move) || String(move || ''));
}

// SAN real d'una jugada (UCI o SAN) recalculada amb chess.js sobre la FEN de
// decisió. És la font de veritat per MOSTRAR jugades: mai no es confia en una
// SAN desada que no es pugui verificar. Retorna null si la jugada no és legal.
function sanOnFen(fen, move) {
    try {
        const helpers = getPvBoardHelpers();
        const facts = helpers ? helpers.moveFacts(fen, move) : null;
        return facts ? facts.san : null;
    } catch (e) { return null; }
}

// Afegeix la notació SAN entre parèntesis darrere la descripció planera, perquè
// el text sigui verificable contra el tauler i el motor ("...captura a d8 (Rxd8)").
function withSan(humanText, san) {
    const h = String(humanText || '').trim();
    const s = String(san || '').trim();
    if (!s || s === '—' || s === '?' || s === h) return h;
    if (h.indexOf(s) !== -1) return h; // la descripció ja porta la SAN
    return `${h} (${s})`;
}

// =================== ANÀLISI PER FASES DE LA PARTIDA ===================
function classifyPhaseByMoveNumber(n) {
    const num = n || 0;
    if (num <= 10) return 'opening';
    if (num <= 28) return 'middlegame';
    return 'endgame';
}

// Precisió i temes d'error per fase (obertura / mig joc / final) a partir dels
// moveReviews desats de la partida.
function buildPhaseStats(entry) {
    const reviews = Array.isArray(entry?.moveReviews) ? entry.moveReviews : [];
    const mk = () => ({ good: 0, total: 0, errs: [] });
    const phases = { opening: mk(), middlegame: mk(), endgame: mk() };
    reviews.forEach(r => {
        if (!r) return;
        const p = phases[classifyPhaseByMoveNumber(r.moveNumber)];
        p.total++;
        if (r.quality === 'excel' || r.quality === 'good') p.good++;
        if (r.quality === 'inaccuracy' || r.quality === 'mistake' || r.quality === 'blunder') p.errs.push(r);
    });
    const summarize = (p) => {
        const themeCounts = {};
        p.errs.forEach(r => {
            let key = 'general';
            try { key = detectPlanSubtheme(r); } catch (e) { key = 'general'; }
            const label = planThemeDisplayLabel(key);
            themeCounts[label] = (themeCounts[label] || 0) + 1;
        });
        const themes = Object.keys(themeCounts)
            .sort((a, b) => themeCounts[b] - themeCounts[a])
            .slice(0, 2);
        return {
            precision: p.total > 0 ? Math.round((p.good / p.total) * 100) : null,
            total: p.total,
            errors: p.errs.length,
            themes
        };
    };
    return { opening: summarize(phases.opening), middlegame: summarize(phases.middlegame), endgame: summarize(phases.endgame) };
}

// Comentari de millora segons els temes d'error d'una fase (reaprofita el banc de
// plans humans). Si no hi ha temes concrets, dona un consell genèric de la fase
// en el registre de la veu triada. A les veus casual i tècnica el consell de
// fase és sempre el de la seva veu (el detall del tema ja surt al costat).
function buildPhaseAdvice(themes, phaseKey, voiceStyle) {
    const style = getReviewVoiceStyle(voiceStyle);
    const advices = REVIEW_VOICE_TEXT[style].phaseAdvice || REVIEW_VOICE_TEXT.balanced.phaseAdvice;
    const fallback = advices[phaseKey] || REVIEW_VOICE_TEXT.balanced.phaseAdvice[phaseKey] || '';
    if (!themes || !themes.length || style !== 'balanced') return fallback;
    const labelToKey = {};
    Object.keys(HUMAN_PLAN_BANK).forEach(k => { labelToKey[planThemeDisplayLabel(k)] = k; });
    const key = labelToKey[themes[0]];
    const pool = (key && HUMAN_PLAN_BANK[key] && HUMAN_PLAN_BANK[key].objective) ? HUMAN_PLAN_BANK[key].objective : null;
    if (pool && pool.length) {
        const tip = fillPlanTemplate(pickFreshPlanLine(pool, `phaseadvice:${phaseKey}:${key}`), {});
        if (tip) return tip;
    }
    return fallback;
}

/* =================== GRÀFIC DE PRECISIÓ PER FASES + REPTE «REJUGAR +5%» ===================
   Al detall de cada partida de l'historial es dibuixa un gràfic (SVG propi, sense
   llibreries): eix vertical = % d'encert ACUMULAT (la mateixa mètrica que la barra
   de precisió en viu), eix horitzontal = número de moviment de l'usuari, amb les
   tres franges de la partida (obertura / mig joc / final). Sota el gràfic, cada
   fase té la seva fitxa amb el % aconseguit i el botó «Rejugar +5%», que porta el
   jugador a la primera jugada de la fase per rejugar-la contra el motor amb un
   objectiu un 5% més alt del que va aconseguir a la partida original. */

const PHASE_REPLAY_BONUS = 5;
// Si la partida original era amb rellotge, la fase es rejuga amb rellotge:
// cada bàndol rep aquesta fracció del temps total del ritme original.
const PHASE_REPLAY_CLOCK_FRACTION = 0.3;
const PHASE_DISPLAY_LABELS = { opening: 'Obertura', middlegame: 'Mig joc', endgame: 'Final' };
const HISTORY_ICON_SVG = '<svg class="btn-ic" aria-hidden="true"><use href="#ic-history"/></svg>';

// Estat del repte «Rejugar +5%»: el pla pendent (el consumeix startGame) i el repte viu.
let phaseReplayPending = null;
let phaseReplayState = null;

// Línia temporal de les jugades del jugador amb la precisió acumulada després de
// cada una (bona = excel·lent o bona, com a la barra de precisió en viu).
function computeHistoryMoveTimeline(entry) {
    const reviews = Array.isArray(entry?.moveReviews) ? entry.moveReviews.slice() : [];
    reviews.sort((a, b) => (Number(a?.moveNumber) || 0) - (Number(b?.moveNumber) || 0));
    const out = [];
    let good = 0, total = 0;
    reviews.forEach(r => {
        if (!r || !r.quality) return;
        total++;
        if (r.quality === 'excel' || r.quality === 'good') good++;
        out.push({
            idx: total,
            moveNumber: Number(r.moveNumber) || total,
            quality: r.quality,
            phase: classifyPhaseByMoveNumber(Number(r.moveNumber) || total),
            cumPct: Math.round((good / total) * 100),
            review: r
        });
    });
    return out;
}

// Converteix una puntuació del MultiPV desat ({eval, evalType}) a centipeons.
function multipvScoreToCp(item) {
    if (!item || typeof item.eval !== 'number') return null;
    if (item.evalType === 'mate') {
        const n = Math.min(Math.abs(item.eval), 50);
        return item.eval > 0 ? 10000 - n * 10 : -10000 + n * 10;
    }
    return item.eval;
}

// Diferència (en cp) entre la millor jugada i la segona opció del motor en la
// posició de decisió. Serveix per detectar moviments excepcionals: si el marge
// és gran, trobar la millor jugada tenia mèrit de debò.
function reviewBestSecondGap(r) {
    const multi = Array.isArray(r?.multipvBefore) ? r.multipvBefore : [];
    if (multi.length >= 2) {
        const cps = multi.map(multipvScoreToCp).filter(v => typeof v === 'number');
        if (cps.length >= 2) return cps[0] - cps[1];
    }
    // Entrades sense MultiPV cru: la millor puntuació és evalBefore i les
    // alternatives desades són les opcions 2 i 3 del motor.
    const alts = Array.isArray(r?.alternatives) ? r.alternatives : [];
    if (alts.length && typeof r.evalBefore === 'number' && typeof alts[0].eval === 'number') {
        return r.evalBefore - alts[0].eval;
    }
    return null;
}

// Moviment excepcional: el jugador va trobar EXACTAMENT la millor jugada del
// motor en una posició on la segona opció era clarament pitjor. Mai no s'inventa:
// sense dades de MultiPV/alternatives no es marca res.
const BRILLIANT_MIN_GAP_CP = 150;
function isBrilliantReview(r) {
    if (!r || r.quality !== 'excel' || !r.fen) return false;
    const played = String(r.playerMove || '').toLowerCase().trim();
    const best = String(r.bestMove || '').toLowerCase().trim();
    if (!played || !best || played !== best) return false;
    const gap = reviewBestSecondGap(r);
    return typeof gap === 'number' && gap >= BRILLIANT_MIN_GAP_CP;
}

function selectBrilliantReviews(entry, maxCount = 2) {
    const reviews = Array.isArray(entry?.moveReviews) ? entry.moveReviews : [];
    return reviews
        .filter(isBrilliantReview)
        .sort((a, b) => (reviewBestSecondGap(b) || 0) - (reviewBestSecondGap(a) || 0))
        .slice(0, maxCount);
}

// Ítems de "Moments clau" per als moviments excepcionals: frase verificada per
// veu, insígnia verda i enllaç que marca NOMÉS la jugada feta (en verd) al tauler.
function buildBrilliantMomentItems(entry, voiceStyle, opts = {}) {
    const imported = !!opts.imported;
    const actor = opts.actor || 'el jugador analitzat';
    return selectBrilliantReviews(entry).map(r => {
        const phrase = r.fen ? bestPhraseByVoice(r.fen, r.playerMove || r.playerMoveSan, voiceStyle) : null;
        if (!phrase) return null;
        const san = sanOnFen(r.fen, r.playerMove) || r.playerMoveSan || '';
        const gap = reviewBestSecondGap(r) || 0;
        const link = `<a href="#" class="hist-brilliant-link" data-move-number="${r.moveNumber || ''}" data-san="${escapeHtml(san)}" data-uci="${escapeHtml(r.playerMove || '')}" data-fen="${escapeHtml(r.fen || '')}">${escapeHtml(phrase.body)}</a>`;
        const badge = coachQualityBadgeHtml({ quality: 'excel', swing: 0 });
        const why = gap >= 800
            ? 'Era pràcticament l\'única jugada bona en aquella posició.'
            : `La segona millor opció del motor quedava clarament per sota (uns ${(gap / 100).toFixed(1)} peons de diferència).`;
        let sentence = imported
            ? `${escapeHtml(actor)} va trobar la millor jugada: ${link}.`
            : `vas trobar la millor jugada: ${link}.`;
        const audit = ElTaulerCore.auditReviewVoiceText(String(sentence + ' ' + why).replace(/<[^>]*>/g, ' '), voiceStyle);
        const tail = audit.ok ? `${sentence} ${escapeHtml(why)}` : sentence;
        return {
            moveNumber: Number(r.moveNumber) || 0,
            html: `<li style="margin-bottom:10px;"><strong>Jugada ${escapeHtml(String(r.moveNumber || '?'))}</strong> · ${badge}: ${tail}</li>`
        };
    }).filter(Boolean);
}

// Glifs d'escacs com a codificació secundària dels punts del gràfic (a més del
// color): així les qualitats es distingeixen també en e-paper i amb daltonisme.
const CHART_QUALITY_META = {
    blunder: { glyph: '??', color: '#e74c3c', label: 'Errada greu' },
    mistake: { glyph: '?', color: '#e67e22', label: 'Error' },
    inaccuracy: { glyph: '?!', color: '#d4ac0d', label: 'Imprecisió' },
    brilliant: { glyph: '!', color: '#2ecc71', label: 'Moviment excepcional' }
};

// Dibuixa el gràfic de precisió del detall de l'historial. Amb entrada nul·la o
// sense revisió jugada a jugada, amaga la targeta sencera.
function renderHistoryPhaseChart(entry) {
    const card = $('#history-graph-card');
    const holder = document.getElementById('history-graph');
    const cardsEl = document.getElementById('history-phase-cards');
    if (!card.length || !holder || !cardsEl) return;
    const timeline = entry ? computeHistoryMoveTimeline(entry) : [];
    if (timeline.length < 2) {
        card.hide();
        holder.innerHTML = '';
        cardsEl.innerHTML = '';
        return;
    }
    card.show();

    const n = timeline.length;
    const W = Math.max(300, Math.min(760, holder.clientWidth || 560));
    const H = 222;
    const padL = 38, padR = 16, padT = 26, padB = 38;
    const plotW = W - padL - padR;
    const plotH = H - padT - padB;
    const xFor = idx => padL + (n === 1 ? plotW / 2 : (idx - 1) * (plotW / (n - 1)));
    const yFor = pct => padT + plotH * (1 - pct / 100);
    const halfStep = n > 1 ? (plotW / (n - 1)) / 2 : plotW / 2;

    let svg = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Precisió acumulada per moviment de l'usuari, amb les fases de la partida">`;

    // Franges de fase (obertura / mig joc / final) com a fons alternat + etiqueta.
    const phasesInOrder = ['opening', 'middlegame', 'endgame'];
    const bands = [];
    phasesInOrder.forEach(ph => {
        const pts = timeline.filter(t => t.phase === ph);
        if (!pts.length) return;
        bands.push({ phase: ph, firstIdx: pts[0].idx, lastIdx: pts[pts.length - 1].idx });
    });
    bands.forEach((band, bi) => {
        const x1 = Math.max(padL, xFor(band.firstIdx) - halfStep);
        const x2 = Math.min(padL + plotW, xFor(band.lastIdx) + halfStep);
        if (bi % 2 === 1) {
            svg += `<rect class="hgc-band" x="${x1.toFixed(1)}" y="${padT}" width="${(x2 - x1).toFixed(1)}" height="${plotH}"/>`;
        }
        if (bi > 0) {
            svg += `<line class="hgc-band-sep" x1="${x1.toFixed(1)}" y1="${padT - 14}" x2="${x1.toFixed(1)}" y2="${padT + plotH}"/>`;
        }
        const cx = (x1 + x2) / 2;
        svg += `<text class="hgc-band-label" x="${cx.toFixed(1)}" y="${padT - 8}" text-anchor="middle">${PHASE_DISPLAY_LABELS[band.phase]}</text>`;
    });

    // Graella horitzontal (0-100%) fina i discreta, amb les etiquetes de l'eix Y.
    [0, 25, 50, 75, 100].forEach(pct => {
        const y = yFor(pct);
        svg += `<line class="hgc-grid" x1="${padL}" y1="${y.toFixed(1)}" x2="${padL + plotW}" y2="${y.toFixed(1)}"/>`;
        svg += `<text class="hgc-axis" x="${padL - 6}" y="${(y + 3).toFixed(1)}" text-anchor="end">${pct}%</text>`;
    });

    // Etiquetes de l'eix X: primer moviment i final de cada franja (número de
    // moviment de l'usuari), amb el títol de l'eix en una línia a part.
    const xTickIdx = new Set([1]);
    bands.forEach(b => xTickIdx.add(b.lastIdx));
    xTickIdx.forEach(idx => {
        svg += `<text class="hgc-axis" x="${xFor(idx).toFixed(1)}" y="${H - 22}" text-anchor="middle">${idx}</text>`;
    });
    svg += `<text class="hgc-axis" x="${(padL + plotW / 2).toFixed(1)}" y="${H - 6}" text-anchor="middle" opacity="0.85">moviments teus</text>`;

    // Àrea + línia de precisió acumulada.
    const linePts = timeline.map(t => `${xFor(t.idx).toFixed(1)},${yFor(t.cumPct).toFixed(1)}`);
    svg += `<path class="hgc-area" d="M${xFor(1).toFixed(1)},${yFor(0).toFixed(1)} L${linePts.join(' L')} L${xFor(n).toFixed(1)},${yFor(0).toFixed(1)} Z"/>`;
    svg += `<path class="hgc-line" d="M${linePts.join(' L')}"/>`;

    // Punts significatius: errades (vermell/taronja/groc amb ?? ? ?!) i moviments
    // excepcionals (només verd amb !). La resta de jugades queden a la línia.
    const brilliantSet = new Set(selectBrilliantReviews(entry, 3).map(r => r.fen));
    const dots = [];
    timeline.forEach(t => {
        let kind = null;
        if (t.quality === 'blunder' || t.quality === 'mistake' || t.quality === 'inaccuracy') kind = t.quality;
        else if (t.review && t.review.fen && brilliantSet.has(t.review.fen)) kind = 'brilliant';
        if (kind) dots.push({ t, kind });
    });
    dots.forEach(({ t, kind }) => {
        const meta = CHART_QUALITY_META[kind];
        const x = xFor(t.idx).toFixed(1);
        const y = yFor(t.cumPct).toFixed(1);
        const r = t.review || {};
        const san = (r.fen ? sanOnFen(r.fen, r.playerMove || r.playerMoveSan) : null) || r.playerMoveSan || '';
        // L'àrea de toc és més gran que el punt (mínim ~26px) i porta les dades de la jugada.
        svg += `<circle class="hgc-hit" cx="${x}" cy="${y}" r="13" tabindex="0" role="button"`
            + ` data-kind="${kind}" data-idx="${t.idx}" data-move-number="${t.moveNumber}" data-cum="${t.cumPct}"`
            + ` data-san="${escapeHtml(san)}" data-uci="${escapeHtml(r.playerMove || '')}"`
            + ` data-best="${escapeHtml(r.bestMove || '')}" data-fen="${escapeHtml(r.fen || '')}"`
            + ` aria-label="Jugada ${t.moveNumber}: ${meta.label}. Toca per veure-la al tauler."><title>Jugada ${t.moveNumber} · ${meta.label}</title></circle>`;
        svg += `<circle class="hgc-dot" cx="${x}" cy="${y}" r="4.5" fill="${meta.color}" pointer-events="none"/>`;
        svg += `<text class="hgc-glyph" x="${x}" y="${(yFor(t.cumPct) - 9).toFixed(1)}" pointer-events="none">${meta.glyph}</text>`;
    });

    // Etiqueta directa del final de la línia: la precisió final de la partida.
    const lastT = timeline[n - 1];
    const endX = xFor(n), endY = yFor(lastT.cumPct);
    const endAnchor = endX > padL + plotW - 30 ? 'end' : 'start';
    const endLabelY = Math.max(padT + 10, endY - 8);
    svg += `<text class="hgc-endlabel" x="${(endAnchor === 'end' ? endX - 2 : endX + 4).toFixed(1)}" y="${endLabelY.toFixed(1)}" text-anchor="${endAnchor}">${lastT.cumPct}%</text>`;
    svg += '</svg>';

    holder.innerHTML = svg + '<div class="history-graph-tooltip"></div>';
    bindHistoryChartDots(holder, entry);
    renderHistoryPhaseCards(entry, timeline);
}

// Tooltip + clic dels punts del gràfic: mostra la jugada i, en clicar, la porta
// al tauler amb el mateix ressaltat que els moments clau (vermell la teva, verd
// la millor; si és un moviment excepcional, NOMÉS la jugada en verd).
function bindHistoryChartDots(holder, entry) {
    const tooltip = holder.querySelector('.history-graph-tooltip');
    const hits = holder.querySelectorAll('.hgc-hit');
    const showTip = (el) => {
        if (!tooltip) return;
        const kind = el.getAttribute('data-kind');
        const meta = CHART_QUALITY_META[kind] || {};
        const san = el.getAttribute('data-san') || '';
        const mn = el.getAttribute('data-move-number');
        const cum = el.getAttribute('data-cum');
        tooltip.textContent = '';
        const strong = document.createElement('strong');
        strong.textContent = `Jugada ${mn}${san ? ' · ' + san : ''}`;
        tooltip.appendChild(strong);
        tooltip.appendChild(document.createElement('br'));
        tooltip.appendChild(document.createTextNode(`${meta.label || ''} ${meta.glyph || ''}`.trim()));
        tooltip.appendChild(document.createElement('br'));
        tooltip.appendChild(document.createTextNode(`Encert acumulat: ${cum}%`));
        tooltip.style.display = 'block';
        const holderRect = holder.getBoundingClientRect();
        const elRect = el.getBoundingClientRect();
        let left = elRect.left - holderRect.left + elRect.width / 2 + 10;
        let top = elRect.top - holderRect.top - 10;
        const maxLeft = holder.clientWidth - tooltip.offsetWidth - 4;
        if (left > maxLeft) left = Math.max(4, elRect.left - holderRect.left - tooltip.offsetWidth - 10);
        tooltip.style.left = `${Math.max(4, left)}px`;
        tooltip.style.top = `${Math.max(0, top)}px`;
    };
    const hideTip = () => { if (tooltip) tooltip.style.display = 'none'; };
    hits.forEach(el => {
        el.addEventListener('pointerenter', () => showTip(el));
        el.addEventListener('pointerleave', hideTip);
        el.addEventListener('focus', () => showTip(el));
        el.addEventListener('blur', hideTip);
        const activate = (event) => {
            event.preventDefault();
            showTip(el);
            const kind = el.getAttribute('data-kind');
            const moveNumber = Number(el.getAttribute('data-move-number'));
            const san = el.getAttribute('data-san') || '';
            const uci = el.getAttribute('data-uci') || '';
            const best = el.getAttribute('data-best') || '';
            const fen = el.getAttribute('data-fen') || '';
            jumpToHistoryMove(moveNumber, san, fen, uci);
            if (kind === 'brilliant') {
                // Moviment excepcional: només la jugada feta, en verd.
                if (activeReviewHighlight) {
                    activeReviewHighlight.best = activeReviewHighlight.played || uci || san;
                    activeReviewHighlight.played = null;
                    applyReviewHighlights();
                }
            } else if (best) {
                setKeyMomentBest(best);
            }
            const boardEl = document.getElementById('history-board');
            if (boardEl && boardEl.scrollIntoView) boardEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        };
        el.addEventListener('click', activate);
        el.addEventListener('keydown', (event) => {
            if (event.key === 'Enter' || event.key === ' ') activate(event);
        });
    });
}

// Fitxes de fase sota el gràfic: % d'encert DINS de cada fase, jugades i errades,
// i el botó del repte «Rejugar +5%».
function renderHistoryPhaseCards(entry, timeline) {
    const cardsEl = document.getElementById('history-phase-cards');
    if (!cardsEl) return;
    const html = ['opening', 'middlegame', 'endgame'].map(key => {
        const pts = (timeline || []).filter(t => t.phase === key);
        const name = PHASE_DISPLAY_LABELS[key];
        if (!pts.length) {
            return `<div class="history-phase-card"><div class="hpc-name">${name}</div><div class="hpc-empty">La partida no va arribar a aquesta fase.</div></div>`;
        }
        const good = pts.filter(t => t.quality === 'excel' || t.quality === 'good').length;
        const errs = pts.length - good;
        const phasePct = Math.round((good / pts.length) * 100);
        const plan = computePhaseReplayPlan(entry, key);
        const clockTxt = plan && plan.timeControlId
            ? ` Es juga amb rellotge: el 30% del temps de ${getTimeControlLabel(plan.timeControlId)}.`
            : '';
        const btn = plan
            ? `<button type="button" class="btn phase-replay-btn" data-phase="${key}" title="Torna a la jugada ${plan.startMoveNumber} i rejuga ${name.toLowerCase()} contra el motor amb un objectiu del ${plan.targetPct}% (a la partida hi vas fer un ${plan.origPhasePct}%).${clockTxt}">${HISTORY_ICON_SVG}Rejugar +5%</button>`
            : `<div class="hpc-meta" style="margin-top:6px;">Sense prou dades per rejugar-la.</div>`;
        return `<div class="history-phase-card">
            <div class="hpc-name">${name}</div>
            <div class="hpc-pct">${phasePct}%</div>
            <div class="hpc-meta">${pts.length} ${pts.length === 1 ? 'jugada' : 'jugades'} · ${errs} ${errs === 1 ? 'errada' : 'errades'}${plan ? ` · objectiu ${plan.targetPct}%` : ''}</div>
            ${btn}
        </div>`;
    }).join('');
    cardsEl.innerHTML = html;
    $(cardsEl).find('.phase-replay-btn').off('click').on('click', function() {
        const phaseKey = $(this).data('phase');
        startPhaseReplayChallenge(entry, phaseKey);
    });
}

// Pla del repte «Rejugar +5%» d'una fase: posició inicial (FEN abans de la teva
// primera jugada de la fase), nombre de jugades a jugar i objectiu. Tots els
// percentatges són DE LA FASE (encerts dins la fase / jugades de la fase): el
// mateix número que mostra la fitxa, de manera que l'objectiu és exactament
// aquell número +5. Si la partida original era amb rellotge, el repte també en
// porta: cada bàndol rep el 30% del temps total del ritme original.
function computePhaseReplayPlan(entry, phaseKey) {
    if (!entry) return null;
    const timeline = computeHistoryMoveTimeline(entry);
    if (!timeline.length) return null;
    const inPhase = timeline.filter(t => t.phase === phaseKey);
    if (!inPhase.length) return null;
    const first = inPhase[0];
    const playerColor = entry.playerColor === 'b' ? 'b' : 'w';
    const moves = getHistoryMoves(entry);
    if (!moves.length) return null;
    const startPly = (first.moveNumber - 1) * 2 + (playerColor === 'b' ? 1 : 0);
    if (startPly < 0 || startPly >= moves.length) return null;
    let baseFen = null;
    try {
        const g = new Chess();
        for (let i = 0; i < startPly; i++) {
            if (!g.move(moves[i], { sloppy: true })) return null;
        }
        if (g.game_over()) return null;
        // La posició reconstruïda ha de tocar al jugador; si no, les dades de la
        // revisió no quadren amb la partida real i el repte no seria fidel.
        if (g.turn() !== playerColor) return null;
        baseFen = g.fen();
    } catch (e) { return null; }
    const goodInPhase = inPhase.filter(t => t.quality === 'excel' || t.quality === 'good').length;
    const origPhasePct = Math.round((goodInPhase / inPhase.length) * 100);
    const tcId = (entry.timeControl && entry.timeControl !== 'none'
        && TIME_CONTROLS.some(t => t.id === entry.timeControl)) ? entry.timeControl : null;
    return {
        entryId: entry.id,
        phaseKey,
        phaseLabel: PHASE_DISPLAY_LABELS[phaseKey],
        playerColor,
        baseFen,
        startMoveNumber: first.moveNumber,
        movesTarget: inPhase.length,
        origPhasePct,
        targetPct: Math.min(100, origPhasePct + PHASE_REPLAY_BONUS),
        timeControlId: tcId,
        engineRoc: (typeof entry.roc === 'number' && entry.roc > 0) ? entry.roc : null
    };
}

// Arrenca el repte: surt de l'historial i comença una partida real contra el
// motor des de la primera jugada de la fase. No toca ELO, ni lliga, ni historial.
function startPhaseReplayChallenge(entry, phaseKey) {
    const plan = computePhaseReplayPlan(entry, phaseKey);
    if (!plan) {
        showToast('Aquesta fase no es pot rejugar (falten dades de la revisió).', 'warn');
        return;
    }
    stopHistoryPlayback();
    // Cap sessió d'exercicis a mitges: el repte és una partida normal amb objectiu.
    isRandomBundleSession = false;
    isMatchErrorReviewSession = false;
    isSrsReviewSession = false;
    isDailyPuzzleSession = false;
    isTacticsSession = false;
    matchErrorQueue = [];
    currentMatchError = null;
    currentBundleSource = null;
    currentBundleSeverity = null;
    phaseReplayPending = plan;
    $('#history-screen').hide();
    startGame(false, plan.baseFen);
}

// HUD del repte a la pantalla de joc: fase, jugada actual, objectiu.
function updatePhaseReplayHud() {
    const banner = $('#phase-replay-banner');
    if (!banner.length) return;
    if (currentGameMode !== 'phase_replay' || !phaseReplayState) {
        banner.hide();
        return;
    }
    const st = phaseReplayState;
    const current = Math.min(st.movesPlayed + (st.finished ? 0 : 1), st.movesTarget);
    const clockTxt = st.timeControlId ? ` · rellotge 30% de ${getTimeControlLabel(st.timeControlId)}` : '';
    $('#phase-replay-banner-text').text(
        `Rejugues ${st.phaseLabel.toLowerCase()} · jugada ${current} de ${st.movesTarget} · objectiu ${st.targetPct}% (a l'original ${st.origPhasePct}%)${clockTxt}`
    );
    banner.show();
}

// Marca vertical i text de l'objectiu del panell de precisió: al repte és
// l'objectiu real (+5%); a la resta de partides, el 75% de sempre.
function updatePrecisionTargetUI() {
    const marker = document.getElementById('precision-target');
    const text = document.getElementById('precision-target-text');
    const target = (currentGameMode === 'phase_replay' && phaseReplayState) ? phaseReplayState.targetPct : 75;
    if (marker) marker.style.left = `${target}%`;
    if (text) text.textContent = `${target}%`;
}

// Es crida quan s'ha acabat d'avaluar una jugada del jugador durant el repte.
function notePhaseReplayMoveEvaluated() {
    if (currentGameMode !== 'phase_replay' || !phaseReplayState || phaseReplayState.finished) return;
    phaseReplayState.movesPlayed++;
    updatePhaseReplayHud();
    if (phaseReplayState.movesPlayed >= phaseReplayState.movesTarget) {
        finishPhaseReplay('completed');
    }
}

function phaseReplayInputLocked() {
    return currentGameMode === 'phase_replay' && phaseReplayState && phaseReplayState.finished;
}

// Tanca el repte: atura el motor, calcula el resultat i mostra la finestra.
// No es registra res (ni ELO, ni historial, ni estadístiques de partida).
// Els comptadors comencen a zero al repte, així que finalPct és el % DE LA FASE
// rejugada: directament comparable amb origPhasePct i amb l'objectiu (+5).
function finishPhaseReplay(reason) {
    if (!phaseReplayState || phaseReplayState.finished) return;
    const st = phaseReplayState;
    st.finished = true;
    stopGameClock();
    if (engineMoveTimeout) clearTimeout(engineMoveTimeout);
    $('#blunder-alert').hide();
    hidePostGameStatusChip();
    try { if (stockfish) stockfish.postMessage('stop'); } catch (e) {}
    st.finalPct = totalPlayerMoves > 0 ? Math.round((goodMoves / totalPlayerMoves) * 100) : 0;
    st.reason = reason;
    // Rendir-se o quedar-se sense temps no pot comptar com a repte superat.
    st.success = reason !== 'resign' && reason !== 'flag_player' && st.finalPct >= st.targetPct;
    updatePhaseReplayHud();
    showPhaseReplayOverlay(st);
}

function showPhaseReplayOverlay(st) {
    const overlay = $('#phase-replay-overlay');
    if (!overlay.length) return;
    const icon = st.success ? '🎉' : (st.reason === 'resign' ? '🏳️' : (st.reason === 'flag_player' ? '⏱️' : '🎯'));
    const title = st.success ? 'Repte superat!'
        : (st.reason === 'resign' ? 'Repte abandonat'
        : (st.reason === 'flag_player' ? "T'has quedat sense temps" : 'Objectiu no assolit'));
    $('#phase-replay-result-icon').text(icon);
    $('#phase-replay-result-title').text(title);
    const detail = $('#phase-replay-result-detail');
    let html = `<p><strong>${escapeHtml(st.phaseLabel)}</strong>: has acabat amb <strong>${st.finalPct}%</strong> d'encert a la fase.`
        + ` L'objectiu era <strong>${st.targetPct}%</strong> (a la partida original hi vas fer un ${st.origPhasePct}%).</p>`;
    html += `<div class="prr-meter"><div class="prr-meter-fill${st.success ? '' : ' ko'}" style="width:${Math.max(0, Math.min(100, st.finalPct))}%"></div>`
        + `<div class="prr-meter-target" style="left:${st.targetPct}%"></div></div>`;
    if (st.reason === 'flag_player') {
        html += `<div class="prr-note">El rellotge del repte era el 30% del temps de ${escapeHtml(getTimeControlLabel(st.timeControlId) || 'la partida original')} i se t'ha acabat. Torna-ho a provar jugant una mica més de pressa.</div>`;
    } else if (st.reason === 'flag_engine') {
        html += `<div class="prr-note">El rival s'ha quedat sense temps.</div>`;
    } else if (st.reason === 'gameover' && st.movesPlayed < st.movesTarget) {
        html += `<div class="prr-note">La partida s'ha acabat abans d'hora: has jugat ${st.movesPlayed} de ${st.movesTarget} jugades del repte.</div>`;
    } else if (!st.success && st.reason !== 'resign') {
        html += `<div class="prr-note">Torna-ho a provar: només et cal ${st.targetPct - st.finalPct > 0 ? `un ${st.targetPct - st.finalPct}% més` : 'una mica més de precisió'}.</div>`;
    }
    detail.html(html);
    const retryBtn = $('#btn-phase-replay-retry');
    retryBtn.off('click').on('click', () => {
        overlay.hide();
        const entry = findHistoryEntryById(st.entryId);
        if (!entry) {
            showToast('La partida original ja no és a l\'historial.', 'warn');
            returnToHistoryFromPhaseReplay();
            return;
        }
        startPhaseReplayChallenge(entry, st.phaseKey);
    });
    overlay.find('.overlay-close-x').off('click').on('click', () => overlay.hide());
    wireNavTrio(overlay, {
        sectionLabel: `${HISTORY_ICON_SVG} Historial`,
        onSection: () => returnToHistoryFromPhaseReplay()
    });
    overlay.css('display', 'flex');
}

// Torna a l'historial amb la partida del repte seleccionada.
function returnToHistoryFromPhaseReplay() {
    const targetId = phaseReplayState ? phaseReplayState.entryId : null;
    returnToMainMenuImmediate();
    $('#start-screen').hide();
    $('#history-screen').show();
    initHistoryBoard();
    renderGameHistory();
    const entry = targetId ? findHistoryEntryById(targetId) : null;
    if (entry) openHistoryEntry(entry);
    navPush('history-screen');
    setTimeout(() => resizeHistoryBoardToViewport(), 0);
}

// =================== NAVEGACIÓ A LA PRÀCTICA D'OBERTURA ===================
// Troba l'obertura del repertori (CURATED_OPENINGS) més semblant a la partida
// jugada, comparant la coincidència de jugades des de l'inici (prefix comú).
function findClosestCuratedOpening(sanMoves) {
    if (!Array.isArray(CURATED_OPENINGS) || !Array.isArray(sanMoves) || !sanMoves.length) return null;
    const norm = s => String(s || '').replace(/[+#!?]/g, '');
    const game = sanMoves.map(norm);
    let best = null;
    CURATED_OPENINGS.forEach((op, i) => {
        const line = (op.moves || []).map(norm);
        let match = 0;
        for (let k = 0; k < Math.min(line.length, game.length); k++) {
            if (line[k] === game[k]) match++; else break;
        }
        if (match >= 2 && (!best || match > best.match)) best = { index: i, opening: op, match };
    });
    return best;
}

// Obre la pràctica de l'obertura del repertori (per índex) amb el color demanat.
// Reprodueix EXACTAMENT la mateixa preparació que en entrar des del menú
// d'obertures (mateix ordre: render → inicialitza tauler → mostra pantalla →
// arrenca → redimensiona), de manera que s'arriba al mateix punt d'inici net de
// la pràctica de l'obertura, però amb l'obertura concreta ja seleccionada.
function practiceOpeningFromHistory(idx, color) {
    try {
        const forceColor = (color === 'w' || color === 'b') ? color : undefined;
        renderOpeningStatsScreen();
        renderPersonalRepertoire();
        renderPersonalOpeningSection();
        renderOpeningHieroglyphicBanner();
        renderOpeningLessonButtons();
        initOpeningBundleBoard();
        $('#history-screen').hide();
        $('#start-screen').hide();
        $('#opening-screen').show();
        navPush('opening-screen');
        if (typeof idx === 'number' && idx >= 0) {
            startOpeningLesson(idx, forceColor);
        } else {
            startOpeningPracticeAsColor(forceColor || openingPracticeUserColor);
            setOpeningScreenMode('overview');
            showToast('No tinc una lliçó concreta d’aquesta obertura; practica-la lliurement.', 'info');
        }
        setTimeout(() => resizeOpeningBoardToViewport(), 50);
    } catch (e) { console.warn('practiceOpeningFromHistory', e); }
}

// Tema dominant de les errades de la partida, reduït a les sis famílies de
// "La lliçó d'avui" (material, atac al rei, profilaxi, obertura, final,
// general). Surt de la classificació local dels moveReviews, mai d'IA lliure.
function dominantLessonTheme(entry) {
    const reviews = Array.isArray(entry?.moveReviews) ? entry.moveReviews : [];
    const counts = {};
    reviews.forEach(r => {
        if (!r || !['inaccuracy', 'mistake', 'blunder'].includes(r.quality)) return;
        let key = 'general';
        try { key = detectPlanSubtheme(r) || 'general'; } catch (e) { key = 'general'; }
        counts[key] = (counts[key] || 0) + 1;
    });
    let top = null, topN = 0;
    Object.keys(counts).forEach(k => { if (counts[k] > topN) { top = k; topN = counts[k]; } });
    if (!top) return 'general';
    if (/material|fork|pin|skewer|hanging|tactic/.test(top)) return 'material';
    if (/king|attack|mate/.test(top)) return 'king_attack';
    if (/defens|prophyla|quiet/.test(top)) return 'prophylaxis';
    if (/opening|develop/.test(top)) return 'opening';
    if (/endgame|final|passed/.test(top)) return 'endgame';
    return 'general';
}


function historyEntryReviewedSideLabel(entry, opts = {}) {
    const color = entry && entry.playerColor === 'b' ? 'b' : 'w';
    const headers = (entry && entry.importHeaders) || {};
    const name = color === 'b' ? headers.Black : headers.White;
    const fallback = color === 'b' ? 'les negres' : 'les blanques';
    if (name && name !== '?') return opts.withColor ? `${name} (${fallback})` : name;
    return fallback;
}

function historyEntryReviewedSideIntro(entry, voiceStyle) {
    const color = entry && entry.playerColor === 'b' ? 'negres' : 'blanques';
    const who = historyEntryReviewedSideLabel(entry, { withColor: false });
    const rhythm = historyTimeControlLabel(entry);
    const rhythmText = rhythm ? ` de ${rhythm}` : '';
    if (voiceStyle === 'technical') {
        return `Partida${rhythmText}: s'avaluen les decisions de ${who}, que jugava amb ${color}.`;
    }
    return `En aquesta partida${rhythmText}, la revisió se centra en ${who}, que jugava amb ${color}.`;
}

function composeImportedDebriefText(entry, facts, voiceStyle) {
    const who = historyEntryReviewedSideLabel(entry);
    const prec = facts && facts.precision !== null ? `${facts.precision}%` : '—';
    const errors = facts ? ((facts.blunders || 0) + (facts.mistakes || 0)) : 0;
    const tema = facts && facts.topErrorTheme
        ? humanizeDominantTheme(facts.topErrorTheme, { outcome: facts.dominantOutcome, seed: entry && entry.id }, { voiceStyle })
        : null;
    let text = `Anàlisi de ${who}: precisió ${prec}.`;
    if (errors > 0 && tema) text += ` Els moments més delicats giren sobretot al voltant de ${tema}.`;
    else if (errors > 0) text += ` Hi ha ${errors === 1 ? 'un moment crític' : `${errors} moments crítics`} per revisar amb calma.`;
    else text += ` No hi ha errades greus destacades en el color analitzat.`;
    text += ` La ressenya parla dels protagonistes de la partida, no del compte que l'ha importada.`;
    return text;
}

// =================== RESSENYA LOCAL EN HTML (sense OpenAI) ===================
// Construeix la ressenya rica de l'historial: debrief, color del jugador, lliçó
// del dia, obertura amb enllaç a la pràctica i correcció per fases (amb nombre
// de jugades), moments clau amb jugades descriptives clicables i pla de 10
// minuts per repassar les jugades més importants.
function renderLocalReviewHtml(entry, opts = {}) {
    if (!entry) return '';
    const blocks = [];
    try {
        // Veu de la ressenya: la demanada explícitament (desplegable de la
        // ressenya) o la preferència de l'usuari. Només canvia la redacció.
        const voiceStyle = getReviewVoiceStyle(opts.voiceStyle);
        const importedReview = historyEntryIsImported(entry);
        const reviewedActor = importedReview ? historyEntryReviewedSideLabel(entry) : 'tu';
        const facts = buildDebriefFacts(entry);
        // Llavor de ressenya: permet regenerar una redacció local DIFERENT (veu i
        // màxima noves) cada cop que es prem «Regenerar la ressenya», sense dependre
        // de cap clau d'IA. Si no s'ha regenerat mai, la llavor és l'id de partida.
        const seedKey = entry.id + (entry.reviewSeed ? ':r' + entry.reviewSeed : '');

        // --- Màxima d'inici ---
        let maxim = '';
        try { maxim = pickOfflineMaxim((facts && (facts.topErrorTheme || facts.weakestTheme)) || 'general'); } catch (e) { maxim = ''; }
        if (maxim) {
            blocks.push(`<blockquote style="margin:0 0 12px 0; padding:8px 12px; border-left:3px solid var(--accent-gold); font-style:italic; opacity:0.95;">“${escapeHtml(maxim)}”</blockquote>`);
        }

        // --- Moment clau de la partida (secció destacada, a dalt de tot) ---
        try {
            const kmHtml = renderKeyMomentHtml(entry);
            if (kmHtml) blocks.push(kmHtml);
        } catch (e) { console.warn('renderKeyMomentHtml', e); }

        if (facts) {
            const debrief = importedReview
                ? composeImportedDebriefText(entry, facts, voiceStyle)
                : composeDebriefText(facts, seedKey, pickCoachVoiceForKey(seedKey), voiceStyle);
            if (debrief) blocks.push(`<p>${escapeHtml(debrief)}</p>`);
        }

        // --- Color del jugador (i ritme, si era una partida amb rellotge): una
        // sola frase natural que situa quines decisions es comenten. A les PGN
        // importades es parla del protagonista analitzat, no de l'usuari. ---
        blocks.push(`<p>${escapeHtml(importedReview
            ? historyEntryReviewedSideIntro(entry, voiceStyle)
            : ElTaulerCore.playerColorIntro(entry.playerColor, voiceStyle, historyTimeControlLabel(entry)))}</p>`);

        // --- La lliçó d'avui: una consigna curta segons el patró dominant,
        // derivada de dades locals (mai d'IA lliure) ---
        const lesson = ElTaulerCore.lessonOfTheDay(dominantLessonTheme(entry), voiceStyle);
        if (lesson) blocks.push(`<p><strong>La lliçó d'avui:</strong> ${escapeHtml(lesson)}</p>`);

        const phases = buildPhaseStats(entry);
        const pct = v => (typeof v === 'number' ? `${v}%` : '—');
        // Línia de fase amb el nombre de jugades i avís de poques dades.
        const phaseLine = p => ElTaulerCore.formatPhaseLine(p.precision, p.total, voiceStyle);

        // Capçalera de la línia d'obertura per veu. En casual es prioritza la
        // lectura humana: sense ECO i amb una valoració en paraules en lloc de
        // "correcció X% en N jugades" (l'ECO i el % es poden veure a la llista
        // de jugades i a la resta de fases). En balanced/technical es manté la
        // dada precisa.
        const openingCorrectionCasual = p => {
            const pr = p && typeof p.precision === 'number' ? p.precision : null;
            if (pr === null || (p.total || 0) < 2) return 'Has sortit bé de l’obertura.';
            if (pr >= 80) return 'L’obertura ha estat força correcta.';
            if (pr >= 60) return 'L’obertura ha anat prou bé.';
            return 'L’obertura ha tingut algun ensurt.';
        };
        const openingHead = (labelHtml, name, eco, p) => {
            if (voiceStyle === 'casual') {
                return `${labelHtml} ${escapeHtml(name)}. ${escapeHtml(openingCorrectionCasual(p))}`;
            }
            const ecoHtml = eco ? ` (${escapeHtml(eco)})` : '';
            return `${labelHtml} ${escapeHtml(name)}${ecoHtml} · ${escapeHtml(phaseLine(p) || `correcció ${pct(p.precision)}.`)}`;
        };
        const ecoParen = eco => (voiceStyle === 'casual' || !eco) ? '' : ` (${escapeHtml(eco)})`;

        // --- Obertura (centrada en LA TEVA obertura, sigui quina sigui) ---
        const sanMoves = getHistoryMoves(entry);
        if (!openingTrie) { try { initOpeningSystem(); } catch (e) {} }
        let oa = null;
        try { oa = analyzeGameOpening(sanMoves); } catch (e) { oa = null; }
        // Obertura realitzada (per posició al repertori si hi encaixa, o per ECO).
        let curated = null;
        try { curated = findCuratedOpeningForGame(sanMoves); } catch (e) { curated = null; }
        // QUINA obertura del repertori estaves jugant TU (per les teves jugades),
        // i si el rival et va forçar a canviar.
        let userOp = null;
        try { userOp = importedReview ? null : identifyUserOpening(entry); } catch (e) { userOp = null; }

        const realizedName = curated ? curated.name : (oa ? oa.name : null);
        const realizedEco = curated ? curated.eco : (oa ? oa.eco : null);
        // La partida s'ha mantingut DINS la teva obertura del repertori?
        const stayedInUserOpening = !!(userOp && curated && curated.index === userOp.index);
        // El rival t'ha forçat a canviar d'obertura (va sortir ell primer de la línia
        // i la partida ja no és la teva obertura)?
        const forcedChange = !!(userOp && userOp.forcedByOpponent && !stayedInUserOpening);

        let practiceIdx = null, practiceName = null, practiceEco = null;

        if (userOp && forcedChange) {
            // CANVI FORÇAT: 100% de correcció d'obertura i argument del canvi.
            const devNum = Math.floor((userOp.firstDevPly || 0) / 2) + 1;
            const devNotation = `${devNum}${userOp.firstDevBy === 'w' ? '.' : '...'}${userOp.deviationMove}`;
            let txt = `<strong>La teva obertura:</strong> ${escapeHtml(userOp.name)}${ecoParen(userOp.eco)} · correcció <strong>100%</strong>.`;
            txt += ` El rival no va entrar a la teva línia: va jugar <strong>${escapeHtml(devNotation)}</strong>`;
            if (userOp.expectedMove) txt += ` (hi esperaves ${escapeHtml(userOp.expectedMove)})`;
            if (realizedName && (!realizedEco || realizedEco !== userOp.eco)) {
                txt += `, transposant cap a ${escapeHtml(realizedName)}${ecoParen(realizedEco)}`;
            }
            txt += `. Vas mantenir el teu pla amb solidesa, així que el canvi no és culpa teva: la correcció d'obertura és del 100%.`;
            blocks.push(`<p>${txt}</p>`);
            practiceIdx = userOp.index; practiceName = userOp.name; practiceEco = userOp.eco;
        } else if (userOp) {
            // Vas jugar la teva obertura (el rival hi va entrar, o la vas variar tu).
            let txt = openingHead('<strong>La teva obertura:</strong>', userOp.name, userOp.eco, phases.opening);
            if (!stayedInUserOpening && userOp.firstDevPly >= 0 && userOp.firstDevBy === (entry.playerColor || 'w')) {
                const dn = Math.floor(userOp.firstDevPly / 2) + 1;
                txt += ` Vas sortir de la teva línia a la jugada ${dn}`;
                txt += userOp.expectedMove ? ` (la teoria seguia amb ${escapeHtml(userOp.expectedMove)}).` : '.';
            }
            blocks.push(`<p>${txt}</p>`);
            practiceIdx = userOp.index; practiceName = userOp.name; practiceEco = userOp.eco;
        } else if (realizedName) {
            // No hem pogut identificar cap obertura teva del repertori: mostrem
            // l'obertura realitzada (per posició/ECO) amb la desviació de la teoria.
            let openingTxt = openingHead(importedReview ? '<strong>Obertura de la partida:</strong>' : '<strong>Obertura:</strong>', realizedName, realizedEco, phases.opening);
            if (!curated && oa && oa.deviationMove && oa.deviationBy && entry.playerColor && oa.deviationBy === entry.playerColor) {
                const moveNum = Math.floor((oa.deviationPly || 0) / 2) + 1;
                openingTxt += importedReview
                    ? ` ${escapeHtml(reviewedActor)} va sortir de la teoria a la jugada ${moveNum}`
                    : ` Vas sortir de la teoria a la jugada ${moveNum}`;
                if (Array.isArray(oa.theoryMoves) && oa.theoryMoves.length) {
                    let devFen = null;
                    try {
                        const g = new Chess();
                        for (let i = 0; i < (oa.deviationPly || 0); i++) { if (!g.move(sanMoves[i], { sloppy: true })) break; }
                        devFen = g.fen();
                    } catch (e) { devFen = null; }
                    const theoryDesc = devFen ? voiceMoveText(devFen, oa.theoryMoves[0], oa.theoryMoves[0], voiceStyle) : oa.theoryMoves[0];
                    openingTxt += `; la teoria seguia amb ${escapeHtml(theoryDesc)}.`;
                } else openingTxt += '.';
            }
            blocks.push(`<p>${openingTxt}</p>`);
            if (curated) { practiceIdx = curated.index; practiceName = curated.name; practiceEco = curated.eco; }
        }

        // --- Obertura del repertori per practicar (enllaços per a tots dos colors) ---
        if (practiceIdx === null) {
            const closest = findClosestCuratedOpening(sanMoves);
            if (closest) { practiceIdx = closest.index; practiceName = closest.opening.name; practiceEco = closest.opening.eco; }
        }
        if (practiceIdx !== null && practiceName) {
            // Els enllaços visibles comencen amb majúscula i no semblen UI
            // enganxada: "Practicar amb blanques · Practicar amb negres". En
            // casual s'integren en una frase natural ("Pots practicar-la...").
            const nameHtml = `<strong>${escapeHtml(practiceName)}</strong>`;
            const ecoHtml = practiceEco ? ` (${escapeHtml(practiceEco)})` : '';
            const mkLink = (color, text) => `<a href="#" class="opening-practice-link" data-idx="${practiceIdx}" data-color="${color}">${text}</a>`;
            let practiceHtml;
            if (voiceStyle === 'casual') {
                // Sense ECO al cos; enllaços integrats amb minúscula dins la frase.
                const lead = importedReview
                    ? `l'obertura del repertori més semblant per estudiar és ${nameHtml}`
                    : ((userOp || curated)
                        ? `reforça la teva ${nameHtml} del repertori`
                        : `l'obertura del repertori més semblant és ${nameHtml}`);
                practiceHtml = `<strong>Per practicar:</strong> ${lead}. Pots practicar-la ${mkLink('w', 'amb blanques')} o ${mkLink('b', 'amb negres')}.`;
            } else {
                const lead = importedReview
                    ? `${voiceStyle === 'technical' ? 'la línia de repertori més propera' : 'l\'obertura del repertori més semblant a la partida'} és ${nameHtml}${ecoHtml}`
                    : ((userOp || curated)
                        ? `reforça la teva ${nameHtml}${ecoHtml} del repertori`
                        : `${voiceStyle === 'technical' ? 'la línia de repertori més propera' : 'l\'obertura del repertori més semblant a la que vas jugar'} és ${nameHtml}${ecoHtml}`);
                practiceHtml = `<strong>Per practicar:</strong> ${lead}. ${mkLink('w', 'Practicar amb blanques')} · ${mkLink('b', 'Practicar amb negres')}.`;
            }
            blocks.push(`<p>${practiceHtml}</p>`);
        }

        // --- Mig joc ---
        if (phases.middlegame.total > 0) {
            let midTxt = `<strong>Mig joc:</strong> ${escapeHtml(phaseLine(phases.middlegame))}`;
            // "joc general" no aporta res com a "error més habitual": es filtra.
            const midThemes = (phases.middlegame.themes || []).filter(t => t && t !== 'joc general');
            if (midThemes.length) {
                midTxt += ` Errors més habituals: ${midThemes.map(escapeHtml).join(', ')}.`;
            } else {
                midTxt += ` ${escapeHtml(voiceText(voiceStyle, 'noPhaseErrors'))}`;
            }
            blocks.push(`<p>${midTxt}</p>`);
        }

        // --- Final (amb menys de 2 jugades no diu res fiable i s'omet) ---
        if (phases.endgame.total >= 2) {
            let endTxt = `<strong>Final:</strong> ${escapeHtml(phaseLine(phases.endgame))}`;
            const advice = buildPhaseAdvice(phases.endgame.themes, 'endgame', voiceStyle);
            if (advice) endTxt += ` ${escapeHtml(advice)}`;
            blocks.push(`<p>${endTxt}</p>`);
        }

        // --- Moments clau (jugades descriptives clicables): les errades (vermell
        // la teva jugada, verd la millor) I els moviments excepcionals (només
        // verd la jugada feta), tot ordenat per número de jugada. ---
        const moments = buildHumanPlanMoments(entry, null, { ...opts, voiceStyle });
        const brilliantMoments = buildBrilliantMomentItems(entry, voiceStyle, { imported: importedReview, actor: reviewedActor });
        // FENs d'aquesta partida que poden generar un jeroglífic (per marcar-los).
        const heiroSeeds = entryHieroglyphicSeedFenKeys(entry);
        const heiroKeyOf = (f) => { try { return ElTaulerCore.puzzleFenKey ? ElTaulerCore.puzzleFenKey(f) : f; } catch (e) { return f; } };
        if (moments.length || brilliantMoments.length) {
            const errorItems = moments.map(m => {
                // Frases per veu VERIFICADES sobre la FEN de decisió: si la
                // millor jugada no s'hi pot verificar, el moment no es mostra
                // (mai una jugada inventada; passa al següent moment vàlid).
                const best = m.fen ? bestPhraseByVoice(m.fen, m.bestMoveUci || m.best, voiceStyle) : null;
                if (!best) return null;
                // Enllaç especialitzat: la millor jugada no es va jugar mai, així que
                // naveguem a la posició de decisió (per la jugada realment feta) i
                // hi ressaltem la jugada recomanada al tauler.
                const link = `<a href="#" class="hist-keymove-link" data-move-number="${m.moveNumber || ''}" data-san="${escapeHtml(m.played || '')}" data-played-uci="${escapeHtml(m.playedUci || '')}" data-best="${escapeHtml(m.bestMoveUci || m.best || '')}" data-fen="${escapeHtml(m.fen || '')}">${escapeHtml(best.body)}</a>`;
                const show = coachSectionsFor(m.quality);
                const badge = coachQualityBadgeHtml(m);
                // Marca 🔮 si aquest moment pot alimentar la generació d'un jeroglífic.
                const isHeiroSeed = m.fen && heiroSeeds.has(heiroKeyOf(m.fen));
                const heiroBadge = isHeiroSeed
                    ? ` <span class="hg-seed-badge" title="Aquest moment es pot convertir en un jeroglífic">${HG_ICON_SVG}</span>`
                    : '';
                const moveNumLabel = `<strong>Jugada ${escapeHtml(String(m.moveNumber))}</strong>${heiroBadge}`;
                // Inclou la jugada feta perquè el moment sigui autocontingut (i no
                // calgui repetir-lo a "Errades comentades"). Si, per una atribució
                // errònia, la jugada feta coincideix amb la millor, no mostrem el
                // dual contradictori ("vas jugar X; la millor era X").
                const playedSan = String(m.played || '').trim();
                const bestSan = String(m.best || '').trim();
                const samePlayedBest = playedSan && bestSan && playedSan === bestSan;
                let playedPhrase = (!samePlayedBest && m.fen)
                    ? playedPhraseByVoice(m.fen, m.playedUci || m.played, voiceStyle)
                    : '';
                if (importedReview && playedPhrase) {
                    playedPhrase = playedPhrase
                        .replace(/^vas jugar /i, `${reviewedActor} va jugar `)
                        .replace(/^vas /i, `${reviewedActor} va `);
                }
                let tail = playedPhrase
                    ? `${escapeHtml(playedPhrase)}. ${escapeHtml(best.prefix.charAt(0).toUpperCase() + best.prefix.slice(1))}${link}.`
                    : `la millor jugada era ${link}.`;
                // Auditoria final del text (sense HTML): si alguna construcció
                // prohibida s'ha escapat (UCI, SAN nua en casual, fletxes,
                // "vas jugar el cavall ... va a ..."), es degrada a la forma
                // mínima segura en lloc de mostrar text incoherent.
                const tailAudit = ElTaulerCore.auditReviewVoiceText(String(tail).replace(/<[^>]*>/g, ' '), voiceStyle);
                if (!tailAudit.ok) tail = `la millor jugada era ${link}.`;
                const header = badge
                    ? `${moveNumLabel} · ${badge} (${escapeHtml(m.theme)}): ${tail}`
                    : `${moveNumLabel} (${escapeHtml(m.theme)}): ${tail}`;
                // Cada línia només s'afegeix si és una frase completa: res de
                // camps tallats amb "…" ni acabats en connector.
                const coachLine = (visible, value, label) => {
                    const v = String(value || '').trim();
                    if (!visible || !v || isIncompleteCoachText(v)) return '';
                    return label
                        ? `<span><strong>${label}:</strong> ${escapeHtml(v)}</span>`
                        : `<span>${escapeHtml(v)}</span>`;
                };
                const lines = [
                    header,
                    coachLine(show.fact, m.structured?.fact || m.positional, 'Posició'),
                    coachLine(show.mistake, m.structured?.mistake || m.diagnosis, 'Què va fallar'),
                    coachLine(show.consequence, m.structured?.consequence, 'Conseqüència'),
                    coachLine(show.refutation, m.structured?.refutation),
                    coachLine(show.plan, m.structured?.plan || m.plan, 'Pla millor'),
                    coachLine(show.continuation, m.structured?.continuation, 'Moviments següents')
                ].filter(Boolean);
                // Si tot ha quedat filtrat, un mínim segur en lloc de res.
                if (lines.length === 1) lines.push(`<span>${escapeHtml(voiceText(voiceStyle, 'safeFallback'))}</span>`);
                return {
                    moveNumber: Number(m.moveNumber) || 0,
                    html: `<li style="margin-bottom:10px;">${lines.join('<br>')}</li>`
                };
            }).filter(Boolean);
            // Cronologia única: errades i moviments excepcionals per ordre de jugada.
            const items = errorItems.concat(brilliantMoments)
                .sort((a, b) => a.moveNumber - b.moveNumber)
                .map(x => x.html)
                .join('');
            const heiroNote = heiroSeeds.size
                ? ` <span class="hg-seed-note">${HG_ICON_SVG} fins a ${heiroSeeds.size} ${heiroSeeds.size === 1 ? 'jeroglífic generable' : 'jeroglífics generables'}</span>`
                : '';
            if (items) {
                blocks.push(`<p><strong>Moments clau:</strong>${heiroNote}</p><ul style="margin:4px 0 0 18px; padding:0;">${items}</ul>`);
            }
        }

        // --- Pla de 10 minuts: les 2-3 jugades més importants per repassar ---
        const planText = ElTaulerCore.buildTenMinutePlan(moments.map(m => Number(m.moveNumber)), voiceStyle);
        const cleanPlan = planText.replace(/^Pla de 10 minuts:\s*/, '');
        blocks.push(`<p><strong>Pla de 10 minuts:</strong> ${escapeHtml(importedReview
            ? cleanPlan.replace(/\bteves\b/g, 'del protagonista').replace(/\bteva\b/g, 'del protagonista').replace(/\bpròxima partida\b/g, 'propera partida del color analitzat')
            : cleanPlan)}</p>`);

        // --- Tancament motivador (segons la veu; estable per llavor de ressenya).
        // No repeteix una frase que ja hagi sortit al resum inicial: si coincideix,
        // en tria una altra del banc. ---
        let motivation = pickVoiceMotivation(voiceStyle, seedKey);
        const priorText = blocks.join(' ');
        if (motivation && priorText.indexOf(escapeHtml(motivation)) !== -1) {
            const pool = (REVIEW_VOICE_TEXT[voiceStyle] || REVIEW_VOICE_TEXT.balanced).motivation || [];
            const alt = pool.find(t => priorText.indexOf(escapeHtml(t)) === -1);
            motivation = alt || '';
        }
        if (motivation) blocks.push(`<p>${escapeHtml(motivation)}</p>`);

        // --- Llista completa de jugades (per copiar i verificar la detecció) ---
        // Posem totes les jugades en ordre, en notació numerada estil PGN, en un
        // bloc seleccionable amb un botó de còpia, per poder comprovar fàcilment
        // on falla l'assignació d'obertures.
        if (Array.isArray(sanMoves) && sanMoves.length) {
            const moveList = sanMoves
                .map((m, i) => (i % 2 === 0 ? `${(i / 2) + 1}. ${m}` : m))
                .join(' ');
            const safe = escapeHtml(moveList);
            blocks.push(
                `<div class="review-movelist" style="margin-top:12px;">` +
                    `<strong>Jugades de la partida</strong> ` +
                    `<button type="button" class="btn btn-secondary review-copy-moves" data-moves="${safe}" ` +
                        `style="padding:2px 8px; font-size:0.8rem; margin-left:6px;"><svg class="hg-ic" aria-hidden="true"><use href="#ic-copy"/></svg> Copiar</button>` +
                    `<pre class="review-moves-pre" style="white-space:pre-wrap; word-break:break-word; ` +
                        `user-select:all; -webkit-user-select:all; background:rgba(127,127,127,0.12); ` +
                        `padding:8px 10px; border-radius:6px; margin-top:6px; font-family:monospace; ` +
                        `font-size:0.85rem; line-height:1.5;">${safe}</pre>` +
                `</div>`
            );
        }
    } catch (e) { console.warn('renderLocalReviewHtml', e); }
    return blocks.join('\n');
}


// Claus (id de partida + FEN) amb una crida en curs: l'estat 'pending' persistit
// no és fiable (l'app es pot tancar a mig generar), així que el control de
// duplicats viu només en memòria i una nota no acabada es torna a demanar.
const errorNotesInFlight = new Set();

async function requestErrorNotes(entry, severeErrors) {
    if (!entry || !openaiApiKey) return;
    const errors = (Array.isArray(severeErrors) && severeErrors.length ? severeErrors : getEntrySevereErrors(entry)).slice(0, ERROR_NOTES_MAX);
    if (!errors.length) return;
    if (!entry.errorNotes) entry.errorNotes = {};
    const pending = errors.filter(err => {
        const key = getErrorNoteKey(err);
        if (!key || errorNotesInFlight.has(`${entry.id}:${key}`)) return false;
        const note = entry.errorNotes[key];
        return !(note && note.status === 'done' && note.text);
    });
    if (!pending.length) return;
    pending.forEach(err => {
        const key = getErrorNoteKey(err);
        errorNotesInFlight.add(`${entry.id}:${key}`);
        entry.errorNotes[key] = { status: 'pending', text: '' };
    });
    refreshHistoryErrorNotes(entry);
    // Les notes es redacten amb la veu per defecte de l'usuari (no amb una veu
    // temporal de la ressenya): es desa amb la nota per saber a quina veu pertany.
    const notesVoiceStyle = getReviewVoiceStyle();
    await Promise.all(pending.map(async err => {
        const key = getErrorNoteKey(err);
        try {
            const result = await callOpenAI(buildErrorNotePrompt(err), { generationConfig: { maxOutputTokens: 600 } });
            if (!result.ok || !result.text) throw new Error(result.errorMessage || `OpenAI error ${result.status}`);
            // Correcció normativa + auditoria: si el text no és fiable (SAN,
            // calcs, residus...), es descarta i la fitxa mostra l'explicació
            // local de buildLocalErrorNote, que sempre és correcta.
            const esmena = esmenaCatalaCoach(result.text.replace(/\*\*/g, '').trim(), { maxParaules: 60 });
            if (!esmena.ok) throw new Error('Text descartat pel corrector: ' + esmena.problemes.map(p => p.codi).join(', '));
            entry.errorNotes[key] = { status: 'done', text: esmena.text, voiceStyle: notesVoiceStyle };
        } catch (e) {
            console.error('[ErrorNotes]', e?.message || e);
            entry.errorNotes[key] = { status: 'error', text: '', message: e?.message || '' };
        } finally {
            errorNotesInFlight.delete(`${entry.id}:${key}`);
        }
    }));
    saveStorage();
    refreshHistoryErrorNotes(entry);
}

function refreshHistoryErrorNotes(entry) {
    if (historyReplay && historyReplay.entry && entry && historyReplay.entry.id === entry.id) {
        updateHistoryErrorNotes(historyReplay.entry);
    }
}

function updateHistoryErrorNotes(entry) {
    const container = $('#history-error-notes');
    const block = $('#history-error-notes-block');
    if (!container.length) return;
    // Comentem un mínim de 3 errades (si la partida en té), completant amb les
    // pitjors imprecisions quan no hi ha prou errades greus. Les jugades que ja
    // s'expliquen a "Moments clau" no es repeteixen aquí: si no en queda cap,
    // el bloc sencer s'amaga.
    const allErrors = entry ? getEntryReviewErrors(entry, 3, ERROR_NOTES_MAX) : [];
    let momentKeys = new Set();
    try { momentKeys = new Set(selectHumanPlanReviews(entry).map(m => reviewErrorKey(m))); } catch (e) {}
    const errors = allErrors.filter(err => !momentKeys.has(reviewErrorKey(err)));
    if (!errors.length) {
        if (block.length) block.hide();
        container.empty();
        return;
    }
    if (block.length) block.show();
    const notes = entry.errorNotes || {};
    // Veu vigent de la ressenya oberta: canviar-la només regenera aquest text.
    const voiceStyle = historyReviewVoiceStyle();
    let html = '';
    errors.forEach((err, idx) => {
        const d = describeSevereError(err);
        const note = notes[getErrorNoteKey(err)] || null;
        // Frases per veu verificades sobre la FEN ("vas portar el cavall...",
        // "vas jugar Nh4: el cavall de f3 va a h4"), mai SAN desada sense
        // verificar ni construccions "vas jugar el cavall ... va a ...".
        const playedPhrase = playedPhraseByVoice(err.fen, err.playerMove || err.playerMoveSan, voiceStyle);
        const best = bestPhraseByVoice(err.fen, err.bestMove || err.bestMoveSan, voiceStyle);
        // La nota d'OpenAI es va redactar amb una veu concreta (les antigues,
        // amb l'equilibrada): si la veu actual és una altra, es mostra
        // l'explicació local re-redactada, sense tornar a cridar cap IA.
        const noteMatchesVoice = note && (note.voiceStyle || 'balanced') === voiceStyle;
        let body;
        if (note && note.status === 'done' && note.text && noteMatchesVoice) body = escapeHtml(note.text);
        else if (note && note.status === 'pending') body = '<em>S’està generant l’explicació.</em>';
        // Sense nota d'OpenAI (o sense clau, o amb una altra veu): explicació
        // local a partir de l'anàlisi de Stockfish ja desada.
        else body = escapeHtml(buildLocalErrorNote(err, entry, { voiceStyle }));
        const samePB = d.played && d.best && d.played === d.best;
        let headMoves = (samePB || !playedPhrase || !best)
            ? (best ? `la millor jugada era <strong>${escapeHtml(best.body)}</strong>` : 'revisa la posició al tauler')
            : `<strong>${escapeHtml(playedPhrase)}</strong> · ${escapeHtml(best.prefix)}<strong>${escapeHtml(best.body)}</strong>`;
        const headAudit = ElTaulerCore.auditReviewVoiceText(String(headMoves).replace(/<[^>]*>/g, ' '), voiceStyle);
        if (!headAudit.ok) headMoves = best ? `la millor jugada era <strong>${escapeHtml(best.body)}</strong>` : 'revisa la posició al tauler';
        html += `<div class="error-note" data-error-idx="${idx}" role="button" tabindex="0" title="Clica per tornar a generar aquest exercici al tauler i resoldre'l amb pista i màxima">
            <div class="error-note-head">${coachQualityBadgeHtml({ quality: err.quality || (err.severity === 'high' ? 'blunder' : 'mistake'), swing: err.swing, evalBefore: err.evalBefore, evalAfter: err.evalAfter })} · Jugada ${escapeHtml(String(d.moveNumber))}: ${headMoves}</div>
            <div class="error-note-body">${body}</div>
            <div class="error-note-action">Clica per portar aquesta errada al tauler i corregir-la en dos moviments amb Pista i Màxima.</div>
        </div>`;
    });
    container.html(html);
    container.find('.error-note').off('click keydown').on('click keydown', function(event) {
        if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        const idx = Number(this.dataset.errorIdx);
        const err = errors[idx];
        startHistoryErrorPractice(err);
    });
}

function startHistoryErrorPractice(err) {
    if (!err || !err.fen) return false;
    matchErrorReturnReviewSnapshot = null;
    const entry = historyReplay && historyReplay.entry ? historyReplay.entry : null;
    const siblingErrors = getEntrySevereErrors(entry)
        .filter(candidate => candidate && candidate.fen && candidate.fen !== err.fen);
    stopHistoryPlayback();
    isRandomBundleSession = false;
    isSrsReviewSession = false;
    isDailyPuzzleSession = false;
    matchErrorQueue = siblingErrors;
    currentMatchError = err;
    isMatchErrorReviewSession = true;
    currentBundleSource = 'history';
    currentBundleSeverity = err.severity || (err.quality === 'blunder' ? 'high' : 'med');
    currentGameMode = 'bundle';
    currentOpponent = null;
    showToast('Errada carregada al tauler: resol-la en dos moviments. Pots fer servir Pista o Màxima.', 'success');
    startGame(true, err.fen);
    return true;
}

function buildOpenAIBundleHintPrompt(step, context = {}) {
    const stepNumber = step === 2 ? 2 : 1;
    const sentenceCount = stepNumber === 1 ? 2 : 1;
    const sentenceText = sentenceCount === 1 ? '1 frase' : '2 frases';
    const maxChars = 600;
    
    // Construir context posicional
    let contextText = '';
    if (context.fen) {
        contextText += `\nPOSICIÓ (FEN): ${context.fen}`;
    }
    if (context.playerMove) {
        contextText += `\nJugada feta: ${context.playerMove}`;
    }
    if (context.bestMove) {
        contextText += `\nMillor jugada: ${context.bestMove}`;
    }
    if (context.bestMovePv && context.bestMovePv.length) {
        contextText += `\nVariant principal: ${context.bestMovePv.slice(0, 4).join(' ')}`;
    }
    if (context.severity) {
        const severityLabels = { low: 'lleu', med: 'mitjà', high: 'greu' };
        contextText += `\nGravetat: Error ${severityLabels[context.severity] || 'desconegut'}`;
    }
    
    const extraStep1 = stepNumber === 1
        ? `\n\nPer al pas 1, genera dues frases com a màxim:\n- La primera frase ha d'apuntar a un concepte tàctic o estratègic general aplicable a aquesta posició.\n- La segona frase ha d'orientar subtilment cap a la peça o zona clau sense revelar directament la jugada.\n`
        : '';
    
    return `Ets un entrenador d'escacs expert. Analitza aquesta situació i genera ${sentenceText} en català amb màximes o principis d'escacs per ajudar a trobar la millor jugada del pas ${stepNumber}.
${contextText}

REGLES IMPERATIVES:
- Cada frase ha de tenir entre 20 i 250 caràcters
- Les màximes han de ser específiques i accionables, no genèriques
- NO facis servir frases de menys de 5 paraules
- NO repeteixis conceptes entre frases
- NO facis servir cometes, emojis, ni enumeracions
- Centra't en conceptes tàctics concrets: forquilles, clavades, atacs dobles, debilitats de peó, peces sobrecarregades, línies obertes, control del centre
- Les màximes han de guiar sense revelar directament la solució
${extraStep1}
BONS EXEMPLES de màximes per al pas 1:
Les peces actives sempre busquen caselles que controlin múltiples objectius simultàniament
Identifica les peces enemigues que defensen múltiples punts i sobrecarrega-les
Quan el rei està al centre les columnes obertes són autopistes d'atac

BONS EXEMPLES de màximes per al pas 2:
Després d'una tàctica guanyadora cal consolidar amb jugades naturals de desenvolupament
Mantén la pressió sobre els punts febles abans que l'adversari pugui reagrupar-se

Genera ara ${sentenceText} específica${sentenceCount === 1 ? '' : 's'} per aquesta posició:`;
}

