function buildOpeningAlternativesPrompt(sequence, continuations, selectedOpening) {
    const movesStr = sequence.join(' ');

    // Preparar llista d'alternatives
    let alternativesText = '';
    const moves = Object.keys(continuations);

    for (const move of moves.slice(0, 5)) { // Màxim 5 alternatives
        const openings = continuations[move];
        const names = openings.map(o => o.name).slice(0, 3).join(', ');
        alternativesText += `- ${move}: ${names}\n`;
    }

    const currentOpeningInfo = selectedOpening
        ? `OBERTURA ACTUAL: [${selectedOpening.eco || '??'}] ${selectedOpening.name}`
        : 'POSICIÓ: Sense obertura específica detectada';

    const voice = getOpeningStrategicVoice();
    return `Ets ${voice.name} aplicant "${voice.work}" als escacs.

SEQÜÈNCIA JUGADA: ${movesStr || '(inici)'}
${currentOpeningInfo}

CONTINUACIONS POSSIBLES:
${alternativesText || 'Cap continuació teòrica'}

TASCA: Escriu una anàlisi completa en català (entre 5 i 10 frases):

1. OBERTURA ACTUAL: Explica què és aquesta obertura, el seu origen històric si el coneixes, i quin és el seu objectiu estratègic principal.

2. ALTERNATIVES: Per cada continuació possible, descriu-la amb metàfores ${voice.style}:
   - NO diguis els moviments directament (${moves.slice(0, 3).join(', ')})
   - Usa al·lusions: "el camí del centre", "el flanc de rei", "la diagonal oculta", "l'avanç dels peons", "el salt del cavall"
   - Explica quina filosofia estratègica representa cada camí

3. CONSELL: Acaba amb un consell estratègic inspirat en ${voice.name} sobre preparació, terreny central, iniciativa, engany, pressió, atac indirecte, adaptació i conversió de l'obertura en avantatge de mig joc.

REGLES:
- Entre 5 i 10 frases
- Sense emojis ni numeració
- To estratègic ${voice.style}
- En català
- IMPORTANT: Acaba sempre amb un punt final

Respon:`
}

function updateOpeningMaximButton() {
    const btn = document.getElementById('btn-opening-bundle-maxim');
    if (!btn) return;
    const label = btn.querySelector('span');
    const disabledByMode = !!hieroglyphicExerciseActive || document.body.classList.contains('opening-mode-hieroglyphic');
    btn.style.display = disabledByMode ? 'none' : 'inline-flex';
    btn.disabled = disabledByMode || !!openingMaximPending;
    btn.classList.toggle('thinking', !!openingMaximPending);
    if (label) label.textContent = openingMaximPending ? 'Pensant...' : 'Màxima';
}

function getOpeningMaximContextToken() {
    return {
        fen: openingPracticeGame ? openingPracticeGame.fen() : '',
        sequence: JSON.stringify(openingCurrentSequence || []),
        lesson: !!openingLessonActive,
        hieroglyphic: !!hieroglyphicExerciseActive,
        errorPractice: !!openingErrorPracticeActive,
        id: ++openingMaximRequestCounter
    };
}

function isOpeningMaximContextCurrent(token) {
    return !!token
        && openingPracticeGame
        && token.fen === openingPracticeGame.fen()
        && token.sequence === JSON.stringify(openingCurrentSequence || [])
        && token.lesson === !!openingLessonActive
        && token.hieroglyphic === !!hieroglyphicExerciseActive
        && token.errorPractice === !!openingErrorPracticeActive
        && token.id === openingMaximRequestCounter;
}

function classifyOpeningPositionForMaxim() {
    const fen = openingPracticeGame ? openingPracticeGame.fen() : '';
    const moves = openingPracticeGame ? openingPracticeGame.history() : [];
    const oa = moves.length ? analyzeGameOpening(moves) : null;
    const validNext = getValidOpeningMoves(moves);
    if (openingLessonActive) return { theme: 'lesson', title: 'Màxima de lliçó', opening: openingLessonInfo, fen, moves, detected: oa, validNext };
    if (openingErrorPracticeActive) return { theme: 'error', title: 'Màxima per corregir l’error', opening: null, fen, moves, detected: oa, validNext };
    if (oa && oa.name) return { theme: 'detected', title: 'Base teòrica detectada', opening: oa, fen, moves, validNext };
    if (openingSelectedOpening) return { theme: 'opening', title: 'Màxima d’obertura', opening: openingSelectedOpening, fen, moves, detected: oa, validNext };
    return { theme: moves.length ? 'position' : 'general', title: 'Màxima d’obertura', opening: null, fen, moves, detected: oa, validNext };
}

function buildOfflineOpeningMaxim(info = classifyOpeningPositionForMaxim()) {
    const voice = getOpeningStrategicVoice();
    const openingName = info.opening?.name || info.detected?.name || '';
    const themeMap = { lesson: 'opening', error: 'opening', detected: 'opening', opening: 'opening', position: 'development', general: 'general' };
    const coachText = buildLocalCoachText({ theme: themeMap[info.theme] || 'opening', mode: 'opening' });
    let text = coachText.combined || coachText.maxim;
    if (info.theme === 'detected' && openingName) {
        text = `A la línia ${openingName}, ${text.charAt(0).toLowerCase()}${text.slice(1)}`;
    }
    return { voice, title: info.title || 'Màxima d’obertura', text, openingName };
}

function renderOpeningMaximHtml(text, title = 'Màxima d’obertura', meta = '') {
    const voice = getOpeningStrategicVoice();
    const safeText = escapeHtml(text || '');
    const safeTitle = escapeHtml(title || 'Màxima d’obertura');
    const safeMeta = meta ? `<div style="font-weight:600; color:#c9a227; margin-bottom:8px; font-size:0.9em;">${escapeHtml(meta)}</div>` : '';
    return `<div class="opening-maxim-box">
        <div class="maxim-title">${safeTitle}</div>
        <div class="maxim-voice">${escapeHtml(voice.name)} · ${escapeHtml(voice.work)}</div>
        ${safeMeta}
        <div class="maxim-text">"${safeText}"</div>
    </div>`;
}

function showOfflineOpeningMaxim() {
    const info = classifyOpeningPositionForMaxim();
    const offline = buildOfflineOpeningMaxim(info);
    const meta = offline.openingName ? `Base teòrica detectada: ${offline.openingName}` : '';
    const html = renderOpeningMaximHtml(offline.text, offline.title, meta);
    lastOpeningMaxim = html;
    const noteEl = document.getElementById('opening-practice-note');
    if (noteEl) noteEl.innerHTML = html;
}

async function requestOpeningMaximLlull() {
    if (!openingPracticeGame) return;
    if (hieroglyphicExerciseActive) {
        updateOpeningMaximButton();
        return;
    }
    if (!openaiApiKey) {
        showOfflineOpeningMaxim();
        return;
    }
    if (openingMaximPending) return;

    openingMaximPending = true;
    const contextToken = getOpeningMaximContextToken();
    updateOpeningMaximButton();
    const noteEl = document.getElementById('opening-practice-note');

    const info = classifyOpeningPositionForMaxim();
    const isStart = openingCurrentSequence.length === 0 && !openingLessonActive && !openingErrorPracticeActive;

    if (noteEl) {
        noteEl.innerHTML = '<div style="padding:8px; background:rgba(100,100,255,0.15); border-radius:8px;">Sun Tzu medita sobre el terreny...</div>';
    }

    let prompt;
    let continuationsData = null;
    const localTheme = info.theme === 'position' ? 'development' : (info.theme || 'opening');
    const localMaximCandidates = getOfflineMaximCandidates(localTheme, 3);
    const localCoachText = buildLocalCoachText({ theme: localTheme, mode: 'opening-prompt' });
    const localMaximText = localMaximCandidates.length ? `
TEXT LOCAL DE REFERÈNCIA (pots adaptar-ne el to i la idea):
- Màxima: ${localCoachText.maxim}
- Pista: ${localCoachText.hint}
- Explicació breu: ${localCoachText.explanation}

MÀXIMES LOCALS CANDIDATES (tria'n una idea o adapta-la sense copiar necessàriament):
- ${localMaximCandidates.join('\n- ')}
` : '';

    if (openingLessonActive) {
        const voice = getOpeningStrategicVoice();
        prompt = `Ets ${voice.name} escrivint en l'estil de ${voice.work}.

LLIÇÓ ACTUAL: ${openingLessonInfo ? `${openingLessonInfo.name} (${openingLessonInfo.eco})` : 'obertura'}
IDEA: ${openingLessonInfo?.idea || 'preparació, centre i iniciativa'}
SEQÜÈNCIA: ${(openingLessonLine || []).join(' ')}
PROGRÉS: ${openingLessonStep}/${openingLessonLine.length}

${localMaximText}
Escriu una màxima breu en català per ajudar l'alumne a entendre la lliçó actual. Parla de preparació abans de la batalla, terreny central, ritme, iniciativa i conversió al mig joc. No revelis la jugada concreta. 2 o 3 frases, sense emojis, sense cometes embolcallant tot el text.`;
    } else if (openingErrorPracticeActive) {
        const voice = getOpeningStrategicVoice();
        prompt = `Ets ${voice.name} escrivint en l'estil de ${voice.work}.

MODE: correcció d'un error d'obertura en les primeres 10 jugades.
FEN: ${openingPracticeGame.fen()}
MOVIMENT: ${openingErrorMoveFilter || '—'} (${openingErrorColorFilter === 'w' ? 'blanques' : openingErrorColorFilter === 'b' ? 'negres' : '—'})

${localMaximText}
Escriu una màxima breu en català sobre corregir l'errada sense revelar la jugada exacta, ni caselles, ni notació. Ha de parlar de recuperar el centre, no precipitar l'atac, conservar iniciativa i adaptar-se al rival. 2 o 3 frases, sense emojis.`;
    } else if (isStart) {
        prompt = `${buildOpeningEncouragementPrompt()}
${localMaximText}`;
    } else {
        continuationsData = getOpeningContinuations(openingCurrentSequence);
        prompt = `${buildOpeningAlternativesPrompt(openingCurrentSequence, continuationsData.continuations, openingSelectedOpening)}
${localMaximText}`;
    }

    try {
        const result = await callOpenAI(prompt, {
            generationConfig: {
                maxOutputTokens: isStart ? 700 : 1800
            }
        });
        if (!result.ok) throw new Error(result.errorMessage || `OpenAI error ${result.status}`);
        if (!isOpeningMaximContextCurrent(contextToken)) return;

        let cleanText = result.text
            .replace(/^\d+\.\s*/gm, '')
            .replace(/^[-•]\s*/gm, '')
            .replace(/\*\*/g, '')
            .replace(/^["«]|["»]$/g, '')
            .trim();
        if (cleanText && !/[.!?]$/.test(cleanText)) cleanText += '.';

        let meta = '';
        if (!isStart && openingSelectedOpening) {
            meta = `[${openingSelectedOpening.eco || '??'}] ${openingSelectedOpening.name}`;
        } else if (info.opening?.name || info.detected?.name) {
            meta = `Base teòrica detectada: ${info.opening?.name || info.detected?.name}`;
        }
        if (continuationsData && Object.keys(continuationsData.continuations).length > 0) {
            meta += `${meta ? ' · ' : ''}${Object.keys(continuationsData.continuations).length} continuacions possibles`;
        }

        const html = renderOpeningMaximHtml(cleanText, info.title || 'Màxima d’obertura', meta);
        lastOpeningMaxim = html;
        if (noteEl) noteEl.innerHTML = html;
    } catch (err) {
        console.error('[OpenAI Opening]', err?.message || err);
        if (isOpeningMaximContextCurrent(contextToken) && noteEl) {
            const msg = getOpenAIStatusLabel({ ok: false, status: 0, errorMessage: err?.message || '' });
            noteEl.innerHTML = `<div style="padding:10px; background:rgba(255,100,100,0.2); border-radius:8px;">${escapeHtml(msg)}. Es fa servir una màxima local.</div>`;
            showOfflineOpeningMaxim();
        }
    } finally {
        if (contextToken.id === openingMaximRequestCounter) openingMaximPending = false;
        updateOpeningMaximButton();
    }
}

function showOfflineBundleMaxim() {
    const theme = classifyPositionTheme(currentBundleFen || '', '');
    const m1 = pickOfflineMaxim(theme);
    const m2 = pickOfflineMaxim('general');
    let html = '<div style="padding:12px; background:rgba(100,150,255,0.12); border-left:3px solid #6495ed; border-radius:8px; line-height:1.6;">';
    html += '<div style="font-weight:600; color:var(--accent-gold); margin-bottom:6px;">💡 Principis d\'escacs:</div>';
    html += `<div style="font-style:italic; margin:4px 0;">${m1}</div>`;
    if (m2 !== m1) html += `<div style="font-style:italic; margin:4px 0;">${m2}</div>`;
    html += '</div>';
    lastBundleOpenAIHint = html;
    $('#status').html(html);
}

async function requestOpenAIBundleHint() {
    if (!blunderMode || !currentBundleFen) return;
    if (!openaiApiKey) {
        // Sense clau: banc de màximes local en comptes d'un avís d'error.
        showOfflineBundleMaxim();
        return;
    }
    if (bundleOpenAIHintPending) return;

    // Cau per FEN: reaprofita la màxima si ja s'ha generat per aquesta posició.
    const cacheKey = `bundle:${currentBundleFen}:${bundleSequenceStep}`;
    const cached = getCachedOpenAI(cacheKey);
    if (cached) { lastBundleOpenAIHint = cached; $('#status').html(cached); return; }
    
    bundleOpenAIHintPending = true;
    updateBundleHintButtons();
    
    const statusEl = $('#status');
    statusEl.html('<div style="padding:8px; background:rgba(100,100,255,0.15); border-radius:8px;">🧠 Generant màxima d\'escacs...</div>');
    
    let prompt;
    if (bundleFixedSequence) {
        prompt = buildBundleOpenAIPromptWithFixedSequence(bundleSequenceStep);
    } else {
        const errorContext = {};
        let currentError = savedErrors.find(e => e.fen === currentBundleFen);

        if (!currentError) {
            for (const entry of gameHistory) {
                if (entry.severeErrors && Array.isArray(entry.severeErrors)) {
                    currentError = entry.severeErrors.find(e => e.fen === currentBundleFen);
                    if (currentError) break;
                }
            }
        }

        if (currentError) {
            errorContext.fen = currentError.fen;
            errorContext.bestMove = currentError.bestMove;
            errorContext.playerMove = currentError.playerMove;
            errorContext.severity = currentError.severity;
            errorContext.bestMovePv = currentError.bestMovePv || [];
        } else {
            errorContext.fen = currentBundleFen;
        }

        const step = bundleSequenceStep === 2 ? 2 : 1;
        prompt = buildOpenAIBundleHintPrompt(step, errorContext);
    }
    
    if (!prompt) {
        bundleOpenAIHintPending = false;
        updateBundleHintButtons();
        return;
    }
    
    try {
        const result = await callOpenAI(prompt, { generationConfig: { maxOutputTokens: 2000 } });
        if (!result.ok || !result.text) throw new Error(result.errorMessage || `OpenAI error ${result.status}`);
        // Correcció normativa línia a línia (les màximes es mostren tal qual).
        const redactor = getRedactor();
        const text = redactor ? redactor.corregirCatala(result.text) : result.text;

        const lines = text.split('\n').filter(l => l.trim());
        const validLines = lines.filter(line => {
            const words = line.trim().split(/\s+/).length;
            return words >= 5;
        });
        
        if (validLines.length === 0) {
            throw new Error('Respostes massa curtes');
        }
              
        const trimmedLines = validLines.map(l => l.trim());
        
        let html = '<div style="padding:12px; background:rgba(100,150,255,0.12); border-left:3px solid #6495ed; border-radius:8px; line-height:1.6;">';
        html += '<div style="font-weight:600; color:var(--accent-gold); margin-bottom:6px;">💡 Principis d\'escacs:</div>';
        trimmedLines.forEach(line => {
            html += `<div style="font-style:italic; margin:4px 0;">${line.trim()}</div>`;
        });
        html += '</div>';
        
        // CANVI: Guardar el missatge generat
        lastBundleOpenAIHint = html;
        setCachedOpenAI(`bundle:${currentBundleFen}:${bundleSequenceStep}`, html);
        statusEl.html(html);

    } catch (err) {
        console.error(err);
        statusEl.html('<div style="padding:10px; background:rgba(255,100,100,0.2); border-radius:8px;">❌ No s\'ha pogut generar la màxima. Torna-ho a provar.</div>');
    } finally {
        bundleOpenAIHintPending = false;
        updateBundleHintButtons();
    }
}


function buildOpenAIReviewPrompt(entry, severeErrors) {
    const summary = entry.counts || {};
    const moves = getHistoryMoves(entry);
    // Si no ens passen errades (o l'entrada antiga no en tenia desades), les
    // derivem de la informació guardada (severeErrors + moveReviews) perquè la
    // regeneració sempre tingui contingut concret a analitzar.
    if (!Array.isArray(severeErrors) || !severeErrors.length) {
        severeErrors = getEntryReviewErrors(entry);
    }
    
    const errorsDetail = severeErrors.map((err, idx) => {
        const moveNum = err.moveNumber || '?';
        const played = err.playerMoveSan || err.playerMove || '?';
        const best = err.bestMoveSan || err.bestMove || '?';
        const swing = err.swing || 0;
        const pvLine = (err.bestMovePvSan || err.bestMovePv || []).slice(0, 4).join(' ');
        // La línia del motor només es presenta com a "forçada" si està
        // demostrat; si no, s'etiqueta com a possible variant perquè el model
        // no la vengui com a seqüència obligada.
        let pvDetail = '—';
        if (pvLine) {
            const fi = reviewForcingInfo(err);
            const lang = ElTaulerCore.classifyPvLanguage({
                bestPv: err.bestPv || err.bestMovePv || [],
                forcingInfo: fi
            });
            if (lang === 'forced') pvDetail = `${pvLine} (seqüència forçada demostrada)`;
            else if (lang === 'illustrative') {
                pvDetail = (fi && fi.allRepliesLosing)
                    ? `${pvLine} (possible variant, NO forçada, però qualsevol resposta del rival quedava perduda)`
                    : `${pvLine} (possible variant del motor, NO forçada: el rival tenia altres opcions)`;
            }
        }

        return `Errada ${idx + 1}:
  - Número de jugada: ${moveNum}
  - Jugada feta: ${played}
  - Millor jugada: ${best}
  - Pèrdua: ${swing} centipeons
  - Línia del motor: ${pvDetail}`;
    }).join('\n\n');

    const totalMoves = moves.length;
    
    const voice = getStrategicVoice();
    return `Ets un mestre d'escacs que ensenya amb l'esperit de "${voice.work}" de ${voice.name}: to ${voice.style}.

DADES DE LA PARTIDA
- Resultat: ${entry.result || '—'}
- Precisió: ${typeof entry.precision === 'number' ? `${entry.precision}%` : '—'}
- Total jugades: ${totalMoves}
- Jugades bones: ${(summary.excel || 0) + (summary.good || 0)}
- Imprecisions: ${summary.inaccuracy || 0}
- Errades greus: ${(summary.mistake || 0) + (summary.blunder || 0)}

ERRADES CONCRETES A ANALITZAR
${errorsDetail || 'Cap errada greu detectada.'}

FORMAT OBLIGATORI PER REFERENCIAR JUGADES
Quan mencionis una jugada específica, SEMPRE utilitza exactament aquest format:
"jugada X (SAN)" - on X és el número i SAN la notació algebraica.
Exemples correctes:
- "A la jugada 12 (Nxe5), vas perdre material..."
- "L'errada a la jugada 8 (Qd3) va ser decisiva..."
- "Calia jugar diferent a la jugada 15 (Bxf7+)..."

INSTRUCCIONS
1. Comença amb un TÍTOL: una màxima memorable entre cometes dobles
2. Paràgraf d'anàlisi general del rendiment (sense felicitacions excessives)
3. Per CADA error, escriu només 1 frase breu que digui què fallava i quina era la idea correcta
4. Paràgraf de conclusió amb el principi clau per millorar

REGLES
- Màxim 220 paraules
- Prosa natural en paràgrafs (sense llistes ni numeracions)
- Comentaris de jugada curts: evita explicacions llargues i repeticions
- No diguis mai que una línia era "forçada", "obligada" o "guanyadora segura" si les dades no ho marquen com a seqüència forçada demostrada; parla de "possible variant"
- Les màximes sempre entre cometes dobles
- To objectiu i professional

EXEMPLES DE MÀXIMES
"Desenvolupa les peces abans d'atacar"
"El rei al centre és un rei en perill"
"Abans de moure, mira què ataca el rival"
"Les peces han de treballar juntes"`;
}

async function requestOpenAIReview(entry, severeErrors) {
    if (!entry || !openaiApiKey) return;
    const existingReview = entry.aiReview || entry.deepseekReview;
    if (existingReview && existingReview.status === 'pending') return;
    // NOTA: si ja existeix una ressenya, NO sortim: el botó «Regenerar la ressenya»
    // ha de poder tornar a demanar-ne una de nova.
    const resolvedErrors = Array.isArray(severeErrors) && severeErrors.length
        ? severeErrors
        : getEntryReviewErrors(entry);
    entry.aiReview = { status: 'pending', text: '' };
    saveStorage();
    updateHistoryReview(historyReplay && historyReplay.entry && historyReplay.entry.id === entry.id ? historyReplay.entry : entry);
    const prompt = buildOpenAIReviewPrompt(entry, resolvedErrors);
    try {
        const result = await callOpenAI(prompt, { generationConfig: { maxOutputTokens: 4096 } });
        if (!result.ok || !result.text) throw new Error(result.errorMessage || `OpenAI error ${result.status}`);
        entry.aiReview = { status: 'done', text: result.text };
    } catch (error) {
        entry.aiReview = {
            status: 'error',
            message: 'No s’ha pogut generar la revisió amb OpenAI.'
        };
    }
    saveStorage();
    if (historyReplay && historyReplay.entry && historyReplay.entry.id === entry.id) {
        updateHistoryReview(historyReplay.entry);
    }
}

function historyStepForward() {
    if (!historyReplay || !historyReplay.entry || historyReplay.moveIndex >= historyReplay.moves.length) return;
    const move = historyReplay.moves[historyReplay.moveIndex];
    const mv = historyReplay.game.move(move, { sloppy: true });
    historyReplay.moveIndex++;
    historyReplay.lastMove = mv ? { from: mv.from, to: mv.to } : null;
    activeReviewHighlight = null; // navegació manual: treu els ressaltats del moment clau
    updateHistoryBoard();
}

function historyStepBack() {
    if (!historyReplay || !historyReplay.entry || historyReplay.moveIndex <= 0) return;
    historyReplay.game.undo();
    historyReplay.moveIndex--;
    const h = historyReplay.game.history({ verbose: true });
    const last = h.length ? h[h.length - 1] : null;
    historyReplay.lastMove = last ? { from: last.from, to: last.to } : null;
    activeReviewHighlight = null; // navegació manual: treu els ressaltats del moment clau
    updateHistoryBoard();
}

function startHistoryPlayback() {
    if (!historyReplay || !historyReplay.entry || historyReplay.moves.length === 0 || historyReplay.isPlaying) return;
    historyReplay.isPlaying = true;
    updateHistoryControls();
    historyReplay.timer = setInterval(() => {
        if (historyReplay.moveIndex >= historyReplay.moves.length) {
            stopHistoryPlayback();
            return;
        }
        historyStepForward();
    }, 900);
}

function stopTvPlayback() {
    if (tvReplay && tvReplay.timer) {
        clearInterval(tvReplay.timer);
        tvReplay.timer = null;
    }
    if (tvReplay) tvReplay.isPlaying = false;
    updateTvControls();
}

function updateTvControls() {
    const playBtn = $('#tv-play');
    const pauseBtn = $('#tv-pause');
    const prevBtn = $('#tv-prev');
    const nextBtn = $('#tv-next');
    const hintBtn = $('#tv-hint');
    const hasEntry = tvReplay && tvReplay.moves;
    const movesCount = hasEntry ? tvReplay.moves.length : 0;
    const atStart = !hasEntry || tvReplay.moveIndex === 0;
    const atEnd = !hasEntry || tvReplay.moveIndex >= movesCount;

    const lockedByPuzzle = tvJeroglyphicsActive || tvJeroglyphicsAnalyzing || tvJeroglyphicsIncorrect;

    playBtn.prop('disabled', !hasEntry || movesCount === 0 || tvReplay.isPlaying || atEnd || lockedByPuzzle);
    pauseBtn.prop('disabled', !hasEntry || !tvReplay.isPlaying || lockedByPuzzle);
    prevBtn.prop('disabled', !hasEntry || atStart || tvReplay.isPlaying || lockedByPuzzle);
    nextBtn.prop('disabled', !hasEntry || atEnd || tvReplay.isPlaying || lockedByPuzzle);
     hintBtn.prop('disabled', !tvJeroglyphicsActive || tvJeroglyphicsSolved);
    updateTvBoardInteractivity();  
    updateTvEndActions();
}

function updateTvProgress() {
    const progress = $('#tv-progress');
    if (!tvReplay || !tvReplay.moves) {
        progress.text('0/0');
        return;
    }
    progress.text(`${tvReplay.moveIndex}/${tvReplay.moves.length}`);
}

function updateTvEndActions() {
    const actions = $('#tv-end-actions');
    if (!tvReplay || !tvReplay.moves || tvReplay.moves.length === 0) {
        actions.hide();
        return;
    }
    const atEnd = tvReplay.moveIndex >= tvReplay.moves.length;
    if (atEnd && !tvReplay.isPlaying) actions.show();
    else actions.hide();
}

function updateTvBoard() {
    if (!tvBoard || !tvReplay || !tvReplay.game) return;
    tvBoard.position(tvReplay.game.fen(), false);
    resizeTvBoardToViewport();
    clearTvHintHighlight();   
    updateTvProgress();
    updateTvControls();
    updateTvJeroglyphicsUI();
}

function initTvBoard() {
    if (tvBoard) return;
    const boardEl = document.getElementById('tv-board');
    if (!boardEl) return;
    tvBoard = Chessboard('tv-board', {
        draggable: true,
        position: 'start',
        onDragStart: tvOnDragStart,
        onDrop: tvOnDrop,
        onSnapEnd: tvOnSnapEnd,      
        pieceTheme: 'https://chessboardjs.com/img/chesspieces/wikipedia/{piece}.png'
    });
    resizeTvBoardToViewport();
    updateTvBoardInteractivity();
}

function updateTvBoardInteractivity() {
    if (!tvBoard) return;
    const shouldUseTap = tvJeroglyphicsActive && deviceType === 'mobile' && controlMode === 'tap' && isTouchDevice();
    tvBoard.draggable = !shouldUseTap;
    if (shouldUseTap) {
        enableTvTapToMove();
    } else {
        disableTvTapToMove();
    }
}

function clearTvHintHighlight() {
    $('#tv-board .square-55d63').removeClass('highlight-hint');
}

function highlightTvHintSquare(square) {
    clearTvHintHighlight();
    if (!square) return;
    $(`#tv-board .square-55d63[data-square='${square}']`).addClass('highlight-hint');
}

function tvOnDragStart(source, piece) {
    if (!tvJeroglyphicsActive || tvJeroglyphicsAnalyzing || tvJeroglyphicsSolved || tvJeroglyphicsIncorrect) return false;
    if (!tvReplay || !tvReplay.game) return false;
    if ((tvReplay.game.turn() === 'w' && piece.search(/^b/) !== -1) ||
        (tvReplay.game.turn() === 'b' && piece.search(/^w/) !== -1)) return false;
}

function tvOnDrop(source, target) {
    if (!tvJeroglyphicsActive || tvJeroglyphicsSolved || !tvReplay || !tvReplay.game) return 'snapback';
    clearTvHintHighlight();
    const testGame = new Chess(tvReplay.game.fen());
    const move = testGame.move({ from: source, to: target, promotion: 'q' });
    if (!move) return 'snapback';
    const uciBase = move.from + move.to;
    const uci = uciBase + (move.promotion ? move.promotion : '');
    const accepted = tvJeroglyphicsTopMoves.filter(Boolean);
    const ok = accepted.length > 0 && accepted.some(candidate => (
        candidate === uci || candidate === uciBase || candidate.startsWith(uciBase)
    ));
    showMoveFeedback('tv-board', move.from, move.to, ok ? 'correct' : 'incorrect');
    if (ok) {
        setTvStatus('Correcte! Pots continuar la partida.');
        tvJeroglyphicsSolved = true;
        tvJeroglyphicsIncorrect = false;
        tvJeroglyphicsAnalyzing = false;
        updateTvJeroglyphicsUI();
        updateTvControls()
    } else {
        setTvStatus('Incorrecte. Torna-ho a provar.');
        tvJeroglyphicsIncorrect = true;
        updateTvJeroglyphicsUI();
        updateTvControls();
    }
    return 'snapback';
}

function tvOnSnapEnd() {
    if (!tvBoard || !tvReplay || !tvReplay.game) return;
    tvBoard.position(tvReplay.game.fen(), false);
}

function setTvStatus(message, isError = false) {
    const status = $('#tv-status');
    status.text(message || '');
    status.css('color', isError ? 'var(--severity-high)' : 'var(--text-secondary)');
}

function getTvJeroglyphicsTurnLabel() {
    if (!tvReplay || !tvReplay.game) return '';
    return tvReplay.game.turn() === 'w' ? 'Juguen Blanques' : 'Juguen Negres';
}

function updateTvJeroglyphicsUI() {
    const turnEl = $('#tv-jeroglyphics-turn');
    const overlayEl = $('#tv-jeroglyphics-overlay');
    const correctEl = $('#tv-jeroglyphics-result-correct');
    const incorrectEl = $('#tv-jeroglyphics-result-incorrect');
    if (turnEl.length) {
        if (tvJeroglyphicsActive) {
            turnEl.text(getTvJeroglyphicsTurnLabel());
            turnEl.show();
        } else {
            turnEl.hide();
        }
    }
    if (overlayEl.length) {
        const showOverlay = tvJeroglyphicsActive && (tvJeroglyphicsSolved || tvJeroglyphicsIncorrect);
        overlayEl.toggle(showOverlay);
        correctEl.toggle(!!tvJeroglyphicsSolved);
        incorrectEl.toggle(!!tvJeroglyphicsIncorrect);
    }
}

function updateTvDetails(entry) {
    const resultEl = $('#tv-result');
    const metaEl = $('#tv-meta');
    const eloEl = $('#tv-elo');
    const whiteEl = $('#tv-white-player');
    const blackEl = $('#tv-black-player');
    if (!entry) {
        resultEl.text('—');
        metaEl.text('Sense dades.');
        eloEl.text('—');
        whiteEl.text('—');
        blackEl.text('—');
        return;
    }
    resultEl.text(`${entry.white} vs ${entry.black}`);
    metaEl.text(`${entry.event} · ${entry.date}`);
    eloEl.text(`${entry.whiteElo} vs ${entry.blackElo}`);
    whiteEl.text(entry.white || '—');
    blackEl.text(entry.black || '—');
}

function resetTvJeroglyphicsState() {
    tvJeroglyphicsActive = false;
    tvJeroglyphicsAnalyzing = false;
    tvJeroglyphicsHinting = false;
    tvJeroglyphicsTopMoves = [];
    tvJeroglyphicsPvMoves = {};
    tvJeroglyphicsTargetIndex = null;
    tvJeroglyphicsActualMove = null;
    tvJeroglyphicsResumePlayback = false;
    tvJeroglyphicsSolved = false;
    tvJeroglyphicsIncorrect = false;
    clearTvHintHighlight();
    updateTvJeroglyphicsUI();
}

async function fetchTvPgn(entry) {
    if (!entry) return '';
    if (entry.pgnUrl) {
        try {
            const response = await fetch(entry.pgnUrl, {
                headers: { 'Accept': 'application/x-chess-pgn' }
            });
            if (!response.ok) throw new Error('PGN fetch failed');
            const text = await response.text();
            const trimmed = text.trim();
            if (trimmed) return trimmed;
        } catch (err) {
            // Fall through to embedded PGN if available.
        }
    }
    return entry.pgnText ? entry.pgnText.trim() : '';
}

function shuffleArray(items) {
    const list = items.slice();
    for (let i = list.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
}

function formatTvDate(date = new Date()) {
    return date.toISOString().slice(0, 10).replace(/-/g, '.');
}

function normalizeTvPlayerName(player, fallback) {
    if (!player) return fallback;
    if (player.user) return player.user.name || player.user.id || fallback;
    return player.name || player.id || player.username || fallback;
}

function normalizeTvElo(player) {
    if (!player) return '—';
    return player.rating || player.elo || '—';
}

function extractTvGameFromPayload(payload) {
    if (!payload) return null;
    if (payload.gameId || payload.id) return payload;
    if (payload.featured) return payload.featured;
    if (payload.current) return payload.current;
    if (payload.game) return payload.game;
    if (payload.channels && typeof payload.channels === 'object') {
        const candidates = Object.values(payload.channels);
        for (const candidate of candidates) {
            if (!candidate) continue;
            if (candidate.gameId || candidate.id) return candidate;
            if (candidate.game) return candidate.game;
        }
    }
    return null;
}

let cachedTopPlayers = null;
let topPlayersCacheTime = 0;
const TOP_PLAYERS_CACHE_MS = 3600000;

async function getTopPlayers() {
    const now = Date.now();
    if (cachedTopPlayers && (now - topPlayersCacheTime) < TOP_PLAYERS_CACHE_MS) {
        return cachedTopPlayers;
    }

    const categories = ['classical', 'rapid', 'blitz'];
    const allUsers = new Set();

    for (const cat of categories) {
        try {
            const response = await fetch(`https://lichess.org/api/player/top/30/${cat}`);
            if (!response.ok) continue;
            const data = await response.json();
            const users = data.users || [];
            users.forEach(u => allUsers.add(u.username));
        } catch (err) {}
    }

    if (allUsers.size > 0) {
        cachedTopPlayers = Array.from(allUsers);
        topPlayersCacheTime = now;
    }

    return cachedTopPlayers || ['DrNykterstein', 'penguingim1', 'Fins0', 'lance5500', 'opperwezen'];
}

async function fetchMastersGame() {
    const fen = MASTERS_OPENINGS[Math.floor(Math.random() * MASTERS_OPENINGS.length)];

    try {
        const response = await fetch(
            `https://explorer.lichess.ovh/masters?fen=${encodeURIComponent(fen)}&topGames=15`,
            { headers: { 'Accept': 'application/json' } }
        );
        if (!response.ok) return null;

        const data = await response.json();
        const topGames = data.topGames || [];
        if (!topGames.length) return null;

        const game = topGames[Math.floor(Math.random() * topGames.length)];
        if (!game.id) return null;

        const pgnResponse = await fetch(
            `https://lichess.org/game/export/${game.id}`,
            { headers: { 'Accept': 'application/x-chess-pgn' } }
        );
        if (!pgnResponse.ok) return null;

        const pgnText = await pgnResponse.text();
        if (!pgnText || pgnText.trim().length < 50) return null;

        return {
            id: `masters-${game.id}`,
            white: game.white?.name || 'Blanques',
            black: game.black?.name || 'Negres',
            whiteElo: game.white?.rating || '—',
            blackElo: game.black?.rating || '—',
            event: 'Masters Database',
            date: game.year ? `${game.year}` : '—',
            result: game.winner === 'white' ? '1-0' : game.winner === 'black' ? '0-1' : '1/2-1/2',
            pgnText: pgnText.trim()
        };
    } catch (err) {
        console.warn('fetchMastersGame error:', err);
        return null;
    }
}

async function fetchTopPlayerGame() {
    const topPlayers = await getTopPlayers();
    const user = topPlayers[Math.floor(Math.random() * topPlayers.length)];
    
    try {
        const response = await fetch(
            `https://lichess.org/api/games/user/${user}?max=50&finished=true&perfType=blitz,rapid,classical&clocks=false&evals=false`,
            {
                headers: { 'Accept': 'application/x-chess-pgn' },
                cache: 'no-store'
            }
        );
        if (!response.ok) return null;
        
        const allPgn = await response.text();
        if (!allPgn || allPgn.trim().length < 50) return null;
        
        const games = allPgn.split(/\n(?=\[Event )/).filter(g => g.trim().length > 100);
        if (!games.length) return null;
        
        const validGames = games.filter(pgn => {
            const result = pgn.match(/\[Result\s+"([^"]+)"\]/);
            if (!result || result[1] === '*') return false;
            const moves = pgn.split(/\d+\.\s/).length - 1;
            return moves >= 20;
        });

        if (!validGames.length) return null;
        const pgnText = validGames[Math.floor(Math.random() * validGames.length)];
        
        const getHeader = (name) => {
            const match = pgnText.match(new RegExp(`\\[${name}\\s+"([^"]+)"\\]`));
            return match ? match[1] : null;
        };
        
        const gameId = getHeader('Site')?.split('/').pop() || `lichess-${Date.now()}`;
        const result = getHeader('Result');
        
        if (!result || result === '*') return null;
        
        return {
            id: `lichess-${gameId}`,
            white: getHeader('White') || 'Blanques',
            black: getHeader('Black') || 'Negres',
            whiteElo: getHeader('WhiteElo') || '—',
            blackElo: getHeader('BlackElo') || '—',
            event: getHeader('Event') || 'Lichess',
            date: getHeader('UTCDate') || getHeader('Date') || formatTvDate(),
            result: result,
            pgnText: pgnText.trim()
        };

    } catch (err) {
        console.warn('fetchTopPlayerGame error:', err);
        return null;
    }
}

async function fetchLichessDbGameByElo(targetElo) {
    const fen = MASTERS_OPENINGS[Math.floor(Math.random() * MASTERS_OPENINGS.length)];
    const rating = mapEloToLichessRating(targetElo);
    const speed = TV_LICHESS_SPEEDS[Math.floor(Math.random() * TV_LICHESS_SPEEDS.length)];

    try {
        const response = await fetch(
            `https://explorer.lichess.ovh/lichess?fen=${encodeURIComponent(fen)}&topGames=15&ratings=${rating}&speeds=${speed}`,
            { headers: { 'Accept': 'application/json' } }
        );
        if (!response.ok) return null;

        const data = await response.json();
        const topGames = data.topGames || [];
        if (!topGames.length) return null;

        const game = topGames[Math.floor(Math.random() * topGames.length)];
        if (!game.id) return null;

        const pgnResponse = await fetch(
            `https://lichess.org/game/export/${game.id}`,
            { headers: { 'Accept': 'application/x-chess-pgn' } }
        );
        if (!pgnResponse.ok) return null;

        const pgnText = await pgnResponse.text();
        if (!pgnText || pgnText.trim().length < 50) return null;

        const whiteName = game.white?.name || 'Blanques';
        const blackName = game.black?.name || 'Negres';

        return {
            id: `lichess-db-${game.id}`,
            white: whiteName,
            black: blackName,
            whiteElo: game.white?.rating || rating || '—',
            blackElo: game.black?.rating || rating || '—',
            event: `Lichess ${speed}`,
            date: game.year ? `${game.year}` : formatTvDate(),
            result: game.winner === 'white' ? '1-0' : game.winner === 'black' ? '0-1' : '1/2-1/2',
            pgnText: pgnText.trim()
        };
    } catch (err) {
        console.warn('fetchLichessDbGameByElo error:', err);
        return null;
    }
}

async function loadTvGame(entry) {
    if (!entry) return;
    stopTvPlayback();
    resetTvJeroglyphicsState();      
    initTvBoard();  
    setTvStatus('Carregant partida...');
    const rawPgnText = await fetchTvPgn(entry);
    let pgnText = selectTvPgn(rawPgnText);
    let pgnGame = new Chess();
    let loaded = pgnGame.load_pgn(pgnText, { sloppy: true });
    if (!loaded && entry.pgnText) {
        const fallbackText = selectTvPgn(entry.pgnText);
        pgnGame = new Chess();
        loaded = pgnGame.load_pgn(fallbackText, { sloppy: true });
        if (loaded) pgnText = fallbackText;
    }
    if (!loaded) {
        tvReplay = null;
        updateTvDetails(null);
        updateTvProgress();
        updateTvControls();
        setTvStatus('No s’ha pogut carregar la partida.', true);
       return false;
    }
      const header = pgnGame.header ? pgnGame.header() : {};
    const result = header && header.Result ? header.Result : '*';
    const termination = header && header.Termination ? String(header.Termination).toLowerCase() : '';
    const normalizedPgn = pgnText.trim();
    const endMatch = normalizedPgn.match(/(1-0|0-1|1\/2-1\/2|\*)\s*$/);
    const endToken = endMatch ? endMatch[1] : null;
    const isOngoing = result === '*'
        || termination.includes('unterminated')
        || termination.includes('abandoned')
        || !endToken
        || endToken !== result;
    if (isOngoing) {
        tvReplay = null;
        updateTvDetails(null);
        updateTvProgress();
        updateTvControls();
        setTvStatus('Partida inacabada. Buscant-ne una de completa...', true);
        return false;
    }
    const moves = pgnGame.history();
    if (moves.length < MIN_TV_MOVES) {
        tvReplay = null;
        updateTvDetails(null);
        updateTvProgress();
        updateTvControls();
        setTvStatus('Partida massa curta per TV.', true);
        return false;
    }
    tvReplay = {
        data: entry,
        game: new Chess(),
        moves: moves,
        moveIndex: 0,
        timer: null,
        isPlaying: false
    };
    updateTvDetails(entry);
    updateTvBoard();
    setTvStatus(`Partida carregada · ${moves.length} jugades.`);
    return true;
}

function splitTvPgnBlocks(pgnText) {
    if (!pgnText) return [];
    const normalized = pgnText.replace(/\r\n/g, '\n').trim();
    if (!normalized) return [];
    const blocks = normalized.split(/\n(?=\[Event\s)/g);
    return blocks.map(block => block.trim()).filter(Boolean);
}

function selectTvPgn(pgnText) {
    if (!pgnText) return '';
    const blocks = splitTvPgnBlocks(pgnText);
    if (!blocks.length) return pgnText.trim();
    if (blocks.length === 1) return blocks[0];
    let best = blocks[0];
    let bestMoves = -1;
    blocks.forEach(block => {
        const game = new Chess();
        if (!game.load_pgn(block, { sloppy: true })) return;
        const count = game.history().length;
        if (count > bestMoves) {
            bestMoves = count;
            best = block;
        }
    });
    return best;
}

function pickRandomTvGame() {
    if (!TV_FALLBACK_POOL.length) return null;
    if (!tvReplay || !tvReplay.data) return TV_FALLBACK_POOL[randInt(0, TV_FALLBACK_POOL.length - 1)];
    const currentId = tvReplay.data.id;
    const options = TV_FALLBACK_POOL.filter(entry => entry.id !== currentId);
    if (!options.length) return TV_FALLBACK_POOL[0];
    return options[randInt(0, options.length - 1)];
}

async function loadRandomTvGame() {
    randomizeTvElo();
    const dynamicEntry = await fetchLichessDbGameByElo(tvSelectedElo);
    if (dynamicEntry) {
        lastTvDynamicId = dynamicEntry.id;
        const ok = await loadTvGame(dynamicEntry);
        if (ok) return;
    }
    const attempts = TV_FALLBACK_POOL.length || 1;
    for (let i = 0; i < attempts; i++) {
        const next = pickRandomTvGame();
        const ok = await loadTvGame(next);
        if (ok) return;
    }
}

function shouldTriggerTvJeroglyphics() {
    if (!tvJeroglyphicsEnabled || tvJeroglyphicsActive || tvJeroglyphicsAnalyzing) return false;
    if (!tvReplay || !tvReplay.moves) return false;
    const moveIndex = tvReplay.moveIndex || 0;
    if (moveIndex < TV_JEROGLYPHICS_START) return false;
    if ((moveIndex - TV_JEROGLYPHICS_START) % TV_JEROGLYPHICS_INTERVAL !== 0) return false;
    const remaining = tvReplay.moves.length - moveIndex;
    return remaining > TV_JEROGLYPHICS_END_BUFFER;
}

function startTvJeroglyphics(resumePlayback) {
    if (!tvReplay || !tvReplay.game) return;
    if (!stockfish && !ensureStockfish()) {
        setTvStatus('Motor Stockfish no disponible.', true);
        return;
    }
    tvJeroglyphicsActive = true;
    tvJeroglyphicsAnalyzing = true;
    tvJeroglyphicsHinting = false;
    tvJeroglyphicsTopMoves = [];
    tvJeroglyphicsPvMoves = {};
    tvJeroglyphicsTargetIndex = tvReplay.moveIndex;
    tvJeroglyphicsActualMove = tvReplay.moves[tvReplay.moveIndex] || null;
    tvJeroglyphicsResumePlayback = !!resumePlayback;
    tvJeroglyphicsSolved = false;
    tvJeroglyphicsIncorrect = false;
    clearTvHintHighlight();
    stopTvPlayback();
    setTvStatus('Jeroglífic: buscant la millor jugada...');
    updateTvControls();
    updateTvJeroglyphicsUI();
    
    try { stockfish.postMessage('setoption name MultiPV value 1'); } catch (e) {}
    stockfish.postMessage(`position fen ${tvReplay.game.fen()}`);
    stockfish.postMessage('go depth 12');
}

function finishTvJeroglyphics(options = {}) {
    const { advanceMove = true, resumePlayback = tvJeroglyphicsResumePlayback } = options;
    tvJeroglyphicsActive = false;
    tvJeroglyphicsAnalyzing = false;
    tvJeroglyphicsHinting = false;
    tvJeroglyphicsSolved = false;
    tvJeroglyphicsIncorrect = false;
    tvJeroglyphicsResumePlayback = false;
    clearTvHintHighlight();
    try { stockfish.postMessage('setoption name MultiPV value 1'); } catch (e) {}

    if (advanceMove && tvReplay && tvReplay.game) {
        const move = tvJeroglyphicsActualMove;
        tvJeroglyphicsActualMove = null;
        if (move) {
            try {
                tvReplay.game.move(move, { sloppy: true });
                tvReplay.moveIndex++;
                updateTvBoard();
            } catch (e) {}
        }
    } else {
        tvJeroglyphicsActualMove = null;
        updateTvControls();
        updateTvJeroglyphicsUI();
    }
    if (resumePlayback && tvReplay && !tvReplay.isPlaying) startTvPlayback();
}

function cancelTvJeroglyphics(message) {
    if (message) setTvStatus(message);
    tvJeroglyphicsResumePlayback = false;
    finishTvJeroglyphics();
}

function requestTvJeroglyphicsHint() {
    if (!tvJeroglyphicsActive || tvJeroglyphicsSolved || tvJeroglyphicsIncorrect || !tvReplay || !tvReplay.game) return;
    if (tvJeroglyphicsAnalyzing) {
        setTvStatus('Esperant la millor jugada...');
        return;
    }
    if (tvJeroglyphicsTopMoves.length > 0) {
        const toSquare = tvJeroglyphicsTopMoves[0].substring(2, 4);
        highlightTvHintSquare(toSquare);
        setTvStatus(`Pista: Alguna peça ha d'anar a ${toSquare}`);
        return;
    }
    if (!stockfish && !ensureStockfish()) {
        setTvStatus('Motor Stockfish no disponible.', true);
        return;
    }
    tvJeroglyphicsHinting = true;
    setTvStatus('Buscant pista...');
    stockfish.postMessage(`position fen ${tvReplay.game.fen()}`);
    stockfish.postMessage('go depth 15');
}

function tvStepForward() {
    if (!tvReplay || !tvReplay.moves || tvReplay.moveIndex >= tvReplay.moves.length) return;
    if (shouldTriggerTvJeroglyphics()) {
        startTvJeroglyphics(tvReplay.isPlaying);
        return;
    }   
    const move = tvReplay.moves[tvReplay.moveIndex];
    tvReplay.game.move(move, { sloppy: true });
    tvReplay.moveIndex++;
    updateTvBoard();
}

function tvStepBack() {
    if (!tvReplay || !tvReplay.moves || tvReplay.moveIndex <= 0) return;
    tvReplay.game.undo();
    tvReplay.moveIndex--;
    updateTvBoard();
}

function startTvPlayback() {
    if (!tvReplay || !tvReplay.moves || tvReplay.moves.length === 0 || tvReplay.isPlaying) return;
    tvReplay.isPlaying = true;
    updateTvControls();
    tvReplay.timer = setInterval(() => {
        if (tvReplay.moveIndex >= tvReplay.moves.length) {
            stopTvPlayback();
            return;
        }
        tvStepForward();
    }, 2000);
}

function resetTvReplay() {
    if (!tvReplay || !tvReplay.moves) return;
    stopTvPlayback();
    resetTvJeroglyphicsState();
    tvReplay.game = new Chess();
    tvReplay.moveIndex = 0;
    updateTvBoard();
}

let historyFilters = { result: 'all', mode: 'all', prec: 0 };

function historyEntryPasses(entry) {
    if (historyFilters.result !== 'all' && entryOutcome(entry) !== historyFilters.result) return false;
    // El filtre de mode només té sentit a la pestanya de partides pròpies (a la
    // pestanya PGN totes són importades i el desplegable està amagat).
    if (historyActiveTab !== 'pgn' && historyFilters.mode !== 'all' && entry.mode !== historyFilters.mode) return false;
    if (historyFilters.prec > 0 && (typeof entry.precision !== 'number' || entry.precision < historyFilters.prec)) return false;
    return true;
}

// Icona i classe visual del resultat d'una partida per a la llista de l'historial.
function historyOutcomeMeta(entry) {
    const outcome = entryOutcome(entry);
    if (outcome === 'win') return { outcome, cls: 'hi-win', icon: '🏆' };
    if (outcome === 'loss') return { outcome, cls: 'hi-loss', icon: '💔' };
    if (outcome === 'draw') return { outcome, cls: 'hi-draw', icon: '🤝' };
    return { outcome: null, cls: 'hi-draw', icon: '♟' };
}

// Classe de color d'una precisió (mateixos llindars que la barra en viu de la partida).
function precisionPillClass(p) {
    if (typeof p !== 'number') return '';
    if (p >= 75) return 'hp-good';
    if (p >= 50) return 'hp-mid';
    return 'hp-low';
}

// Fitxes-resum de la capçalera de l'historial, segons la pestanya activa:
// per a les partides pròpies, partides/balanç/precisió; per a la pestanya PGN,
// quantes partides hi ha (del màxim de 10) i quantes estan analitzades.
function renderHistorySummary() {
    const el = $('#history-summary');
    if (!el.length) return;
    const tile = (label, value) => `<div class="history-summary-tile"><div class="hst-label">${label}</div><div class="hst-value">${value}</div></div>`;
    if (historyActiveTab === 'pgn') {
        if (!importedGameHistory.length) { el.empty().hide(); return; }
        let analyzed = 0, precSum = 0, precN = 0;
        importedGameHistory.forEach(e => {
            if (historyEntryReviewCount(e)) analyzed++;
            if (typeof e.precision === 'number') { precSum += e.precision; precN++; }
        });
        const avg = precN ? Math.round(precSum / precN) : null;
        el.html(
            tile('Partides PGN', `${importedGameHistory.length} de ${IMPORTED_HISTORY_MAX}`) +
            tile('Analitzades', String(analyzed)) +
            tile('Precisió mitjana', avg === null ? '—' : `${avg}%`)
        ).show();
        return;
    }
    if (!gameHistory.length) { el.empty().hide(); return; }
    let wins = 0, losses = 0, draws = 0, precSum = 0, precN = 0;
    gameHistory.forEach(e => {
        const o = entryOutcome(e);
        if (o === 'win') wins++;
        else if (o === 'loss') losses++;
        else if (o === 'draw') draws++;
        if (typeof e.precision === 'number') { precSum += e.precision; precN++; }
    });
    const avg = precN ? Math.round(precSum / precN) : null;
    el.html(
        tile('Partides', String(gameHistory.length)) +
        tile('Balanç', `${wins}V · ${draws}E · ${losses}D`) +
        tile('Precisió mitjana', avg === null ? '—' : `${avg}%`)
    ).show();
}

// Sincronitza els botons de pestanya de l'historial (actiu, comptadors), el
// títol de la llista i la visibilitat del filtre de mode amb la pestanya activa.
function syncHistoryTabsUi() {
    const mineBtn = $('#history-tab-mine');
    const pgnBtn = $('#history-tab-pgn');
    if (!mineBtn.length || !pgnBtn.length) return;
    const isPgn = historyActiveTab === 'pgn';
    mineBtn.toggleClass('active', !isPgn).attr('aria-selected', String(!isPgn));
    pgnBtn.toggleClass('active', isPgn).attr('aria-selected', String(isPgn));
    mineBtn.text(`Les meves partides${gameHistory.length ? ` (${gameHistory.length})` : ''}`);
    pgnBtn.text(`Partides PGN${importedGameHistory.length ? ` (${importedGameHistory.length})` : ''}`);
    $('#history-filter-mode').toggle(!isPgn);
    const titleEl = $('#history-list-title');
    if (titleEl.length) titleEl.text(isPgn ? 'Partides importades (PGN)' : 'Partides jugades a l\'app');
}

// Canvia la pestanya activa de l'historial. Si la partida seleccionada no és
// de la pestanya nova, es deixa anar i renderGameHistory carrega la més nova.
function setHistoryActiveTab(tab) {
    const next = tab === 'pgn' ? 'pgn' : 'mine';
    if (historyActiveTab !== next) {
        historyActiveTab = next;
        const current = historyReplay && historyReplay.entry;
        if (!current || historyEntryIsImported(current) !== (next === 'pgn')) historyReplay = null;
    }
    renderGameHistory();
}

// Obre una entrada concreta assegurant que la seva pestanya (pròpies o PGN)
// està activa; les tornades de reptes i repassos d'errades passen per aquí.
function openHistoryEntry(entry) {
    if (!entry) return;
    const tab = historyEntryIsImported(entry) ? 'pgn' : 'mine';
    if (historyActiveTab !== tab) {
        historyActiveTab = tab;
        renderGameHistory();
    }
    loadHistoryEntry(entry);
}

// ── Grups desplegables de l'historial ────────────────────────────────────────
// Amb desenes de partides desades, una llista plana és inservible: les partides
// es reparteixen en seccions per antiguitat (Avui, Ahir, Fa 2 dies, Fa 1
// setmana, Fa 1 mes...) i només les més recents arriben desplegades.
//
// Aquí només hi viu QUÈ ha tocat l'usuari (clau del grup → obert/tancat), per
// pestanya. No es desa entre sessions a propòsit: les claus són relatives a
// AVUI, i «fa 2 dies» demà ja no vol dir el mateix.
let historyGroupOpenState = { mine: {}, pgn: {} };

function historyGroupStateForTab() {
    const tab = historyActiveTab === 'pgn' ? 'pgn' : 'mine';
    if (!historyGroupOpenState[tab]) historyGroupOpenState[tab] = {};
    return historyGroupOpenState[tab];
}

// Resum d'una secció: quantes partides hi ha i, a les partides pròpies, el
// balanç del grup (les PGN no tenen resultat propi i només es compten).
function historyGroupSummary(group) {
    const n = group.entries.length;
    const count = `${n} ${n === 1 ? 'partida' : 'partides'}`;
    if (historyActiveTab === 'pgn') return count;
    let wins = 0, draws = 0, losses = 0;
    group.entries.forEach(entry => {
        const o = entryOutcome(entry);
        if (o === 'win') wins++;
        else if (o === 'draw') draws++;
        else if (o === 'loss') losses++;
    });
    if (!wins && !draws && !losses) return count;
    return `${count} · ${wins}V · ${draws}E · ${losses}D`;
}

// Targeta d'una partida de la llista.
function historyItemHtml(entry, activeId) {
    const movesCount = Math.ceil(getHistoryMoves(entry).length / 2);
    const om = historyOutcomeMeta(entry);
    const prec = typeof entry.precision === 'number' ? entry.precision : null;
    const imported = historyEntryIsImported(entry);
    // A la pestanya PGN el titular són els jugadors (capçaleres del PGN
    // o nom del fitxer) i el resultat original passa a la línia de sota.
    const title = imported
        ? (entry.players || entry.result || 'Partida PGN')
        : (entry.result || '—');
    const metaParts = [];
    if (imported && entry.players) {
        const rawResult = entry.importHeaders && entry.importHeaders.Result && entry.importHeaders.Result !== '*'
            ? entry.importHeaders.Result
            : entry.result;
        if (rawResult) metaParts.push(rawResult);
    }
    metaParts.push(entry.label || '—', describeHistoryGame(entry), `${movesCount} jugades`);
    const meta = metaParts.join(' · ');
    return `
        <div class="history-item ${om.cls}${entry.id === activeId ? ' active' : ''}" data-history-id="${entry.id}" role="button" tabindex="0" title="Obre el detall i la revisió d'aquesta partida">
            <div class="history-item-icon" aria-hidden="true">${om.icon}</div>
            <div class="history-item-main">
                <div class="history-item-title">${escapeHtml(title)}</div>
                <div class="history-item-meta">${escapeHtml(meta)}</div>
            </div>
            <div class="history-item-side">
                <span class="history-prec-pill ${precisionPillClass(prec)}" title="Precisió de la partida">${prec === null ? '—' : `${prec}%`}</span>
                <button class="btn history-delete" data-history-id="${entry.id}" title="Esborrar aquesta partida de l'historial" aria-label="Esborrar aquesta partida de l'historial"><svg class="btn-ic" aria-hidden="true"><use href="#ic-trash"/></svg></button>
            </div>
        </div>
    `;
}

// Secció desplegable d'un grup d'antiguitat.
function historyGroupHtml(group, isOpen, activeId) {
    const tab = historyActiveTab === 'pgn' ? 'pgn' : 'mine';
    const bodyId = `history-group-${tab}-${group.key}`;
    const items = group.entries.map(entry => historyItemHtml(entry, activeId)).join('');
    return `
        <div class="history-group${isOpen ? ' open' : ''}" data-group-key="${escapeHtml(group.key)}">
            <button type="button" class="history-group-head" aria-expanded="${isOpen ? 'true' : 'false'}" aria-controls="${bodyId}">
                <span class="history-group-chevron" aria-hidden="true">›</span>
                <span class="history-group-label">${escapeHtml(group.label)}</span>
                <span class="history-group-meta">${escapeHtml(historyGroupSummary(group))}</span>
            </button>
            <div class="history-group-body" id="${bodyId}"${isOpen ? '' : ' hidden'}>${items}</div>
        </div>
    `;
}

// Botó «Desplega-ho tot / Plega-ho tot»: només surt si hi ha més d'un grup.
function syncHistoryGroupsToggle() {
    const btn = $('#history-groups-toggle');
    if (!btn.length) return;
    const heads = $('#history-list .history-group-head');
    if (heads.length < 2) { btn.hide(); return; }
    const anyClosed = heads.toArray().some(el => el.getAttribute('aria-expanded') !== 'true');
    btn.show()
        .text(anyClosed ? 'Desplega-ho tot' : 'Plega-ho tot')
        .attr('title', anyClosed ? 'Obre tots els grups de partides' : 'Tanca tots els grups de partides')
        .data('action', anyClosed ? 'expand' : 'collapse');
}

// Obre o tanca un grup (sense repintar la llista: així no salta l'scroll).
function setHistoryGroupOpen(wrap, open) {
    const el = $(wrap);
    if (!el.length) return;
    const key = el.data('group-key');
    el.toggleClass('open', open);
    el.find('.history-group-head').first().attr('aria-expanded', open ? 'true' : 'false');
    el.find('.history-group-body').first().prop('hidden', !open);
    if (key) historyGroupStateForTab()[key] = open;
}

// Marca la partida seleccionada a la llista sense repintar-la sencera.
function syncHistoryListActive() {
    const activeId = historyReplay && historyReplay.entry ? historyReplay.entry.id : null;
    $('#history-list .history-item').each(function() {
        $(this).toggleClass('active', $(this).data('history-id') === activeId);
    });
}

function renderGameHistory() {
    const container = $('#history-list');
    if (!container.length) return;
    syncHistoryTabsUi();
    renderHistorySummary();
    const list = activeHistoryList();
    const countEl = $('#history-count');
    if (!list.length) {
        container.html(`<div class="history-empty">${historyActiveTab === 'pgn'
            ? 'Encara no hi ha cap partida PGN. Prem «Importa PGN» per carregar-ne una (p. ex. de grans mestres) i podràs rejugar-la i analitzar-la aquí.'
            : 'Encara no hi ha partides guardades. Juga una partida i la revisió apareixerà aquí.'}</div>`);
        if (countEl.length) countEl.text('');
        syncHistoryGroupsToggle();
        // El detall només es buida si la partida oberta ja no existeix enlloc
        // (l'altra pestanya pot seguir tenint la seva selecció carregada).
        if (!historyReplay || !historyReplay.entry || !findHistoryEntryById(historyReplay.entry.id)) {
            historyReplay = null;
            updateHistoryDetails(null);
        }
        return;
    }
    const filtered = list.filter(historyEntryPasses);
    if (countEl.length) {
        countEl.text(filtered.length === list.length
            ? `${list.length} ${list.length === 1 ? 'partida' : 'partides'}`
            : `${filtered.length} de ${list.length}`);
    }
    if (!filtered.length) {
        container.html('<div class="history-empty">Cap partida coincideix amb els filtres.</div>');
        syncHistoryGroupsToggle();
        return;
    }
    const activeId = historyReplay && historyReplay.entry ? historyReplay.entry.id : null;
    // Seccions per antiguitat (Avui, Ahir, Fa 2 dies, Fa 1 setmana...), de la
    // més recent a la més antiga, amb les més noves ja desplegades.
    const groups = ElTaulerCore.groupHistoryEntriesByAge(filtered);
    const groupState = historyGroupStateForTab();
    const openFlags = ElTaulerCore.historyGroupsOpenState(groups, groupState);
    groups.forEach((group, i) => {
        // El grup de la partida que s'està veient al detall s'obre sol, tret que
        // l'usuari l'hagi plegat a mà: si no, la selecció quedaria amagada.
        if (!openFlags[i] && !Object.prototype.hasOwnProperty.call(groupState, group.key)
            && activeId && group.entries.some(entry => entry.id === activeId)) {
            openFlags[i] = true;
        }
    });
    container.html(groups.map((group, i) => historyGroupHtml(group, openFlags[i], activeId)).join(''));
    // Capçalera del grup: plega/desplega la seva llista de partides.
    container.find('.history-group-head').off('click').on('click', function() {
        const wrap = $(this).closest('.history-group');
        setHistoryGroupOpen(wrap, $(this).attr('aria-expanded') !== 'true');
        syncHistoryGroupsToggle();
    });
    syncHistoryGroupsToggle();
    // Tota la targeta obre el detall de la partida (a més del teclat, per accessibilitat).
    container.find('.history-item').off('click keydown').on('click keydown', function(event) {
        if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        const id = $(this).data('history-id');
        const entry = findHistoryEntryById(id);
        if (!entry) return;
        loadHistoryEntry(entry);
        syncHistoryListActive();
        // En mòbil, porta la vista al detall de la partida seleccionada.
        if (deviceType === 'mobile') {
            const detailEl = document.getElementById('history-detail');
            if (detailEl && detailEl.scrollIntoView) {
                setTimeout(() => detailEl.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
            }
        }
    });
        stopTvPlayback();
    // Esborrar una partida concreta de l'historial (amb confirmació). Actualitza el
    // desat (i la sincronització al núvol) i refresca la llista i el detall.
    $('.history-delete').off('click').on('click', function(e) {
        if (e && typeof e.stopPropagation === 'function') e.stopPropagation();
        const id = $(this).data('history-id');
        const entry = findHistoryEntryById(id);
        if (!entry) return;
        showAppConfirm(
            'Segur que vols esborrar aquesta partida de l\'historial? Aquesta acció no es pot desfer.',
            () => {
                // L'entrada pot ser d'una llista o de l'altra: esborra d'on sigui.
                const ownIdx = gameHistory.findIndex(item => item.id === id);
                if (ownIdx !== -1) gameHistory.splice(ownIdx, 1);
                else {
                    const impIdx = importedGameHistory.findIndex(item => item.id === id);
                    if (impIdx === -1) return;
                    importedGameHistory.splice(impIdx, 1);
                }
                // El cos pesat de la partida viu a IndexedDB: se n'ha d'anar amb ella.
                forgetHistoryEntryBody(id);
                try { saveStorage(); } catch (err) { console.warn('[Historial] esborrar', err); }
                // Si esborrem la partida que s'estava mostrant, buida el detall perquè
                // renderGameHistory en carregui una altra (o mostri l'estat buit).
                if (historyReplay && historyReplay.entry && historyReplay.entry.id === id) {
                    historyReplay = null;
                }
                renderGameHistory();
                showToast('Partida esborrada de l\'historial', 'success');
            },
            { title: 'Esborrar partida', confirmText: 'Esborra', cancelText: 'Cancel·la' }
        );
    });
    if (!historyReplay || !historyReplay.entry) {
        loadHistoryEntry(list[list.length - 1]);
    }
}

function recordGameHistory(resultLabel, finalPrecision, counts, options = {}) {
    if (blunderMode) return;
    const moves = game.history();
    const now = new Date();
    const entry = {
        id: `game_${now.getTime()}`,
        label: now.toLocaleDateString('ca-ES', { day: '2-digit', month: 'short' }) + ' ' + now.toLocaleTimeString('ca-ES', { hour: '2-digit', minute: '2-digit' }),
        date: now.toISOString(),
        mode: currentGameMode,
        result: resultLabel,
        precision: finalPrecision,
        counts: counts,
        moves: moves,
        errors: currentGameErrors.map(err => ({
            fen: err.fen,
            severity: err.severity,
            bestMove: err.bestMove || null,
            playerMove: err.playerMove || null,
            bestMovePv: err.bestMovePv || []
        })),
        moveReviews: currentReview.map(review => ({
            moveNumber: review.moveNumber,
            quality: review.quality,
            color: review.color,
            swing: review.swing || 0,
            fen: review.fen || null,
            bestMove: review.bestMove || null,
            bestMoveSan: review.bestMoveSan || null,
            playerMove: review.playerMove || null,
            playerMoveSan: review.playerMoveSan || null,
            bestMovePv: review.bestMovePv || [],
            alternatives: review.alternatives || [],
            // Les tres línies crues del motor: és el que fa possible el test de
            // Tres camins sobre partides velles. `alternatives` sol bastar per
            // reconstruir-les, però hi perd els mats (queden com a ±10000 cp).
            multipvBefore: review.multipvBefore || null,
            evalBefore: review.evalBefore ?? null,
            evalAfter: review.evalAfter ?? null,
            refutationPv: review.refutationPv || [],
            afterFen: review.afterFen || null
        })),
        review: [], // ← BUIDAT: ja no cal guardar review completa
        // Persistim les errades greus derivades de la revisió completa perquè
        // l'entrada sigui AUTOSUFICIENT per regenerar la ressenya més endavant
        // (encara que `review` es buidi i `currentReview` ja no existeixi).
        severeErrors: Array.isArray(options.severeErrors) && options.severeErrors.length
            ? options.severeErrors
            : getSevereErrors(currentReview),
        aiReview: options.aiReview || options.deepseekReview || options.geminiReview || null,
        playerColor: playerColor,
        // Ritme de rellotge amb què es va jugar ('none' si era sense rellotge):
        // la revisió l'ensenya com a tipus de partida i el repte «Rejugar +5%»
        // el fa servir per posar rellotge a la fase que es rejuga.
        timeControl: currentGameTimeControlId || 'none',
        opponent: currentOpponent || null,
        fen: game.fen(),
        pgn: game.pgn(),
        roc: currentElo,
        level: aiDifficulty,
        accuracy: finalPrecision,
        mistakes: counts?.mistake || 0,
        createdAt: now.toISOString(),
        updatedAt: now.toISOString()
    };
    // Moment clau de la partida (decisió més rellevant de l'usuari): es desa en
    // forma compacta si n'hi ha cap de prou important; si no, queda absent.
    try { entry.keyMoment = keyMomentToStored(computeKeyMoment(entry)); } catch (e) { entry.keyMoment = null; }
    // Resum per fases (sis números): va a l'ÍNDEX lleuger, de manera que el
    // perfil del bessó pugui mirar totes les partides guardades encara que les
    // seves revisions ja no siguin a la memòria.
    try { entry.phaseStats = ElTaulerCore.bessoPhaseStatsFromGame(entry); } catch (e) { entry.phaseStats = null; }
    // Resum de debilitats de la partida: mateix criteri (índex lleuger), perquè
    // el perfil del Rival Antídot es pugui recalcular sense carregar revisions.
    try { entry.antidoteStats = ElTaulerCore.antidoteWeaknessStatsFromGame(entry); } catch (e) { entry.antidoteStats = null; }
    // Proves del Rival Antídot: compactes (PV retallades) i a l'índex, de manera
    // que viatgen amb les còpies de seguretat i la sincronització del compte.
    if (currentGameMode === 'antidote') {
        const antidoteData = antidoteGameDataForHistory();
        if (antidoteData) entry.antidote = antidoteData;
    }
    gameHistory.push(entry);
    // La jornada de lliga que acabava de guardar el resultat ja pot apuntar a
    // la seva partida: així s'hi arriba des de la classificació.
    try { linkLeagueRoundToGame(entry); } catch (e) {}
    if (gameHistory.length > HISTORY_MAX) gameHistory = gameHistory.slice(-HISTORY_MAX);
    // El cos de les partides que han deixat de ser recents es descarrega de la
    // memòria (a IndexedDB hi segueix, i es torna a carregar en obrir-les).
    shedColdHistoryBodies();
    pruneHistoryBodies();
}

function isOpeningMoveCorrect(quality) {
    return quality === 'excel' || quality === 'good';
}

// Converteix qualitat a precisió aproximada (0-100)
function qualityToPrecision(quality, swing) {
    // Si tenim swing, calcular precisió basada en centipawns perduts
    // Swing 0 = 100%, Swing 100 = ~50%, Swing 200+ = ~0%
    if (typeof swing === 'number' && swing > 0) {
        return Math.max(0, Math.round(100 - (swing / 2)));
    }
    // Fallback basat en qualitat
    switch (quality) {
        case 'excel': return 100;
        case 'good': return 85;
        case 'inaccuracy': return 60;
        case 'mistake': return 35;
        case 'blunder': return 10;
        default: return 50;
    }
}

function buildOpeningMoveStats() {
    const recentEntries = gameHistory
        .slice(-10)
        .filter(entry => Array.isArray(entry.moveReviews) && entry.moveReviews.length);
    const stats = [];
    const colors = [
        { key: 'w', label: 'Blanques' },
        { key: 'b', label: 'Negres' }
    ];

    colors.forEach(color => {
        for (let moveNumber = 1; moveNumber <= 10; moveNumber++) {
            let total = 0;
            let totalPrecision = 0;
            let countBelow75 = 0;
            const errorPositions = []; // Guardar posicions amb error

            recentEntries.forEach(entry => {
                const match = entry.moveReviews.find(review => (
                    review.moveNumber === moveNumber && review.color === color.key
                ));
                if (!match) return;

                total += 1;
                const precision = qualityToPrecision(match.quality, match.swing);
                totalPrecision += precision;

                // Si la precisió és inferior al 75%, guardar l'error
                if (precision < 75) {
                    countBelow75 += 1;
                    // Primer intentar obtenir del moveReview
                    if (match.fen && match.bestMove) {
                        errorPositions.push({
                            fen: match.fen,
                            bestMove: match.bestMove,
                            quality: match.quality
                        });
                    } else if (Array.isArray(entry.errors)) {
                        // Fallback: buscar en entry.errors pel número de moviment
                        for (const err of entry.errors) {
                            if (!err.fen || !err.bestMove) continue;
                            // Extreure moveNum i color del FEN
                            const fenParts = err.fen.split(' ');
                            if (fenParts.length < 6) continue;
                            const fenColor = fenParts[1]; // 'w' o 'b'
                            const fenMoveNum = parseInt(fenParts[5], 10);
                            // El FEN mostra qui ha de moure, que és qui va fer l'error
                            if (fenColor === color.key && fenMoveNum === moveNumber) {
                                errorPositions.push({
                                    fen: err.fen,
                                    bestMove: err.bestMove,
                                    quality: match.quality
                                });
                                break; // Només un error per partida/moviment
                            }
                        }
                    }
                }
            });

            const avgPrecision = total > 0 ? Math.round(totalPrecision / total) : null;

            stats.push({
                moveNumber,
                color: color.label,
                colorKey: color.key,
                total,
                avgPrecision,
                countBelow75,
                errorPositions
            });
        }
    });

    return { stats, totalEntries: recentEntries.length };
}

function setOpeningScreenMode(mode = 'overview') {
    // Dos jeroglífics diferents comparteixen el tauler d'obertures: el personal
    // (tàctica de les teves partides) i el d'obertura (teoria del repertori
    // catalogat). Tots dos amaguen la resta de blocs; el text els distingeix.
    const isOpeningHiero = mode === 'hieroglyphic-opening';
    const isHieroglyphicMode = mode === 'hieroglyphic' || isOpeningHiero;
    document.body.classList.toggle('opening-mode-hieroglyphic', isHieroglyphicMode);
    const header = document.querySelector('#opening-screen .stats-header h1');
    const logo = document.querySelector('#opening-screen .stats-header .app-logo');
    if (header) header.textContent = isOpeningHiero ? 'Jeroglífic d’obertura' : (isHieroglyphicMode ? 'Jeroglífics' : 'Obertures');
    if (logo) logo.innerHTML = isHieroglyphicMode ? HG_ICON_SVG : '📖';
    // El nom del bloc viu en un span propi: el mode jeroglífic el reescriu sense
    // endur-se la icona ni el xip del número, que s'amaga perquè aquí no hi som
    // per fer el Bloc 2.
    $('#opening-practice-section .opening-section-title .obs-name').text(isOpeningHiero ? 'Jeroglífic d’obertura' : (isHieroglyphicMode ? 'Jeroglífic personal' : 'Pràctica de línia'));
    $('#opening-practice-section .opening-section-title .obs-num').toggle(!isHieroglyphicMode);
    const practiceDesc = isOpeningHiero
        ? 'Desxifra la pista i troba la jugada teòrica d’una obertura del repertori, a partir del tercer o quart moviment.'
        : (isHieroglyphicMode
            ? 'Desxifra una seqüència tàctica validada amb Stockfish a partir d’un moment clau de les teves partides.'
            : 'Practica obertures amb un màxim de 10 moviments per bàndol. La base teòrica detectada només identifica línies; el repertori recomanat és la guia pedagògica principal.');
    $('#opening-practice-section .opening-section-desc').text(practiceDesc);
    $('#opening-practice-section .opening-mode-row').toggle(!isHieroglyphicMode);
    $('#opening-precision-panel').toggle(!isHieroglyphicMode);
    // Al jeroglífic d'obertura hi havia dos botons de casa (el petit d'aquesta
    // fila i el gran del final de la secció): el petit passa a ser el botó de
    // fer-ne un altre, que és el que es vol allà.
    $('#btn-opening-hiero-next').toggle(isOpeningHiero);
    $('#btn-opening-bundle-menu').toggle(!isOpeningHiero);
    // …i, per deixar l'exercici sense marxar de la pantalla, la sortida cap a la
    // secció d'Obertures.
    $('#btn-opening-hiero-back').toggle(isOpeningHiero);
    // La pista només desapareix amb l'exercici resolt; qualsevol canvi de mode
    // la torna a deixar disponible.
    $('#btn-opening-bundle-hint').show();
    document.body.classList.remove('opening-hiero-solved');
    const sections = {
        // El bàner «La teva obertura» encapçala la pantalla: segueix els
        // mateixos blocs, i desapareix quan es resol un exercici concret.
        personal: $('#personal-opening-banner'),
        // …i, just a sota, el dels jeroglífics d'obertura: les dues portes
        // d'entrada destacades de la secció van sempre juntes.
        hieroBanner: $('#opening-hieroglyphic-banner'),
        lessons: $('#opening-lessons-section'),
        practice: $('#opening-practice-section'),
        stats: $('#opening-stats-section'),
        repertoire: $('#opening-repertoire-section'),
        hieroglyphic: $('#opening-hieroglyphic-section')
    };
    Object.values(sections).forEach($el => { if ($el && $el.length) $el.show(); });
    if (mode === 'lesson' || mode === 'practice') {
        sections.practice.show();
    } else if (mode === 'error-practice') {
        sections.personal.hide();
        sections.hieroBanner.hide();
        sections.lessons.hide();
        sections.stats.hide();
        sections.repertoire.hide();
        sections.hieroglyphic.hide();
        sections.practice.show();
    } else if (isHieroglyphicMode) {
        sections.personal.hide();
        sections.hieroBanner.hide();
        sections.lessons.hide();
        sections.stats.hide();
        sections.repertoire.hide();
        sections.practice.show();
        // No mostrem el bloc d'entrada "Jeroglífics d'obertura" sota el tauler:
        // el mode actual ja és el jeroglífic.
        sections.hieroglyphic.hide();
    }
    // L'opció de rendir-se NO ha d'aparèixer quan es resol un error o un jeroglífic
    // (només té sentit a les partides i a la pràctica d'obertures).
    const hideResign = (mode === 'error-practice' || isHieroglyphicMode);
    $('#btn-opening-bundle-resign').toggle(!hideResign);
    updateOpeningMaximButton();
    // Cada mode ensenya i amaga blocs diferents: el tauler es torna a mesurar
    // amb l'espai que li queda de debò.
    resizeOpeningBoardToViewport();
}

/* ===================== EL TEU REPERTORI =====================
   Primera meitat de l'«obertura personal»: en comptes de recomanar res, es
   llegeix l'historial i s'ensenya què jugues DE DEBÒ a l'obertura —amb quina
   freqüència hi arribes, què hi puntues i on deixes el llibre—, separat per
   blanques i negres. La lògica és pura i viu a core.js
   (createRepertoireHelpers); aquí només hi ha la lectura de l'estat i el pintat.
   No hi intervé el motor: totes les xifres surten de partides reals. */

let repertoireHelpers = null;
function getRepertoireHelpers() {
    if (!repertoireHelpers && typeof Chess !== 'undefined') {
        try { repertoireHelpers = ElTaulerCore.createRepertoireHelpers(Chess); } catch (e) { repertoireHelpers = null; }
    }
    return repertoireHelpers;
}

// Repertori a partir de l'historial propi. El graf de posicions és el que
// permet dir si una jugada és de llibre; si encara s'està construint, el
// repertori es calcula igualment i el llibre queda com a desconegut.
function buildPersonalRepertoireData() {
    const helpers = getRepertoireHelpers();
    if (!helpers) return null;
    const graph = getOpeningPositionGraph();
    try {
        return helpers.buildPersonalRepertoire(gameHistory, {
            theory: graph ? graph.theory : null,
            byPos: graph ? graph.byPos : null
        });
    } catch (e) {
        console.warn('[Repertori] no s\'ha pogut construir', e);
        return null;
    }
}

// Una línia es parteix en trossos «4.d3 Nf6» que no es trenquen mai per dins.
// Així la línia sencera pot passar de línia a la pantalla en comptes d'amagar
// les últimes jugades darrere d'un desplaçament lateral: una línia que no es
// veu fins al final no diu què jugar, que és per al que serveix.
function movePairsHtml(moves, moveHtml) {
    const groups = [];
    (moves || []).forEach(step => {
        const num = Math.floor(step.ply / 2);
        const last = groups.length ? groups[groups.length - 1] : null;
        let group = last && last.num === num ? last : null;
        if (!group) { group = { num: num, html: '' }; groups.push(group); }
        // El número va al davant del tros; si el tros comença amb les negres
        // (línia que arrenca a mitja jugada), es diu com toca: «4...Nf6».
        if (!group.html) group.html += `<span class="rep-num">${num + 1}.${step.ply % 2 === 0 ? '' : '..'}</span>`;
        group.html += moveHtml(step);
    });
    return groups.map(g => `<span class="rep-pair">${g.html}</span>`).join(' ');
}

// Línia en notació llegible («1.e4 e5 2.Nf3») amb la jugada que surt del
// llibre marcada. La SAN es mostra crua, com a la transcripció de l'historial.
function repertoireLineHtml(line, offBookPly) {
    return movePairsHtml(line, step => {
        const cls = ['rep-move'];
        if (step.mine) cls.push('rep-mine');
        if (offBookPly !== null && step.ply === offBookPly) cls.push('rep-offbook');
        return `<span class="${cls.join(' ')}">${escapeHtml(step.san)}</span>`;
    });
}

function repertoireScoreClass(score) {
    if (typeof score !== 'number') return '';
    if (score >= 60) return 'rep-score-good';
    if (score >= 45) return 'rep-score-mid';
    return 'rep-score-low';
}

function renderRepertoireColumn(rep, label, icon, side) {
    if (!rep) return '';
    const plural = n => n === 1 ? 'partida' : 'partides';
    // El bàndol es llegeix pel color, com al repertori recomanat del Bloc 1:
    // daurat el que jugues amb blanques, blau-pissarra el que jugues amb negres.
    let html = `<div class="rep-color-block rep-side-${side === 'black' ? 'black' : 'white'}">
        <div class="rep-color-title">${icon} ${label} <span class="rep-color-count">${rep.games} ${plural(rep.games)}</span></div>`;
    if (!rep.games) {
        html += `<div class="rep-empty">Encara no has jugat cap partida amb ${label.toLowerCase()}. Quan en juguis, aquí hi sortirà el teu repertori real.</div></div>`;
        return html;
    }
    if (!rep.enough) {
        const falten = rep.minColorGames - rep.games;
        html += `<div class="rep-warning">Mostra petita: amb ${rep.games} ${plural(rep.games)} les xifres encara ballen. Te'n ${falten === 1 ? 'falta' : 'falten'} ${falten} per tenir-les fiables.</div>`;
    }
    rep.branches.forEach(branch => {
        // Amb blanques la primera jugada és teva; amb negres és la del rival i
        // el repertori es llegeix «contra 1.e4, jugo…».
        const headline = rep.branchesAreMine
            ? `Jugo <strong>${escapeHtml(branch.san)}</strong>`
            : `Contra <strong>1.${escapeHtml(branch.san)}</strong>`;
        const nameLine = branch.name
            ? `<div class="rep-name">${escapeHtml(branch.name)}${branch.eco ? ` · ${escapeHtml(branch.eco)}` : ''}</div>`
            : '';
        let offBook = '';
        if (branch.offBookPly !== null) {
            const moveNumber = Math.floor(branch.offBookPly / 2) + 1;
            const who = branch.offBookBy === 'me' ? 'surts del llibre' : 'el rival surt del llibre';
            offBook = `<div class="rep-offbook-note">A la jugada ${moveNumber} ${who} amb ${escapeHtml(branch.offBookSan)}.</div>`;
        } else if (rep.theoryKnown && branch.line.length) {
            offBook = `<div class="rep-offbook-note rep-inbook">Tota la línia és al llibre.</div>`;
        }
        html += `
            <div class="rep-branch">
                <div class="rep-branch-head">
                    <div class="rep-branch-move">${headline}</div>
                    <div class="rep-branch-share">${branch.share}% · ${branch.games} ${plural(branch.games)}</div>
                </div>
                ${nameLine}
                <div class="rep-line">${repertoireLineHtml(branch.line, branch.offBookPly)}</div>
                <div class="rep-branch-stats">
                    <span class="rep-stat ${repertoireScoreClass(branch.score)}">${branch.score === null ? '—' : `${branch.score}%`} de puntuació</span>
                    <span class="rep-stat">${branch.wins}V · ${branch.draws}E · ${branch.losses}D</span>
                    <span class="rep-stat">${branch.precision === null ? '—' : `${branch.precision}%`} de precisió</span>
                </div>
                ${offBook}
            </div>`;
    });
    return html + '</div>';
}

function renderPersonalRepertoire() {
    const el = document.getElementById('repertoire-list');
    if (!el) return;
    const noteEl = document.getElementById('repertoire-note');
    const data = buildPersonalRepertoireData();
    if (!data) {
        el.innerHTML = '<div class="rep-empty">El repertori encara no es pot calcular.</div>';
        if (noteEl) noteEl.textContent = '—';
        return;
    }
    if (!data.white.games && !data.black.games) {
        el.innerHTML = '<div class="rep-empty">Encara no hi ha partides pròpies a l\'historial. Juga unes quantes partides i aquí hi trobaràs el teu repertori real: què jugues, amb quina freqüència, què hi puntues i on deixes el llibre.</div>';
        if (noteEl) noteEl.textContent = '—';
        return;
    }
    el.innerHTML =
        renderRepertoireColumn(data.white, 'Blanques', '♔', 'white') +
        renderRepertoireColumn(data.black, 'Negres', '♚', 'black');
    if (noteEl) {
        const total = data.white.games + data.black.games;
        noteEl.textContent = data.white.theoryKnown
            ? `Basat en les teves ${total} ${total === 1 ? 'partida' : 'partides'} de l'historial.`
            : `Basat en les teves ${total} ${total === 1 ? 'partida' : 'partides'}. El llibre d'obertures encara s'està carregant.`;
    }
}

/* ===================== L'OBERTURA PERSONAL =====================
   Segona meitat: del repertori real se'n deriva un de PROPOSAT. La cerca i les
   decisions són pures i viuen a core.js (createPersonalOpeningBuilder); aquí hi
   ha el que no pot ser pur: parlar amb Stockfish, ensenyar progrés, deixar
   cancel·lar i desar el resultat.

   El motor es demana posició a posició, per ordre de probabilitat d'arribar-hi,
   amb un pressupost tancat: així el temps es gasta a les línies que et trobaràs
   de debò i la construcció acaba sempre.

   Es construeix fins a les teves 5 primeres jugades (PERSONAL_OPENING_CONFIG.
   maxOwnMoves), que són les 10 o 11 primeres semijugades de la partida segons
   el color: amb negres el rival hi afegeix la que obre. */

const PERSONAL_OPENING_KEY = 'chess_personalOpening';
const PERSONAL_OPENING_DEPTH = 16;
const PERSONAL_OPENING_MULTIPV = 4;
const PERSONAL_OPENING_MOVETIME_MS = 1200;
const PERSONAL_OPENING_TIMEOUT_MS = 8000;

let personalOpenings = { w: null, b: null };
let personalOpeningBuild = null;   // { color, cancelled, done, total, note }
let personalOpeningsOutdated = false;   // n'hi havia de fetes amb regles velles

// Una obertura desada només val si l'ha feta el constructor d'ara: les d'abans
// es van fer amb una altra fondària i una altra forma d'arbre, i ensenyar-les
// seria prometre una cosa i donar-ne una altra.
function personalOpeningIsCurrent(opening) {
    return !!opening && opening.build === ElTaulerCore.PERSONAL_OPENING_BUILD;
}

function loadPersonalOpenings() {
    let parsed = null;
    try {
        const raw = localStorage.getItem(PERSONAL_OPENING_KEY);
        parsed = raw ? JSON.parse(raw) : null;
    } catch (e) { parsed = null; }
    const kept = { w: null, b: null };
    let outdated = false;
    ['w', 'b'].forEach(color => {
        const stored = parsed && parsed[color];
        if (!stored) return;
        if (personalOpeningIsCurrent(stored)) kept[color] = stored;
        else outdated = true;
    });
    personalOpenings = kept;
    personalOpeningsOutdated = outdated;
    // Les velles s'esborren del desat, no només de la memòria: si no, cada
    // arrencada tornaria a trobar-les i a dir el mateix.
    if (outdated) savePersonalOpenings();
    return personalOpenings;
}

function savePersonalOpenings() {
    try { localStorage.setItem(PERSONAL_OPENING_KEY, JSON.stringify(personalOpenings)); } catch (e) {}
}

let personalOpeningBuilder = null;
function getPersonalOpeningBuilder() {
    if (!personalOpeningBuilder && typeof Chess !== 'undefined') {
        try { personalOpeningBuilder = ElTaulerCore.createPersonalOpeningBuilder(Chess); } catch (e) { personalOpeningBuilder = null; }
    }
    return personalOpeningBuilder;
}

// Motor PROPI de la construcció. El worker compartit va ple d'estat del joc en
// viu (força limitada, MultiPV 1) i, sobretot, els missatges que encara fa una
// cerca arriben a l'oient de la següent: cada anàlisi es trobava responent amb
// les dades de l'anterior. Amb un worker a part la construcció no s'ha de
// barallar amb ningú, i es tanca en acabar.
let personalOpeningEngine = null;

function ensurePersonalOpeningEngine() {
    if (personalOpeningEngine) return personalOpeningEngine;
    const worker = createStockfishWorker();
    if (!worker) return null;
    personalOpeningEngine = worker;
    try {
        worker.postMessage('uci');
        worker.postMessage('setoption name UCI_LimitStrength value false');
        worker.postMessage('ucinewgame');
    } catch (e) {}
    return personalOpeningEngine;
}

function releasePersonalOpeningEngine() {
    if (!personalOpeningEngine) return;
    try { personalOpeningEngine.postMessage('stop'); } catch (e) {}
    try { personalOpeningEngine.terminate(); } catch (e) {}
    personalOpeningEngine = null;
}

// Avaluació d'una posició per al constructor: MultiPV normalitzat a
// {san, cp} des del punt de vista de qui mou (el conveni que espera el nucli).
// Retorna null si el motor no ha pogut dir res: el nucli ho tracta com a
// "aquesta branca s'atura", mai com a permís per endevinar.
async function evaluateOpeningPosition(fen) {
    const engine = ensurePersonalOpeningEngine();
    if (!engine) return null;
    let res = null;
    try {
        res = await analyzePositionEnrichedTimed(
            engine, fen, PERSONAL_OPENING_DEPTH, PERSONAL_OPENING_MULTIPV,
            PERSONAL_OPENING_MOVETIME_MS, PERSONAL_OPENING_TIMEOUT_MS);
    } catch (e) { return null; }
    const cpOf = a => (a.evalType === 'mate' ? (a.eval > 0 ? 10000 : -10000) : a.eval);
    const moves = ((res && res.alternatives) || [])
        .filter(a => a && a.move && typeof a.eval === 'number')
        .map(a => {
            let san = null;
            try { san = uciToSan(fen, a.move); } catch (e) { san = null; }
            return san ? { san: san, cp: cpOf(a) } : null;
        })
        .filter(Boolean)
        .sort((a, b) => b.cp - a.cp);
    return moves.length ? { moves: moves } : null;
}

// Valor d'UNA jugada concreta a la MATEIXA posició i amb la mateixa cerca que
// la resta (`searchmoves`): així la pèrdua es mesura dins d'una sola escala.
// Analitzar la posició de després i canviar-li el signe seria comparar dues
// cerques diferents, i a poca profunditat això inventa pèrdues de desenes de
// centpeons a jugades perfectament normals.
function evaluateOpeningCandidate(fen, san) {
    const engine = ensurePersonalOpeningEngine();
    if (!engine) return Promise.resolve(null);
    let uci = null;
    try {
        const chess = new Chess(fen);
        const move = chess.move(san, { sloppy: true });
        if (move) uci = move.from + move.to + (move.promotion || '');
    } catch (e) { uci = null; }
    if (!uci) return Promise.resolve(null);
    return new Promise(resolve => {
        let best = null;
        let done = false;
        let timeoutId = null;
        const finish = () => {
            if (done) return;
            done = true;
            try { engine.removeEventListener('message', onMessage); } catch (e) {}
            if (timeoutId) clearTimeout(timeoutId);
            resolve(best === null ? null : { moves: [{ san: san, cp: best }] });
        };
        const onMessage = event => {
            const line = event.data;
            if (typeof line !== 'string') return;
            if (line.startsWith('info') && line.includes(' pv ')) {
                const info = parseUciInfo(line);
                if (info && typeof info.score === 'number') {
                    best = info.scoreType === 'mate'
                        ? (info.score > 0 ? 10000 : -10000)
                        : info.score;
                }
            } else if (line.startsWith('bestmove')) finish();
        };
        timeoutId = setTimeout(() => { try { engine.postMessage('stop'); } catch (e) {} finish(); }, PERSONAL_OPENING_TIMEOUT_MS);
        try {
            engine.addEventListener('message', onMessage);
            engine.postMessage('setoption name MultiPV value 1');
            engine.postMessage(`position fen ${fen}`);
            engine.postMessage(`go depth ${PERSONAL_OPENING_DEPTH} movetime ${PERSONAL_OPENING_MOVETIME_MS} searchmoves ${uci}`);
        } catch (e) { finish(); }
    });
}

function personalOpeningBuildInProgress() {
    return !!(personalOpeningBuild && !personalOpeningBuild.done);
}

function cancelPersonalOpeningBuild() {
    if (personalOpeningBuild) personalOpeningBuild.cancelled = true;
}

// Construeix l'obertura personal d'un color. Reclama el motor mentre dura
// (dues anàlisis alhora sobre el mateix worker es roben les respostes) i el
// deixa com l'ha trobat en acabar.
async function buildPersonalOpening(color, options = {}) {
    const builder = getPersonalOpeningBuilder();
    if (!builder) return null;
    if (personalOpeningBuildInProgress()) return null;
    if (deepReviewInProgress || waitingForBlunderAnalysis) {
        showToast('Hi ha una anàlisi en curs; torna-ho a provar d\'aquí a un moment.', 'info');
        return null;
    }
    const graph = getOpeningPositionGraph();
    const state = builder.start(gameHistory, color, Object.assign({ graph: graph }, options.config || {}));
    const build = { color: color, cancelled: false, done: false, evaluated: 0, note: '' };
    personalOpeningBuild = build;
    const onProgress = typeof options.onProgress === 'function' ? options.onProgress : () => {};

    try {
        // La construcció fa servir un motor propi (ensurePersonalOpeningEngine),
        // però la generació en segon pla competeix per la CPU: se li demana que
        // pari mentre dura.
        try { requestBackgroundPrepAbort(); } catch (e) {}
        ensurePersonalOpeningEngine();

        let job;
        while ((job = builder.nextPosition(state))) {
            if (build.cancelled) break;
            let evaluation = null;
            if (job.fen) {
                evaluation = job.kind === 'candidate'
                    ? await evaluateOpeningCandidate(job.fen, job.san)
                    : await evaluateOpeningPosition(job.fen);
            }
            builder.feed(state, evaluation);
            build.evaluated = state.evaluated;
            onProgress(state.evaluated, state.evaluated + builder.remaining(state), job);
        }
    } catch (e) {
        console.warn('[Obertura personal] error construint', e);
    } finally {
        build.done = true;
        // El motor de la construcció no ha de sobreviure-la: el compartit no
        // s'ha tocat i aquest ja no fa falta.
        releasePersonalOpeningEngine();
    }

    const result = builder.result(state);
    result.builtAt = new Date().toISOString();
    result.cancelled = build.cancelled;
    result.historyGames = gameHistory.length;
    if (!build.cancelled) {
        personalOpenings[color] = result;
        personalOpeningsOutdated = false;
        savePersonalOpenings();
    }
    personalOpeningBuild = null;
    return result;
}

// ── Pintat de l'obertura personal ───────────────────────────────────────────

const PERSONAL_OPENING_REASONS = {
    'own-best': 'la teva, i també la millor del motor',
    'own-sound': 'la teva, validada pel motor',
    'own-playable': 'la teva; el motor en prefereix una altra, però aguanta',
    'replaces-unsound': 'canvia la que jugues',
    'replaces-unknown': 'el motor no ha pogut mesurar la teva',
    'new': 'nova: aquí encara no hi tens partides'
};

function personalOpeningColorLabel(color) {
    return color === 'b' ? 'negres' : 'blanques';
}

// Probabilitat d'arribar al final d'una línia. Ara que les línies arriben fins
// a la teva 5a jugada, aquest número és petit de debò: la partida ha de repetir
// deu semijugades seguides. Arrodonir-lo a «0%» faria semblar que la línia no
// serveix de res, quan el que diu és que el rival hi té moltes tries.
function personalOpeningProbBadge(prob) {
    const pct = (typeof prob === 'number' ? prob : 0) * 100;
    return pct > 0 && pct < 1 ? '&lt;1%' : `${Math.round(pct)}%`;
}

function personalOpeningProbPhrase(prob) {
    const pct = (typeof prob === 'number' ? prob : 0) * 100;
    return pct > 0 && pct < 1 ? 'menys de l\'1%' : `un ${Math.round(pct)}%`;
}

// Línia en notació llegible, amb les jugades pròpies en negreta i marca a les
// que canvien respecte del que jugues.
function personalOpeningLineHtml(moves) {
    return movePairsHtml(moves, step => {
        const cls = ['rep-move'];
        if (step.mine) cls.push('rep-mine');
        if (step.mine && step.source === 'engine') cls.push('rep-changed');
        const title = step.mine
            ? `${PERSONAL_OPENING_REASONS[step.reason] || ''}${typeof step.cpLoss === 'number' ? ` · ${step.cpLoss} cp` : ''}`
            : (step.source === 'engine' ? 'rèplica del motor (aquí no hi tens partides)' : `te l'han jugat ${step.games} ${step.games === 1 ? 'vegada' : 'vegades'}`);
        return `<span class="${cls.join(' ')}" title="${escapeHtml(title)}">${escapeHtml(step.san)}</span>`;
    });
}

// Decisions on l'obertura proposada s'aparta del que jugues: és el que
// realment cal mirar-se.
function personalOpeningChanges(root) {
    const changes = [];
    (function walk(node, path) {
        (node.children || []).forEach(child => {
            const next = path.concat([child]);
            if (child.mine && child.source === 'engine' && child.replaces) {
                changes.push({ node: child, path: next });
            }
            walk(child, next);
        });
    })(root, []);
    changes.sort((a, b) => b.node.reachProb - a.node.reachProb);
    return changes;
}

function renderPersonalOpeningResult(color) {
    const opening = personalOpenings[color];
    if (!opening) return '';
    const s = opening.summary;
    const label = personalOpeningColorLabel(color);
    const tile = (value, caption) => `<div class="rep-tile"><div class="rep-tile-value">${value}</div><div class="rep-tile-caption">${caption}</div></div>`;
    let html = `<div class="rep-built" data-color="${color}">
        <div class="rep-built-head">
            <div class="rep-built-title">Amb ${label}</div>
            <div class="rep-built-meta">${opening.evaluated} posicions analitzades · ${opening.historyGames} partides a l'historial</div>
        </div>
        <div class="rep-tiles">
            ${tile(s.ownMoves, 'jugades teves')}
            ${tile(`${s.fromOwnGames}/${s.ownMoves}`, 'de les teves partides')}
            ${tile(`${s.coverage}%`, 'del que et trobaràs')}
            ${tile(s.avgCpLoss === null ? '—' : `${s.avgCpLoss} cp`, 'pèrdua mitjana')}
        </div>`;

    const lines = ElTaulerCore.personalOpeningLines(opening.root).slice(0, 6);
    if (lines.length) {
        html += '<div class="rep-subtitle">Les teves línies</div>';
        lines.forEach((line, idx) => {
            html += `<div class="rep-built-line">
                <div class="rep-built-line-head">
                    <span class="rep-built-prob">${personalOpeningProbBadge(line.prob)}</span>
                    <button class="btn btn-secondary rep-train-btn" data-color="${color}" data-line="${idx}">Entrena-la</button>
                </div>
                <div class="rep-line">${personalOpeningLineHtml(line.moves)}</div>
            </div>`;
        });
    }

    const changes = personalOpeningChanges(opening.root);
    if (changes.length) {
        html += '<div class="rep-subtitle">Què et proposa canviar</div>';
        changes.slice(0, 5).forEach(change => {
            const node = change.node;
            const before = change.path.slice(0, -1).map(step =>
                (step.ply % 2 === 0 ? `${Math.floor(step.ply / 2) + 1}.` : '') + step.san).join(' ');
            const moveNumber = Math.floor(node.ply / 2) + 1;
            html += `<div class="rep-change">
                <div class="rep-change-line">${before ? escapeHtml(before) : 'Des de l\'inici'}</div>
                <div class="rep-change-body">A la jugada ${moveNumber} jugues <strong>${escapeHtml(node.replaces.san)}</strong>${
                    typeof node.replaces.cpLoss === 'number' ? ` (perd ${node.replaces.cpLoss} cp)` : ''
                } ${node.replaces.games ? `en ${node.replaces.games} ${node.replaces.games === 1 ? 'partida' : 'partides'}` : ''} → et proposa <strong>${escapeHtml(node.san)}</strong>.</div>
            </div>`;
        });
    }

    if (!s.ownMoves) {
        html += '<div class="rep-empty">El motor no ha pogut validar cap jugada. Torna-ho a provar amb el tauler tancat.</div>';
    }
    return html + '</div>';
}

function renderPersonalOpeningSection() {
    const el = document.getElementById('personal-opening-result');
    if (!el) return;
    const data = buildPersonalRepertoireData();
    ['w', 'b'].forEach(color => {
        const btn = document.getElementById(`btn-build-opening-${color}`);
        if (!btn) return;
        const games = data ? (color === 'w' ? data.white.games : data.black.games) : 0;
        const min = ElTaulerCore.PERSONAL_OPENING_CONFIG.minColorGames;
        const built = !!personalOpenings[color];
        const busy = personalOpeningBuildInProgress();
        btn.textContent = built
            ? `Refés-la amb ${personalOpeningColorLabel(color)}`
            : `Construeix-la amb ${personalOpeningColorLabel(color)}`;
        btn.disabled = busy || games < min;
        const short = min - games;
        btn.title = games < min
            ? `${short === 1 ? 'Et falta 1 partida' : `Et falten ${short} partides`} amb ${personalOpeningColorLabel(color)}.`
            : '';
    });
    el.innerHTML = ['w', 'b'].map(renderPersonalOpeningResult).join('');
    const min = ElTaulerCore.PERSONAL_OPENING_CONFIG.minColorGames;
    const white = data ? data.white.games : 0;
    const black = data ? data.black.games : 0;
    const missing = [];
    if (white < min) missing.push({ n: min - white, label: 'blanques' });
    if (black < min) missing.push({ n: min - black, label: 'negres' });
    // «partides» va només al primer tros: «3 partides amb blanques i 1 amb
    // negres». Amb un sol color i una sola partida, tot va en singular.
    const total = missing.reduce((sum, m) => sum + m.n, 0);
    const parts = missing.map((m, idx) => idx === 0
        ? `${m.n} ${m.n === 1 ? 'partida' : 'partides'} amb ${m.label}`
        : `${m.n} amb ${m.label}`);
    const hintEl = document.getElementById('personal-opening-hint');
    if (hintEl) {
        // La fondària es diu en jugades TEVES (és el que has de memoritzar) i
        // surt de la configuració, no d'un número escrit aquí: si algun dia
        // canvia, la frase canvia sola.
        const own = ElTaulerCore.PERSONAL_OPENING_CONFIG.maxOwnMoves;
        hintEl.textContent = missing.length
            ? `${total === 1 ? 'Et falta' : 'Et falten'} ${parts.join(' i ')} perquè les teves dades diguin prou.`
            : `Analitza amb Stockfish les teves ${own} primeres jugades. Triga una estona i pots aturar-ho quan vulguis.`;
    }
    updatePersonalOpeningBannerStatus(missing, parts, total);
}

// Estat resumit del bàner plegat: amb el panell tancat, aquesta línia és tot el
// que se'n veu, i ha de dir si la tens construïda, per quin bàndol i quant en
// surt. Rep la mateixa feina de comptar partides que ja fa la frase de dins.
function updatePersonalOpeningBannerStatus(missing, parts, totalMissing) {
    const el = document.getElementById('personal-opening-status');
    if (!el) return;
    const build = personalOpeningBuildInProgress() ? personalOpeningBuild : null;
    if (build) {
        el.textContent = `Construint-la amb ${personalOpeningColorLabel(build.color)}…`;
        return;
    }
    const countLines = color => {
        const opening = personalOpenings[color];
        if (!opening || !opening.root) return 0;
        try { return ElTaulerCore.personalOpeningLines(opening.root).length; } catch (e) { return 0; }
    };
    const built = ['w', 'b'].filter(color => !!personalOpenings[color]);
    if (built.length) {
        const lines = built.reduce((sum, color) => sum + countLines(color), 0);
        const labels = built.map(personalOpeningColorLabel).join(' i ');
        const missingSide = built.length === 1 ? `, encara no amb ${personalOpeningColorLabel(built[0] === 'w' ? 'b' : 'w')}` : '';
        el.textContent = `Construïda amb ${labels}${missingSide} · ${lines} ${lines === 1 ? 'línia' : 'línies'}.`;
        return;
    }
    if (missing.length) {
        el.textContent = `${totalMissing === 1 ? 'Et falta' : 'Et falten'} ${parts.join(' i ')}.`;
        return;
    }
    // Si se n'ha llençat una de vella, es diu: fer desaparèixer el que algú
    // tenia construït sense explicar-ho seria un error, no una millora.
    el.textContent = personalOpeningsOutdated
        ? 'La que tenies es va fer amb regles antigues i s\'ha esborrat: refés-la.'
        : 'Encara no la tens construïda.';
}

// El bàner és clickable: la funció viu dins del panell que obre.
function setPersonalOpeningPanelOpen(open) {
    const btn = document.getElementById('btn-personal-opening-toggle');
    const panel = document.getElementById('personal-opening-panel');
    if (!btn || !panel) return;
    panel.hidden = !open;
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
}

function personalOpeningPanelIsOpen() {
    const panel = document.getElementById('personal-opening-panel');
    return !!panel && !panel.hidden;
}

function updatePersonalOpeningProgress(done, total, job) {
    const box = document.getElementById('personal-opening-progress');
    const bar = document.getElementById('personal-opening-progress-bar');
    const text = document.getElementById('personal-opening-progress-text');
    if (!box) return;
    box.hidden = false;
    const pct = total ? Math.min(100, Math.round((done / total) * 100)) : 0;
    if (bar) bar.style.width = `${pct}%`;
    if (text) {
        const what = job && job.kind === 'candidate'
            ? `comprovant la teva ${job.san}`
            : (job && job.mine ? 'triant la teva jugada' : 'mirant què et responen');
        text.textContent = `${done} de ~${total} posicions · ${what}`;
    }
}

// Entrena una línia de l'obertura personal al tauler de pràctica. La línia es
// converteix en una «lliçó» amb el mateix format que el repertori curat, amb
// una frase per jugada que explica d'on surt cadascuna.
function trainPersonalOpeningLine(color, lineIndex) {
    const opening = personalOpenings[color];
    if (!opening) return;
    const lines = ElTaulerCore.personalOpeningLines(opening.root);
    const line = lines[lineIndex];
    if (!line || !line.moves.length) { showToast('Aquesta línia ja no hi és; refés l\'obertura.', 'warn'); return; }
    const named = line.moves.filter(step => step.name).pop();
    const lesson = {
        eco: named ? named.eco : '—',
        name: named ? `La teva obertura · ${named.name}` : 'La teva obertura',
        userColor: color,
        cat: color === 'w' ? 'white' : 'black',
        idea: `Línia del teu repertori: hi arribes en ${personalOpeningProbPhrase(line.prob)} de les partides amb ${personalOpeningColorLabel(color)}.`,
        moves: line.moves.map(step => step.san),
        movePhrases: line.moves.map(step => {
            if (!step.mine) {
                return step.source === 'engine'
                    ? `${step.san}: rèplica que el motor considera de les millors (aquí encara no hi tens partides).`
                    : `${step.san}: te l'han jugat ${step.games} ${step.games === 1 ? 'vegada' : 'vegades'}.`;
            }
            const why = PERSONAL_OPENING_REASONS[step.reason] || '';
            const cp = typeof step.cpLoss === 'number' && step.cpLoss > 0 ? ` (${step.cpLoss} cp per sota de la millor)` : '';
            return `${step.san}: ${why}${cp}.`;
        })
    };
    startOpeningLessonWith(lesson, color, null);
}

async function startPersonalOpeningBuild(color) {
    if (personalOpeningBuildInProgress()) return;
    const cancelBtn = document.getElementById('btn-cancel-build-opening');
    if (cancelBtn) cancelBtn.hidden = false;
    // El progrés, el botó d'aturar i el resultat viuen dins del panell: mentre
    // es construeix ha d'estar obert, i s'hi queda per veure com ha quedat.
    setPersonalOpeningPanelOpen(true);
    renderPersonalOpeningSection();
    updatePersonalOpeningProgress(0, 1, null);
    const result = await buildPersonalOpening(color, { onProgress: updatePersonalOpeningProgress });
    const box = document.getElementById('personal-opening-progress');
    if (box) box.hidden = true;
    if (cancelBtn) cancelBtn.hidden = true;
    renderPersonalOpeningSection();
    if (!result) return;
    if (result.cancelled) showToast('Construcció aturada', 'info');
    else showToast(`Obertura amb ${personalOpeningColorLabel(color)} llesta ♟`, 'success');
}

// Variable global per guardar estadístiques d'obertura
let openingStatsData = [];

function collectAllOpeningErrorPositions() {
    const positions = [];
    openingStatsData.forEach(stat => {
        if (!Array.isArray(stat.errorPositions)) return;
        stat.errorPositions.forEach(position => {
            positions.push({
                ...position,
                colorKey: stat.colorKey,
                moveNumber: stat.moveNumber
            });
        });
    });
    return positions;
}

function renderOpeningStatsScreen(useExistingData = false) {
    const listEl = $('#opening-stats-list');
    const noteEl = $('#opening-stats-note');
    if (!listEl.length) return;

    let stats, totalEntries;
    if (useExistingData && openingStatsData && openingStatsData.length > 0) {
        // Usar dades existents (actualitzades després de pràctica)
        stats = openingStatsData;
        totalEntries = stats.reduce((max, s) => Math.max(max, s.total), 0);
    } else {
        // Reconstruir des de gameHistory
        const result = buildOpeningMoveStats();
        stats = result.stats;
        totalEntries = result.totalEntries;
        openingStatsData = stats;
    }

    // Separar per color
    const whiteStats = stats.filter(s => s.colorKey === 'w');
    const blackStats = stats.filter(s => s.colorKey === 'b');

    let html = `
        <div class="opening-stats-header" style="font-weight:600; margin-bottom:8px;">
            <span>Mov.</span>
            <span>Precisió</span>
            <span>Errors</span>
        </div>
        <div style="font-weight:600; color:var(--text-secondary); margin:10px 0 5px; font-size:0.85em;">♔ Blanques</div>
    `;

    whiteStats.forEach((item, idx) => {
        const precisionClass = item.avgPrecision !== null && item.avgPrecision < 75 ? 'color:var(--severity-med)' : '';
        const hasErrors = item.countBelow75 > 0;
        const errorDisplay = hasErrors
            ? `<span class="move-link" data-color="w" data-move="${item.moveNumber}">${item.countBelow75}</span>`
            : item.total > 0 ? '<span class="move-link-disabled">0</span>' : '—';
        html += `
            <div class="opening-stats-row">
                <div class="move-cell">${item.moveNumber}</div>
                <div style="${precisionClass}">${item.avgPrecision === null ? '—' : `${item.avgPrecision}%`}</div>
                <div>${errorDisplay}</div>
            </div>
        `;
    });

    html += `<div style="font-weight:600; color:var(--text-secondary); margin:15px 0 5px; font-size:0.85em;">♚ Negres</div>`;

    blackStats.forEach((item, idx) => {
        const precisionClass = item.avgPrecision !== null && item.avgPrecision < 75 ? 'color:var(--severity-med)' : '';
        const hasErrors = item.countBelow75 > 0;
        const errorDisplay = hasErrors
            ? `<span class="move-link" data-color="b" data-move="${item.moveNumber}">${item.countBelow75}</span>`
            : item.total > 0 ? '<span class="move-link-disabled">0</span>' : '—';
        html += `
            <div class="opening-stats-row">
                <div class="move-cell">${item.moveNumber}</div>
                <div style="${precisionClass}">${item.avgPrecision === null ? '—' : `${item.avgPrecision}%`}</div>
                <div>${errorDisplay}</div>
            </div>
        `;
    });

    listEl.html(html);

    // Afegir handlers de clic amb event delegation
    listEl.off('click', '.move-link').on('click', '.move-link', function(e) {
        e.preventDefault();
        e.stopPropagation();
        const color = $(this).attr('data-color');
        const moveNum = parseInt($(this).attr('data-move'), 10);
        startOpeningErrorPractice(color, moveNum);
    });

    if (noteEl.length) {
        noteEl.text(totalEntries > 0 ? `Basat en les últimes ${totalEntries} partides.` : '—');
    }
}

// Inicia la pràctica d'un error d'obertura
function startOpeningErrorPractice(color, moveNum) {
    hideOpeningRestartOverlay();
    // Buscar les posicions d'error per aquest color i moviment
    const stat = openingStatsData.find(s => s.colorKey === color && s.moveNumber === moveNum);

    if (!stat || !stat.errorPositions || stat.errorPositions.length === 0) {
        showToast('No hi ha posicions disponibles. Juga noves partides per practicar errors.', 'warn');
        return;
    }

    openingErrorPracticeActive = true;
    openingErrorCurrentPositions = stat.errorPositions.map(position => ({
        ...position,
        colorKey: stat.colorKey,
        moveNumber: stat.moveNumber
    }));
    console.log('[StartPractice] Posicions inicials:', openingErrorCurrentPositions.length);
    openingErrorColorFilter = color;
    openingErrorMoveFilter = moveNum;
    openingErrorMovesRemaining = 2; // Dues jugades per resoldre

    // Seleccionar un error aleatori
    loadRandomOpeningError();
}

function loadRandomOpeningError() {
    if (openingErrorCurrentPositions.length === 0) {
        showOpeningErrorSuccessOverlay(true); // No en queden
        return;
    }

    // Seleccionar aleatori
    const idx = Math.floor(Math.random() * openingErrorCurrentPositions.length);
    const error = openingErrorCurrentPositions[idx];

    openingErrorCurrentIndex = idx; // Guardar índex per eliminar després
    openingErrorCurrentFen = error.fen;
    openingErrorBestMove = error.bestMove;
    openingPracticeBestMove = error.bestMove; // Per a la pista
    if (error.colorKey) {
        openingErrorColorFilter = error.colorKey;
    }
    if (error.moveNumber) {
        openingErrorMoveFilter = error.moveNumber;
    }
    openingErrorMovesRemaining = 2; // Reset a 2 jugades

    // Inicialitzar el tauler d'obertures amb la posició
    if (!openingBundleBoard) {
        initOpeningBundleBoard();
    }

    openingPracticeGame = new Chess(error.fen);
    openingPracticeMoveCount = 0;
    openingPracticeEngineThinking = false;
    openingPracticeGoodMoves = 0;
    openingPracticeTotalMoves = 0;

    // Determinar orientació segons el torn
    const turn = openingPracticeGame.turn();
    openingBundleBoard.orientation(turn === 'w' ? 'white' : 'black');
    openingBundleBoard.position(error.fen);

    setOpeningScreenMode('error-practice');

    // Forçar redimensionament del tauler per assegurar visualització
    setTimeout(() => resizeOpeningBoardToViewport(), 100);

    // Scroll al tauler
    const boardEl = document.getElementById('opening-board');
    if (boardEl) {
        boardEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }

    // Actualitzar nota
    const noteEl = document.getElementById('opening-practice-note');
    if (noteEl) {
        noteEl.innerHTML = `<div style="padding:8px; background:rgba(201,162,39,0.15); border-radius:8px;">Practica l'errada de la jugada ${openingErrorMoveFilter} (${openingErrorColorFilter === 'w' ? 'blanques' : 'negres'}) - 2 jugades</div>`;
    }

    updateOpeningPrecisionDisplay();
    clearOpeningMoveVisualFeedback();
}

function handleOpeningErrorSuccess() {
    openingErrorMovesRemaining -= 1;

    // Si queden jugades, fer que l'oponent respongui
    if (openingErrorMovesRemaining > 0) {
        // Demanar moviment de Stockfish per l'oponent
        requestOpeningErrorOpponentMove();
        return;
    }

    // Treure la posició resolta de la llista per índex
    console.log('[ErrorSuccess] Abans splice:', openingErrorCurrentPositions.length, 'index:', openingErrorCurrentIndex);
    if (openingErrorCurrentIndex >= 0 && openingErrorCurrentIndex < openingErrorCurrentPositions.length) {
        openingErrorCurrentPositions.splice(openingErrorCurrentIndex, 1);
    }
    console.log('[ErrorSuccess] Després splice:', openingErrorCurrentPositions.length);

    // Actualitzar també openingStatsData per reflectir l'error resolt
    if (openingErrorColorFilter && openingErrorMoveFilter) {
        const stat = openingStatsData.find(s =>
            s.colorKey === openingErrorColorFilter && s.moveNumber === openingErrorMoveFilter
        );
        if (stat && stat.errorPositions && stat.errorPositions.length > 0) {
            // Eliminar la posició resolta dels stats
            if (openingErrorCurrentFen) {
                stat.errorPositions = stat.errorPositions.filter(p => p.fen !== openingErrorCurrentFen);
            } else if (stat.errorPositions.length > 0) {
                stat.errorPositions.shift(); // Eliminar el primer si no tenim FEN
            }
            stat.countBelow75 = stat.errorPositions.length;
        }
    }

    openingErrorCurrentFen = null;
    openingErrorBestMove = null;
    openingErrorCurrentIndex = -1;

    showOpeningErrorSuccessOverlay(false);
}

// Recull tots els errors d'obertura disponibles de tots els moviments/colors
function getAllOpeningErrors() {
    const allErrors = [];
    if (!openingStatsData) return allErrors;

    for (const stat of openingStatsData) {
        if (stat.errorPositions && stat.errorPositions.length > 0) {
            for (const pos of stat.errorPositions) {
                allErrors.push({
                    ...pos,
                    colorKey: stat.colorKey,
                    moveNumber: stat.moveNumber
                });
            }
        }
    }
    return allErrors;
}

function requestOpeningErrorOpponentMove() {
    if (!openingPracticeGame || openingPracticeGame.game_over()) {
        // Si la partida ha acabat, completar
        openingErrorMovesRemaining = 0;
        handleOpeningErrorSuccess();
        return;
    }

    // Utilitzar Stockfish per obtenir el millor moviment de l'oponent
    if (!stockfish && !ensureStockfish()) {
        // Si no hi ha Stockfish, fer moviment aleatori
        const moves = openingPracticeGame.moves();
        if (moves.length > 0) {
            const randomMove = moves[Math.floor(Math.random() * moves.length)];
            openingPracticeGame.move(randomMove);
            openingBundleBoard.position(openingPracticeGame.fen());
            // Obtenir el nou millor moviment per l'usuari
            requestOpeningErrorBestMoveForUser();
        }
        return;
    }

    openingPracticeEngineThinking = true;
    stockfishRequestor = 'opening-error-opponent';
    try {
        stockfish.postMessage('stop');
        stockfish.postMessage('ucinewgame');
        stockfish.postMessage('position fen ' + openingPracticeGame.fen());
        stockfish.postMessage('go depth 10');
    } catch (e) {
        openingPracticeEngineThinking = false;
    }
}

function requestOpeningErrorBestMoveForUser() {
    if (!stockfish && !ensureStockfish()) {
        openingErrorBestMove = null;
        openingPracticeBestMove = null;
        return;
    }

    stockfishRequestor = 'opening-error-bestmove';
    try {
        stockfish.postMessage('stop');
        stockfish.postMessage('position fen ' + openingPracticeGame.fen());
        stockfish.postMessage('go depth 12');
    } catch (e) {}
}


function canContinueOpeningErrorFenGame() {
    return !!(openingPracticeGame && !openingPracticeGame.game_over());
}

function continueOpeningErrorFenGame() {
    if (!openingPracticeGame || openingPracticeGame.game_over()) return false;
    const fen = openingPracticeGame.fen();
    const orientation = openingBundleBoard && typeof openingBundleBoard.orientation === 'function'
        ? openingBundleBoard.orientation()
        : (openingPracticeGame.turn() === 'w' ? 'white' : 'black');
    exitOpeningErrorPractice();
    $('#opening-error-success-overlay').hide();
    $('#start-screen, #opening-screen').hide();
    $('#game-screen').addClass('active').show();
    navPush('game-screen');
    game = new Chess(fen);
    playerColor = openingPracticeUserColor === 'b' ? 'b' : 'w';
    blunderMode = false;
    currentGameMode = 'fen_max';
    currentOpponent = { id: 'fen-max', name: 'ELO màxim', elo: ELO_MAX };
    currentGameActiveStrengthElo = ELO_MAX;
    currentGameEngineDepth = eloToSearchDepth(ELO_MAX);
    isEngineThinking = false;
    engineMoveApplyPending = false;
    pendingMoveEvaluation = false;
    totalPlayerMoves = 0;
    totalEngineMoves = 0;
    goodMoves = 0;
    goodEngineMoves = 0;
    if (board) board.destroy();
    board = Chessboard('myBoard', {
        orientation: orientation === 'black' ? 'black' : 'white',
        draggable: (controlMode === 'drag'),
        position: game.fen(),
        onDragStart: onDragStart,
        onDrop: onDrop,
        onSnapEnd: onSnapEnd,
        pieceTheme: 'https://chessboardjs.com/img/chesspieces/wikipedia/{piece}.png'
    });
    if (controlMode === 'tap') { detachDragGuards(); disableTapToMove(); enableTapToMove(); }
    else { disableTapToMove(); attachDragGuards(); clearTapSelection(); }
    ensureStockfish();
    if (stockfish) applyEngineEloStrength(ELO_MAX);
    $('#engine-elo').text(`ELO ${ELO_MAX}`);
    $('#game-mode-title').text('♟ Continua contra ELO màxim');
    $('#btn-resign').show().prop('disabled', false);
    clearEngineMoveHighlights();
    resetGameMoveNav();
    updatePrecisionDisplay();
    updateAIPrecisionDisplay();
    updateStatus();
    setTimeout(() => { resizeBoardToViewport(); }, 0);
    if (game.turn() !== playerColor) {
        setTimeout(makeEngineMove, 300);
    }
    return true;
}

function wireContinueOpeningErrorFenButton(overlay) {
    const btn = overlay.find('.btn-continue-fen-game');
    const show = canContinueOpeningErrorFenGame();
    btn.toggle(show).prop('disabled', !show).text(`♟ Continua contra ELO màxim`);
    btn.off('click').on('click', () => { continueOpeningErrorFenGame(); });
}

function showOpeningErrorSuccessOverlay(noMore) {
    const overlay = $('#opening-error-success-overlay');
    if (!overlay.length) {
        exitOpeningErrorPractice();
        return;
    }
    overlay.find('.bundle-success-title').text('Error d\'obertura resolt');

    const remaining = collectAllOpeningErrorPositions().length;
    const allErrors = getAllOpeningErrors();
    const globalRemaining = allErrors.length;
    const showAgainBtn = remaining > 0 || globalRemaining > 0;
    console.log('[Overlay] remaining:', remaining, 'globalRemaining:', globalRemaining, 'noMore:', noMore, 'showBtn:', showAgainBtn);

    // Mostrar missatge adequat
    let message;
    if (globalRemaining === 0) {
        message = 'Has resolt totes les errades!';
    } else if (remaining > 0) {
        message = `${remaining} errad${remaining > 1 ? 'es' : 'a'} restant${remaining > 1 ? 's' : ''}`;
    } else {
        message = `${globalRemaining} errad${globalRemaining > 1 ? 'es' : 'a'} d'altres moviments`;
    }
    $('#opening-error-remaining').text(message);

    // Mostrar/amagar botó segons si queden errors
    const btnAgain = document.getElementById('btn-opening-error-again');
    console.log('[Overlay] btnAgain element:', btnAgain);
    if (btnAgain) {
        btnAgain.style.display = showAgainBtn ? 'inline-block' : 'none';
        console.log('[Overlay] btnAgain.style.display:', btnAgain.style.display);
    }

    wireContinueOpeningErrorFenButton(overlay);
    overlay.css('display', 'flex');

    // Event handlers
    wireNavTrio(overlay, {
        onHome: () => {
            exitOpeningErrorPractice();
            goToHomeScreen();
        },
        sectionLabel: '<svg class="btn-ic" aria-hidden="true"><use href="#ic-book"/></svg>Obertures',
        onSection: () => exitOpeningErrorPractice()
    });

    if (btnAgain) {
        btnAgain.onclick = function() {
            overlay.hide();
            openingErrorCurrentPositions = collectAllOpeningErrorPositions();
            if (openingErrorCurrentPositions.length > 0) {
                // Encara queden del filtre actual
                setOpeningScreenMode('error-practice');
                openingErrorMovesRemaining = 2;
                loadRandomOpeningError();
            } else {
                // Canviar a errors globals
                const allErrors = getAllOpeningErrors();
                if (allErrors.length > 0) {
                    // Seleccionar un aleatori de tots
                    const idx = Math.floor(Math.random() * allErrors.length);
                    const error = allErrors[idx];
                    // Actualitzar filtres al nou error
                    openingErrorColorFilter = error.colorKey;
                    openingErrorMoveFilter = error.moveNumber;
                    // Carregar totes les posicions d'aquest nou filtre
                    const stat = openingStatsData.find(s =>
                        s.colorKey === error.colorKey && s.moveNumber === error.moveNumber
                    );
                    if (stat && stat.errorPositions) {
                        openingErrorCurrentPositions = [...stat.errorPositions];
                    }
                    setOpeningScreenMode('error-practice');
                    openingErrorMovesRemaining = 2;
                    loadRandomOpeningError();
                } else {
                    exitOpeningErrorPractice();
                }
            }
        };
    }
}

function exitOpeningErrorPractice() {
    openingErrorPracticeActive = false;
    openingErrorCurrentPositions = [];
    openingErrorCurrentFen = null;
    openingErrorBestMove = null;

    setOpeningScreenMode('overview');

    // Tornar a renderitzar estadístiques amb dades actualitzades
    renderOpeningStatsScreen(true);

    // Reset tauler
    startOpeningPracticeAsColor(openingPracticeUserColor);
}

