const HUMANPLAN_RECENT_KEY = 'eltauler_recent_human_plans';
let _humanPlanRecent = null;
function ensureHumanPlanRecent() {
    if (_humanPlanRecent) return _humanPlanRecent;
    const stored = readJsonStorage(HUMANPLAN_RECENT_KEY, {});
    _humanPlanRecent = (stored && typeof stored === 'object') ? stored : {};
    return _humanPlanRecent;
}
function formatSwingForText(value) {
    const n = Math.abs(Math.round(Number(value) || 0));
    if (n >= 1000) return 'molt d’avantatge';
    if (n >= 500) return 'més de 5 peons d’avaluació';
    return `${n} CP`;
}


// Accés segur al redactor normatiu (redactor.js). Si per qualsevol motiu no
// s'hagués carregat, el text passa sense esmenar: mai no bloqueja l'app.
function getRedactor() {
    try { if (typeof ElTaulerRedactor !== 'undefined' && ElTaulerRedactor) return ElTaulerRedactor; } catch (e) {}
    return null;
}

// Canonada de qualitat per a text generat (OpenAI): correcció normativa +
// auditoria. Si `ok` és fals, qui crida ha de descartar el text i quedar-se
// amb la redacció local, que sempre és correcta i fidel a les dades.
function esmenaCatalaCoach(text, opcions) {
    const r = getRedactor();
    if (!r) return { text: String(text || '').trim(), ok: true, problemes: [] };
    return r.esmenarTextEntrenador(text, opcions || {});
}

// Regla de registre segons la veu de l'entrenador, per als textos d'IA. No
// toca les normes de notació de cada prompt (si un prompt prohibeix la SAN,
// segueix prohibida): només fixa el to i la densitat de tecnicismes.
const REVIEW_VOICE_OPENAI_RULES = {
    casual: '- TO DE VEU (casual): parla planer, directe i amable, com a un principiant; evita tecnicismes com "seqüència forçada", "sobrecàrrega" o "compensació posicional" i explica-ho amb paraules senzilles, sense fer-ho infantil.',
    balanced: '',
    technical: '- TO DE VEU (tècnic): escriu precís i professional, per a un jugador avançat; pots usar termes com forquilla, clavada, desviació, sobrecàrrega o qualitat, mantenint les frases curtes i sense allargar el text.'
};
// Bloc de normes d'estil compartit que s'afegeix a tots els prompts de
// l'entrenador perquè el model escrigui català normatiu, amb % i sense SAN,
// en el registre de la veu per defecte de l'usuari.
function coachStyleRulesBlock() {
    const r = getRedactor();
    let block = r ? '\n' + r.REGLES_ESTIL_CATALA : '';
    const voiceRule = REVIEW_VOICE_OPENAI_RULES[getReviewVoiceStyle()];
    if (voiceRule) block += '\n' + voiceRule;
    return block;
}

function polishCoachText(text, opts = {}) {
    const redactor = getRedactor();
    let out = String(redactor ? redactor.corregirCatala(text || '') : (text || ''))
        .replace(/\s+/g, ' ')
        .replace(/\s+([,.;:!?])/g, '$1')
        .replace(/\b[Ee]l dama\b/g, 'la dama')
        .replace(/\b[Ee]l torre\b/g, 'la torre')
        .replace(/\b[Ee]l peça\b/g, 'la peça')
        .replace(/\b[Pp]etit relliscada\b/g, 'Petita relliscada')
        .replace(/\bla decisió la jugada triada\b/g, 'la jugada triada')
        .replace(/\bla decisió la millor jugada\b/g, 'la millor jugada')
        .replace(/\b(la millor jugada) ho feia millor\b/g, '$1 ho resolia millor')
        .replace(/\b(la millor jugada) hi apuntava\b/g, '$1 apuntava a aquest pla')
        .replace(/\b(la millor jugada) ho feia\b/g, '$1 ho aconseguia')
        .replace(/\s+([.!?])$/g, '$1')
        .trim();
    if (!out) return '';
    if (!/[.!?]$/.test(out) && opts.sentence !== false) out += '.';
    return out.charAt(0).toUpperCase() + out.slice(1);
}

function validateCoachText(text) {
    const raw = String(text || '').trim();
    const words = raw ? raw.split(/\s+/).length : 0;
    const issues = [];
    if (!raw) issues.push('empty');
    if (/\bel dama\b/i.test(raw)) issues.push('bad_article_dama');
    if (/\bel torre\b/i.test(raw)) issues.push('bad_article_torre');
    if (/\b[KQRBN][a-h]?[1-8]?x?[a-h][1-8][+#]?\b/.test(raw)) issues.push('san_notation');
    if ((raw.match(/\bCP\b/g) || []).length > 1) issues.push('too_many_cp_mentions');
    if (words > 42) issues.push('too_long');
    if (/(\b\w+\b)(?:\s+\1){2,}/i.test(raw)) issues.push('repeated_word');
    return { ok: issues.length === 0, issues, words, score: Math.max(0, 100 - issues.length * 20 - Math.max(0, words - 42)) };
}

function ensureCoachTextQuality(text, fallback = '', opts = {}) {
    const polished = polishCoachText(text, opts);
    const quality = validateCoachText(polished);
    if (quality.ok || !fallback) return polished;
    const polishedFallback = polishCoachText(fallback, opts);
    return validateCoachText(polishedFallback).score >= quality.score ? polishedFallback : polished;
}

// Escurça SENSE deixar mai una frase a mitges amb "…": talla per frases
// senceres (redactor.js). Millor una frase completa de menys que text trencat.
function shortenCoachComment(text, maxWords = 18) {
    const raw = String(text || '').trim();
    if (!raw) return '';
    const redactor = getRedactor();
    if (redactor && redactor.escurcaFrasesSenceres) return redactor.escurcaFrasesSenceres(raw, maxWords);
    return raw;
}

// Una línia de l'entrenador només es mostra si és una frase completa: res de
// punts suspensius finals ni connectors penjats ("i el", "en lloc de"...).
function isIncompleteCoachText(text) {
    const t = String(text || '').trim();
    if (!t) return false;
    const redactor = getRedactor();
    if (redactor && redactor.esTextIncomplet) return redactor.esTextIncomplet(t);
    return /(\.\.\.|…)$/.test(t);
}

// Fallback curt i segur quan una explicació queda buida o trencada.
const SAFE_COACH_FALLBACK = 'La jugada afluixava la posició. Revisa la millor jugada al tauler i compara què queda defensat.';

function compactStructuredCoachText(text, fallback = '', opts = {}) {
    return shortenCoachComment(ensureCoachTextQuality(text, fallback, opts), opts.maxWords || 18);
}

function fillPlanTemplate(str, moment) {
    const m = moment || {};
    // En les frases explicatives fem servir referències curtes. La descripció completa
    // de la jugada ja surt a l'enllaç principal; repetir-la dins cada frase feia textos
    // artificials com "la decisió la dama va a e1".
    return polishCoachText(String(str || '')
        .replace(/\{n\}/g, m.moveNumber ?? '?')
        .replace(/\{played\}/g, m.playedRef || 'la jugada triada')
        .replace(/\{best\}/g, m.bestRef || 'la millor jugada')
        .replace(/\{swing\}\s*CP/g, formatSwingForText(m.swing))
        .replace(/\{swing\}/g, Math.abs(Math.round(Number(m.swing) || 0))));
}
// Tria una variant evitant les usades recentment; l'historial es persisteix a
// localStorage, així no es repeteix ni entre partides ni entre sessions.
function pickFreshPlanLine(pool, bucket) {
    if (!Array.isArray(pool) || !pool.length) return '';
    if (pool.length === 1) return pool[0];
    const store = ensureHumanPlanRecent();
    const recent = Array.isArray(store[bucket]) ? store[bucket] : [];
    const fresh = pool.filter(x => !recent.includes(x));
    const choice = randItem(fresh.length ? fresh : pool);
    const keep = Math.max(1, Math.min(pool.length - 1, Math.ceil(pool.length / 2)));
    store[bucket] = [choice, ...recent.filter(x => x !== choice)].slice(0, keep);
    writeJsonStorage(HUMANPLAN_RECENT_KEY, store);
    return choice;
}
function toInlineAdvice(text) {
    const t = String(text || '').trim().replace(/[.…]+$/, '');
    return t ? t.charAt(0).toLowerCase() + t.slice(1) : t;
}
function resolveHumanPlanThemeKey(moment) {
    let key = planBankKeyFor(moment && moment.themeKey);
    if (!key) {
        const label = String((moment && moment.theme) || '').toLowerCase();
        if (/rei|atac/.test(label)) key = 'king_attack';
        else if (/forquilla/.test(label)) key = 'fork';
        else if (/clavada/.test(label)) key = 'pin';
        else if (/raig|enfilad|broquet/.test(label)) key = 'skewer';
        else if (/peó passat|passat/.test(label)) key = 'passed_pawn';
        else if (/profilax|defens/.test(label)) key = 'defensive_move';
        else if (/simplif/.test(label)) key = 'simplification';
        else if (/activitat/.test(label)) key = 'piece_activity';
        else if (/tranquil|iniciativa/.test(label)) key = 'quiet_improvement';
        else if (/material/.test(label)) key = 'material';
        else if (/centre|ruptura/.test(label)) key = 'center';
        else if (/obertura|desenvolup/.test(label)) key = 'opening';
        else if (/final/.test(label)) key = 'endgame';
        else key = 'general';
    }
    const phase = moment && moment.phase;
    if (key === 'general') {
        if (phase === 'obertura') key = 'opening';
        else if (phase === 'final') key = 'endgame';
    }
    return HUMAN_PLAN_BANK[key] ? key : 'general';
}

