        const file = this.files && this.files[0];
        this.value = ''; // permet tornar a triar el mateix fitxer
        if (!file) return;
        pgnImportFileName = file.name || null;
        const reader = new FileReader();
        reader.onload = () => {
            $('#pgn-import-text').val(String(reader.result || ''));
            parsePgnImportText();
        };
