// Text simple (cadena) d'una clau de la capa de veu, amb reserva a la veu
// equilibrada si l'estil demanat no té la clau.
function voiceText(style, key, fallbackKey = null) {
    const safeStyle = getReviewVoiceStyle(style);
    const own = REVIEW_VOICE_TEXT[safeStyle] ? REVIEW_VOICE_TEXT[safeStyle][key] : null;
    if (typeof own === 'string' && own) return own;
    const bal = REVIEW_VOICE_TEXT.balanced[fallbackKey || key];
    return (typeof bal === 'string' && bal) ? bal : '';
}

// Vector de variants d'un grup ('outcomeDiagnosis', 'outcomePlan'...) per a una
// clau, amb reserva a la veu equilibrada. Retorna [] si tampoc no hi és.
function voicePool(style, group, key) {
    const safeStyle = getReviewVoiceStyle(style);
    const own = REVIEW_VOICE_TEXT[safeStyle] && REVIEW_VOICE_TEXT[safeStyle][group];
    if (own && Array.isArray(own[key]) && own[key].length) return own[key];
    const bal = REVIEW_VOICE_TEXT.balanced[group];
    return (bal && Array.isArray(bal[key])) ? bal[key] : [];
}

// Connector de gravetat ("Això era crític perquè...") segons la veu.
function voiceSeverityIntro(style, quality) {
    const safeStyle = getReviewVoiceStyle(style);
    const q = (quality === 'blunder' || quality === 'mistake') ? quality : 'inaccuracy';
    const own = REVIEW_VOICE_TEXT[safeStyle].severity || REVIEW_VOICE_TEXT.balanced.severity;
    return own[q] || REVIEW_VOICE_TEXT.balanced.severity[q];
}

// Frase motivacional final de la ressenya: estable per partida (canvia amb la
// llavor de «Regenerar la ressenya»), diferent segons la veu.
function pickVoiceMotivation(style, seedKey) {
    const safeStyle = getReviewVoiceStyle(style);
    const pool = REVIEW_VOICE_TEXT[safeStyle].motivation || REVIEW_VOICE_TEXT.balanced.motivation || [];
    if (!pool.length) return '';
    return pool[coachStableHash(String(seedKey || '') + ':motivacio') % pool.length];
}

/* =================== TEMA DOMINANT EN LLENGUATGE ÚTIL =====================
   "joc general" és massa vague. Aquesta funció el converteix (i concreta els
   temes reals) en una frase útil segons la veu. Quan el tema és 'general' i
   sabem l'OUTCOME dominant de la partida (conversió d'avantatge, atac fluix,
   pèrdua de material...), diem què va passar de debò en comptes de "general".
   Les frases no porten dades ni SAN: només descriuen el patró. */
const DOMINANT_THEME_TEXT = {
    casual: {
        _byOutcome: {
            conversion: ['convertir l’avantatge sense donar aire al rival', 'rematar quan ja tenies la partida de cara', 'tancar les posicions bones amb més decisió'],
            attack: ['atacar abans de tenir prou peces preparades', 'llançar l’atac al rei sense acabar de preparar-lo'],
            material: ['vigilar què et pot capturar el rival abans de moure', 'no deixar peces despenjades'],
            counterplay: ['no donar contrajoc quan ja estaves millor', 'evitar que el rival agafés iniciativa']
        },
        fork: 'aprofitar (o evitar) els dobles atacs de cavall',
        pin: 'les clavades: peces que no es poden moure sense perdre’n una de més grossa',
        skewer: 'els atacs en línia (raig X) sobre peces alineades',
        king_attack: 'atacar el rei abans de tenir prou peces a prop',
        material: 'comptar bé què et pot capturar el rival abans de moure',
        center: 'el control del centre',
        opening: 'sortir bé de l’obertura, amb les peces fora i el rei segur',
        endgame: 'els finals: activar el rei i convertir sense presses',
        general: 'triar un pla clar i seguir-lo unes quantes jugades'
    },
    balanced: {
        _byOutcome: {
            conversion: ['la conversió de l’avantatge sense donar contrajoc', 'rematar les posicions guanyadores amb decisió'],
            attack: ['coordinar l’atac al rei abans de llançar-lo', 'preparar l’atac amb prou peces'],
            material: ['el compte d’atacants i defensors abans de capturar', 'no deixar peces indefenses'],
            counterplay: ['limitar el contrajoc del rival quan estaves millor', 'mantenir la iniciativa']
        },
        fork: 'les forquilles',
        pin: 'les clavades',
        skewer: 'els atacs en raig X',
        king_attack: 'l’atac al rei',
        material: 'la cura del material',
        center: 'el control del centre',
        opening: 'el desenvolupament i el centre a l’obertura',
        endgame: 'la tècnica de finals',
        general: 'triar i seguir un pla concret'
    },
    technical: {
        _byOutcome: {
            conversion: ['la conversió de l’avantatge i el control del contrajoc', 'transformar avantatges decisius en continuacions forçades', 'la conversió de posicions guanyadores limitant recursos defensius'],
            attack: ['l’atac al rei sense prou coordinació de peces ni seqüència forçada', 'la coordinació de peces en atac i la conversió de posicions guanyadores'],
            material: ['l’equilibri entre atacants i defensors abans de capturar', 'la seguretat del material davant seqüències tàctiques'],
            counterplay: ['el control del contrajoc amb avantatge', 'la retenció de la iniciativa en posicions favorables']
        },
        fork: 'els dobles atacs (forquilla)',
        pin: 'les clavades i la immobilització de peces',
        skewer: 'els atacs en raig X sobre peces alineades',
        king_attack: 'l’atac al rei sense prou coordinació de peces ni seqüència forçada',
        material: 'l’equilibri material i el compte d’atacants i defensors',
        center: 'el control i la ruptura del centre',
        opening: 'el desenvolupament, el control central i la seguretat del rei',
        endgame: 'la conversió i la tècnica de finals',
        general: 'la tria i execució d’un pla concret'
    }
};
function humanizeDominantTheme(themeKey, context = {}, opts = {}) {
    const style = getReviewVoiceStyle(opts.voiceStyle);
    const bank = DOMINANT_THEME_TEXT[style] || DOMINANT_THEME_TEXT.balanced;
    const growth = normalizeGrowthTheme(themeKey);
    // Tema concret conegut: frase específica per veu (mai el sec "joc general").
    if (growth && growth !== 'general' && bank[growth]) return bank[growth];
    // Tema 'general': si sabem l'outcome dominant, diem què va passar de debò.
    const outcome = String(context.outcome || '');
    let bucket = null;
    if (/win_slip|advantage_slip|lets_win|lets_advantage/.test(outcome)) bucket = 'conversion';
    else if (/counterplay|initiative|cedes/.test(outcome)) bucket = 'counterplay';
    else if (/mate|king|attack/.test(outcome)) bucket = 'attack';
    else if (/loses_|major|piece|exchange|pawn/.test(outcome)) bucket = 'material';
    if (bucket && bank._byOutcome && bank._byOutcome[bucket] && bank._byOutcome[bucket].length) {
        const pool = bank._byOutcome[bucket];
        return pool[coachStableHash(String(context.seed || outcome || '') + ':domtheme:' + bucket) % pool.length];
    }
    return bank.general;
}

/* =================== NOMENCLATURA DE JUGADES SEGONS LA VEU ===================
   FONT ÚNICA DE VERITAT per descriure una jugada: es valida sobre la FEN amb
   chess.js (moveFacts) i tot el text —SAN inclosa— surt d'aquesta verificació,
   mai d'una cadena antiga desada. Si la jugada no és legal sobre la FEN, es
   retorna null i qui crida ha d'amagar el moment o usar un fallback segur.
     casual    → llenguatge natural, sense SAN ni UCI ("el cavall va a f7")
     balanced  → descripció amb la SAN entre parèntesis ("el cavall va a f7 (Nf7)")
     technical → SAN al davant i la descripció al costat ("Nxf7+ (el cavall...)")
   A més del text en línia, retorna les peces per compondre frases:
     accio    → infinitiu ("portar el cavall de f3 a h4") per a "vas ..." /
                "el millor pla era ..." en veu casual
     clausula → subjecte+verb sense color ("el cavall de f3 va a h4") per a
                "vas jugar Nh4: ..." en veus equilibrada i tècnica
   ========================================================================== */
function describeMoveByVoice(fen, moveUciOrSan, opts = {}) {
    const voiceStyle = getReviewVoiceStyle(opts.voiceStyle);
    let facts = null;
    try {
        const helpers = getPvBoardHelpers();
        facts = helpers ? helpers.moveFacts(fen, moveUciOrSan) : null;
    } catch (e) { facts = null; }
    if (!facts) return null;
    const R = (typeof ElTaulerRedactor !== 'undefined') ? ElTaulerRedactor : null;
    const veu = (R && R.descriuJugadaPerVeu) ? R.descriuJugadaPerVeu(facts, { estil: voiceStyle }) : null;
    const clausula = (veu && veu.clausula) || (R && R.descriuMovimentFets ? R.descriuMovimentFets(facts) : '') || facts.san;
    const accio = (veu && veu.accio) || clausula;
    let text;
    if (voiceStyle === 'casual') text = clausula;
    else if (voiceStyle === 'technical') text = (facts.san && facts.san !== clausula) ? `${facts.san} (${clausula})` : clausula;
    else text = withSan(clausula, facts.san);
    return { text, san: facts.san, from: facts.origen, to: facts.desti, accio, clausula };
}

// Drecera de describeMoveByVoice quan només cal la cadena de text. Si la
// jugada no és verificable sobre la FEN, el fallback només s'usa quan NO
// sembla UCI (cap veu no pot mostrar mai "g5f7"); si no, cadena buida.
function voiceMoveText(fen, move, fallback, voiceStyle) {
    const d = describeMoveByVoice(fen, move, { voiceStyle });
    if (d && d.text) return d.text;
    const fb = String(fallback || '').trim();
    if (fb && !/^[a-h][1-8][a-h][1-8][qrbn]?$/i.test(fb)) return fb;
    return '';
}

// "Vas jugar ..." segons la veu, a partir de la jugada VERIFICADA sobre la FEN:
//   casual    → "vas portar el cavall de f3 a h4"
//   balanced  → "vas jugar Nh4: el cavall de f3 va a h4"
//   technical → "vas jugar Nh4: el cavall de f3 es reubica a h4"
// Retorna '' si la jugada no és verificable (qui crida decideix el fallback).
function playedPhraseByVoice(fen, move, voiceStyle) {
    const style = getReviewVoiceStyle(voiceStyle);
    const d = describeMoveByVoice(fen, move, { voiceStyle: style });
    if (!d) return '';
    if (style === 'casual') return `vas ${d.accio}`;
    return `vas jugar ${d.san}: ${d.clausula}`;
}

// "La millor era ..." segons la veu, en dues peces perquè el cos pugui ser un
// enllaç clicable. Mai el format maquinal "la millor era → SAN".
//   casual    → { prefix: 'el millor pla era ', body: 'portar la dama a d2' }
//   balanced  → { prefix: 'la millor era ', body: 'Qd2: la dama va a d2' }
//   technical → { prefix: 'la millor era ', body: 'Qd2: la dama es reubica a d2' }
function bestPhraseByVoice(fen, move, voiceStyle) {
    const style = getReviewVoiceStyle(voiceStyle);
    const d = describeMoveByVoice(fen, move, { voiceStyle: style });
    if (!d) return null;
    if (style === 'casual') return { prefix: 'el millor pla era ', body: d.accio };
    return { prefix: 'la millor era ', body: `${d.san}: ${d.clausula}` };
}

// El càstig concret de la jugada feta, en llenguatge planer (nom de la peça i
// casella de destí) en comptes de notació algebraica. En condicional ("podia"):
// és la millor rèplica del motor, no una seqüència que hagi de passar per força.
function buildRefutationNote(moment, voiceStyle) {
    const m = moment || {};
    const style = getReviewVoiceStyle(voiceStyle);
    const afterFen = m.afterFen;
    const pv = Array.isArray(m.refutationPv) ? m.refutationPv : [];
    if (!afterFen || pv.length < 1) return '';
    const seq = describeLineHuman(afterFen, pv, 0, 3, style);
    return seq ? `${voiceText(style, 'refutationIntro')}: ${seq}.` : '';
}

function buildStructuredConsequence(moment, voiceStyle) {
    const m = moment || {};
    const style = getReviewVoiceStyle(voiceStyle);
    const severity = voiceSeverityIntro(style, m.quality);

    // Resultat determinista a partir de la refutació i l'avaluació reals.
    const outcome = classifyMoveOutcome(m);
    if (outcome) {
        const pool = voicePool(style, 'outcomeConsequence', outcome).length
            ? voicePool(style, 'outcomeConsequence', outcome)
            : voicePool(style, 'outcomeConsequence', 'lets_advantage_slip');
        const base = `${severity} ${toInlineAdvice(pickStableLine(pool, m))}`;
        // Cost en peons: visible en tècnica; en casual NO carrega la frase
        // principal (el número ja surt al badge), llevat que sigui informació
        // qualitativa de mat ("tenies mat en 3"), que sí que s'hi manté.
        const cost = coachCostSuffix(m);
        if (!cost) return `${base}.`;
        if (style === 'casual' && /cost aproximat/.test(cost)) return `${base}.`;
        return `${base} (${cost}).`;
    }

    // Legacy (partides sense avaluació ni refutació): comportament per tema.
    const themeKey = resolveHumanPlanThemeKey(m);
    const pool = STRUCTURED_CONSEQUENCES[themeKey] || STRUCTURED_CONSEQUENCES.general;
    const line = fillPlanTemplate(pickFreshPlanLine(pool, themeKey + ':structured:consequence'), m);
    return `${severity} ${toInlineAdvice(line)}.`;
}

function buildStructuredLocalExplanation(moment, plan = {}, opts = {}) {
    const fallbackPlan = plan && typeof plan === 'object' ? plan : {};
    // La veu de l'entrenador canvia la redacció d'aquests camps, mai els fets.
    const voiceStyle = getReviewVoiceStyle(opts.voiceStyle);
    // full=true (exportació per analitzar): no retallem el text a 14-16 paraules
    // amb "…"; deixem les frases senceres perquè no quedin tallades a mitja frase.
    const full = !!opts.full;
    const fld = (text, fallback, o = {}) => {
        const polished = ensureCoachTextQuality(text, fallback, o);
        return full ? polished : shortenCoachComment(polished, o.maxWords || 18);
    };
    const sanFld = (text, maxWords) => full ? String(text || '').trim() : shortenCoachComment(text, maxWords);
    const fact = moment && moment.positional
        ? moment.positional
        : `Era una posició de ${moment?.theme || 'joc general'} en fase de ${moment?.phase || 'partida'}.`;
    // Per als resultats forts, fem servir diagnòstic i pla COHERENTS amb el que
    // realment va passar, perquè no contradiguin la conseqüència ni el tauler.
    // ensureCoachTextQuality (a baix) ja capitalitza i afegeix punt final.
    const outcome = classifyMoveOutcome(moment || {});
    const diagPool = outcome ? voicePool(voiceStyle, 'outcomeDiagnosis', outcome) : [];
    const mistake = diagPool.length
        ? pickStableLine(diagPool, moment, 'diag')
        : (stripPlanIntro(fallbackPlan.diagnosis) || 'La jugada triada no resolia la necessitat principal de la posició.');
    const consequence = buildStructuredConsequence(moment || {}, voiceStyle);
    const planPool = outcome ? voicePool(voiceStyle, 'outcomePlan', outcome) : [];
    const betterPlan = planPool.length
        ? pickStableLine(planPool, moment, 'plan')
        : (fallbackPlan.plan || 'El pla millor era triar una jugada amb funció clara i menys contrajoc.');
    return {
        fact: fld(fact, '', { maxWords: 16 }),
        mistake: fld(mistake, 'La jugada triada no resolia la necessitat principal.', { maxWords: 16 }),
        consequence: fld(consequence, '', { maxWords: 16 }),
        plan: fld(betterPlan, 'Tria una jugada amb funció clara i poc contrajoc.', { maxWords: 16 }),
        // La continuació i la refutació contenen notació SAN deliberadament, així
        // que NO passen pel validador de text (que penalitza la SAN).
        continuation: sanFld(buildContinuationNote(moment || {}, voiceStyle), 14),
        refutation: sanFld(buildRefutationNote(moment || {}, voiceStyle), 14),
        question: fld(fallbackPlan.question || '', '', { sentence: false, maxWords: 14 })
    };
}

// Selecció dels moments clau (els 2-3 pitjors errors mostrables), SENSE
// construir-ne els textos: la fan servir buildHumanPlanMoments i el filtre
// que evita repetir aquestes jugades a "Errades comentades".
function selectHumanPlanReviews(entry) {
    const reviews = Array.isArray(entry?.moveReviews) ? entry.moveReviews : [];
    const priority = { blunder: 4, mistake: 3, inaccuracy: 2, good: 1, excel: 0 };
    const validationOpts = reviewErrorValidationOpts(entry);
    return reviews
        .filter(r => r && ['inaccuracy', 'mistake', 'blunder'].includes(r.quality))
        // Validació forta: cap moment amb FEN o jugades invàlides, número de
        // jugada impossible o jugada feta igual a la millor (swing fantasma).
        .filter(r => isRenderableReviewError(entry, r, validationOpts))
        .sort((a, b) => ((priority[b.quality] || 0) - (priority[a.quality] || 0)) || ((b.swing || 0) - (a.swing || 0)))
        // Fins a 5 moments clau (abans 3): així a la ressenya apareixen més
        // moviments clau i errors principals de la partida.
        .slice(0, 5);
}

function buildHumanPlanMoments(entry, insights = null, opts = {}) {
    const ins = insights || buildPlayerInsights(entry && entry.id);
    const voiceStyle = getReviewVoiceStyle(opts.voiceStyle);
    return selectHumanPlanReviews(entry)
        .map(r => {
            const ctx = buildPlanContext(r);
            const themeKey = detectPlanSubtheme(r, ctx);
            const isPattern = !!(ins && ins.recurringTheme && ins.recurringCount >= 3
                && planThemeToGrowth(themeKey) === ins.recurringTheme);
            const moment = {
                moveNumber: r.moveNumber || '?',
                phase: phaseFromContext(ctx, r.moveNumber),
                themeKey,
                theme: planThemeDisplayLabel(themeKey),
                // SAN recalculada sobre la FEN: la que es mostra i la que fa
                // servir l'enllaç per localitzar la jugada a l'historial.
                played: (r.fen ? sanOnFen(r.fen, r.playerMove || r.playerMoveSan) : null) || r.playerMoveSan || r.playerMove || '—',
                playedUci: (r.playerMove && r.playerMove !== '—') ? r.playerMove : null,
                best: (r.fen ? sanOnFen(r.fen, r.bestMove || r.bestMoveSan) : null) || r.bestMoveSan || r.bestMove || '—',
                // Versions en llenguatge planer per a les frases (sense notació SAN).
                playedDesc: r.fen ? moveHumanText(r.fen, r.playerMove || r.playerMoveSan, r.playerMoveSan) : (r.playerMoveSan || '—'),
                bestDesc: r.fen ? moveHumanText(r.fen, r.bestMove || r.bestMoveSan, r.bestMoveSan) : (r.bestMoveSan || '—'),
                playedRef: 'la jugada triada',
                bestRef: 'la millor jugada',
                bestMoveUci: r.bestMove || null,
                swing: Math.round(r.swing || 0),
                quality: r.quality || 'inaccuracy',
                evalBefore: r.evalBefore ?? null,
                evalAfter: r.evalAfter ?? null,
                refutationPv: Array.isArray(r.refutationPv) ? r.refutationPv : [],
                afterFen: r.afterFen || null,
                fen: r.fen || null,
                pv: Array.isArray(r.bestMovePv) ? r.bestMovePv : [],
                // Dades de forçament de la línia (reanàlisi profunda o derivades
                // al vol), per triar el llenguatge de la narració de la PV.
                forcingInfo: r.forcingInfo || null,
                multipvBefore: r.multipvBefore || null,
                replyAlternatives: r.replyAlternatives || null,
                evalAfterBest: r.evalAfterBest ?? null,
                positional: buildPositionalNote(ctx),
                candidates: buildCandidatesNote(r, voiceStyle),
                isPattern
            };
            const plan = buildLocalHumanPlan(moment);
            return { ...moment, ...plan, structured: buildStructuredLocalExplanation(moment, plan, opts) };
        });
}

function buildHumanPlansOpenAIPrompt(entry, moments) {
    return `Ets un entrenador d'escacs que escriu en català natural. Redacta un "Entrenador de plans humans" variat i gens repetitiu.

DADES DE LA PARTIDA
${JSON.stringify({ resultat: entry?.result || '—', precisio: entry?.precision ?? null }, null, 2)}

MOMENTS CRÍTICS DETECTATS PEL MOTOR (no els qüestionis ni inventis jugades):
${JSON.stringify(moments.map(m => ({ jugada: m.moveNumber, fase: m.phase, tema: m.theme, jugada_feta: m.played, millor_jugada: m.best, perdua_centipeons: m.swing, qualitat: m.quality })), null, 2)}

Retorna exactament ${moments.length} blocs, un per moment, separats per una línia en blanc. Cada bloc ha de tenir aquest format exacte:
PLA X: títol curt
Diagnòstic: una frase molt breu sobre què passava.
Pla: una frase curta amb el pla correcte.
Pregunta: una pregunta curta.
Objectiu: una microtasca breu.

Regles: no facis markdown, no emojis, no llistes amb guions, màxim 45 paraules per bloc, català natural i precís, no inventis variants noves.${coachStyleRulesBlock()}`;
}

// Opcions d'auditoria dels plans humans: es permeten els números de jugada,
// les pèrdues en centipeons (i el seu equivalent en peons) i la numeració
// dels blocs; s'hi tolera la notació SAN perquè les dades del prompt ja la
// contenen i el jugador la veu igualment a la fitxa del moment.
function humanPlansAuditOptions(entry, moments) {
    const xifres = [];
    if (entry && typeof entry.precision === 'number') xifres.push(entry.precision);
    (moments || []).forEach(m => {
        if (typeof m.moveNumber === 'number') xifres.push(m.moveNumber);
        if (typeof m.swing === 'number') {
            xifres.push(Math.abs(Math.round(m.swing)));
            xifres.push(Math.round(Math.abs(m.swing) / 100));
            xifres.push(Math.abs(m.swing) / 100);
        }
    });
    for (let i = 1; i <= (moments || []).length; i++) xifres.push(i);
    return { xifresPermeses: xifres, percentatges: [], permetSan: true, maxParaules: 80 * Math.max(1, (moments || []).length) };
}


function buildSingleMovePracticeSequence(moment) {
    if (!moment || !moment.fen || !moment.bestMoveUci) return null;
    try {
        const g = new Chess(moment.fen);
        const move = g.move({
            from: moment.bestMoveUci.slice(0, 2),
            to: moment.bestMoveUci.slice(2, 4),
            promotion: moment.bestMoveUci.length > 4 ? moment.bestMoveUci[4] : undefined
        });
        if (!move) return null;
        let position = null;
        try { position = parseFenPosition(moment.fen); } catch (e) { position = null; }
        let threats = { threats: [], themes: [], immediateThreats: [] };
        try { threats = analyzePvThreats(moment.fen, [moment.bestMoveUci]) || threats; } catch (e) {}
        return {
            initialFen: moment.fen,
            totalSteps: 1,
            step1: {
                fen: moment.fen,
                playerMove: moment.bestMoveUci,
                playerMoveSan: move.san,
                alternatives: [],
                position: position,
                threats: threats
            },
            fullSequence: [moment.bestMoveUci],
            fullSequenceSan: [move.san]
        };
    } catch (e) {
        return null;
    }
}

// TIER 4 — exercici de 2-3 jugades a partir de la millor línia (PV), no només 1.
function buildMultiMovePracticeSequence(moment) {
    const pv = (moment && Array.isArray(moment.pv)) ? moment.pv : [];
    if (!moment || !moment.fen || pv.length < 3) return null;
    try {
        const g = new Chess(moment.fen);
        const steps = [], replies = [];
        for (let i = 0; i < pv.length; i++) {
            const u = pv[i];
            if (!u || u.length < 4) break;
            const before = g.fen();
            const mv = g.move({ from: u.slice(0, 2), to: u.slice(2, 4), promotion: u.length > 4 ? u[4] : undefined });
            if (!mv) break;
            if (i % 2 === 0) steps.push({ fen: before, uci: u, san: mv.san });
            else replies.push({ fen: before, uci: u, san: mv.san });
            if (steps.length >= 3 && replies.length >= 2) break;
        }
        let totalSteps;
        if (steps.length >= 3 && replies.length >= 2) totalSteps = 3;
        else if (steps.length >= 2 && replies.length >= 1) totalSteps = 2;
        else return null;
        const mkStep = (s) => {
            let position = null, threats = { threats: [], themes: [], immediateThreats: [] };
            try { position = parseFenPosition(s.fen); } catch (e) {}
            try { threats = analyzePvThreats(s.fen, [s.uci]) || threats; } catch (e) {}
            return { fen: s.fen, playerMove: s.uci, playerMoveSan: s.san, alternatives: [], position, threats };
        };
        const mkReply = (r) => ({ fen: r.fen, move: r.uci, moveSan: r.san, eval: 0 });
        const seq = {
            initialFen: moment.fen,
            totalSteps,
            step1: mkStep(steps[0]),
            opponentMove: mkReply(replies[0]),
            step2: mkStep(steps[1]),
            fullSequence: [steps[0].uci, replies[0].uci, steps[1].uci],
            fullSequenceSan: [steps[0].san, replies[0].san, steps[1].san]
        };
        if (totalSteps === 3) {
            seq.opponentMove2 = mkReply(replies[1]);
            seq.step3 = mkStep(steps[2]);
            seq.fullSequence.push(replies[1].uci, steps[2].uci);
            seq.fullSequenceSan.push(replies[1].san, steps[2].san);
        }
        return seq;
    } catch (e) {
        return null;
    }
}

function startHumanPlanPractice(moment) {
    const seq = buildMultiMovePracticeSequence(moment) || buildSingleMovePracticeSequence(moment);
    if (!seq) {
        showToast('No puc preparar aquest pla com a exercici jugable.', 'warn');
        return;
    }
    $('#review-modal').hide();
    isRandomBundleSession = false;
    isMatchErrorReviewSession = false;
    isSrsReviewSession = false;
    isDailyPuzzleSession = false;
    isTacticsSession = false;
    matchErrorQueue = [];
    currentMatchError = null;
    currentBundleSource = 'human_plan';
    currentBundleSeverity = null;
    currentGameMode = 'bundle';
    currentOpponent = null;
    pendingPreparedSequence = seq;
    startGame(true, seq.initialFen);
}

function appendHumanPlanPracticeButton(card, moment) {
    if (!moment || !moment.fen || !moment.bestMoveUci) return;
    const btn = $('<button class="btn btn-secondary human-plan-practice" type="button">Practica aquest pla</button>');
    btn.on('click', () => startHumanPlanPractice(moment));
    card.append(btn);
}

function renderHumanPlanCards(container, moments, voice = null) {
    const panel = $('<div class="human-plan-panel"></div>');
    const titleText = voice ? `🧭 Entrenador de plans humans · ${voice.name}` : '🧭 Entrenador de plans humans';
    panel.append($('<div class="coach-kicker human-plan-title"></div>').append($('<span></span>').text(titleText)));
    if (voice && voice.tagline) {
        panel.append($('<div class="coach-text human-plan-voice"></div>')
            .css({ opacity: 0.72, 'font-size': '0.82rem', 'margin': '2px 0 8px' })
            .text(`${voice.name} · ${voice.tagline}`));
    }
    const list = $('<div class="human-plan-list"></div>');
    moments.forEach((m, idx) => {
        const card = $('<div class="coach-item human-plan-card"></div>');
        const main = $('<div class="coach-item-main"></div>');
        main.append($('<div class="coach-item-title"></div>').text(`Pla ${idx + 1} · Jugada ${m.moveNumber} (${m.played}) · ${m.theme}`));
        const lines = [
            `<strong>Diagnòstic:</strong> ${escapeHtml(shortenCoachComment(m.diagnosis, 16))}`,
            `<strong>Pla:</strong> ${escapeHtml(shortenCoachComment(m.plan, 16))}`
        ];
        if (m.positional) lines.push(`<strong>A la posició:</strong> ${escapeHtml(shortenCoachComment(m.positional, 14))}`);
        if (m.candidates) lines.push(`<strong>Línia:</strong> ${escapeHtml(shortenCoachComment(m.candidates, 16))}`);
        if (m.isPattern) lines.push(`<strong>⚠️ Patró teu:</strong> aquest tema ja t'ha fallat altres partides recents.`);
        lines.push(`<strong>Pregunta:</strong> ${escapeHtml(shortenCoachComment(m.question, 14))}`);
        lines.push(`<strong>Objectiu:</strong> ${escapeHtml(shortenCoachComment(m.objective, 14))}`);
        main.append($('<div class="coach-text human-plan-text"></div>').html(lines.join('<br>')));
        card.append(main);
        appendHumanPlanPracticeButton(card, m);
        list.append(card);
    });
    panel.append(list);
    container.append(panel);
    return panel;
}

function renderOpenAIHumanPlans(panel, text, moments = []) {
    if (!panel || !panel.length || !text) return;
    const blocks = String(text).split(/\n\s*\n/).map(b => b.trim()).filter(Boolean);
    if (!blocks.length) return;
    const list = panel.find('.human-plan-list');
    if (!list.length) return;
    list.empty();
    blocks.forEach((block, idx) => {
        const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
        const title = lines.shift() || 'Pla humà';
        const card = $('<div class="coach-item human-plan-card"></div>');
        const main = $('<div class="coach-item-main"></div>');
        main.append($('<div class="coach-item-title"></div>').text(title.replace(/^PLA\s*\d+\s*:\s*/i, '')));
        main.append($('<div class="coach-text human-plan-text"></div>').html(escapeHtml(lines.join('\n')).replace(/\n/g, '<br>')));
        const mm = moments[idx];
        const extra = [];
        if (mm && mm.positional) extra.push(`<strong>A la posició:</strong> ${escapeHtml(mm.positional)}`);
        if (mm && mm.candidates) extra.push(`<strong>Línia:</strong> ${escapeHtml(mm.candidates)}`);
        if (extra.length) main.append($('<div class="coach-text human-plan-text"></div>').css('margin-top', '4px').html(extra.join('<br>')));
        card.append(main);
        appendHumanPlanPracticeButton(card, moments[idx]);
        list.append(card);
    });
}

function renderGameDebrief(targetEntry) {
    const box = $('#review-debrief');
    if (!box.length) return;
    box.hide();
    if (blunderMode) return;
    // El debrief de l'entrenador es genera LOCALMENT (sense OpenAI). Es mostra tant
    // a la revisió de la partida que s'acaba de jugar com en reobrir partides
    // antigues des de l'historial; per això acceptem una entrada concreta i ja no
    // limitem la visualització a les partides recents.
    const entry = targetEntry || gameHistory[gameHistory.length - 1];
    if (!entry) return;
    let facts = null;
    try { facts = buildDebriefFacts(entry); } catch (e) { console.warn('No s\'ha pogut generar el debrief', e); }
    if (!facts) return;

    const coachVoice = pickCoachVoiceForKey(entry.id);
    const localText = composeDebriefText(facts, entry.id, coachVoice, getReviewVoiceStyle());
    box.empty().show();
    box.append($('<div class="coach-kicker"></div>').append(
        $('<span></span>').text(`🎓 L'entrenador diu · ${coachVoice.name}`),
        $('<button class="coach-speak-btn" title="Escolta-ho en veu alta">🔊</button>')
    ));
    const textEl = $('<div class="coach-text"></div>').text(localText);
    box.append(textEl);
    box.find('.coach-speak-btn').on('click', () => speakCoachText(textEl.text()));
    updateCoachSpeakButtons();

    const openingNote = buildOpeningNote(entry);
    if (openingNote) box.append($('<div class="coach-text"></div>').css({ opacity: 0.85, 'margin-top': '6px' }).text(openingNote));

    const playerInsights = buildPlayerInsights(entry.id);
    const insightsNote = buildInsightsNote(playerInsights);
    if (insightsNote) box.append($('<div class="coach-text"></div>').css({ opacity: 0.85, 'margin-top': '6px' }).text(insightsNote));

    const humanPlanMoments = buildHumanPlanMoments(entry, playerInsights);
    let humanPlansPanel = null;
    if (humanPlanMoments.length) {
        humanPlansPanel = renderHumanPlanCards(box, humanPlanMoments, coachVoice);
    }

    if (!coachDebriefPending) {
        coachDebriefPending = true;
        requestOpenAICoachText(`debrief:${entry.id}`, buildDebriefOpenAIPrompt(facts), text => textEl.text(text), 1800, debriefAuditOptions(facts))
            .finally(() => { coachDebriefPending = false; });
    }
    if (humanPlansPanel && humanPlanMoments.length) {
        requestOpenAICoachText(
            `human-plans:${entry.id}:v1`,
            buildHumanPlansOpenAIPrompt(entry, humanPlanMoments),
            text => renderOpenAIHumanPlans(humanPlansPanel, text, humanPlanMoments),
            3000,
            humanPlansAuditOptions(entry, humanPlanMoments)
        );
    }
}

/* --------------------- Veu (TTS en català, opcional) --------------------- */

function initCoachVoice() {
    if (!('speechSynthesis' in window)) return;
    const pickVoice = () => {
        try {
            const voices = window.speechSynthesis.getVoices() || [];
            coachCatalanVoice = voices.find(v => /^ca([-_]|$)/i.test(v.lang || '')) || null;
        } catch (e) { coachCatalanVoice = null; }
        updateCoachSpeakButtons();
    };
    pickVoice();
    try { window.speechSynthesis.addEventListener('voiceschanged', pickVoice); } catch (e) {}
}

function isCoachTtsAvailable() {
    return ('speechSynthesis' in window) && !!coachCatalanVoice;
}

function updateCoachSpeakButtons() {
    $('.coach-speak-btn').toggle(isCoachTtsAvailable());
}

// TIER 4 — converteix la notació d'escacs a paraules perquè el TTS la llegeixi bé.
function speakableChessText(text) {
    if (!text) return text;
    const pieces = { K: 'rei', Q: 'dama', R: 'torre', B: 'alfil', N: 'cavall' };
    let t = String(text);
    t = t.replace(/\bO-O-O\b/g, 'enroc llarg').replace(/\bO-O\b/g, 'enroc curt');
    t = t.replace(/\b([KQRBN])([a-h]?[1-8]?)(x?)([a-h][1-8])(=[QRBN])?([+#]?)/g,
        (m, p, dis, cap, dest, promo, chk) => {
            let out = pieces[p];
            if (dis) out += ' ' + dis.split('').join(' ');
            if (cap) out += ' pren';
            out += ' ' + dest.split('').join(' ');
            if (promo) out += ' corona ' + (pieces[promo[1]] || '');
            if (chk === '+') out += ' escac'; else if (chk === '#') out += ' escac i mat';
            return out;
        });
    t = t.replace(/\b([a-h])x([a-h][1-8])(=[QRBN])?([+#]?)/g,
        (m, f, dest, promo, chk) => {
            let out = f + ' pren ' + dest.split('').join(' ');
            if (promo) out += ' corona ' + (pieces[promo[1]] || '');
            if (chk === '+') out += ' escac'; else if (chk === '#') out += ' escac i mat';
            return out;
        });
    return t;
}

function speakCoachText(text) {
    if (!isCoachTtsAvailable() || !text) return;
    try {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(speakableChessText(text));
        utterance.voice = coachCatalanVoice;
        utterance.lang = coachCatalanVoice.lang || 'ca-ES';
        utterance.rate = 0.95;
        window.speechSynthesis.speak(utterance);
    } catch (e) { console.warn('TTS no disponible', e); }
}

/* --------------------- Pla diari de l'entrenador --------------------- */

// Clau del dia (UTC, igual que getToday/missions): el pla canvia cada mitjanit UTC.
function getPlanDayKey() { return getToday(); }

// Dia anterior d'una clau de pla (les claus són dates UTC en format YYYY-MM-DD).
function previousPlanDayKey(day) {
    const t = Date.parse(`${day}T00:00:00Z`);
    return new Date(t - 86400000).toISOString().split('T')[0];
}

/* Ratxa del pla: dies seguits completant tots els passos. És el motor de la
   progressió: cada dia consecutiu completat apuja una mica el volum de l'endemà. */
const PLAN_STREAK_KEY = 'chess_planStreak';

function loadPlanStreak() {
    const s = readJsonStorage(PLAN_STREAK_KEY, null);
    if (!s || typeof s !== 'object') return { lastDay: null, streak: 0, total: 0 };
    return { lastDay: s.lastDay || null, streak: s.streak || 0, total: s.total || 0 };
}

function registerPlanCompleted(day) {
    const s = loadPlanStreak();
    if (s.lastDay === day) return s;
    s.streak = s.lastDay === previousPlanDayKey(day) ? s.streak + 1 : 1;
    s.lastDay = day;
    s.total += 1;
    writeJsonStorage(PLAN_STREAK_KEY, s);
    return s;
}

// Ratxa vigent per a un dia concret: val 0 si ni avui ni ahir es va completar el pla.
function currentPlanStreak(day) {
    const s = loadPlanStreak();
    if (s.lastDay === day || s.lastDay === previousPlanDayKey(day)) return s.streak;
    return 0;
}

/* Reptes que el pla pot proposar com a pas extra. Només s'ofereix el que l'app
   pot servir ara mateix: prometre un test de Tres camins sense prou preguntes,
   o un jeroglífic sense cap a la cua, seria un pas impossible de completar. */
function availablePlanChallenges() {
    const out = [];
    if (triaTestAvailableNow()) {
        out.push({
            type: 'tria_test', theme: null, metric: 'tria',
            title: 'Fes un test de Tres camins',
            why: 'Tria entre les tres millors jugades de posicions teves: és on es veu si reconeixes la bona sense poder moure peces.',
            target: 1, baseline: growthStats.triaTestsCompleted || 0
        });
    }
    if (hieroglyphicsAvailableNow()) {
        out.push({
            type: 'hieroglyphic', theme: null, metric: 'hiero',
            title: 'Resol 1 jeroglífic',
            why: 'Tres moviments seguits sense veure el rival: obliga a calcular fins al final en comptes de provar sort.',
            target: 1, baseline: (typeof hieroglyphicStats === 'object' && hieroglyphicStats ? hieroglyphicStats.solved : 0) || 0
        });
    }
    if (openingHieroglyphicsAvailableNow()) {
        out.push({
            type: 'opening_hieroglyphic', theme: 'opening', metric: 'opening_hiero',
            title: "Resol 1 jeroglífic d'obertura",
            why: 'Desxifrar la jugada teòrica del repertori fixa les obertures molt millor que llegir-ne la línia.',
            target: 1, baseline: growthStats.openingHieroCompleted || 0
        });
    }
    return out;
}

/* L'últim pas del pla: la partida on es posa a prova el que s'ha entrenat. Es
   sorteja entre les quatre modalitats amb el pes de la freqüència amb què val la
   pena fer-les (la partida normal mana; el rellotge, l'antídot i el joc vista hi
   entren de tant en tant). Durant el calibratge inicial només hi ha la normal,
   que és l'única modalitat desbloquejada. */
function pickPlanApplyItem(rng) {
    const base = {
        id: 'apply', kind: 'Posa-ho en pràctica', theme: null, target: 1
    };
    const normalGame = Object.assign({}, base, {
        type: 'free_game', metric: 'games',
        title: 'Juga 1 partida sencera',
        why: "L'entrenament només compta quan surt a la partida: juga amb calma i busca-hi el que has treballat avui.",
        baseline: totalGamesPlayed || 0
    });
    if (isCalibrationRequired()) return normalGame;

    const roll = rng();
    if (roll < 0.25) {
        const tcId = pickPlanTimeControlId(rng);
        return Object.assign({}, base, {
            type: 'timed_game', metric: 'timed_games', timeControlId: tcId,
            title: `Juga 1 partida amb rellotge (${getTimeControlLabel(tcId)})`,
            why: "Amb el rellotge en marxa les decisions es prenen d'una altra manera: aquí es veu de debò què tens automatitzat.",
            baseline: growthStats.timedGamesPlayed || 0
        });
    }
    if (roll < 0.45) {
        return Object.assign({}, base, {
            type: 'antidote_game', metric: 'antidote_games',
            title: 'Juga 1 partida contra el Rival Antídot',
            why: 'El rival buscarà justament les posicions que et costen: és la manera més directa de veure si el que has entrenat aguanta.',
            baseline: growthStats.antidoteGamesPlayed || 0
        });
    }
    if (roll < 0.60) {
        return Object.assign({}, base, {
            type: 'positional_game', metric: 'positional_games',
            title: 'Juga 1 partida de Joc vista',
            why: 'Amb la vista limitada et toca calcular abans de moure, que és exactament el que costa de mantenir en una partida normal.',
            baseline: growthStats.positionalGamesPlayed || 0
        });
    }
    return normalGame;
}

// Ritme de la partida amb rellotge del pla: el que el jugador ja tingui triat si
// n'hi ha cap, i si no, un dels ritmes mitjans (ni hyperbullet ni clàssic).
function pickPlanTimeControlId(rng) {
    if (pendingFreeTimeControl && pendingFreeTimeControl !== 'none') return pendingFreeTimeControl;
    const options = ['3+2', '5+0', '10+0'];
    return options[Math.floor((rng ? rng() : Math.random()) * options.length)] || PLAN_DEFAULT_TIME_CONTROL;
}

/* Ruta guiada del dia: passos ordenats de menys a més exigència, cadascun amb el
   seu perquè. L'estructura pedagògica és fixa (escalfament → repàs → focus →
   repte del dia → posar-ho en pràctica) i el contingut s'adapta a les dades del
   jugador:
   - el focus és el tema més fluix amb errors recents,
   - el repte del dia rota entre les modalitats disponibles (tres camins,
     jeroglífics, jeroglífics d'obertura),
   - el volum creix amb la ratxa de dies completant el pla (progressió),
   - els objectius es mesuren amb comptadors que ja existeixen (baseline al crear el pla). */
function buildWeeklyPlan() {
    loadThemeMastery();
    loadGrowthStats();
    const day = getPlanDayKey();
    const rng = mulberry32(hashStr(`plan:${day}`));
    const streak = currentPlanStreak(day);
    const level = Math.min(3, streak); // 0..3: apuja el volum a mesura que la ratxa creix

    const errorThemes = {};
    savedErrors.slice(-30).forEach(err => {
        const t = normalizeGrowthTheme(classifyPositionTheme(err.fen || '', err.playerMove || ''));
        errorThemes[t] = (errorThemes[t] || 0) + 1;
    });
    const themes = Object.keys(THEME_MASTERY_DEFAULTS).filter(t => t !== 'general');
    themes.sort((a, b) => (themeMastery[a] - themeMastery[b]) || ((errorThemes[b] || 0) - (errorThemes[a] || 0)));
    // El focus rota cada dia entre els temes més fluixos (prioritzant els que tenen errors recents)
    const withErrors = themes.filter(t => (errorThemes[t] || 0) > 0);
    const pool = (withErrors.length ? withErrors : themes).slice(0, 3);
    const focusTheme = pool[Math.floor(rng() * pool.length)] || themes[0];
    const focusMastery = Math.round((themeMastery[focusTheme] || 0) * 100);
    const focusErrors = errorThemes[focusTheme] || 0;
    const due = getDueErrors().length;

    const items = [];

    // Pas 1 — Escalfament: entrada fàcil que desperta la visió tàctica.
    const tacticsTarget = 2 + level + Math.floor(rng() * 2);
    items.push({
        id: 'warmup', kind: 'Escalfament', type: 'tactics', theme: null, metric: 'tactics',
        title: `Resol ${tacticsTarget} exercicis de tàctica`,
        why: "Comença pel més senzill: uns quants exercicis per despertar la vista abans de la feina de debò.",
        target: tacticsTarget, baseline: tacticsStats.solved || 0
    });

    // Pas 2 — Repàs: consolidar el que ja s'ha vist (repetició espaiada o obertura).
    if (due > 0) {
        const srsTarget = Math.min(due, 2 + (level >= 2 ? 1 : 0));
        items.push({
            id: 'review', kind: 'Repàs', type: 'srs_review', theme: null, metric: 'srs',
            title: srsTarget === 1 ? 'Corregeix 1 error pendent de repàs' : `Corregeix ${srsTarget} errors pendents de repàs`,
            why: `Tens ${due} ${due === 1 ? 'posició on vas fallar esperant-te' : 'posicions on vas fallar esperant-te'}: repassar-les just quan toca és com es fixa l'aprenentatge.`,
            target: srsTarget, baseline: growthStats.srsCompleted || 0
        });
    } else if (getOpeningPhaseErrors().length > 0) {
        const openTarget = 1 + Math.floor(rng() * 2);
        items.push({
            id: 'review', kind: 'Repàs', type: 'opening_drill', theme: 'opening', metric: 'opening_drill',
            title: openTarget === 1
                ? "Rectifica 1 errada d'obertura (2 jugades correctes)"
                : `Rectifica ${openTarget} errades d'obertura (2 jugades correctes)`,
            why: "Les 10 primeres jugades marquen tota la partida: rectificar el que va fallar evita repetir-ho.",
            target: openTarget, baseline: growthStats.openingDrillsCompleted || 0
        });
    }

    // Pas 3 — Focus del dia: treball dirigit al tema més fluix.
    if (savedErrors.length > 0) {
        items.push({
            id: 'focus', kind: 'Focus del dia', type: 'weakness_training', theme: focusTheme, metric: 'weakness',
            title: `Entrena ${getThemeLabel(focusTheme)} (1 sessió)`,
            why: focusErrors > 0
                ? `És el teu tema més fluix (${focusMastery}% de domini) i hi has fallat ${focusErrors} ${focusErrors === 1 ? 'cop' : 'cops'} fa poc: avui el fem pujar.`
                : `És el teu tema més fluix (${focusMastery}% de domini): una sessió dirigida és la manera més ràpida de fer-lo pujar.`,
            target: 1, baseline: growthStats.weaknessSessionsCompleted || 0
        });
    }

    // Pas 4 — Repte del dia: una modalitat diferent cada dia, de les que l'app
    // té a punt en aquest moment (si no n'hi ha cap de disponible, se salta).
    const challenges = availablePlanChallenges();
    if (challenges.length) {
        const challenge = challenges[Math.floor(rng() * challenges.length)];
        items.push(Object.assign({ id: 'challenge', kind: 'Repte del dia' }, challenge));
    }

    // Pas final — Posa-ho en pràctica: transferir l'entrenament a una partida
    // real. La manera de jugar-la rota entre les quatre modalitats, perquè cada
    // una entrena una cosa diferent (temps, punts febles, càlcul, joc normal).
    items.push(pickPlanApplyItem(rng));

    const finalItems = items.slice(0, 5);
    finalItems.forEach((item, i) => { item.step = i + 1; });

    return {
        day,
        createdAt: Date.now(),
        version: WEEKLY_PLAN_VERSION,
        focusTheme,
        focusMastery,
        srsAtStart: due,
        streakAtStart: streak,
        completedAt: null,
        openaiSummary: null,
        summaryVersion: PLAN_SUMMARY_REFRESH_VERSION,
        items: finalItems
    };
}

function weeklyPlanItemProgress(item) {
    let current = 0;
    if (item.metric === 'weakness') current = (growthStats.weaknessSessionsCompleted || 0) - item.baseline;
    else if (item.metric === 'srs') current = (growthStats.srsCompleted || 0) - item.baseline;
    else if (item.metric === 'tactics') current = (tacticsStats.solved || 0) - item.baseline;
    else if (item.metric === 'games') current = (totalGamesPlayed || 0) - item.baseline;
    else if (item.metric === 'opening_drill') current = (growthStats.openingDrillsCompleted || 0) - item.baseline;
    else if (item.metric === 'mate_drill') current = (growthStats.mateDrillsCompleted || 0) - item.baseline;
    else if (item.metric === 'tria') current = (growthStats.triaTestsCompleted || 0) - item.baseline;
    else if (item.metric === 'opening_hiero') current = (growthStats.openingHieroCompleted || 0) - item.baseline;
    else if (item.metric === 'timed_games') current = (growthStats.timedGamesPlayed || 0) - item.baseline;
    else if (item.metric === 'antidote_games') current = (growthStats.antidoteGamesPlayed || 0) - item.baseline;
    else if (item.metric === 'positional_games') current = (growthStats.positionalGamesPlayed || 0) - item.baseline;
    else if (item.metric === 'hiero') current = ((typeof hieroglyphicStats === 'object' && hieroglyphicStats ? hieroglyphicStats.solved : 0) || 0) - item.baseline;
    return Math.max(0, Math.min(item.target, current));
}

const COACH_PLAN_TEMPLATES = [
    "He mirat les teves últimes partides i el que més et frena és {tema} (domini del {pct}%). Avui t'he preparat una ruta de {passos} passos, del més senzill al més exigent: escalfa, corregeix i acaba posant-ho a prova en una partida.",
    "Pla d'avui en {passos} passos, per ordre: cada pas prepara el següent, així que no cal fer-ho tot alhora. El fil conductor és {tema} (domini del {pct}%), i cada pas completat el fa una mica més teu.",
    "Avui treballem {tema}, el teu punt més fluix ({pct}% de domini). Segueix la ruta de {passos} passos en ordre: comença suau amb l'escalfament i acaba aplicant-ho tot en una partida de veritat."
];

function composeWeeklyPlanText(plan) {
    const rng = mulberry32(hashStr(`plan:${plan.day}`));
    const tpl = COACH_PLAN_TEMPLATES[Math.floor(rng() * COACH_PLAN_TEMPLATES.length)];
    return fillCoachTemplate(tpl, {
        tema: getThemeLabel(plan.focusTheme),
        pct: plan.focusMastery,
        passos: plan.items.length
    });
}

function buildWeeklyPlanOpenAIPrompt(plan) {
    return `Ets un entrenador d'escacs proper que parla en català i tuteja l'alumne.
Escriu 2 o 3 frases (màxim 55 paraules en total) presentant la ruta d'entrenament d'avui, NOMÉS amb aquests fets:
${JSON.stringify({
        tema_a_reforcar: getThemeLabel(plan.focusTheme),
        domini_del_tema_percent: plan.focusMastery,
        repassos_pendents: plan.srsAtStart,
        dies_seguits_completant_el_pla: plan.streakAtStart || 0,
        passos_en_ordre: plan.items.map(i => `${i.step}. ${i.kind}: ${i.title}`)
    }, null, 2)}
Explica que els passos van del més senzill al més exigent i que convé seguir-los en ordre.
Sense llistes, sense markdown, sense emojis. To motivador però concret.${coachStyleRulesBlock()}`;
}

// Opcions d'auditoria del resum del pla diari: només les xifres del pla
// (domini del tema, repassos, ratxa i numeració dels passos).
function weeklyPlanAuditOptions(plan) {
    const xifres = [];
    if (typeof plan.focusMastery === 'number') xifres.push(plan.focusMastery);
    if (typeof plan.srsAtStart === 'number') xifres.push(plan.srsAtStart);
    xifres.push(plan.streakAtStart || 0);
    (plan.items || []).forEach(i => { if (typeof i.step === 'number') xifres.push(i.step); });
    xifres.push((plan.items || []).length);
    return {
        xifresPermeses: xifres,
        percentatges: typeof plan.focusMastery === 'number' ? [plan.focusMastery] : [],
        maxParaules: 70
    };
}

function ensureWeeklyPlan() {
    const day = getPlanDayKey();
    const stored = readJsonStorage(WEEKLY_PLAN_KEY, null);
    if (stored && stored.day === day && stored.version === WEEKLY_PLAN_VERSION && Array.isArray(stored.items) && stored.items.length) {
        weeklyPlan = stored;
        if ((weeklyPlan.summaryVersion || 0) < PLAN_SUMMARY_REFRESH_VERSION) {
            weeklyPlan.openaiSummary = null;
            weeklyPlan.summaryVersion = PLAN_SUMMARY_REFRESH_VERSION;
            writeJsonStorage(WEEKLY_PLAN_KEY, weeklyPlan);
        }
    } else {
        weeklyPlan = buildWeeklyPlan();
        writeJsonStorage(WEEKLY_PLAN_KEY, weeklyPlan);
    }
    renderWeeklyPlan();
}

/* Rellotge de compte enrere fins al pla de demà (canvia a mitjanit UTC, com getToday).
   Quan arriba a 0, el pla es regenera automàticament. */
let planCountdownTimer = null;

function startPlanCountdown() {
    if (planCountdownTimer) return;
    updatePlanCountdown();
    planCountdownTimer = setInterval(updatePlanCountdown, 1000);
}

function updatePlanCountdown() {
    const el = document.getElementById('plan-countdown');
    if (!el) return;
    const now = new Date();
    const nextChange = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1);
    const ms = Math.max(0, nextChange - now.getTime());
    const h = Math.floor(ms / 3600000);
    const m = Math.floor(ms / 60000) % 60;
    const s = Math.floor(ms / 1000) % 60;
    el.textContent = `⏳ ${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    if (weeklyPlan && weeklyPlan.day !== getPlanDayKey()) ensureWeeklyPlan();
}

// Prou marge perquè es llegeixi la primera frase sencera abans del [Continuar llegint].
const PLAN_SUMMARY_COLLAPSE_CHARS = 120;

function getCollapsedPlanSummary(text) {
    if (text.length <= PLAN_SUMMARY_COLLAPSE_CHARS) return text;
    return `${text.slice(0, PLAN_SUMMARY_COLLAPSE_CHARS).trimEnd()}…`;
}

function renderPlanSummaryText() {
    const el = document.getElementById('weekly-plan-summary');
    const btn = document.getElementById('btn-plan-summary-toggle');
    if (!el || !btn) return;

    const fullText = el.dataset.fullText || '';
    const shouldCollapse = fullText.length > PLAN_SUMMARY_COLLAPSE_CHARS;
    const expanded = el.dataset.expanded === 'true';
    const visibleText = shouldCollapse && !expanded ? getCollapsedPlanSummary(fullText) : fullText;

    el.classList.toggle('expanded', expanded || !shouldCollapse);
    el.textContent = visibleText;
    btn.style.display = shouldCollapse ? 'inline-block' : 'none';
    btn.textContent = expanded ? "▲ Mostra'n menys" : '[Continuar llegint]';
    btn.setAttribute('aria-expanded', expanded ? 'true' : 'false');
    btn.setAttribute('aria-label', expanded ? 'Mostra menys text del pla de l\'entrenador' : 'Continua llegint el pla complet de l\'entrenador');
}

function setPlanSummaryText(text) {
    const el = document.getElementById('weekly-plan-summary');
    if (!el) return;
    const nextText = text || '';
    const previousFullText = el.dataset.fullText || '';
    const wasExpanded = el.dataset.expanded === 'true';
    el.dataset.fullText = nextText;
    // No pleguem de nou el resum cada vegada que es refresca la pantalla: si el
    // text és el mateix, respectem que l'usuari ja havia premut [Continuar llegint].
    el.dataset.expanded = previousFullText === nextText && wasExpanded ? 'true' : 'false';
    renderPlanSummaryText();
}

/* El resum del pla només mostra els primers 40 caràcters quan és llarg.
   El botó [Continuar llegint] desplega el text sencer sense scroll intern. */
function updatePlanSummaryToggle() {
    const el = document.getElementById('weekly-plan-summary');
    const btn = document.getElementById('btn-plan-summary-toggle');
    if (!el || !btn) return;
    if (!btn.dataset.bound) {
        btn.dataset.bound = '1';
        btn.addEventListener('click', event => {
            event.preventDefault();
            el.dataset.expanded = el.dataset.expanded === 'true' ? 'false' : 'true';
            renderPlanSummaryText();
        });
    }
    renderPlanSummaryText();
}

// Identitat visual de cada pas del pla: color, icona i etiqueta curta. La clau
// és el `type` de la tasca, de manera que un pas nou només ha d'aparèixer aquí.
const PLAN_ITEM_LOOKS = {
    tactics: { tone: 'tactics', icon: '⚡' },
    srs_review: { tone: 'srs', icon: '🔁' },
    opening_drill: { tone: 'opening', icon: '📖' },
    mate_drill: { tone: 'mate', icon: '♚' },
    weakness_training: { tone: 'focus', icon: '🎯' },
    tria_test: { tone: 'tria', icon: '🔀' },
    hieroglyphic: { tone: 'hiero', icon: '🧩' },
    opening_hieroglyphic: { tone: 'opening', icon: '📜' },
    timed_game: { tone: 'clock', icon: '⏱️' },
    antidote_game: { tone: 'antidote', icon: '🧬' },
    positional_game: { tone: 'positional', icon: '🔭' },
    free_game: { tone: 'game', icon: '♟️' }
};

function launchWeeklyPlanItem(item) {
    try {
        if (item.type === 'opening_drill') return startOpeningErrorDrill();
        if (item.type === 'mate_drill') return void startMateDrill();
        if (item.type === 'tria_test') return openTriaTest();
        if (item.type === 'hieroglyphic') return void openHieroglyphicsFromBanner();
        if (item.type === 'opening_hieroglyphic') return openOpeningHieroglyphicFromHome();
        if (item.type === 'timed_game') return startTimedGameFromPlan(item.timeControlId);
        if (item.type === 'antidote_game') return openAntidoteIntro();
        if (item.type === 'positional_game') return startPositionalGameFromPlan();
        if (item.type === 'free_game') {
            if (typeof novaPartida === 'function') return novaPartida();
        }
        // Reutilitzem el flux de tasques de creixement: fixa currentGrowthTask i
        // així el comptador de sessions completades també compta per al pla.
        return executeGrowthTask({ type: item.type, theme: item.theme || 'general', source: 'weekly_plan' });
    } catch (e) {
        console.warn('No s\'ha pogut iniciar la tasca del pla diari', e);
        showToast('No he pogut iniciar aquesta tasca ara mateix.', 'warn');
    }
}

// Fins on s'ha desplegat la ruta la darrera vegada que es va pintar, per animar
// només el pas que acaba d'aparèixer.
let planRevealState = { day: null, index: -1 };

function renderWeeklyPlan() {
    const panel = $('#weekly-plan-panel');
    if (!panel.length || !weeklyPlan) return;
    panel.show();
    startPlanCountdown();
    const summary = weeklyPlan.openaiSummary || weeklyPlan.geminiSummary || composeWeeklyPlanText(weeklyPlan);
    setPlanSummaryText(summary);
    updatePlanSummaryToggle();

    const items = weeklyPlan.items;
    const progressById = {};
    let doneCount = 0;
    items.forEach(item => {
        const p = weeklyPlanItemProgress(item);
        progressById[item.id] = p;
        if (p >= item.target) doneCount++;
    });
    const allDone = doneCount >= items.length;

    // La ratxa es registra un sol cop, el moment en què el pla del dia queda complet.
    if (allDone && !weeklyPlan.completedAt) {
        weeklyPlan.completedAt = Date.now();
        registerPlanCompleted(weeklyPlan.day);
        writeJsonStorage(WEEKLY_PLAN_KEY, weeklyPlan);
        showToast("🏆 Pla d'avui completat!", 'success');
    }

    const streak = currentPlanStreak(weeklyPlan.day);
    const streakEl = document.getElementById('plan-streak');
    if (streakEl) {
        streakEl.style.display = streak >= 2 ? '' : 'none';
        streakEl.textContent = `🔥 ${streak} dies`;
    }

    const globalFill = document.querySelector('#weekly-plan-progress .coach-plan-progress-fill');
    const globalLabel = document.querySelector('#weekly-plan-progress .coach-plan-progress-label');
    if (globalFill) globalFill.style.width = `${Math.round((doneCount / items.length) * 100)}%`;
    if (globalLabel) globalLabel.textContent = `${doneCount}/${items.length} passos`;

    // La ruta es va desplegant: es veuen els passos fets i el que toca ara, i el
    // següent apareix quan aquest queda enllestit. Així la pantalla ensenya una
    // sola cosa a fer en comptes de cinc, i el pla creix a mesura que avança.
    const firstPending = items.findIndex(item => progressById[item.id] < item.target);
    const revealIndex = firstPending === -1 ? items.length - 1 : firstPending;
    // Un pas «acabat d'aparèixer» s'anima; en tornar a pintar la mateixa
    // pantalla, no (si no, l'animació saltaria a cada refresc del rellotge).
    const justRevealed = planRevealState.day === weeklyPlan.day
        && planRevealState.index >= 0 && planRevealState.index < revealIndex;
    planRevealState = { day: weeklyPlan.day, index: revealIndex };

    const list = $('#weekly-plan-list').empty();
    items.forEach((item, idx) => {
        if (idx > revealIndex) return;   // encara no toca: apareixerà al seu torn
        const progress = progressById[item.id];
        const done = progress >= item.target;
        const pct = Math.round((progress / item.target) * 100);
        const look = PLAN_ITEM_LOOKS[item.type] || { tone: 'focus', icon: '•' };
        const actionable = !done;
        const row = $(`
            <div class="coach-item tone-${look.tone}${done ? ' done' : ''}${actionable ? ' is-actionable' : ''}${(actionable && justRevealed) ? ' is-revealing' : ''}"
                 ${actionable ? 'role="button" tabindex="0"' : ''}>
                <div class="coach-step-badge">${done ? '✓' : item.step || idx + 1}</div>
                <div class="coach-item-main">
                    <div class="coach-item-kind"><span class="coach-item-ic" aria-hidden="true">${look.icon}</span><span class="coach-item-kind-text"></span></div>
                    <div class="coach-item-title"></div>
                    <div class="coach-item-why"></div>
                    <div class="coach-item-progress">
                        <div class="coach-item-bar"><div class="coach-item-fill" style="width:${pct}%"></div></div>
                        <span class="coach-item-count">${progress}/${item.target}</span>
                    </div>
                </div>
                <button class="btn coach-item-go">${done ? '✓ Fet' : 'Comença ›'}</button>
            </div>`);
        row.find('.coach-item-kind-text').text(item.kind || '');
        row.find('.coach-item-title').text(item.title);
        const whyEl = row.find('.coach-item-why');
        if (item.why && !done) whyEl.text(item.why); else whyEl.hide();
        const goBtn = row.find('.coach-item-go');
        if (!actionable) {
            goBtn.prop('disabled', true);
        } else {
            // Tota la fila hi porta, no només el botó.
            const go = () => launchWeeklyPlanItem(item);
            row.attr('title', `Ves-hi: ${item.title}`);
            row.on('click', go);
            row.on('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); }
            });
            goBtn.on('click', (e) => { e.stopPropagation(); go(); });
        }
        list.append(row);
    });

    // Els passos que encara no toquen no es pinten: només se'n diu quants en
    // queden, perquè se sàpiga que la ruta continua.
    const pending = items.length - (revealIndex + 1);
    if (pending > 0) {
        list.append($('<div class="coach-plan-next"></div>').text(pending === 1
            ? "Encara queda 1 pas més: apareixerà quan acabis aquest."
            : `Encara queden ${pending} passos més: cadascun apareix quan acabes l'anterior.`));
    }

    const doneBanner = document.getElementById('weekly-plan-done');
    if (doneBanner) {
        doneBanner.style.display = allDone ? '' : 'none';
        if (allDone) {
            doneBanner.textContent = streak >= 2
                ? `🏆 Pla d'avui completat — ${streak} dies seguits! Demà el llistó pujarà una mica.`
                : "🏆 Pla d'avui completat! Torna demà: cada dia seguit fa créixer la ratxa i el repte.";
        }
    }

    // Poliment OpenAI un sol cop per dia (es persisteix dins del pla).
    if (!weeklyPlan.openaiSummary && openaiApiKey && !coachPlanOpenAIPending) {
        coachPlanOpenAIPending = true;
        requestOpenAICoachText(`dailyplan:${weeklyPlan.day}`, buildWeeklyPlanOpenAIPrompt(weeklyPlan), text => {
            weeklyPlan.openaiSummary = text;
            writeJsonStorage(WEEKLY_PLAN_KEY, weeklyPlan);
            setPlanSummaryText(text);
            updatePlanSummaryToggle();
        }, 1800, weeklyPlanAuditOptions(weeklyPlan)).finally(() => { coachPlanOpenAIPending = false; });
    }
}

/* ===================== MOTIUS TÀCTICS I NOUS EXERCICIS DEL PLA =====================
   1) analyzeTacticalMotive: tradueix la línia de Stockfish (jugada + PV) a un motiu
      tàctic concret (mat, forquilla, clavada, raig X, peça sense defensa, canvi
      guanyador, atac al rei) de manera determinista amb chess.js.
   2) Exercicis d'obertura: errades reals de les teves 10 primeres jugades, amb el
      flux de 2 jugades correctes i el bàner de context.
   3) Mats en 3: posicions de final verificades pel motor (s'accepten només si el
      mat arriba exactament a la 3a jugada del jugador). */

const MOTIVE_PIECE_NAMES = { p: 'el peó', n: 'el cavall', b: "l'alfil", r: 'la torre', q: 'la dama', k: 'el rei' };
const MOTIVE_PIECE_VALUES = { p: 1, n: 3, b: 3, r: 5, q: 9, k: 99 };

// Contracció "de + article" en català: "de el cavall" → "del cavall"
function deCasella(sq) {
    return (sq && (sq[0] === 'a' || sq[0] === 'e')) ? `d'${sq}` : `de ${sq}`;
}

function deNom(name) {
    if (!name) return "de la peça";
    if (name.startsWith('el ')) return 'del ' + name.slice(3);
    if (name.startsWith("l'")) return "de l'" + name.slice(2);
    return 'de ' + name;
}

function pvMatePlies(fen, pv) {
    try {
        const g = new Chess(fen);
        for (let i = 0; i < pv.length; i++) {
            const u = pv[i];
            const mv = g.move({ from: u.slice(0, 2), to: u.slice(2, 4), promotion: u.length > 4 ? u[4] : undefined });
            if (!mv) return 0;
            if (g.in_checkmate()) return i + 1;
        }
    } catch (e) {}
    return 0;
}

function findPinOrSkewer(gAfter, square, piece, color) {
    const dirsDiag = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
    const dirsOrto = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const dirs = piece === 'b' ? dirsDiag : (piece === 'r' ? dirsOrto : dirsDiag.concat(dirsOrto));
    const file = square.charCodeAt(0) - 97;
    const rank = parseInt(square[1], 10) - 1;
    for (const [df, dr] of dirs) {
        let f = file + df, r = rank + dr;
        let first = null;
        while (f >= 0 && f < 8 && r >= 0 && r < 8) {
            const sq = String.fromCharCode(97 + f) + (r + 1);
            const p = gAfter.get(sq);
            if (p) {
                if (p.color === color) break;
                if (!first) {
                    if (p.type === 'k') break; // escac directe, no és clavada
                    first = { piece: p, sq };
                } else {
                    if (p.type === 'k') {
                        return { theme: 'pin', text: `una clavada sobre ${MOTIVE_PIECE_NAMES[first.piece.type]} ${deCasella(first.sq)} contra el rei` };
                    }
                    if (MOTIVE_PIECE_VALUES[p.type] > MOTIVE_PIECE_VALUES[first.piece.type]) {
                        return { theme: 'pin', text: `una clavada sobre ${MOTIVE_PIECE_NAMES[first.piece.type]} ${deCasella(first.sq)} davant ${deNom(MOTIVE_PIECE_NAMES[p.type])}` };
                    }
                    if (MOTIVE_PIECE_VALUES[first.piece.type] > MOTIVE_PIECE_VALUES[p.type]) {
                        return { theme: 'skewer', text: `un raig X que travessava ${MOTIVE_PIECE_NAMES[first.piece.type]} ${deCasella(first.sq)}` };
                    }
                    break;
                }
            }
            f += df; r += dr;
        }
    }
    return null;
}

// Retorna { theme, text } amb el motiu tàctic que la millor jugada aprofitava, o null.
function analyzeTacticalMotive(fen, bestMove, bestMovePv = []) {
    if (!fen || !bestMove || String(bestMove).length < 4) return null;
    let g, mv;
    try {
        g = new Chess(fen);
        mv = g.move({ from: bestMove.slice(0, 2), to: bestMove.slice(2, 4), promotion: bestMove.length > 4 ? bestMove[4] : 'q' });
    } catch (e) { return null; }
    if (!mv) return null;

    // 1) Mat immediat o mat forçat dins la línia del motor
    if (g.in_checkmate()) return { theme: 'king_attack', text: 'hi havia escac i mat immediat' };
    const pv = Array.isArray(bestMovePv) ? bestMovePv : [];
    const matePlies = pvMatePlies(fen, pv);
    if (matePlies > 0) {
        const mateMoves = Math.ceil(matePlies / 2);
        return { theme: 'king_attack', text: `hi havia un mat forçat en ${mateMoves} jugad${mateMoves === 1 ? 'a' : 'es'}` };
    }

    const gaveCheck = !!(mv.san && mv.san.includes('+'));

    // 2) Forquilla: des de la nova casella, la peça ataca 2+ peces valuoses
    if (!gaveCheck && mv.piece !== 'k') {
        try {
            const parts = g.fen().split(' ');
            parts[1] = mv.color; parts[3] = '-';
            const g2 = new Chess(parts.join(' '));
            const targets = (g2.moves({ square: mv.to, verbose: true }) || [])
                .filter(m => m.captured && MOTIVE_PIECE_VALUES[m.captured] >= 3);
            if (targets.length >= 2) {
                const names = targets.slice(0, 2).map(m => MOTIVE_PIECE_NAMES[m.captured] || 'una peça');
                return { theme: 'fork', text: `una forquilla ${deNom(MOTIVE_PIECE_NAMES[mv.piece])} a ${mv.to} sobre ${names.join(' i ')}` };
            }
        } catch (e) {}
    }

    // 3) Clavada o raig X amb peces de línia
    if (['b', 'r', 'q'].includes(mv.piece)) {
        const ray = findPinOrSkewer(g, mv.to, mv.piece, mv.color);
        if (ray) return ray;
    }

    // 4) Captures: peça sense defensa o canvi guanyador
    if (mv.captured) {
        const capturedName = MOTIVE_PIECE_NAMES[mv.captured] || 'una peça';
        const reply = pv.length > 1 ? pv[1] : null;
        const recaptures = !!(reply && reply.slice(2, 4) === mv.to);
        if (!recaptures) return { theme: 'material', text: `podies capturar ${capturedName} ${deCasella(mv.to)}, que estava sense defensa` };
        if (MOTIVE_PIECE_VALUES[mv.captured] > MOTIVE_PIECE_VALUES[mv.piece]) {
            return { theme: 'material', text: `un canvi guanyador: ${capturedName} a canvi ${deNom(MOTIVE_PIECE_NAMES[mv.piece])}` };
        }
        return { theme: 'material', text: `una combinació de captures a ${mv.to} que guanyava material` };
    }

    // 5) Atac persistent al rei: dos o més escacs dins la línia
    if (gaveCheck && pv.length) {
        let checks = 0;
        try {
            const gc = new Chess(fen);
            for (const u of pv) {
                const m2 = gc.move({ from: u.slice(0, 2), to: u.slice(2, 4), promotion: u.length > 4 ? u[4] : undefined });
                if (!m2) break;
                if (m2.san.includes('+') || m2.san.includes('#')) checks++;
            }
        } catch (e) {}
        if (checks >= 2) return { theme: 'king_attack', text: 'un atac directe al rei amb escacs seguits' };
    }
    return null;
}

/* --------------------- Tema tàctic de l'exercici --------------------- */
// Orienta sense revelar: diu QUIN tipus de cop cal buscar, mai les caselles.
const TACTIC_THEME_HINTS = {
    fork: { label: 'Forquilla', tip: 'Busca una jugada que ataqui dues peces alhora.' },
    pin: { label: 'Clavada', tip: 'Busca una peça rival que no es pugui moure sense exposar-ne una de més valuosa.' },
    skewer: { label: 'Raig X', tip: "Obliga una peça valuosa a apartar-se per guanyar la que té al darrere." },
    king_attack: { label: 'Atac al rei', tip: 'El rei rival és el blanc: pensa en escacs i amenaces de mat.' },
    material: { label: 'Guany de material', tip: 'Hi ha material per guanyar: revisa captures i peces sense defensa.' },
    calc: { label: 'Combinació', tip: 'Calcula amb ordre: revisa escacs, captures i amenaces abans de decidir.' }
};

// Deriva el tema de l'exercici. Si la primera jugada no té motiu clar (pot ser
// preparatòria), busca'l a les jugades del jugador més endins de la línia; si
// tampoc, dedueix-lo del conjunt de la línia. Mai retorna null.
function deriveTacticTheme(fen, step1) {
    const pv = (step1 && step1.playerMovePv) || [];
    try {
        const direct = analyzeTacticalMotive(fen, step1.playerMove, pv);
        if (direct && TACTIC_THEME_HINTS[direct.theme]) return direct.theme;
    } catch (e) {}
    // Motiu a les jugades següents del jugador dins la PV (índexs parells)
    try {
        const g = new Chess(fen);
        for (let i = 0; i < pv.length && i < 6; i++) {
            if (i > 0 && i % 2 === 0) {
                const m = analyzeTacticalMotive(g.fen(), pv[i], pv.slice(i));
                if (m && TACTIC_THEME_HINTS[m.theme]) return m.theme;
            }
            const u = pv[i];
            if (!g.move({ from: u.slice(0, 2), to: u.slice(2, 4), promotion: u.length > 4 ? u[4] : undefined })) break;
        }
    } catch (e) {}
    // Heurística agregada: escacs del jugador → atac al rei; captures → material
    try {
        const g = new Chess(fen);
        let checks = 0, captures = 0;
        for (let i = 0; i < pv.length && i < 8; i++) {
            const u = pv[i];
            const mv = g.move({ from: u.slice(0, 2), to: u.slice(2, 4), promotion: u.length > 4 ? u[4] : undefined });
            if (!mv) break;
            if (i % 2 === 0) {
                if (mv.san.includes('+') || mv.san.includes('#')) checks++;
                if (mv.captured) captures++;
            }
        }
        if (checks >= 1) return 'king_attack';
        if (captures >= 1) return 'material';
    } catch (e) {}
    return 'calc';
}

// Mostra el tipus de tema tàctic en exercicis sense context d'error propi
// (tàctiques del banc, repte diari). Es crida a startGame, després del bàner d'error.
function renderTacticThemeHint() {
    const banner = $('#tactic-theme-banner');
    if (!banner.length) return;
    banner.hide();
    if (!blunderMode || !bundleFixedSequence) return;
    // El jeroglífic té el seu propi panell (comentari + historial); no mostrem el tema.
    if (currentBundleSource === 'bestline') return;
    // Si ja hi ha bàner d'error propi, aquell ja explica el motiu; no dupliquem.
    if (currentErrorContext) return;
    // Al mat en 3, el títol ja anuncia l'objectiu.
    if (currentBundleSource === 'mate_drill') return;
    const step1 = bundleFixedSequence.step1 || {};
    let theme = 'calc';
    try { theme = deriveTacticTheme(bundleFixedSequence.initialFen, step1); } catch (e) {}
    const hint = TACTIC_THEME_HINTS[theme] || TACTIC_THEME_HINTS.calc;
    const textEl = $('#tactic-theme-text').empty();
    textEl.append($('<span></span>').text('🎯 Tema: '));
    textEl.append($('<strong></strong>').text(hint.label));
    textEl.append($('<span></span>').text(` · ${hint.tip}`));
    banner.show();
}

/* --------------------- Exercicis d'errors d'obertura --------------------- */

function getOpeningPhaseErrors() {
    return savedErrors.filter(e => {
        const fm = parseInt((e.fen || '').split(' ')[5]) || 99;
        return fm <= 10 && e.playerMove;
    });
}

function startOpeningErrorDrill() {
    if (!guardCalibrationAccess()) return;
    const pool = getOpeningPhaseErrors();
    if (!pool.length) {
        showToast("No tens errades d'obertura guardades. Juga partides i tornaran a aparèixer aquí.", 'warn');
        return;
    }
    const choice = pickPreferPrepared(pool, e => e.fen);
    isSrsReviewSession = false;
    isDailyPuzzleSession = false;
    isRandomBundleSession = false;
    isMatchErrorReviewSession = false;
    isTacticsSession = false;
    matchErrorQueue = [];
    currentMatchError = null;
    currentBundleSource = 'opening_drill';
    currentBundleSeverity = null;
    $('#bundle-modal').remove();
    currentGameMode = 'bundle';
    currentOpponent = null;
    startGame(true, choice.fen);
}

/* --------------------- Mats en 3 jugades (finals) --------------------- */

// Candidats KQ/KR contra rei sol; el motor només accepta els que són mat EXACTE en 3.
const MATE_DRILL_BANK = [
    '6k1/8/6K1/8/8/8/8/4Q3 w - - 0 1',
    '7k/8/5K2/8/8/8/8/6Q1 w - - 0 1',
    '5k2/8/4K3/8/8/8/8/Q7 w - - 0 1',
    '6k1/8/5K2/8/8/8/8/3Q4 w - - 0 1',
    '1k6/8/2K5/8/8/8/8/5Q2 w - - 0 1',
    'k7/8/2K5/8/8/8/8/6Q1 w - - 0 1',
    '6k1/8/8/6K1/8/8/8/4Q3 w - - 0 1',
    '5k2/8/8/4K3/8/8/8/7Q w - - 0 1',
    '7k/8/5K2/8/8/8/8/6R1 w - - 0 1',
    '4k3/8/3K4/8/8/8/8/7Q w - - 0 1',
    '8/7Q/8/8/8/4K3/8/3k4 w - - 0 1',
    '2k5/8/3K4/8/8/8/8/7Q w - - 0 1'
];

let pendingPreparedSequence = null;
let mateDrillPreparing = false;
let lastMateDrillFen = null;

function buildMateSequenceObject(fen, steps, replies, sans) {
    const emptyThreats = { threats: [], themes: [], immediateThreats: [] };
    const decorate = s => Object.assign({ alternatives: [], position: null, threats: emptyThreats }, s);
    return {
        initialFen: fen,
        step1: decorate(steps[0]),
        opponentMove: { move: replies[0].move, moveSan: replies[0].san },
        step2: decorate(steps[1]),
        opponentMove2: { move: replies[1].move, moveSan: replies[1].san },
        step3: decorate(steps[2]),
        totalSteps: 3,
        fullSequence: [steps[0].playerMove, replies[0].move, steps[1].playerMove, replies[1].move, steps[2].playerMove],
        fullSequenceSan: sans
    };
}

// Construeix i VERIFICA una seqüència de mat en 3: segueix la línia del motor i
// només retorna la seqüència si l'escac i mat arriba a la 3a jugada del jugador.
async function prepareMateSequence(fen) {
    if (!stockfish) { ensureStockfish(); await new Promise(r => setTimeout(r, 500)); }
    if (!stockfish) return null;
    let waitCount = 0;
    while (!stockfishReady && waitCount < 20) { await new Promise(r => setTimeout(r, 100)); waitCount++; }
    if (!stockfishReady) return null;
    try {
        stockfish.postMessage('stop');
        stockfish.postMessage('setoption name MultiPV value 1');
        await new Promise(r => setTimeout(r, 200));

        const steps = [], replies = [], sans = [];
        let curFen = fen;
        for (let i = 0; i < 3; i++) {
            const analysis = await analyzeFenRobust(curFen, 14, 1, 6000);
            const pm = analysis?.bestMove?.move;
            if (!pm) return null;
            const g = new Chess(curFen);
            const mv = g.move({ from: pm.slice(0, 2), to: pm.slice(2, 4), promotion: pm.length > 4 ? pm[4] : undefined });
            if (!mv) return null;
            steps.push({ fen: curFen, playerMove: pm, playerMoveSan: mv.san });
            sans.push(mv.san);
            if (g.in_checkmate()) return i === 2 ? buildMateSequenceObject(fen, steps, replies, sans) : null;
            if (i === 2 || g.game_over()) return null; // 3 jugades sense mat, o ofegat
            await new Promise(r => setTimeout(r, 250));
            const replyAnalysis = await analyzeFenRobust(g.fen(), 14, 1, 6000);
            const rm = replyAnalysis?.bestMove?.move;
            if (!rm) return null;
            const rmv = g.move({ from: rm.slice(0, 2), to: rm.slice(2, 4), promotion: rm.length > 4 ? rm[4] : undefined });
            if (!rmv || g.game_over()) return null;
            replies.push({ move: rm, san: rmv.san });
            sans.push(rmv.san);
            curFen = g.fen();
            await new Promise(r => setTimeout(r, 250));
        }
        return null;
    } catch (e) {
        console.warn('[MateDrill] Error preparant seqüència', e);
        return null;
    }
}

async function startMateDrill() {
    if (!guardCalibrationAccess() || mateDrillPreparing) return;
    mateDrillPreparing = true;
    showToast('Preparant un mat en 3 jugades... ⏳', 'info');
    try {
        const candidates = MATE_DRILL_BANK.slice();
        for (let i = candidates.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [candidates[i], candidates[j]] = [candidates[j], candidates[i]];
        }
        let seq = null;
        let tried = 0;
        for (const candidate of candidates) {
            if (candidate === lastMateDrillFen && candidates.length > 1) continue;
            if (tried >= 5) break;
            tried++;
            seq = await prepareMateSequence(candidate);
            if (seq) break;
        }
        if (!seq) {
            showToast('No he pogut preparar cap mat ara mateix. Torna-ho a provar.', 'warn');
            return;
        }
        lastMateDrillFen = seq.initialFen;
        isSrsReviewSession = false;
        isDailyPuzzleSession = false;
        isRandomBundleSession = false;
        isMatchErrorReviewSession = false;
        isTacticsSession = false;
        matchErrorQueue = [];
        currentMatchError = null;
        currentBundleSource = 'mate_drill';
        currentBundleSeverity = null;
        $('#bundle-modal').remove();
        currentGameMode = 'bundle';
        currentOpponent = null;
        pendingPreparedSequence = seq;
        startGame(true, seq.initialFen);
    } finally {
        mateDrillPreparing = false;
    }
}

// Mat o taules dins d'un exercici: el mat és èxit; l'ofegat és error i es reintenta.
function handleBundleGameOver() {
    if (game.in_checkmate()) {
        if (pendingMoveEvaluation) { goodMoves++; pendingMoveEvaluation = false; updatePrecisionDisplay(); }
        const played = lastHumanMoveUci || '';
        const playedTo = played.length >= 4 ? played.slice(2, 4) : null;
        if (playedTo) showMainMoveVisualFeedback(playedTo, 'correct');
        lastBundleOpenAIHint = null;
        handleBundleSuccess();
        return;
    }
    if (pendingMoveEvaluation) {
        pendingMoveEvaluation = false;
        totalPlayerMoves = Math.max(0, totalPlayerMoves - 1);
        updatePrecisionDisplay();
    }
    showToast('La posició ha quedat en taules: aquest no era el camí.', 'warn');
    setTimeout(() => resetBundleToStartPosition(), 700);
}

function showDrillSuccessOverlay(titleText, onAgain) {
    const overlay = $('#bundle-success-overlay');
    if (!overlay.length) {
        alert(titleText);
        returnToMainMenuImmediate();
        return;
    }
    overlay.find('.bundle-success-title').text(titleText);
    overlay.find('.bundle-success-remaining').text('Pla diari actualitzat').show();
    overlay.find('#btn-bundle-random-again').text('➡️ Un altre').prop('disabled', false).toggle(true);
    wireContinueSolvedFenButton(overlay);
    overlay.css('display', 'flex');
    $('#btn-bundle-random-again').off('click').on('click', () => {
        overlay.hide();
        onAgain();
    });
    wireNavTrio(overlay, {
        sectionLabel: '<svg class="btn-ic" aria-hidden="true"><use href="#ic-cap"/></svg>Pla d\'entrenament',
        onSection: () => {
            goToHomeScreen();
            // Duu l'usuari directament al panell del pla de l'entrenador.
            setTimeout(() => {
                const panel = document.getElementById('weekly-plan-panel');
                if (panel && panel.style.display !== 'none') panel.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 80);
        }
    });
}

/* ===================== CONTEXT DE L'ERRADA EN EXERCICIS =====================
   Quan un exercici prové d'una errada real de l'usuari (savedErrors o errors de
   la partida acabada), mostrem QUÈ va jugar, QUAN i QUÈ va costar, amb la
   jugada errònia marcada al tauler. Així l'exercici és "rectifica la teva
   errada", no un genèric "troba la millor jugada". */

let currentErrorContext = null;
let errorReplayTimer = null;

const ERROR_SEVERITY_INFO = {
    low: { phrase: "una imprecisió que va deixar escapar una opció millor" },
    med: { phrase: "una errada que et va costar part de l'avantatge" },
    high: { phrase: "una errada greu que va canviar el signe de la partida" }
};

function uciToSanForFen(fen, uci) {
    if (!fen || !uci || String(uci).length < 4) return null;
    try {
        const probe = new Chess(fen);
        const mv = probe.move({ from: uci.slice(0, 2), to: uci.slice(2, 4), promotion: uci.length > 4 ? uci[4] : 'q' });
        return mv ? mv.san : null;
    } catch (e) { return null; }
}

function findBundleErrorRecord(fen) {
    if (!fen) return null;
    if (currentMatchError && currentMatchError.fen === fen && currentMatchError.playerMove) return currentMatchError;
    const saved = savedErrors.find(e => e.fen === fen && e.playerMove);
    if (saved) return saved;
    const inGame = (currentGameErrors || []).find(e => e.fen === fen && e.playerMove);
    return inGame || null;
}

function highlightErrorMove() {
    if (!currentErrorContext) return;
    $(`#myBoard .square-${currentErrorContext.from}`).addClass('square-error-played');
    const toSquare = $(`#myBoard .square-${currentErrorContext.to}`);
    toSquare.addClass('square-error-played');
    if (toSquare.length && !toSquare.find('.error-move-cross').length) {
        // Mateixa icona ✗ que la resta de jugades errònies de l'app.
        const cross = $('<div class="move-icon move-icon-incorrect error-move-cross">✗</div>');
        toSquare.append(cross);
        setTimeout(() => cross.addClass('show'), 10);
    }
}

function clearErrorMoveHighlights() {
    $('#myBoard .square-error-played').removeClass('square-error-played');
    $('#myBoard .error-move-cross').remove();
}

// Mostra o amaga el bàner segons el mode i l'origen de la posició. Es crida a startGame.
function renderBundleErrorContext() {
    const banner = $('#error-context-banner');
    if (!banner.length) return;
    if (errorReplayTimer) { clearTimeout(errorReplayTimer); errorReplayTimer = null; }
    clearErrorMoveHighlights();
    currentErrorContext = null;
    if (!blunderMode || !currentBundleFen) { banner.hide(); return; }
    const record = findBundleErrorRecord(currentBundleFen);
    const san = record ? uciToSanForFen(currentBundleFen, record.playerMove) : null;
    if (!san) { banner.hide(); return; }

    currentErrorContext = {
        from: record.playerMove.slice(0, 2),
        to: record.playerMove.slice(2, 4),
        san
    };
    const sev = ERROR_SEVERITY_INFO[record.severity] || ERROR_SEVERITY_INFO.med;
    const intro = record.date
        ? `El ${record.date} aquí vas jugar `
        : (isMatchErrorReviewSession ? 'En aquesta partida aquí has jugat ' : 'Aquí vas jugar ');

    const motive = record.bestMove
        ? analyzeTacticalMotive(currentBundleFen, record.bestMove, record.bestMovePv || [])
        : null;

    const textEl = $('#error-context-text').empty();
    textEl.append($('<span class="error-context-date"></span>').text('❌ '));
    textEl.append($('<span></span>').text(intro));
    textEl.append($('<strong></strong>').text(`${san}?`));
    textEl.append($('<span></span>').text(`, ${sev.phrase}.`));
    if (motive && motive.text) {
        textEl.append($('<span></span>').text(` El que se't va escapar: ${motive.text}.`));
    }
    textEl.append($('<span></span>').text(" Ara rectifica: juga el que hauries d'haver jugat."));

    $('#btn-error-replay').show().off('click').on('click', previewErrorMove);
    banner.css('display', 'flex');
    // El tauler es crea de forma asíncrona; marquem les caselles quan ja existeix
    setTimeout(highlightErrorMove, 150);
}

// Reprodueix visualment la jugada errònia sobre el tauler i torna a la posició inicial.
function previewErrorMove() {
    if (!currentErrorContext || !board || errorReplayTimer) return;
    // Amb la vista navegada (fletxes) la reproducció animaria la jugada sobre
    // una posició que no li correspon i acabaria repintant la posició en viu.
    if (isViewingGameHistory()) return;
    try { board.move(`${currentErrorContext.from}-${currentErrorContext.to}`); } catch (e) { return; }
    errorReplayTimer = setTimeout(() => {
        errorReplayTimer = null;
        try { board.position(game.fen()); } catch (e) {}
        highlightErrorMove();
    }, 1300);
}

// Quan l'usuari comença a resoldre, retirem les marques perquè no facin nosa.
function onErrorContextPlayerMoved() {
    if (!currentErrorContext) return;
    if (errorReplayTimer) { clearTimeout(errorReplayTimer); errorReplayTimer = null; }
    clearErrorMoveHighlights();
    $('#btn-error-replay').hide();
}

// PWA Install functionality
let deferredPrompt;

window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    $('#install-banner').addClass('show');
});

$('#btn-install').on('click', async () => {
    if (deferredPrompt) {
        deferredPrompt.prompt();
        const { outcome } = await deferredPrompt.userChoice;
        console.log(`Resultat instal·lació: ${outcome}`);
        deferredPrompt = null;
        $('#install-banner').removeClass('show');
    }
});

$('#btn-dismiss-install').on('click', () => {
    $('#install-banner').removeClass('show');
});

// X de les finestres d'èxit: tanca l'overlay per poder veure la posició final
// de l'exercici al tauler. Responem també a touchend/pointerup perquè en mòbil
// el click pot quedar suprimit pels gestors tàctils del tauler; el timestamp
// evita el doble dispar (touchend + click sintètic).
let overlayCloseLastTs = 0;
$(document).on('click touchend pointerup', '.overlay-close-x', function (e) {
    e.preventDefault();
    e.stopPropagation();
    const now = Date.now();
    if (now - overlayCloseLastTs < 400) return;
    overlayCloseLastTs = now;
    $(this).closest('.bundle-success-overlay').hide();
});

// Inicialització
/* ===================== REBOST D'EXERCICIS (pre-generació en segon pla) ===================== */
// Manté sempre uns quants exercicis del lot (tàctiques, correccions d'errades,
// errades d'obertura i repte diari) ja analitzats per Stockfish perquè comencin
// a l'instant, sense esperes ni errades de preparació. Les seqüències es desen a
// localStorage i només es calculen quan el motor està lliure (pantalles de menú).
const PREPARED_SEQ_STORAGE_KEY = 'chess_preparedSequences';
const PREPARED_EXERCISE_HISTORY_KEY = 'chess_preparedExerciseHistory';
const PREPARED_SEQ_TARGET = 8;            // exercicis a punt per categoria
const PREPARED_SEQ_MAX = 60;              // límit total d'entrades al rebost
const PREPARED_SEQ_TTL_MS = 7 * 86400000; // caducitat d'una seqüència preparada
const PREPARED_EXERCISE_HISTORY_MAX = 120;
let preparedSequences = {};               // fen -> { seq, ts }
let preparedExerciseHistory = [];          // auditoria sincronitzable via Firebase
let backgroundPrepPromise = null;
let backgroundPrepCurrentFen = null;
let backgroundPrepAbortRequested = false;
let backgroundPrepProtected = false;      // no interrompre: és l'exercici que vol l'usuari

function savePreparedSequences() {
    try {
        localStorage.setItem(PREPARED_SEQ_STORAGE_KEY, JSON.stringify(preparedSequences));
    } catch (e) {
        console.warn('[PrepBG] No s\'ha pogut desar el rebost d\'exercicis:', e);
        preparedSequences = {};
        try { localStorage.removeItem(PREPARED_SEQ_STORAGE_KEY); } catch (e2) {}
    }
}

function savePreparedExerciseHistory(notifyCloud = true) {
    try {
        localStorage.setItem(PREPARED_EXERCISE_HISTORY_KEY, JSON.stringify(preparedExerciseHistory));
        if (notifyCloud && window.CloudSync && typeof window.CloudSync.onLocalSave === 'function') {
            try { window.CloudSync.onLocalSave(); } catch (e) {}
        }
    } catch (e) {
        console.warn('[PrepBG] No s\'ha pogut desar l\'historial d\'exercicis preparats:', e);
    }
}

function loadPreparedExerciseHistory() {
    try {
        const raw = localStorage.getItem(PREPARED_EXERCISE_HISTORY_KEY);
        if (!raw) { preparedExerciseHistory = []; return; }
        const parsed = JSON.parse(raw);
        preparedExerciseHistory = Array.isArray(parsed)
            ? parsed.filter(item => item && item.fen).slice(0, PREPARED_EXERCISE_HISTORY_MAX)
            : [];
    } catch (e) {
        preparedExerciseHistory = [];
    }
}

function loadPreparedSequences() {
    try {
        const raw = localStorage.getItem(PREPARED_SEQ_STORAGE_KEY);
        if (!raw) return;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return;
        const now = Date.now();
        Object.keys(parsed).forEach(fen => {
            const entry = parsed[fen];
            const seq = entry && entry.seq;
            // Un exercici d'un sol pas (la millor jugada ja fa mat) és tan vàlid
            // com el de dos: el que cal és que hi hagi tants passos com la
            // seqüència diu i la rèplica fixa del rival entre pas i pas.
            const totalSteps = (seq && seq.totalSteps) || 2;
            const wellFormed = !!(seq && seq.initialFen === fen && seq.step1
                && Array.isArray(seq.fullSequence)
                && seq.fullSequence.length >= (2 * totalSteps - 1)
                && (totalSteps < 2 || (seq.step2 && seq.opponentMove))
                && (totalSteps < 3 || (seq.step3 && seq.opponentMove2)));
            if (wellFormed && now - (entry.ts || 0) <= PREPARED_SEQ_TTL_MS) {
                preparedSequences[fen] = entry;
            }
        });
    } catch (e) {
        console.warn('[PrepBG] Rebost corrupte; es descarta:', e);
        preparedSequences = {};
    }
}

function getPreparedExerciseSource(fen) {
    if (dailyPuzzle && dailyPuzzle.fen === fen) return 'daily';
    if (Array.isArray(TACTICS_BANK) && TACTICS_BANK.includes(fen)) return 'tactics';
    const saved = Array.isArray(savedErrors) ? savedErrors.find(e => e && e.fen === fen) : null;
    if (saved) {
        const fm = parseInt((fen || '').split(' ')[5], 10) || 99;
        if (fm <= 10 && saved.playerMove) return 'opening_error';
        if (getErrorDueTime(saved) <= Date.now()) return 'srs_due';
        return 'saved_error';
    }
    return 'bundle';
}

function recordPreparedExercise(fen, seq, source = null) {
    if (!fen || !seq) return;
    const entry = {
        id: 'prep_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8),
        fen,
        source: source || getPreparedExerciseSource(fen),
        generatedAt: Date.now(),
        fullSequence: Array.isArray(seq.fullSequence) ? seq.fullSequence.slice(0, 8) : [],
        fullSequenceSan: Array.isArray(seq.fullSequenceSan) ? seq.fullSequenceSan.slice(0, 8) : []
    };
    preparedExerciseHistory = [
        entry,
        ...preparedExerciseHistory.filter(item => item && !(item.fen === fen && item.source === entry.source))
    ].slice(0, PREPARED_EXERCISE_HISTORY_MAX);
    savePreparedExerciseHistory(true);
}

function cachePreparedSequence(fen, seq, source = null) {
    if (!fen || !seq || seq.initialFen !== fen) return;
    preparedSequences[fen] = { seq: clonePreparedSequence(seq), ts: Date.now() };
    prunePreparedSequences();
    savePreparedSequences();
    recordPreparedExercise(fen, seq, source);
}

function prunePreparedSequences() {
    const now = Date.now();
    let changed = false;
    Object.keys(preparedSequences).forEach(fen => {
        if (now - (preparedSequences[fen].ts || 0) > PREPARED_SEQ_TTL_MS) {
            delete preparedSequences[fen];
            changed = true;
        }
    });
    const fens = Object.keys(preparedSequences);
    if (fens.length > PREPARED_SEQ_MAX) {
        fens.sort((a, b) => (preparedSequences[a].ts || 0) - (preparedSequences[b].ts || 0));
        fens.slice(0, fens.length - PREPARED_SEQ_MAX).forEach(fen => { delete preparedSequences[fen]; });
        changed = true;
    }
    if (changed) savePreparedSequences();
}

function clonePreparedSequence(seq) {
    if (!seq) return null;
    try {
        return JSON.parse(JSON.stringify(seq));
    } catch (e) {
        return seq;
    }
}

// Retorna una còpia del rebost per aquest FEN (si hi és). No es consumeix: la
// mateixa seqüència pot reutilitzar-se en una altra sessió i continuar servint
// d'arrencada instantània fins que caduqui o el límit global obligui a purgar-la.
function takePreparedSequence(fen) {
    const entry = preparedSequences[fen];
    if (!entry || !entry.seq || entry.seq.initialFen !== fen) return null;
    entry.ts = Date.now();
    savePreparedSequences();
    return clonePreparedSequence(entry.seq);
}

// Un exercici arrenca a l'instant si té la seqüència al rebost (preparada en
// segon pla) o si la línia ja ve resolta de fàbrica al banc de tàctiques.
function exerciseStartsInstantly(fen) {
    return !!(fen && (preparedSequences[fen] || TACTICS_BANK_SOLUTIONS[fen]));
}

// Tria aleatòria que prefereix elements que arrenquin a l'instant.
function pickPreferPrepared(items, fenOf = (x) => x) {
    if (!items || !items.length) return null;
    const ready = items.filter(it => exerciseStartsInstantly(fenOf(it)));
    const pool = ready.length ? ready : items;
    return pool[Math.floor(Math.random() * pool.length)];
}

// Mostra estable: primer els FEN ja preparats (per no refer feina), després
// aleatoris nous fins a `count`.
function samplePreferPrepared(fens, count) {
    const unique = Array.from(new Set((fens || []).filter(Boolean)));
    const prepared = unique.filter(f => preparedSequences[f]);
    const rest = unique.filter(f => !preparedSequences[f]);
    for (let i = rest.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [rest[i], rest[j]] = [rest[j], rest[i]];
    }
    return prepared.concat(rest).slice(0, count);
}

// FENs que volem tenir sempre a punt, per ordre de prioritat. Les posicions que
// ja tenen línia de fàbrica al banc no hi entren mai: arrencar-les no costa res i
// el motor en segon pla queda lliure per als exercicis que sí que el necessiten
// (les errades pròpies i el repàs intel·ligent).
function getBackgroundPrepCandidates() {
    const out = [];
    const seen = {};
    const add = (fen) => {
        if (!fen || seen[fen] || TACTICS_BANK_SOLUTIONS[fen]) return;
        seen[fen] = true;
        out.push(fen);
    };
    try { ensureDailyPuzzle(); } catch (e) {}
    if (dailyPuzzle && dailyPuzzle.fen && !dailyPuzzle.solved) add(dailyPuzzle.fen);
    // Només posicions del cicle actual: les resoltes no es tornaran a servir.
    samplePreferPrepared(ElTaulerCore.tacticsPickPool(TACTICS_BANK, tacticsStats.recentFens), PREPARED_SEQ_TARGET).forEach(add);
    getDueErrors().slice(0, PREPARED_SEQ_TARGET).forEach(e => add(e.fen));
    samplePreferPrepared(savedErrors.map(e => e.fen), PREPARED_SEQ_TARGET).forEach(add);
    samplePreferPrepared(getOpeningPhaseErrors().map(e => e.fen), PREPARED_SEQ_TARGET).forEach(add);
    return out;
}

// Només preparem en segon pla quan el motor segur que no fa cap altra feina:
// a les pantalles de menú/estadístiques/configuració i sense cap petició pendent.
function isIdleForBackgroundPrep() {
    const idleScreenVisible = $('#start-screen').is(':visible') || $('#stats-screen').is(':visible') || $('#settings-screen').is(':visible');
    if (!idleScreenVisible || $('#game-screen').hasClass('active')) return false;
    return !isEngineThinking && !pendingMoveEvaluation && !mateDrillPreparing &&
        !openingPracticeEngineThinking && !openingPracticeAnalysisPending &&
        !openingPracticeHintPending && !openingPreCalcPending && !stockfishRequestor;
}

// Repòs "ampli" per generar jeroglífics: n'hi ha prou que no s'estigui jugant una
// partida ni fent un exercici/lliçó i que el motor no treballi per a l'usuari. Així
// el rebost es continua omplint sigui quina sigui la pantalla secundària visible
// (historial, obertures, etc.), no només al menú/estadístiques/ajustos.
function isIdleForHieroglyphicPrep() {
    if ($('#game-screen').hasClass('active')) return false;
    if (hieroglyphicExerciseActive || openingLessonActive || openingErrorPracticeActive) return false;
    // A l'explorador el motor és per a l'usuari (avalua cada posició que toca).
    if (explorerActive) return false;
    // No hi posem personalHieroglyphicPrepInFlight: el propi tick l'activa mentre
    // corre i s'auto-avortaria. La concurrència ja la frena el guard d'entrada
    // d'ensurePersonalHieroglyphicPoolTick i el de deepReviewInProgress d'aquí.
    if (deepReviewInProgress || waitingForBlunderAnalysis) return false;
    return !isEngineThinking && !pendingMoveEvaluation && !mateDrillPreparing &&
        !openingPracticeEngineThinking && !openingPracticeAnalysisPending &&
        !openingPracticeHintPending && !openingPreCalcPending && !stockfishRequestor;
}

// Demana aturar la preparació en segon pla perquè l'usuari necessita el motor.
// Si està preparant justament l'exercici demanat, la deixem acabar i es
// recollirà del rebost en lloc de refer-la.
function requestBackgroundPrepAbort(fenWanted = null) {
    if (!backgroundPrepPromise) return;
    if (fenWanted && backgroundPrepCurrentFen === fenWanted) {
        backgroundPrepProtected = true;
        return;
    }
    backgroundPrepAbortRequested = true;
    try { if (stockfish) stockfish.postMessage('stop'); } catch (e) {}
}

function waitForBackgroundPrepToYield(timeoutMs = 1500) {
    if (!backgroundPrepPromise) return Promise.resolve();
    return Promise.race([
        backgroundPrepPromise.catch(() => {}),
        new Promise(resolve => setTimeout(resolve, timeoutMs))
    ]);
}

async function backgroundPrepTick() {
    try { refillHieroglyphicQueue(); } catch (e) {}
    try { if (typeof renderHieroglyphicBanner === 'function') renderHieroglyphicBanner(); } catch (e) {}
    if (backgroundPrepPromise) return;
    if (typeof isCalibrationActive === 'function' && isCalibrationActive()) return;

    // 1) JEROGLÍFICS — cua sincronitzada (eltauler_hieroglyphics_state): genera com a
    //    màxim 1 jeroglífic per cicle en pantalles tranquil·les, amb bloqueig entre
    //    dispositius, objectius per aparell i mode lleuger (vegeu hgTick). Si acaba de
    //    generar-ne un i encara no s'ha arribat a l'objectiu, torna aviat per continuar.
    if (isIdleForHieroglyphicPrep()) {
        const beforeNew = (typeof hgNewCount === 'function') ? hgNewCount() : 0;
        try { await hgTick(() => backgroundPrepAbortRequested || !isIdleForHieroglyphicPrep()); } catch (e) {}
        const afterNew = (typeof hgNewCount === 'function') ? hgNewCount() : 0;
        if (afterNew > beforeNew && afterNew < hgDeviceTarget()
            && !backgroundPrepAbortRequested && isIdleForHieroglyphicPrep()) {
            setTimeout(backgroundPrepTick, 800);
            return;
        }
        if (afterNew > 0) return;
    }

    // 2) SEQÜÈNCIES D'EXERCICIS (preparació pesada) — es manté al llindar ESTRICTE de
    //    repòs (isIdleForBackgroundPrep: només menú/estadístiques/ajustos).
    if (!isIdleForBackgroundPrep()) return;
    prunePreparedSequences();
    const next = getBackgroundPrepCandidates().find(f => !preparedSequences[f]);
    if (!next) return;
    if (!ensureStockfish()) return;
    backgroundPrepAbortRequested = false;
    backgroundPrepProtected = false;
    backgroundPrepCurrentFen = next;
    backgroundPrepPromise = (async () => {
        try {
            const seq = await prepareBundleSequence(next, {
                silent: true,
                shouldAbort: () => backgroundPrepAbortRequested || (!backgroundPrepProtected && !isIdleForBackgroundPrep())
            });
            if (seq) {
                cachePreparedSequence(next, seq, 'background_' + getPreparedExerciseSource(next));
                console.log('[PrepBG] Exercici a punt:', next);
            }
        } catch (e) {
            console.warn('[PrepBG] Error preparant en segon pla:', e);
        } finally {
            backgroundPrepCurrentFen = null;
            backgroundPrepProtected = false;
            backgroundPrepPromise = null;
        }
    })();
    await backgroundPrepPromise;
    // Si seguim en repòs i queda rebost per omplir, continua de seguida (omplim el
    // rebost com més de pressa millor mentre l'usuari no necessiti el motor).
    if (!backgroundPrepAbortRequested) setTimeout(backgroundPrepTick, 600);
}

$(document).ready(() => {
    updateDeviceType();
    loadStorage();
    if (!isCalibrationActive()) {
        syncEngineEloFromUser();
    }
    void ensureBackupDirHandle({ prompt: false, mode: 'readwrite' });
    applyFontSize(loadFontSize());
    try { initHomeExtras(); } catch (e) { console.warn('[HomeExtras] init', e); }
    const __customId = customGameIdFromUrl();
    const __deepCatalans = isCatalansDeepLink();
    const __mode = (!__customId && !__deepCatalans) ? modeFromUrl() : '';
    history.replaceState(
        { screen: (__customId || __deepCatalans) ? 'catalans-screen' : 'start-screen', customId: __customId || null },
        '',
        __customId ? ('#partida-' + __customId)
            : (__deepCatalans ? screenUrl('catalans-screen')
            : (window.location.pathname + (__mode ? '' : window.location.search)))
    );
    applyEpaperMode(loadEpaperPreference(), { skipSave: true });
    applyDayMode(loadDayModePreference(), { skipSave: true });
    applyControlMode(loadControlMode(), { save: false, rebuild: false });
    applyBoardTheme(loadBoardTheme(), { skipSave: true });
    applyPieceTheme(loadPieceTheme(), { skipSave: true });
    applyLuckyMode(loadLuckyMode(), { skipSave: true, skipRoll: true });
    applyReviewVoiceStyle(loadReviewVoiceStyle(), { skipSave: true });
    loadAntidoteProgress();
    loadAntidoteNoticesPreference();
    bundleAcceptMode = loadBundleAcceptMode();
    const bSel = document.getElementById('bundle-accept-select');
    if (bSel) bSel.value = bundleAcceptMode;
    pendingFreeTimeControl = 'none';
    const tcSel = document.getElementById('new-game-tc-select');
    if (tcSel) tcSel.value = pendingFreeTimeControl;
    refreshPlayClockChips();
    generateDailyMissions(); checkStreak(); initCoachVoice(); ensureWeeklyPlan(); updateDisplay(); setupEvents();
    enablePremoveCancelGesture();
    if (__customId) {
        setTimeout(function () { openCustomGameScreen(__customId, false); }, 0);
    } else if (__deepCatalans) {
        setTimeout(function () { openCatalansScreen(false); }, 0);
    } else if (__mode) {
        // Deep-links de secció (pàgines d'aterratge SEO i dreceres de la PWA):
        // obren l'app directament a la pantalla demanada reutilitzant els botons.
        setTimeout(function () {
            if (__mode === 'game') $('#btn-new-game').click();
            else if (__mode === 'openings') $('#btn-opening').click();
            else if (__mode === 'league') $('#btn-league').click();
        }, 0);
    }
    if (!window.__boardResizeBound) {
        window.__boardResizeBound = true;
        window.addEventListener('resize', () => {
            if (board) { board.resize(); reapplyEngineMoveHighlight(); }
        });
    }

    setInterval(() => {
        if (getToday() !== missionsDate) generateDailyMissions();
        if (weeklyPlan && weeklyPlan.day !== getPlanDayKey()) ensureWeeklyPlan();
    }, 60000);

    // Rebost d'exercicis: recupera les seqüències desades i comença a omplir-lo
    // en segon pla perquè els exercicis arrenquin sense espera. Es persisteix a
    // localStorage (i se sincronitza), així que un cop omplert sobreviu entre
    // sessions. Arrenquem aviat i comprovem sovint per tenir-ne sempre de llestos.
    loadPreparedExerciseHistory();
    loadPreparedSequences();
    setTimeout(backgroundPrepTick, 1200);
    setInterval(backgroundPrepTick, 4000);
    // Quan la pestanya torna a primer pla, reprèn la generació de seguida: els timers
    // es frenen molt en segon pla, així que no esperem el pròxim interval de 4s.
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') setTimeout(backgroundPrepTick, 300);
    });

    // Escalfa el graf d'obertures per posició en segon pla (detecció immune a
    // transposicions), perquè l'anàlisi de partides ja el tingui llest.
    setTimeout(function () { try { prewarmOpeningPositionGraph(); } catch (e) {} }, 4000);
});
